window.HMMA_PAPERS = [{"id": "28934", "title": "Relational Programming with Foundational Models", "authors": ["Ziyang Li", "Jiani Huang", "Jason Liu", "Felix Zhu", "Eric Zhao", "William Dodds", "Neelay Velingker", "Rajeev Alur", "Mayur Naik"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/28934/29776", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "LLaMA", "DeBERTa", "text-embedding-ada-002"], "non_llm_models": {"perception": ["CLIP", "OWL-ViT", "SAM", "ViLT", "DSFD"], "generation": ["Stable Diffusion", "DALL-E"], "execution": []}, "summary": "User queries are parsed by GPT-4 into declarative relational programs (Datalog). The VIEIRA runtime executes these programs by invoking foreign predicates that interface with perception models (CLIP, OWL-ViT, etc.) for visual analysis and generation models (Stable Diffusion) for image synthesis. A probabilistic relational engine aggregates all model outputs with uncertainty quantification to produce the final structured answer."}, {"id": "28308", "title": "PathAsst: A Generative Foundation AI Assistant towards Artificial General Intelligence of Pathology", "authors": ["Yuxuan Sun", "Chenglu Zhu", "Sunyi Zheng", "Kai Zhang", "Lin Sun", "Zhongyi Shui", "Yunlong Zhang", "Honglin Li", "Lin Yang"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/28308/28605", "code": "https://github.com/superjamessyx/Generative-", "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Vicuna-13B"], "non_llm_models": {"perception": ["PathCLIP", "YOLOv7", "ConvNeXt-Tiny", "DPA-P2PNet", "SAM"], "generation": ["Stable Diffusion"], "execution": []}, "summary": "Pathology images are encoded by PathCLIP and projected into Vicuna-13B's embedding space via a fully-connected layer. The LLM interprets the multimodal input and user query, then either generates a direct text response or symbolically invokes specialized sub-models (e.g., YOLOv7 for detection, SAM for segmentation, Stable Diffusion for cell generation). The outputs from these sub-models are processed by Vicuna-13B to produce the final diagnostic report, analysis, or generated cell image."}, {"id": "29905", "title": "Tackling Vision Language Tasks through Learning Inner Monologues", "authors": ["Diji Yang", "Kezhen Chen", "Jinmeng Rao", "Xiaoyuan Guo", "Yawen Zhang", "Jie Yang", "Yi Zhang"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/29905/31583", "code": "https://github.com/ucscirkm/immo", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["BLIP-2"], "generation": [], "execution": []}, "summary": "Image input is processed by BLIP-2 (Observer) to generate an initial caption. Vicuna-7B (Reasoner) then enters a multi-turn dialogue: generating queries based on the task and conversation history, receiving answers from BLIP-2 which perceives specific visual details, and finally producing a text answer after accumulating sufficient information through the Inner Monologue."}, {"id": "29376", "title": "Hypothesis, Verification, and Induction: Grounding Large Language Models with Self-Driven Skill Learning", "authors": ["Shaohui Peng", "Xing Hu", "Qi Yi", "Rui Zhang", "Jiaming Guo", "Di Huang", "Zikang Tian", "Ruizhi Chen", "Zidong Du", "Qi Guo", "Yunji Chen", "Ling Li"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/29376/30598", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Coordinator", "Reflector", "Translator", "Verifier"], "llm_models": ["GPT-3.5-turbo", "GPT-4"], "non_llm_models": {"perception": ["GetObservedObjects", "environment state observation"], "generation": [], "execution": ["PPO policies", "RL skill policies"]}, "summary": "HYVIN operates in four phases: (1) Hypothesis: LLM decomposes instructions into subgoals and generates check functions; (2) Verification: PPO policies train with intrinsic rewards from check functions to verify subgoals; (3) Induction: Verified subgoals are clustered by semantic similarity to train generalized RL skills; (4) Deduction: LLM generates programs using learned skills with iterative debugging to solve complex unseen tasks."}, {"id": "27888", "title": "Visual Chain-of-Thought Prompting for Knowledge-Based Visual Reasoning", "authors": ["Zhenfang Chen", "Qinhong Zhou", "Yikang Shen", "Yining Hong", "Zhiqing Sun", "Dan Gutfreund", "Chuang Gan"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/27888/27801", "code": "https://github.com/UMass-Foundation-Model/VisualCoT.git", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["OPT-66B", "Llama-2-70B"], "non_llm_models": {"perception": ["Faster-RCNN", "BLIP", "CLIP (ViT-B/16)"], "generation": [], "execution": []}, "summary": "The pipeline consists of three modules: (1) See: Faster-RCNN detects object candidates and BLIP generates a global image caption; (2) Think: The LLM attends to key visual concepts related to the question, BLIP generates regional descriptions for these concepts, and the LLM predicts an answer; (3) Confirm: The LLM generates a supporting rationale, which CLIP verifies against the image for consistency. Verified rationales are fed back into the prompt, and the Think-Confirm cycle repeats until answer convergence."}, {"id": "29858", "title": "VELMA: Verbalization Embodiment of LLM Agents for Vision and Language Navigation in Street View", "authors": ["Raphael Schumann", "Wanrong Zhu", "Weixi Feng", "Tsu-Jui Fu", "Stefan Riezler", "William Yang Wang"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/29858/31495", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4", "GPT-3", "LLaMA-7b", "Mixtral"], "non_llm_models": {"perception": ["CLIP-ViT-bigG-14-laion2B-39B-b160k", "CLIP-ViT-large-patch14"], "generation": [], "execution": []}, "summary": "VELMA extracts landmarks from instructions using an LLM, then employs CLIP to score landmark visibility across multiple viewing angles of Street View panoramas. A template-based verbalizer converts visible landmarks and intersection information into text observations. The LLM consumes this verbalized history to directly predict the next discrete action (forward/left/right/turn_around/stop), which is executed by the deterministic Touchdown environment. No separate learned action model is used."}, {"id": "28597", "title": "NavGPT: Explicit Reasoning in Vision-and-Language Navigation with Large Language Models", "authors": ["Gengze Zhou", "Yicong Hong", "Qi Wu"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/28597/29161", "code": "https://github.com/GengzeZhou/NavGPT", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier"], "llm_models": ["GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["BLIP-2 ViT-G FlanT5XL", "Fast-RCNN"], "generation": [], "execution": []}, "summary": "At each navigation step, 24 egocentric views are processed by BLIP-2 (scene captioning) and Fast-RCNN (object detection with depth from the simulator). A prompt manager aggregates these perception outputs, the instruction, and a summarized history into a structured prompt for GPT-4/GPT-3.5. The LLM performs explicit chain-of-thought reasoning and predicts the next viewpoint ID, which is executed deterministically in the Matterport3D simulator. No learned action policy is used."}, {"id": "29421", "title": "SemTra: A Semantic Skill Translator for Cross-Domain Zero-Shot Policy Adaptation", "authors": ["Sangwoo Shin", "Minjong Yoo", "Jeongwoo Lee", "Honguk Woo"], "venue": "AAAI", "year": 2024, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/29421/30681", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4", "PaLM", "GPT-3.5", "GPT2", "GPT2-large", "Bloom"], "non_llm_models": {"perception": ["V-CLIP", "sensor data classifier"], "generation": [], "execution": ["behavior decoder π", "skill boundary detector ΦB", "domain context encoder ΦC", "online context encoder Φ(o)C"]}, "summary": "Multi-modal task prompts (video, sensor, text) are processed by V-CLIP and sensor encoders to extract semantic skills. A PLM performs seq-to-seq translation to generate a semantic skill sequence tailored to the target domain. Context encoders then instantiate these skills with domain-specific parameters, and a behavior decoder outputs executable low-level actions for the target environment."}, {"id": "33160", "title": "VIoTGPT: Learning to Schedule Vision Tools Towards Intelligent Video Internet of Things", "authors": ["Yaoyao Zhong", "Mengshi Qi", "Rui Wang", "Yuhan Qiu", "Yang Zhang", "Huadong Ma"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/33160/35315", "code": "https://github.com/zhongyy/VIoTGPT", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Llama-7B", "Vicuna-7B", "ChatGPT"], "non_llm_models": {"perception": ["Face Recognition", "Person Re-identification", "Gait Recognition", "Vehicle Re-identification", "License Plate Recognition", "Human Pose Estimation", "Human Action Recognition", "Crowd Counting", "Scene Recognition", "Fire/Smoke Detection", "Violence Detection"], "generation": [], "execution": []}, "summary": "User submits a query with visual information → LLM formats it into a ReAct prompt and reasons whether to invoke tools → LLM selects specific vision perception models and queries the video knowledge base → Vision models execute analysis and return observations → LLM receives observations, updates context, and iteratively plans next steps or provides final text feedback to the user."}, {"id": "35048", "title": "Pioneering Explainable Video Fact-Checking with a New Dataset and Multi-role Multimodal Model Approach", "authors": ["Kaipeng Niu", "Danni Xu", "Bingjian Yang", "Wenxuan Liu", "Zheng Wang"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/35048/37203", "code": "https://github.com/MeiTaylor/TRUE-3MFact", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o-mini"], "non_llm_models": {"perception": ["MiniCPM-V 2.6", "VideoLLaVA", "CogVLM", "Deepgram API", "Katna"], "generation": [], "execution": []}, "summary": "Video input is processed by the Video Descriptor (using Katna for keyframes, MiniCPM-V/VideoLLaVA/CogVLM for visual analysis, and Deepgram for audio) to generate textual descriptions. The Claim Verifier assesses evidence sufficiency with confidence scoring. If insufficient, the Question Manager generates questions and routes to either VideoLMM for video-based answers or Information Retriever (Google Search) for external evidence. This iterative loop continues until sufficient evidence is gathered, then the Reasoner outputs the final veracity label, rationale, and supporting evidence."}, {"id": "32280", "title": "Muses: 3D-Controllable Image Generation via Multi-Modal Agent Collaboration", "authors": ["Yanbo Ding", "Shaobin Zhuang", "Kunchang Li", "Zhengrong Yue", "Yu Qiao", "Yali Wang"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32280/34435", "code": "https://github.com/DINGYANB/MUSES", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Llama-3-8B"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "CLIP ViT-B/32"], "generation": ["Stable Diffusion 3", "ControlNet", "Shap-E", "3DTopia", "Blender"], "execution": []}, "summary": "User queries are processed by the Layout Manager (Llama-3) to generate 2D layouts and lift them to 3D via chain-of-thought reasoning. The Model Engineer then retrieves or generates 3D models using a decision tree (shop/online/Shap-E/3DTopia) and aligns object orientations using fine-tuned CLIP. Finally, the Image Artist assembles objects in Blender to render depth/canny conditions, which are fed into ControlNet with Stable Diffusion 3 to generate the final controllable image."}, {"id": "32346", "title": "DME-Driver: Integrating Human Decision Logic and 3D Scene Perception in Autonomous Driving", "authors": ["Wencheng Han", "Dongqian Guo", "Cheng-Zhong Xu", "Jianbing Shen"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32346/34501", "code": null, "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Converge", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaVA", "LLaMA 2"], "non_llm_models": {"perception": ["CLIP", "TrackFormer", "MapFormer", "MotionFormer", "OccFormer", "BEV encoder"], "generation": [], "execution": ["UniAD-based Planner", "Logical-based Planner"]}, "summary": "Multi-view visual inputs are processed by CLIP for the Decision-Maker (LLaVA/LLaMA 2) to generate human-like driving logic text. Simultaneously, the Executor processes visual inputs through a BEV encoder and perception modules (TrackFormer, MapFormer, etc.). The driving logic text is encoded by BERT and fused with BEV features via a LogicalFusioner module, enabling the Planner to generate precise vehicle control signals."}, {"id": "32681", "title": "Modular-Cam: Modular Dynamic Camera-view Video Generation with LLM", "authors": ["Zirui Pan", "Xin Wang", "Yipeng Zhang", "Hong Chen", "Kwan Man Cheng", "Yaofei Wu", "Wenwu Zhu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32681/34836", "code": "https://github.com/pzrain/Modular-Cam", "pattern": "LLM + Generation", "domain": "Video_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Coordinator"], "llm_models": ["GPT-3.5", "ChatGPT3.5-turbo"], "non_llm_models": {"perception": ["CLIP (text encoder)"], "generation": ["Stable Diffusion", "AnimateDiff", "ControlNet", "CamOperator (LoRA modules)", "AdaControlNet"], "execution": []}, "summary": "User text instruction is parsed by GPT-3.5 (LLM-Director) to decompose into sequential scene descriptions and camera transition actions. For each scene, the appropriate CamOperator LoRA module is selected and plugged into the base video generator (AnimateDiff+Stable Diffusion) to control camera motion. AdaControlNet uses the previous scene's ending frame as a condition to ensure visual consistency across scene boundaries. Generated scene clips are concatenated to form the final multi-scene video."}, {"id": "32913", "title": "Combating Multimodal LLM Hallucination via Bottom-Up Holistic Reasoning", "authors": ["Shengqiong Wu", "Hao Fei", "Liangming Pan", "William Yang Wang", "Shuicheng Yan", "Tat-Seng Chua"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32913/35068", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["LLaVA-1.5", "Qwen-VL", "MiniGPT-v2", "GPT-4V"], "non_llm_models": {"perception": ["Grounding DINO", "BLIP"], "generation": [], "execution": []}, "summary": "The pipeline begins with an MLLM generating a partial scene graph from the input image and question. Grounding DINO verifies objects and attributes while BLIP validates relationships, with the results filtering the scene graph. The MLLM then validates and corrects the input question against this verified perception, induces commonsense claims for cognition-level questions, and verifies these claims via web search (Serper API). Finally, the MLLM generates the answer based on the verified perception and commonsense knowledge."}, {"id": "33610", "title": "Instruction-Augmented Long-Horizon Planning: Embedding Grounding Mechanisms in Embodied Mobile Manipulation", "authors": ["Fangyuan Wang", "Shipeng Lyu", "Peng Zhou", "Anqing Duan", "Guodong Guo", "David Navarro-Alarcon"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/33610/35765", "code": "https://github.com/google/nerfies", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["SAM", "CLIP", "LangSAM", "GraspNet"], "generation": [], "execution": ["Tiago++ robot platform", "Pinocchio"]}, "summary": "User instructions are augmented by GPT-4o into PDDL problems using promptable predicates. Vision models (SAM/CLIP/LangSAM/GraspNet) provide grounding feedback via feasibility predicates (detected, graspable, reachable) to quantify environmental constraints. GPT-4o generates and selects optimal actions based on token probabilities, which are executed by the Tiago++ robot using Pinocchio for motion planning. State updates close the loop for iterative replanning."}, {"id": "34661", "title": "DialogDraw: Image Generation and Editing System Based on Multi-Turn Dialogue", "authors": ["Shichao Ma", "Xinfeng Zhang", "Zeng Zhao", "Bai Liu", "Changjie Fan", "Zhipeng Hu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/34661/36816", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Qwen-VL"], "non_llm_models": {"perception": [], "generation": ["SDXL", "ControlNet", "InstructPix2Pix", "Stable Diffusion"], "execution": []}, "summary": "User engages in multi-turn dialogue (providing text instructions and previous images); IRPEM (a fine-tuned Qwen-VL) analyzes the dialogue history to recognize intent and extract structured JSON parameters; the LLM selects and invokes the appropriate drawing pipeline (SDXL for generation, ControlNet for controlled generation, or InstructPix2Pix for editing) with the extracted parameters; the pipeline generates or edits the image, which is returned to the user for subsequent dialogue turns."}, {"id": "32796", "title": "ChatterBox: Multimodal Referring and Grounding with Chain-of-Questions", "authors": ["Yunjie Tian", "Tianren Ma", "Lingxi Xie", "Qixiang Ye"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32796/34951", "code": "https://github.com/sunsmarterjie/ChatterBox", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaVA-13B", "LLaMA"], "non_llm_models": {"perception": ["CLIP-L/14", "iTPN-B", "DINO", "Region Align (RoIAlign)"], "generation": [], "execution": []}, "summary": "Input images are processed by CLIP-L/14 and iTPN-B to extract visual features. LLaVA-13B generates text responses and, when triggered by [REF] or [GND] tokens, coordinates with the Region Align module (for referring) or the DINO-based Grounding Decoder (for grounding) to produce bounding boxes. The system employs referent feedback, where high-confidence bounding boxes (>0.8) from previous rounds are re-embedded via Region Align to maintain coherence in subsequent chain-of-questions turns."}, {"id": "32455", "title": "Multi-Modal Grounded Planning and Efficient Replanning for Learning Embodied Agents with a Few Examples", "authors": ["Taewoong Kim", "Byeonghwi Kim", "Jonghyun Choi"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32455/34610", "code": null, "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4", "GPT-3.5", "LLaMA2", "Vicuna"], "non_llm_models": {"perception": ["CLIP-ViT", "Object Detector"], "generation": [], "execution": []}, "summary": "FLARE's Multi-Modal Planner retrieves few-shot examples by computing multi-modal similarity with frozen CLIP-ViT image embeddings and BERT text embeddings from initial panoramic views and instructions, then prompts an LLM to generate subgoal triplets. Navigation and path execution are handled by a deterministic FMM path planner. During execution, an Object Detector maintains a set of observed objects; if a target remains undetected past an uncertainty threshold, the Environment Adaptive Replanning module uses BERT similarity to substitute the missing object with the most semantically similar detected alternative, continuing execution with the revised subgoal."}, {"id": "33607", "title": "Enhancing Multi-Robot Semantic Navigation Through Multimodal Chain-of-Thought Score Collaboration", "authors": ["Zhixuan Shen", "Haonan Luo", "Kexun Chen", "Fengmao Lv", "Tianrui Li"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/33607/35762", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GLM-4V-9B"], "non_llm_models": {"perception": ["YOLOV10m", "RedNet"], "generation": [], "execution": []}, "summary": "Robot RGB-D observations are processed by YOLOV10m and RedNet to produce object detections and semantic maps that update a global semantic map. GLM-4V-9B performs sequential multimodal Chain-of-Thought reasoning across Perception, Judgment, and Decision modules to score exploration value and select frontier points or history nodes as long-term navigation goals. A Logical Analysis module checks navigational feasibility and collisions, and the deterministic Fast Marching Method generates low-level discrete actions to drive the robot toward the selected goals."}, {"id": "35003", "title": "PhishAgent: A Robust Multimodal Agent for Phishing Webpage Detection", "authors": ["Tri Cao", "Chengyu Huang", "Yuexin Li", "Wang Huilin", "Amy He", "Nay Oo", "Bryan Hooi"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/35003/37158", "code": null, "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLM (Text-based Brand Extractor, Domain Checker, Target Brand Checker)", "MLLM (Image-based Brand Extractor, Recheck Procedure)"], "non_llm_models": {"perception": ["CLIP Text Encoder", "CLIP Image Encoder", "Logo Detection Model", "MLLM (for image-based brand extraction)"], "generation": [], "execution": []}, "summary": "Webpage input undergoes Preprocessing (logo extraction, HTML cleaning) to feed both Offline Knowledge Base (fine-tuned CLIP retriever for top-k brands) and Online Knowledge Base (search queries). The Agent Core first uses Text-based Brand Extractor (LLM) to identify brands from HTML and candidates, falling back to Image-based Brand Extractor (MLLM) on screenshot if needed. Domain Checker and Target Brand Checker verify against retrieved knowledge bases, with a Recheck Procedure re-analyzing screenshots for adversarial cases, ultimately classifying the webpage as phishing or benign."}, {"id": "32387", "title": "Unleashing the Temporal-Spatial Reasoning Capacity of GPT for Training-Free Audio and Language Referenced Video Object Segmentation", "authors": ["Shaofei Huang", "Rui Ling", "Hongyu Li", "Tianrui Hui", "Zongheng Tang", "Xiaoming Wei", "Jizhong Han", "Si Liu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32387/34542", "code": "https://github.com/appletea233/AL-Ref-SAM2", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["GroundingDINO", "SAM 2", "BEATs"], "generation": [], "execution": []}, "summary": "For AVS, audio is processed by BEATs and converted to language format via the LBRU module using GPT-4. For both tasks, the GPT-PS module performs two-step reasoning: first selecting a pivot frame via temporal reasoning, then selecting a pivot box from GroundingDINO candidates via spatial reasoning. The selected box prompts SAM 2 to segment and track the object throughout the video."}, {"id": "34526", "title": "Affordances-Oriented Planning Using Foundation Models for Continuous Vision-Language Navigation", "authors": ["Jiaqi Chen", "Bingqian Lin", "Xinmin Liu", "Lin Ma", "Xiaodan Liang", "Kwan-Yee K. Wong"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/34526/36681", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o", "Gemini-1.5-Pro"], "non_llm_models": {"perception": ["Grounded SAM", "Grounding DINO", "SAM", "depth sensor"], "generation": [], "execution": ["rotate-then-forward policy controller"]}, "summary": "RGB observations are processed by Grounded SAM to segment navigable ground affordances. Visual Affordances Prompting scatters labeled points within these regions, which Gemini-1.5-Pro uses to select waypoints and plan obstacle-avoiding paths. GPT-4o PathAgent then visually reasons over these candidate paths to select the optimal route. Finally, depth and camera intrinsics project the pixel-based path to 3D coordinates, and a low-level controller executes FORWARD/ROTATE actions to navigate the agent."}, {"id": "34965", "title": "SYNAPSE: SYmbolic Neural-Aided Preference Synthesis Engine", "authors": ["Sadanand Modak", "Noah Tobias Patton", "Isil Dillig", "Joydeep Biswas"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/34965/37120", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Grounded-SAM", "Depth Anything", "SegFormer"], "generation": [], "execution": []}, "summary": "User provides a visual demonstration (trajectory) and natural language explanation. GPT-4 extracts entities and predicates, using perception models (Grounded-SAM, Depth Anything, SegFormer) for visual grounding to update a concept library. GPT-4 then synthesizes a neuro-symbolic program sketch with missing numeric parameters (holes). Finally, a MaxSMT solver fills these holes using the demonstration data to produce a complete preference evaluator program."}, {"id": "32384", "title": "VProChart: Answering Chart Question Through Visual Perception Alignment Agent and Programmatic Solution Reasoning", "authors": ["Muye Huang", "Lingling Zhang", "Han Lai", "Wenjun Wu", "Xinyu Zhang", "Jun Liu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32384/34539", "code": "https://github.com/MuyeHuang/VproChart", "pattern": "LLM + Perception + Action", "domain": "Document_Understanding", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2-7B-Instruct"], "non_llm_models": {"perception": ["VPAgent (Swin-Encoder based)", "RoBERTa", "mBART"], "generation": [], "execution": ["Python-style Reasoning Engine"]}, "summary": "The LLM (Qwen2-7B-Instruct) generates a Python-style solution program containing SUBSTEP operators based on the user question. The Python-style Reasoning Engine parses and executes this program sequentially, invoking VPAgent (which uses Swin-Encoder for visual encoding and visual perception alignment) to answer sub-questions and retrieve intermediate values. The engine then performs precise numerical and logical computations on these values to derive the final text answer."}, {"id": "32142", "title": "MuMA-ToM: Multi-modal Multi-Agent Theory of Mind", "authors": ["Haojun Shi", "Suyu Ye", "Xinyu Fang", "Chuanyang Jin", "Leyla Isik", "Yen-Ling Kuo", "Tianmin Shu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32142/34297", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Gemini 1.5 Pro"], "generation": [], "execution": []}, "summary": "Video inputs are processed by Gemini 1.5 Pro (VLM) to extract actions and utterances, while text inputs are parsed by GPT-4o. GPT-4o fuses these multi-modal inputs, reconstructs the initial state, and generates mental state hypotheses (belief, social goal, belief of other's goal) for each answer option. Finally, GPT-4o performs inverse multi-agent planning by estimating the likelihood of observed actions/utterances under each hypothesis to select the most probable answer."}, {"id": "32038", "title": "GenAL: Generative Agent for Adaptive Learning", "authors": ["Rui Lv", "Qi Liu", "Weibo Gao", "Haotian Zhang", "Junyu Lu", "Linbo Zhu"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32038/34193", "code": "https://github.com/karin0018/GenAL", "pattern": "LLM + Perception", "domain": "Other", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo", "Llama2-7B", "Llama3-8B"], "non_llm_models": {"perception": ["Deep Knowledge Tracing (DKT)", "cognitive diagnosis models"], "generation": [], "execution": []}, "summary": "Learner interaction history is first processed by DKT to assess knowledge mastery. The Global Thinking Agent (LLM Reflector) updates the learner profile and reflects on past performance. The Local Teaching Agent (LLM Recommender) then selects the next exercise from a candidate set using a knowledge graph and the updated profile. After the learner answers, feedback is stored in Log Memory and used to update the recommendation strategy in the next iteration."}, {"id": "34123", "title": "Vision-Based Generic Potential Function for Policy Alignment in Multi-Agent Reinforcement Learning", "authors": ["Hao Ma", "Shijie Wang", "Zhiqiang Pu", "Siyao Zhao", "Xiaolin Ai"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/34123/36278", "code": "https://github.com/openai/CLIP", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["MiniCPM-Llama3-V"], "non_llm_models": {"perception": ["CLIP-RN50"], "generation": [], "execution": ["MAPPO-based MARL policies"]}, "summary": "Video replays and training records are fed into MiniCPM-Llama3-V (vLLM), which adaptively selects a CLIP-based potential function from a pre-designed pool. During each training step, environmental states are encoded by CLIP along with the selected instruction to compute a generic potential-based reward via cosine similarity. This reward is combined with sparse environmental rewards to train MAPPO policies, which execute discrete actions (19-dimensional) in the Google Research Football environment."}, {"id": "33602", "title": "Safe Planner: Empowering Safety Awareness in Large Pre-Trained Models for Robot Task Planning", "authors": ["Siyuan Li", "Feifan Liu", "Lingfei Cui", "Jiani Lu", "Qinqin Xiao", "Xirui Yang", "Peng Liu", "Kewu Sun", "Zhe Ma", "Xun Wang"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/33602/35757", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-4v"], "non_llm_models": {"perception": ["ViT (Vision Transformer)"], "generation": [], "execution": ["PPO policies (low-level skills)", "hand-crafted manipulation scripts"]}, "summary": "Natural language instructions are first translated to PDDL goals by GPT-4. The GPT-4v planner then takes these goals, current visual observations, and safety rankings (from the ViT-LSTM safety module) as input to output PDDL operators. Corresponding low-level skills (PPO policies or hand-crafted scripts) execute the operators, and the system replans in a closed loop after each execution step."}, {"id": "32657", "title": "Autonomous LLM-Enhanced Adversarial Attack for Text-to-Motion", "authors": ["Honglei Miao", "Fan Ma", "Ruijie Quan", "Kun Zhan", "Yi Yang"], "venue": "AAAI", "year": 2025, "url": "https://ojs.aaai.org/index.php/AAAI/article/view/32657/34812", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo", "Llama 3"], "non_llm_models": {"perception": ["T2M alignment model (motion encoder)"], "generation": ["MDM", "MLD"], "execution": []}, "summary": "The LLM agent generates candidate adversarial prompts which are used to query victim T2M models (MDM/MLD) to generate motions. The MMIC module extracts motion features using a T2M alignment model and calculates similarity to the target motion. This feedback is provided to the LLM, which iteratively refines the prompts through expansion, refinement, and update processes until finding optimal adversarial prompts that produce target-matching motions while evading detection."}, {"id": "2023.acl-short.65", "title": "Modular Visual Question Answering via Code Generation", "authors": ["Sanjay Subramanian", "Medhini Narasimhan", "Kushal Khangaonkar", "Kevin Yang", "Arsha Nagrani", "Cordelia Schmid", "Andy Zeng", "Trevor Darrell", "Dan Klein"], "venue": "ACL", "year": 2023, "url": "https://aclanthology.org/2023.acl-short.65.pdf", "code": "https://github.com/sanjayss34/codevqa", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Codex (code-davinci-002)"], "non_llm_models": {"perception": ["BLIP (ITM)", "BLIP (ITC)", "BLIP (Captioning)", "sentence-transformers"], "generation": [], "execution": []}, "summary": "Given a question, Codex generates a Python program via few-shot prompting (with examples retrieved using sentence-transformers). The program invokes visual primitives (query, get_pos, find_matching_image) that utilize BLIP models to extract information from images. The program then composes these outputs using Python logic (conditionals, arithmetic) to compute the final text answer. If code execution fails, the system falls back to a baseline query."}, {"id": "2024.findings-acl.908", "title": "Embodied Language Learning: Opportunities, Challenges, and Future Directions", "authors": ["Nadine Amin", "Julia Rayz"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.908.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["PaLM-E", "EmbodiedGPT", "CogLoop", "LLMs"], "non_llm_models": {"perception": ["Vision-Language models", "vision encoders"], "generation": [], "execution": ["RT-2", "control policies", "low-level RL policies", "Gato"]}, "summary": "The paper surveys embodied language learning systems where vision-language models perceive the environment and extract visual information. LLMs (PaLM-E, EmbodiedGPT, CogLoop) act as central orchestrators that reason over natural language instructions and visual inputs, planning and decomposing tasks into actionable sub-goals. These plans are executed by low-level control policies or end-to-end vision-language-action models (RT-2, Gato) that output robotic actions, enabling the grounding of language in sensorimotor experience within physical or simulated worlds."}, {"id": "2024.acl-long.529", "title": "MapGPT: Map-Guided Prompting with Adaptive Path Planning for Vision-and-Language Navigation", "authors": ["Jiaqi Chen", "Bingqian Lin", "Ran Xu", "Zhenhua Chai", "Xiaodan Liang", "Kwan-Yee Wong"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.529.pdf", "code": "https://github.com/chen-judge/MapGPT", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-4", "GPT-4V"], "non_llm_models": {"perception": ["BLIP-2", "Faster R-CNN"], "generation": [], "execution": []}, "summary": "MapGPT uses an optional two-stage perception pipeline where BLIP-2 and Faster R-CNN extract textual descriptions and detections from RGB observations, or a one-stage pipeline where GPT-4V processes images directly. The LLM maintains an online linguistic topological map and performs adaptive multi-step path planning to select navigation actions executed in the simulator."}, {"id": "2024.findings-acl.200", "title": "Semantic Skill Grounding for Embodied Instruction-Following in Cross-Domain Environments", "authors": ["Sangwoo Shin", "SeungHyun Kim", "Youngsoo Jang", "Moontae Lee", "Honguk Woo"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.200.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5", "GPT-4"], "non_llm_models": {"perception": ["InstructBLIP", "PG-InstructBLIP", "sentence-transformer"], "generation": [], "execution": ["VirtualHome low-level skills"]}, "summary": "Given a user instruction and visual observation, a kNN retriever selects skill candidates from a hierarchical database. GPT-3.5/4 generates a semantic skill, which InstructBLIP/PG-InstructBLIP evaluates for executability using visual input. If executable, the skill is performed in VirtualHome; otherwise, the LLM decomposes it into lower-level skills and iterates."}, {"id": "2024.acl-long.594", "title": "Exploring Hybrid Question Answering via Program-based Prompting", "authors": ["Qi Shi", "Han Cui", "Haofeng Wang", "Qingfu Zhu", "Wanxiang Che", "Ting Liu"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.594.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4 (gpt-4-0613)", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["GPT-4-vision-preview"], "generation": [], "execution": ["Python interpreter"]}, "summary": "The user query and table are processed by GPT-4 to generate Python code containing function calls (extract_info, check). A Python interpreter executes this code, during which extract_info invokes GPT-4-vision-preview for image understanding and GPT-4 for text extraction from passages, while check invokes GPT-3.5-turbo for semantic comparison. If execution fails, GPT-4 performs code refinement using error tracebacks before returning the final text answer."}, {"id": "2024.findings-acl.362", "title": "GeoAgent: To Empower LLMs using Geospatial Tools for Address Standardization", "authors": ["Chenghua Huang", "Shisong Chen", "Zhixu Li", "Jianfeng Qu", "Yanghua Xiao", "Jiaxin Liu", "Zhigang Chen"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.362.pdf", "code": "https://github.com/shapely/shapely", "pattern": "LLM + Perception + Action", "domain": "Other", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["ChatGLM-6B"], "non_llm_models": {"perception": ["Geocoding Model (Transformer seq-to-seq)"], "generation": [], "execution": ["S2 Geometry library", "Shapely", "OpenStreetMap (OPM) road information tool"]}, "summary": "The non-standard address is first processed by ChatGLM-6B to plan a sequence of tool calls. The Geocoding Model maps the address text to S2 tokens (spatial locations). Execution tools then perform offset calculations based on directional descriptions and retrieve road information from OPM to refine the location. Finally, the LLM normalizes the address text using the retrieved geographic data and POI database."}, {"id": "2024.acl-long.50", "title": "VisualWebArena: Evaluating Multimodal Agents on Realistic Visual Web Tasks", "authors": ["Jing Yu Koh", "Robert Lo", "Lawrence Jang", "Vikram Duvvur", "Ming Lim", "Po-Yu Huang", "Graham Neubig", "Shuyan Zhou", "Russ Salakhutdinov", "Daniel Fried"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.50.pdf", "code": null, "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4", "GPT-3.5", "Gemini-Pro", "LLaMA-2-70B", "Mixtral-8x7B", "GPT-4V", "IDEFICS-80B-Instruct", "CogVLM"], "non_llm_models": {"perception": ["BLIP-2-T5XL", "LLaVA-v1.5-7B"], "generation": [], "execution": []}, "summary": "VisualWebArena evaluates multimodal web agents on realistic visual web tasks. Caption-augmented variants use BLIP-2-T5XL or LLaVA-v1.5-7B to generate image captions from webpage screenshots, augmenting the accessibility tree provided to an LLM or VLM orchestrator. The orchestrator reasons over observations and outputs discrete web actions (click, type, scroll, etc.), which are executed by a deterministic browser environment. A JavaScript-based Set-of-Marks module optionally overlays bounding boxes and IDs on interactable elements to simplify grounding for VLMs."}, {"id": "2024.findings-acl.640", "title": "ViCor: Bridging Visual Understanding and Commonsense Reasoning with Large Language Models", "authors": ["Kaiwen Zhou", "Kwonjoon Lee", "Teruhisa Misu", "Xin Wang"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.640.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4-0613", "GPT-3.5-turbo-0613"], "non_llm_models": {"perception": ["LLAVA-7B-v1.1", "BLIP2", "BLIP2-FlanT5 XL"], "generation": [], "execution": []}, "summary": "Image input is first processed by LLAVA to generate a caption. The LLM performs initial chain-of-thought reasoning and confidence verification. If confident, it outputs the answer. If not, the LLM classifies the problem as either VCU (Visual Commonsense Understanding) or VCI (Visual Commonsense Inference). For VCU, BLIP2 performs image-text alignment on LLM-transformed declarative sentences. For VCI, the LLM reasons about required visual factors, instructs BLIP2-VQA to gather specific visual clues, selects the best-aligned clues using BLIP2-ITA, and performs final reasoning with the augmented context to produce the answer."}, {"id": "2024.findings-acl.701", "title": "MatPlotAgent: Method and Evaluation for LLM-Based Agentic Scientific Data Visualization", "authors": ["Zhiyu Yang", "Zihan Zhou", "Shuo Wang", "Xin Cong", "Xu Han", "Yukun Yan", "Zhenghao Liu", "Zhixing Tan", "Pengyuan Liu", "Dong Yu", "Zhiyuan Liu", "Xiaodong Shi", "Maosong Sun"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.701.pdf", "code": "https://github.com/thunlp/MatPlotAgent", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "Magicoder-S-DS-6.7B", "Deepseek-coder-6.7B-instruct", "Deepseek-coder-33B-instruct", "WizardCoder-Python-33B-V1.1", "CodeLlama-34B-Instruct"], "non_llm_models": {"perception": ["GPT-4V", "Gemini Pro Vision"], "generation": [], "execution": []}, "summary": "MatPlotAgent is a model-agnostic framework in which a code LLM expands user queries into step-by-step instructions and generates Python plotting code. A deterministic Python interpreter executes the code with Matplotlib to render a draft figure. A separate multi-modal LLM (GPT-4V or Gemini Pro Vision) acts as a visual agent that perceives the draft figure, identifies errors or aesthetic issues, and feeds back natural-language suggestions to the code LLM for iterative refinement. No learned action or generation models are involved."}, {"id": "2024.findings-acl.745", "title": "CorNav: Autonomous Agent with Self-Corrected Planning for Zero-Shot Vision-and-Language Navigation", "authors": ["Xiwen Liang", "Liang Ma", "Shanshan Guo", "Jianhua Han", "Hang Xu", "Shikui Ma", "Xiaodan Liang"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.745.pdf", "code": "https://github.com/liangcici/MO-VLN", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Reflector"], "llm_models": ["Vicuna v1.5", "GPT-4", "GPT-4 Turbo"], "non_llm_models": {"perception": ["RAM++", "Grounding DINO", "SAM (Segment Anything Model)"], "generation": [], "execution": []}, "summary": "CorNav is a zero-shot VLN agent that uses an LLM (Vicuna v1.5 or GPT-4) as a central planner. It consults domain experts: an instruction parsing expert (LLM), a vision perception expert comprising RAM++ for image tagging and Grounding DINO for detection (with SAM for precise segmentation), and a decision-making expert (LLM) that validates actions. The planner generates and self-corrects navigation plans based on environmental feedback. A deterministic local policy uses the Fast Marching Method to compute low-level paths in the simulator."}, {"id": "2024.acl-long.178", "title": "Unified Hallucination Detection for Multimodal Large Language Models", "authors": ["Xiang Chen", "Chenxi Wang", "Yida Xue", "Ningyu Zhang", "Xiaoyan Yang", "Qiang Li", "Yue Shen", "Lei Liang", "Jinjie Gu", "Huajun Chen"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.178.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4V (gpt-4-vision-preview)", "Gemini (Pro Vision)"], "non_llm_models": {"perception": ["Grounding DINO", "MAERec", "Serper Google Search API"], "generation": [], "execution": []}, "summary": "The system first extracts fine-grained claims from MLLM responses using GPT-4V/Gemini. For each claim, the LLM autonomously formulates queries and routes them to appropriate tools: Grounding DINO for object detection, MAERec for scene text recognition, search API for fact verification, and self-reflection for attributes. These tools execute in parallel to gather evidence, which is then aggregated by the LLM to verify each claim as hallucinatory or non-hallucinatory with explanatory rationales."}, {"id": "2024.findings-acl.537", "title": "TextBind: Multi-turn Interleaved Multimodal Instruction-following in the Wild", "authors": ["Huayang Li", "Siheng Li", "Deng Cai", "Longyue Wang", "Lemao Liu", "Taro Watanabe", "Yujiu Yang", "Shuming Shi"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.537.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaMA2-Chat"], "non_llm_models": {"perception": ["BLIP2", "CLIP"], "generation": ["Stable Diffusion XL"], "execution": []}, "summary": "User provides interleaved image-text queries. BLIP2's vision encoder and Q-Former process images into the LLM's embedding space. LLaMA2-Chat generates text responses or text descriptions between special tokens (<start>, <end>) which are encoded by SDXL's text encoder to generate images. Generated images are fed back into the context for subsequent turns, creating a multi-turn interleaved multimodal conversation loop."}, {"id": "2024.acl-long.670", "title": "Agent Lumos: Unified and Modular Training for Open-Source Language Agents", "authors": ["Da Yin", "Faeze Brahman", "Abhilasha Ravichander", "Khyathi Chandu", "Kai-Wei Chang", "Yejin Choi", "Bill Yuchen Lin"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.670.pdf", "code": "https://github.com/allenai/lumos", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaMA-2-7B", "LLaMA-2-13B"], "non_llm_models": {"perception": ["LLaVA-1.5-7B"], "generation": [], "execution": ["Browser", "GPT-4", "GPT-3.5-turbo"]}, "summary": "User tasks are processed by the Planning Module (LLaMA-2) to generate high-level subgoals, which the Grounding Module (LLaMA-2) translates into executable actions. The Execution Module dispatches these actions to heterogeneous tools: LLaVA for visual question answering, Browser for web navigation, and GPT models for text QA. In the LUMOS-I formulation, execution results iteratively feed back to the Planning Module to enable adaptive task completion."}, {"id": "2024.acl-long.37", "title": "OPEx: A Component-Wise Analysis of LLM-Centric Agents in Embodied Instruction Following", "authors": ["Haochen Shi", "Zhiyuan Sun", "Xingdi Yuan", "Marc-Alexandre Côté", "Bang Liu"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.acl-long.37.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["UNet", "MaskRCNN", "ZoeDepth", "SOLQ"], "generation": [], "execution": []}, "summary": "Egocentric RGB is processed by perception models (UNet/MaskRCNN or ZoeDepth/SOLQ) to build 2D semantic maps. A GPT-3.5 Observer translates maps into text descriptions. A GPT-4 Planner decomposes instructions into subtasks, and a GPT-4 Executor selects predefined skills from a skill library. A deterministic action policy and FMM navigator convert selected skills into low-level actions; no learned policy is involved in execution."}, {"id": "2024.findings-acl.12", "title": "Text2DB: Integration-Aware Information Extraction with Large Language Model Agents", "authors": ["Yizhu Jiao", "Sha Li", "Sizhe Zhou", "Heng Ji", "Jiawei Han"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.12.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Named Entity Recognition", "Relation Extraction", "Attribute Extraction", "Text Classification", "GENRE"], "generation": [], "execution": ["Data Infilling", "Row Addition", "Column Addition", "Entity Linking", "Data Normalization"]}, "summary": "The Observer analyzes the database schema and provides few-shot demonstrations to the Planner. The Planner generates Python code calling IE tools (NER, RE, etc.) to extract information from documents. The Analyzer verifies the code through syntax checking and simulated test cases, providing feedback for iterative refinement. Finally, the code is executed to update the database with extracted values."}, {"id": "2024.findings-acl.39", "title": "Large Language Models can Share Images, Too!", "authors": ["Young-Jun Lee", "Dokyong Lee", "Joo Won Sung", "Jonghwan Hyeon", "Ho-Jin Choi"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.39.pdf", "code": "https://github.com/passing2961/DribeR", "pattern": "LLM + Perception + Generation", "domain": "Retrieval_Augmented", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4", "ChatGPT", "LLaMA 2 Chat", "Vicuna", "Falcon"], "non_llm_models": {"perception": ["CLIP"], "generation": ["Stable Diffusion"], "execution": []}, "summary": "The pipeline processes dialogue context through three sequential stages: (1) an LLM decides whether to share an image and identifies the intent/trigger sentence; (2) the LLM generates a descriptive image caption; (3) CLIP retrieves the most relevant image from a database using the caption as a query. For dataset augmentation, Stable Diffusion generates new images from the LLM-produced descriptions."}, {"id": "2024.findings-acl.767", "title": "Selective “Selective Prediction”: Reducing Unnecessary Abstention in Vision-Language Reasoning", "authors": ["Tejas Srinivasan", "Jack Hessel", "Tanmay Gupta", "Bill Yuchen Lin", "Yejin Choi", "Jesse Thomason", "Khyathi Chandu"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.767.pdf", "code": "https://github.com/tejas1995/ReCoVERR", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Coordinator", "Reasoner"], "llm_models": ["GPT-3.5", "Mistral-7B-Instruct", "Tulu-2-7B"], "non_llm_models": {"perception": ["BLIP2", "InstructBLIP", "LLaVA-1.5", "LVIS", "Qwen-VL"], "generation": [], "execution": []}, "summary": "Given an image and question, a VLM generates an initial answer with confidence. If confidence is below threshold, an LLM generates sub-questions to verify the hypothesis. The VLM answers these sub-questions, and high-confidence, relevant evidences are selected using an NLI model to check entailment. If sufficient evidence confirms the hypothesis, the system outputs the answer; otherwise, it iterates up to N times or abstains."}, {"id": "2024.findings-acl.240", "title": "Autonomous Workflow for Multimodal Fine-Grained Training Assistants Towards Mixed Reality", "authors": ["Jiahuan Pei", "Irene Viola", "Haochen Huang", "Junxiao Wang", "Moonisa Ahsan", "Fanghua Ye", "Jiang Yiming", "Yao Sai", "Di Wang", "Zhumin Chen", "Pengjie Ren", "Pablo Cesar"], "venue": "ACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-acl.240.pdf", "code": "https://github.com/xverse-ai/XVERSE-7B", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["MiniGPT-v2"], "generation": [], "execution": ["MR functional tools (StartAssemble, NextStep, APICallObjectRecognitionAR, APICallCheckStepStatusAR, etc.)"]}, "summary": "User queries from the MR environment are received by the Cerebral Language Agent (GPT-3.5-turbo with memory), which plans and reasons over the instruction manual context. When visual understanding is needed, it invokes the Vision-Language Agent (MiniGPT-v2) to process AR video streams, returning symbolic metadata (bounding boxes, assembly status). The LLM then generates natural language responses or dispatches execution commands to MR tools to manipulate the environment (e.g., highlighting components, advancing assembly steps)."}, {"id": "2025.findings-acl.1191", "title": "M2PA: A Multi-Memory Planning Agent for Open Worlds Inspired by Cognitive Theory", "authors": ["YanfangZhou YanfangZhou", "Xiaodong Li", "Yuntao Liu", "Yongqiang Zhao", "Xintong Wang", "Zhenyu Li", "Jinlong Tian", "Xinhai Xu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1191.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator", "Verifier"], "llm_models": ["GPT-4o", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["MineClip", "text-embedding-ada-002"], "generation": [], "execution": ["Controller"]}, "summary": "Working memory retrieves relevant experiences from episodic memory (vector database) using text-embedding-ada-002, combines them with MineClip-encoded visual observations (sensory memory) and task instructions to construct prompts for the LLM (semantic memory) to generate hierarchical plans. The Controller executes high-level actions in Minecraft, while the Reflector monitors execution and provides feedback for closed-loop replanning and dynamic memory updates."}, {"id": "2025.acl-long.600", "title": "Enhancing Interpretable Image Classification Through LLM Agents and Conditional Concept Bottleneck Models", "authors": ["Yiwen Jiang", "Deval Mehta", "Wei Feng", "Zongyuan Ge"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.600.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "GPT-4-turbo"], "non_llm_models": {"perception": ["CLIP ViT-B/32"], "generation": [], "execution": []}, "summary": "GPT-4o generates initial concept candidates based on class names. CoCoBMs (built on CLIP) computes category-specific concept scores on few-shot validation instances. The Agent analyzes these activation patterns to identify redundant or insufficient concepts, then iteratively refines the concept bank through a planning-action loop. Finally, CoCoBMs is trained with an LLM-verified editable matrix that suppresses factually incorrect concept activations to produce interpretable classifications."}, {"id": "2025.findings-acl.466", "title": "AgentStore: Scalable Integration of Heterogeneous Agents As Specialized Generalist Computer Assistant", "authors": ["Chengyou Jia", "Minnan Luo", "Zhuohang Dang", "Qiushi Sun", "Fangzhi Xu", "Junlin Hu", "Tianbao Xie", "Zhiyong Wu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.466.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["InternVL2-8B"], "non_llm_models": {"perception": ["Grounding models (for GUI element detection)"], "generation": [], "execution": ["SheetAgent", "WebAgent", "SlideAgent", "MailAgent", "Image Agent", "MMAgent", "FridayAgent", "APPAgent"]}, "summary": "User task and current OS state are processed by MetaAgent (InternVL2-8B), which predicts specialized AgentTokens to route the task to the most suitable agent(s) from the AgentPool. For simple tasks, the selected agent executes GUI/CLI operations directly. For complex tasks requiring collaboration, MetaAgent switches to Manager mode, decomposes the task into subtasks, and coordinates sequential execution among multiple specialized agents via message passing until the task is completed."}, {"id": "2025.findings-acl.1100", "title": "Query-Driven Multimodal GraphRAG: Dynamic Local Knowledge Graph Construction for Online Reasoning", "authors": ["Chenyang Bu", "Guojie Chang", "Zihao Chen", "CunYuan Dang", "Zhize Wu", "Yi He", "Xindong Wu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1100.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen 2.5 72B"], "non_llm_models": {"perception": ["CLIP", "BERT", "BGE-M3", "LLaVA 34B", "Gemini-1.5-flash"], "generation": [], "execution": []}, "summary": "The pipeline begins with Qwen constructing a Pattern Graph (G1) from the query. Perception models (CLIP, BERT, BGE-M3) perform multimodal retrieval to create a Retrieval Graph (G2). Dual-path entity retrieval and visual evidence integration using LLaVA/Gemini refine this into a Clue Graph (G3). An iterative Evaluate-Augment-Expand loop (using LLM verification for sufficiency) refines G3 into an Evidence Graph (G4), which Qwen reasons over to generate the final text answer."}, {"id": "2025.findings-acl.1158", "title": "GUI Agents: A Survey", "authors": ["Dang Nguyen", "Jian Chen", "Yu Wang", "Gang Wu", "Namyong Park", "Zhengmian Hu", "Hanjia Lyu", "Junda Wu", "Ryan Aponte", "Yu Xia", "Xintong Li", "Jing Shi", "Hongjie Chen", "Viet Dac Lai", "Zhouhang Xie", "Sungchul Kim", "Ruiyi Zhang", "Tong Yu", "Mehrab Tanjim", "Nesreen K. Ahmed", "Puneet Mathur", "Seunghyun Yoon", "Lina Yao", "Branislav Kveton", "Jihyung Kil", "Thien Huu Nguyen", "Trung Bui", "Tianyi Zhou", "Ryan A. Rossi", "Franck Dernoncourt"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1158.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Verifier"], "llm_models": ["GPT-4V", "Qwen-VL", "LLaVA-NEXT", "CogAgent"], "non_llm_models": {"perception": ["OmniParser", "UGround", "OS-Atlas", "SeeClick", "ShowUI", "Falcon-UI", "PIX2STRUCT", "HTML-T5", "accessibility APIs"], "generation": [], "execution": ["AutoGLM", "low-level GUI controllers", "browser automation tools"]}, "summary": "The user provides a task instruction to the LLM/VLM orchestrator, which plans the approach. Perception modules (OmniParser, UGround, etc.) parse the current GUI screenshot to identify interactive elements and their coordinates. The LLM reasons over this structured perception output to generate specific action commands (e.g., click at x,y or type text). Execution modules carry out these actions in the environment, and the resulting new screenshot is fed back to the perception module to continue the iterative interaction loop until task completion."}, {"id": "2025.acl-short.41", "title": "Fast or Slow? Integrating Fast Intuition and Deliberate Thinking for Enhancing Visual Question Answering", "authors": ["Songtao Jiang", "Chenyi Zhou", "Yan Zhang", "Yeying Jin", "Zuozhu Liu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-short.41.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["LLaVA-1.5", "MiniGPT4-V2", "InstructBLIP", "GPT-4V", "Gemini Pro", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["Grounded-SAM"], "generation": [], "execution": []}, "summary": "The MLLM first evaluates question complexity using self-consistency to determine the reasoning strategy. For simple questions, it performs zero-shot reasoning directly. For complex questions, GPT-3.5 extracts key textual elements, Grounded-SAM generates segmentation masks highlighting these critical visual regions, and the MLLM performs final reasoning over the refined image to generate the text answer."}, {"id": "2025.findings-acl.994", "title": "UnrealLLM: Towards Highly Controllable and Interactable 3D Scene Generation by LLM-powered Procedural Content Generation", "authors": ["SongTang SongTang", "Kaiyong Zhao", "Lei Wang", "Yuliang Li", "Xuebo Liu", "Junyi Zou", "Qiang Wang", "Xiaowen Chu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.994.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude 3.5 Sonnet", "GPT-3.5", "o1", "o1-mini"], "non_llm_models": {"perception": ["CLIP (ViT-L/14, ViT-B/16, ViT-B/32)", "Multi-modal LLM (for asset annotation)"], "generation": ["Unreal Engine 5 PCG system"], "execution": []}, "summary": "User queries are processed by a Scene Analyst agent to create structured specifications. The Asset Manager uses CLIP and a Multi-modal LLM to retrieve relevant 3D assets from a multi-modal library, while Node Expert and Pattern Expert agents retrieve technical PCG knowledge via RAG. The Blueprint Generator (GPT-4o/Claude 3.5) integrates these inputs through an iterative refinement loop to construct a text-based PCG blueprint representation, which is converted to executable Unreal Engine 5 blueprints to generate interactive 3D scenes."}, {"id": "2025.acl-long.385", "title": "VQAGuider: Guiding Multimodal Large Language Models to Answer Complex Video Questions", "authors": ["Yuyan Chen", "Jiyuan Jia", "Jiaxin Lu", "Siyue Li", "Yu Guan", "Ming Yang", "Qingpei Guo"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.385.pdf", "code": "https://github.com/Yukyin/VQAGuider", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o", "VideoChat2", "LLaVA OneVision"], "non_llm_models": {"perception": ["VideoObjectDetection", "VideoObjectTracking", "VideoActionRecognition", "VideoFaceDetection", "VideoClassification", "VideoSegmentation", "VideoCaptioning", "VideoSummarization", "VideoKeyFrameCapturing"], "generation": [], "execution": []}, "summary": "The user provides a video and question to the MLLM orchestrator (e.g., VideoChat2, GPT-4o), which recognizes required atomic tasks and matches them to VideoAPIs from a library. The MLLM plans an execution path (sequential or parallel) for these perception APIs. The VideoAPIs process the video and return structured outputs (e.g., object locations, actions), which GPT-4o converts to natural language. Finally, the MLLM aggregates these results and generates the final text answer."}, {"id": "2025.acl-short.6", "title": "Doc-React: Multi-page Heterogeneous Document Question-answering", "authors": ["Junda Wu", "Yu Xia", "Tong Yu", "Xiang Chen", "Sai Sree Harsha", "Akash V Maharaj", "Ruiyi Zhang", "Victor Bursztyn", "Sungchul Kim", "Ryan A. Rossi", "Julian McAuley", "Yunyao Li", "Ritwik Sinha"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-short.6.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["ColPali", "VisRAG-Ret", "InternVL", "MiniCPM"], "generation": [], "execution": []}, "summary": "User query and multi-page documents are processed iteratively: GPT-4o formulates sub-queries and identifies information gaps; ColPali/VisRAG-Ret retrieve relevant pages; InternVL/MiniCPM extract visual information; GPT-4o evaluates residual uncertainty and information gain (using InfoNCE-guided retrieval and entropy metrics), iterating until the final text answer is generated."}, {"id": "2025.acl-long.663", "title": "ReflecTool: Towards Reflection-Aware Tool-Augmented Clinical Agents", "authors": ["Yusheng Liao", "Shuyang Jiang", "Yanfeng Wang", "Yu Wang"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.663.pdf", "code": "https://github.com/BlueZeros/ReflecTool", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Reflector"], "llm_models": ["Qwen2-7B", "Qwen2-72B"], "non_llm_models": {"perception": ["MiniCPM-V-2.6", "InternVL-Chat-V1.5", "HuatuoGPT-Vision", "NER models"], "generation": [], "execution": []}, "summary": "ReflecTool uses an LLM to orchestrate a clinical toolbox of 15 tools. Learned perception modules—including medical VLMs and NER models—process medical images and clinical text. Deterministic tools such as MedRAG, LongDocRAG, UMLS, Bing Search, calculators, a code interpreter, and DBManual provide knowledge retrieval, database access, and calculation. The agent retrieves similar successful trajectories from long-term memory via BM25 to guide tool selection, and a verifier improves tool usage through iterative refinement or candidate selection based on accumulated tool-wise experience."}, {"id": "2025.findings-acl.1169", "title": "Metagent-P: A Neuro-Symbolic Planning Agent with Metacognition for Open Worlds", "authors": ["YanfangZhou YanfangZhou", "Yuntao Liu", "Xiaodong Li", "Yongqiang Zhao", "Xintong Wang", "Jinlong Tian", "Zhenyu Li", "Xinhai Xu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1169.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4-turbo"], "non_llm_models": {"perception": ["MineClip", "text-embedding-ada-002"], "generation": [], "execution": ["MP5 Controller"]}, "summary": "Task input is processed by the Experience-Enhanced Planner (GPT-4) which retrieves multimodal memories encoded via MineClip and text-embedding-ada-002. The Symbolic Reasoning-Driven Verifier checks action feasibility using neuro-symbolic rules before the MP5 Controller executes actions in Minecraft. The Metacognitive Reflector monitors execution, evaluates plans with quantitative confidence scoring, and iteratively feeds back to the Planner for adaptation when anomalies are detected."}, {"id": "2025.acl-long.374", "title": "Evaluation Agent: Efficient and Promptable Evaluation Framework for Visual Generative Models", "authors": ["Fan Zhang", "Shulin Tian", "Ziqi Huang", "Yu Qiao", "Ziwei Liu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.374.pdf", "code": "https://github.com/Vchitect/Evaluation-Agent", "pattern": "LLM + Perception + Generation", "domain": "Benchmark_Evaluation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["VLM (Vision-Language Model)"], "generation": ["Stable Diffusion", "VideoCrafter", "Latte", "ModelScope"], "execution": []}, "summary": "User queries are processed by the Plan Agent (GPT-4) which decomposes evaluation into sub-aspects. The PromptGen Agent generates tailored prompts for visual generative models (SD, VideoCrafter, etc.) to produce samples. An Evaluation Toolkit using VLM performs VQA-based assessment on the generated content, feeding results back to the Plan Agent for iterative refinement across multiple rounds before generating a final detailed analysis."}, {"id": "2025.acl-industry.86", "title": "SingaKids: A Multilingual Multimodal Dialogic Tutor for Language Learning", "authors": ["Zhengyuan Liu", "Geyu Lin", "Hui Li Tan", "Huayun Zhang", "Yanfeng Lu", "Xiaoxue Gao", "Stella Xin Yin", "Sun He", "Hock Huan Goh", "Lung Hsiang Wong", "Nancy F. Chen"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-industry.86.pdf", "code": "https://github.com/huggingface/transformers", "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Qwen1.5-4B"], "non_llm_models": {"perception": ["Whisper-large-V3", "InternVL2.5", "SAM (Segment Anything)", "object detection model", "depth estimation model"], "generation": ["VITS"], "execution": []}, "summary": "Student speech is converted to text by Whisper-large-V3 (ASR), while the input image is processed by InternVL2.5, SAM, object detection, and depth estimation models to extract visual context. Qwen1.5-4B (LLM) acts as the central hub, reasoning over both modalities to generate pedagogical scaffolding and dialogue responses. The text output is then synthesized into speech by VITS (TTS) to complete the interactive tutoring loop."}, {"id": "2025.acl-long.620", "title": "A Unified Agentic Framework for Evaluating Conditional Image Generation", "authors": ["Jifang Wang", "Yangxue Yangxue", "Longyue Wang", "Zhenran Xu", "Yiyu Wang", "Yaowei Wang", "Weihua Luo", "Kaifu Zhang", "Baotian Hu", "Min Zhang"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.620.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Benchmark_Evaluation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o", "Qwen2.5-VL", "Qwen2-VL"], "non_llm_models": {"perception": ["GroundingDINO"], "generation": [], "execution": []}, "summary": "Input (instruction, generated image, conditions) is processed by the LMM which decomposes the evaluation into fine-grained sub-tasks (e.g., background preservation, subject fidelity). The LMM dynamically selects tools from a toolbox (GroundingDINO for localization, Difference for pixel comparison, Highlight for region emphasis) to extract specific observations. The LMM then analyzes these tool outputs to assign sub-scores, which are aggregated via a min operation to produce the final evaluation score and rationale."}, {"id": "2025.acl-long.282", "title": "GUI-explorer: Autonomous Exploration and Mining of Transition-aware Knowledge for GUI Agent", "authors": ["Bin Xie", "Rui Shao", "Gongwei Chen", "Kaiwen Zhou", "Yinchuan Li", "Jie Liu", "Min Zhang", "Liqiang Nie"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.282.pdf", "code": "https://github.com/JiuTian-VL/GUI-explorer", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o", "Qwen2-VL-72B-Instruct-GPTQ-Int4", "Qwen2.5-VL-7B-Instruct"], "non_llm_models": {"perception": ["SigLIP (google/siglip-so400m-patch14-384)"], "generation": [], "execution": ["Android GUI automation controller/environment"]}, "summary": "During exploration, the MLLM generates function-aware goals from structural anchors to guide DFS traversal, collecting trajectories from which transition-aware knowledge (visual patches + operation logic) is extracted and embedded by SigLIP into a vector store. During execution, the MLLM retrieves relevant knowledge via visual-semantic matching, ranks entries via pairwise comparison, and generates GUI actions with dynamic guidance to suppress UI misinterpretation."}, {"id": "2025.findings-acl.1152", "title": "Aria-UI: Visual Grounding for GUI Instructions", "authors": ["Yuhao Yang", "Yue Wang", "Dongxu Li", "Ziyang Luo", "Bei Chen", "Chao Huang", "Junnan Li"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1152.pdf", "code": "https://github.com/AriaUI/Aria-UI", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Aria-UI", "Aria (MoE)", "Qwen2-VL-72B"], "generation": [], "execution": ["GUI automation environment"]}, "summary": "GPT-4o generates stepwise instructions based on the user task and current state. Aria-UI processes the GUI screenshot along with the instruction and action history to predict target element coordinates. These coordinates are then used to execute actions (click, type, scroll) in the web, mobile, or desktop environment to complete the task."}, {"id": "2025.findings-acl.523", "title": "Bayesian Optimization for Controlled Image Editing via LLMs", "authors": ["Chengkun Cai", "Haoliang Liu", "Xu Zhao", "Zhongyu Jiang", "Tianfang Zhang", "Zongkai Wu", "John Lee", "Jenq-Neng Hwang", "Lei Li"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.523.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude 3.5"], "non_llm_models": {"perception": ["CLIP"], "generation": ["Stable Diffusion", "Instruct Pix2Pix"], "execution": []}, "summary": "User provides an image and text editing instruction. The multimodal LLM generates a detailed prompt for the diffusion model. The diffusion model (Stable Diffusion/Instruct Pix2Pix) generates an edited image using current CFG parameters. The LLM and CLIP evaluate the image quality and alignment, producing a score. Bayesian Optimization uses this score to update the CFG parameters (image_cfg_scale and text_cfg_scale), and the process iterates until convergence or maximum iterations."}, {"id": "2025.acl-industry.75", "title": "sudo rm -rf agentic_security", "authors": ["Sejin Lee", "Jian Kim", "Haon Park", "Ashkan Yousefpour", "Sangyoon Yu", "Min Song"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-industry.75.pdf", "code": "https://github.com/AIM-Intelligence/SUDO", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Claude 3.5 Vision", "Claude 3.7 Vision", "Gemini 2.0 Flash", "Llama 3.2 Vision", "GPT-4.5", "o1", "OmniParser V2"], "generation": [], "execution": ["Claude for Computer Use", "MANUS", "OmniParser V2"]}, "summary": "A malicious task first passes through a Detoxifier (GPT-4o) to mask harmful intent, then to a VLM Instruction Generator that creates step-by-step plans based on visual screenshots, followed by a Toxifier (GPT-4o) that reintroduces malicious payloads. The target computer-use agent executes the transformed commands in a live environment, and a checklist-based evaluator assesses success, feeding results back to a Dynamic Updater (GPT-4o) that iteratively refines the attack prompt until successful or a limit is reached."}, {"id": "2025.findings-acl.1113", "title": "CRAB: Cross-environment Agent Benchmark for Multimodal Language Model Agents", "authors": ["Tianqi Xu", "Linyao Chen", "Dai-Jie Wu", "Yanjun Chen", "Zecheng Zhang", "Xiang Yao", "Zhiqiang Xie", "Yongchao Chen", "Shilong Liu", "Bochen Qian", "Anjie Yang", "Zhaoxuan Jin", "Jianbo Deng", "Philip Torr", "Bernard Ghanem", "Guohao Li"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1113.pdf", "code": "https://github.com/JaidedAI/EasyOCR", "pattern": "LLM + Perception + Action", "domain": "Benchmark_Evaluation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "GPT-4 Turbo", "Claude 3 Opus", "Gemini 1.5 Pro", "Pixtral-12B", "LLaVA-OneVision-72B"], "non_llm_models": {"perception": ["GroundingDINO", "EasyOCR"], "generation": [], "execution": ["Android Environment Controller", "Ubuntu Environment Controller"]}, "summary": "The agent receives screenshots from Android/Ubuntu environments, which are processed by GroundingDINO and EasyOCR to detect interactive elements using Set-of-Marks prompting. The multimodal LLM observes the annotated screenshot, plans the next action, and generates structured function calls (click, type, etc.). Actions are executed in the environments, and a Graph Evaluator tracks subtask completion status iteratively until task completion or step limit."}, {"id": "2025.acl-long.449", "title": "The Male CEO and the Female Assistant: Evaluation and Mitigation of Gender Biases in Text-To-Image Generation of Dual Subjects", "authors": ["Yixin Wan", "Kai-Wei Chang"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.449.pdf", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4 Vision (gpt-4-vision-preview)"], "non_llm_models": {"perception": [], "generation": ["DALLE-3", "Stable Diffusion 2"], "execution": []}, "summary": "User provides a text prompt for dual-subject image generation. A T2I model (DALLE-3 or Stable Diffusion) generates the initial image. GPT-4 Vision evaluates the generated image for gender bias using visual reasoning. If bias is detected, the LLM provides adaptive feedback (additional guidelines) to augment the generation context, and the T2I model regenerates the image. This iterative loop continues until fairness is achieved."}, {"id": "2025.acl-long.1511", "title": "CityNavAgent: Aerial Vision-and-Language Navigation with Hierarchical Semantic Planning and Global Memory", "authors": ["Weichen Zhang", "Chen Gao", "Shiquan Yu", "Ruiying Peng", "Baining Zhao", "Qian Zhang", "Jinqiang Cui", "Xinlei Chen", "Yong Li"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.1511.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4V", "GPT-3.5"], "non_llm_models": {"perception": ["GroundingDINO", "SAM"], "generation": [], "execution": []}, "summary": "The open-vocabulary perception module processes panoramic RGB-D observations: GroundingDINO detects objects, SAM generates masks, and a deterministic geometric projector builds a 3D semantic point cloud. The hierarchical semantic planning module uses an LLM (GPT-4V/GPT-3.5) to decompose instructions into landmark sequences, reason about object regions of interest, and compute next waypoints by averaging point-cloud coordinates. A global memory module stores historical trajectories as a topological graph and uses deterministic graph search to assist motion planning. The system outputs low-level actions via deterministic path decomposition, with no learned action policy involved."}, {"id": "2025.acl-long.643", "title": "Cultivating Gaming Sense for Yourself: Making VLMs Gaming Experts", "authors": ["Wenxuan Lu", "Jiangyang He", "Zhanqiu Zhang", "Steven Y. Guo", "Tianning Zang"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.acl-long.643.pdf", "code": "https://github.com/ipsss2/GameSense", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Tight", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["Qwen 2.5 VL"], "non_llm_models": {"perception": ["Grounding DINO", "ResNet50", "CNN"], "generation": [], "execution": ["RL-based GSMs (PPO/SAC policies)"]}, "summary": "Qwen 2.5 VL analyzes real-time game screens and plans high-level tasks. It uses learned perception models (Grounding DINO, ResNet50, CNN) to extract game states. For high-speed interactions, it invokes Game Sense Modules: learned RL-based GSMs (PPO/SAC policies) for adaptive tasks like boss fights, and deterministic rule-based GSMs for rapid-response tasks like FPS shooting. The VLM continuously refines both types of GSMs based on execution feedback and training analysis across iterative optimization cycles."}, {"id": "2025.findings-acl.1226", "title": "PodAgent: A Comprehensive Framework for Podcast Generation", "authors": ["Yujia Xiao", "Lei He", "Haohan Guo", "Feng-Long Xie", "Tan Lee"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.1226.pdf", "code": "https://github.com/yujxx/PodAgent", "pattern": "LLM + Generation", "domain": "Audio_Speech", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": [], "generation": ["CosyVoice", "Bark", "TTA models"], "execution": []}, "summary": "The pipeline begins with a GPT-4 Host-Agent generating guest profiles and an interview outline from a user topic. GPT-4 Guest-Agents then generate expert responses in parallel, which a GPT-4 Writer-Agent compiles into a cohesive conversation script. A GPT-4 Matching-Agent selects appropriate voices from a pre-analyzed voice pool. Finally, TTS models (CosyVoice/Bark) synthesize expressive speech using LLM-predicted style instructions, while TTA models generate sound effects and music for final assembly."}, {"id": "2025.findings-acl.559", "title": "Self-play through Computational Runtimes improves Chart Reasoning", "authors": ["Tautvydas Misiūnas", "Hassan Mansoor", "Jasper Uijlings", "Oriana Riva", "Victor Carbune"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.559.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Gemini 1.5 Flash", "GPT-4o"], "non_llm_models": {"perception": ["PaliGemma-3B"], "generation": [], "execution": ["Python runtime executor"]}, "summary": "Chart image and question are processed by a VLM (Gemini or GPT-4o) which generates Python code decomposing the reasoning task. The code executes in a Python runtime, calling an Image.answer() API that routes to either the VLM itself or a fine-tuned PaliGemma-3B for visual sub-tasks. Arithmetic and logic operations are performed within the code to produce the final answer. During training, the system iteratively refines few-shot examples based on execution correctness against training labels."}, {"id": "2025.findings-acl.341", "title": "RATE-Nav: Region-Aware Termination Enhancement for Zero-shot Object Navigation with Vision-Language Models", "authors": ["Junjie Li", "Nan Zhang", "Xiaoyang Qu", "Kai Lu", "Guokuan Li", "Jiguang Wan", "Jianzong Wang"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.341.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Reasoner", "Verifier"], "llm_models": ["Qwen-vl-max", "Llama-Vision"], "non_llm_models": {"perception": ["YOLO-World", "GLIP", "ConceptGraphs"], "generation": [], "execution": []}, "summary": "RGB-D observations are processed by YOLO-World, GLIP, and ConceptGraphs to build a semantic map. A deterministic geometric region segmentation module (watershed-based) partitions the map, and exploration rates are estimated via Bresenham ray tracing. When the rate exceeds a threshold, key frames are sent to the VLM (Qwen-vl-max or Llama-Vision) for macro-perception and termination assessment. If the VLM judges the target unlikely, the region is deprioritized; otherwise, frontier-based exploration selects target points and the Fast Marching Method executes low-level navigation."}, {"id": "2025.findings-acl.348", "title": "OS-Kairos: Adaptive Interaction for MLLM-Powered GUI Agents", "authors": ["Pengzhou Cheng", "Zheng Wu", "Zongru Wu", "Tianjie Ju", "Aston Zhang", "Zhuosheng Zhang", "Gongshen Liu"], "venue": "ACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-acl.348.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator"], "llm_models": ["GPT-4o", "OS-Atlas-Pro-7B", "OS-Kairos", "Qwen2-VL-7B"], "non_llm_models": {"perception": ["ResNet18", "ConvNeXt-Tiny", "Layout parsing models"], "generation": [], "execution": ["GUI action execution environment (mobile device control)"]}, "summary": "During inference, the system captures a screenshot and uses layout parsing models (ResNet18, ConvNeXt-Tiny) to extract structured UI elements. OS-Kairos (fine-tuned MLLM) processes this visual and textual context to predict both the next action and a confidence score. If the confidence score exceeds threshold γ, the action is executed on the mobile GUI; otherwise, human intervention is requested. This iterative loop continues until task completion. During training, a collaborative probing framework uses GPT-4o as a critic to annotate confidence scores on trajectories generated by the probing agent."}, {"id": "5651a0a840db", "title": "Let's ViCE! Mimicking Human Cognitive Behavior in Image Generation Evaluation", "authors": ["Federico Betti 0001", "Jacopo Staiano", "Lorenzo Baraldi 0002", "Lorenzo Baraldi 0001", "Rita Cucchiara", "Nicu Sebe"], "venue": "ACMMM", "year": 2023, "url": "https://doi.org/10.1145/3581783.3612706", "code": null, "pattern": "LLM + Perception", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["BLIP2 (VQA)"], "generation": [], "execution": []}, "summary": "GPT-3.5-turbo first extracts visual concepts from the input prompt and generates initial 'blind' questions. BLIP2 analyzes the generated image and answers these questions. The LLM then evaluates the answers, and if needed, initiates an iterative refinement cycle by generating follow-up questions for BLIP2. Once satisfied, the LLM computes a final evaluation score based on the accumulated Q&A history and visual concepts."}, {"id": "3882c611b280", "title": "CT2C-QA: Multimodal Question Answering over Chinese Text, Table and Chart", "authors": ["Bowen Zhao", "Tianhao Cheng", "Yuejie Zhang", "Ying Cheng 0005", "Rui Feng 0001", "Xiaobo Zhang"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681053", "code": null, "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Coordinator"], "llm_models": ["GPT-4-0125-preview", "GPT-3.5-turbo-0125"], "non_llm_models": {"perception": ["PaddleOCR", "text-embedding-3-large", "GPT-4-vision-preview"], "generation": [], "execution": []}, "summary": "The Allocating Agent (GPT-4) analyzes the query and webpage to assign modality probabilities and activate relevant Expert Agents (Text, Table, Chart). The Chart Expert uses PaddleOCR and embeddings to retrieve relevant charts, while Text and Table Experts process their respective modalities using GPT-3.5. Finally, the Decision Agent (GPT-4) synthesizes all expert outputs to generate the final answer."}, {"id": "2ca5f0b9f266", "title": "Few-Shot Multimodal Explanation for Visual Question Answering", "authors": ["Dizhan Xue", "Shengsheng Qian", "Changsheng Xu"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681597", "code": "https://github.com/LivXue/FS-MEVQA", "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5"], "non_llm_models": {"perception": ["OWL-ViT"], "generation": [], "execution": ["Image croppers", "Customized Python functions"]}, "summary": "GPT-3.5 generates a multimodal program based on the input question and few-shot examples. The program is executed by open-world tools including OWL-ViT (for object detection), image croppers, and Python functions to infer the answer. GPT-3.5 then translates the execution trace into a natural language explanation with [BOX] tokens. A rethinking mechanism identifies missing visual objects, triggering additional detection iterations to complete the multimodal explanation."}, {"id": "b143bbc4fd52", "title": "De-fine: Decomposing and Refining Visual Programs with Auto-Feedback", "authors": ["Minghe Gao", "Juncheng Li 0006", "Hao Fei 0001", "Liang Pang 0001", "Wei Ji 0008", "Guoming Wang", "Zheqi Lv", "Wenqiao Zhang", "Siliang Tang", "Yueting Zhuang"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681082", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5-Turbo", "LLaMA-7B"], "non_llm_models": {"perception": ["mPLUG-Owl"], "generation": [], "execution": []}, "summary": "GPT-3.5-Turbo generates an executable Python program from a visual query using an abstract logical prompt. The program is executed by a Python interpreter. During execution, intermediate image patches are sent to mPLUG-Owl for visual feedback, while intermediate text variables are processed by LLaMA-7B for textual feedback; static analysis and compiler messages provide compile feedback. GPT-3.5-Turbo then refines the program iteratively based on this aggregated feedback."}, {"id": "755f6c990dfa", "title": "Exploring the Robustness of Decision-Level Through Adversarial Attacks on LLM-Based Embodied Models", "authors": ["Shuyuan Liu", "Jiawei Chen", "Shouwei Ruan", "Hang Su 0006", "Zhaoxia Yin"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3680616", "code": null, "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["TaPA", "Otter", "Llama-2-7b-chat"], "non_llm_models": {"perception": ["Open vocabulary object detector", "Mask RCNN", "CLIP", "BLIP2"], "generation": [], "execution": []}, "summary": "Scene images are processed by open-vocabulary object detectors to extract symbolic object lists. These lists, along with task prompts and optimized adversarial suffixes, are fed to an LLM (TaPA/Otter/Llama-2) to generate step-by-step task plans. The output is sliced into individual steps, and BLIP2 calculates similarity with target tasks to evaluate attack success, with iterative refinement of the adversarial suffix until convergence."}, {"id": "1da5c9b9b68a", "title": "OpenLEAF: A Novel Benchmark for Open-Domain Interleaved Image-Text Generation", "authors": ["Jie An 0002", "Zhengyuan Yang", "Linjie Li", "Jianfeng Wang", "Kevin Lin", "Zicheng Liu 0001", "Lijuan Wang", "Jiebo Luo 0001"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3685511", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": [], "generation": ["DALL-E 3", "Stable Diffusion XL (SDXL)"], "execution": []}, "summary": "The system receives user queries and optional multimodal context. GPT-4V generates the interleaved text narrative, determines image insertion points, and creates text-to-image prompts enriched with global entity and style contexts. These prompts are sequentially fed to either DALL-E 3 or SDXL to generate images, which are then combined with the text to produce the final interleaved image-text sequence."}, {"id": "77bfac7fc372", "title": "GPT4Video: A Unified Multimodal Large Language Model for lnstruction-Followed Understanding and Safety-Aware Generation", "authors": ["Zhanyu Wang", "Longyue Wang", "Zhen Zhao 0001", "Minghao Wu", "Chenyang Lyu", "Huayang Li", "Deng Cai 0002", "Luping Zhou", "Shuming Shi 0001", "Zhaopeng Tu"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681464", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["LLaMA-7B"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "Video Abstractor (dual-attention transformer)"], "generation": ["ZeroScope", "VideoCrafter", "Stable Diffusion", "Make-A-Video", "Text2Video-Zero", "Tune-A-Video"], "execution": []}, "summary": "Video frames are encoded by CLIP ViT-L/14, compressed by the Video Abstractor using dual-attention tokens, and projected into LLaMA-7B's embedding space. The LLM performs video understanding (QA/captioning) or generates textual prompts with trigger tags to orchestrate external Text-to-Video models (ZeroScope, VideoCrafter, etc.) for video generation. A safety detection model filters harmful inputs before processing."}, {"id": "da45735e925e", "title": "An Entailment Tree Generation Approach for Multimodal Multi-Hop Question Answering with Mixture-of-Experts and Iterative Feedback Mechanism", "authors": ["Qing Zhang", "Haocheng Lv", "Jie Liu 0022", "Zhiyun Chen", "Jianyong Duan", "Hao Wang 0018", "Li He", "Mingying Xu"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681479", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5"], "non_llm_models": {"perception": ["LLaVA-1.5", "CLIP", "BERT"], "generation": [], "execution": []}, "summary": "GPT-3.5 decomposes multi-hop questions and retrieves evidence using BERT. LLaVA-1.5 (with CLIP features) extracts visual facts from images based on atomic sub-questions. GPT-3.5 generates an initial entailment tree from the constructed fact base. The tree and question are processed by a shared T5 encoder, routed through task-specific and shared Mixture-of-Experts (MoE) FFN layers, and decoded by separate FRG and QA decoders to produce retrieved facts and answers. These outputs are fed back to GPT-3.5 to iteratively refine the entailment tree."}, {"id": "4adaabfbd60d", "title": "AdaCoder: Adaptive Prompt Compression for Programmatic Visual Question Answering", "authors": ["Mahiro Ukai", "Shuhei Kurita", "Atsushi Hashimoto 0001", "Yoshitaka Ushiku", "Nakamasa Inoue"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681010", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-3.5-turbo", "Claude-3-haiku"], "non_llm_models": {"perception": ["Object detection models (via ViperGPT APIs)", "CLIP-based models (via ViperGPT APIs)"], "generation": [], "execution": ["Python execution engine"]}, "summary": "Given an image and question, the LLM first classifies the question type to select an adaptively compressed preprompt containing relevant API definitions and code snippets. The LLM then generates a Python program using this compressed prompt. The Python execution engine runs the generated code, which dynamically calls vision APIs (object detection, CLIP-based models) to process the image and derive the final answer."}, {"id": "4aff1c9872d9", "title": "GG-Editor: Locally Editing 3D Avatars with Multimodal Large Language Model Guidance", "authors": ["Yunqiu Xu", "Linchao Zhu", "Yi Yang 0001"], "venue": "ACMMM", "year": 2024, "url": "https://doi.org/10.1145/3664647.3681039", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion v1.5", "DMTet", "PBR Material Model"], "execution": []}, "summary": "Given a source avatar and text prompts, GPT-4V first analyzes rendered views through a coarse-to-fine pipeline (view selection → grid selection → iterative bounding box refinement) to mine 3D editing regions. These regions constrain a geometry-appearance decoupled optimization where DMTet edits geometry and the PBR model edits appearance, both guided by Stable Diffusion SDS/ODS losses. GPT-4V additionally generates local prompts to coordinate global-local view synergy during optimization, producing the final edited 3D avatar."}, {"id": "5cddd38e4198", "title": "Multi-Agent System for Comprehensive Soccer Understanding", "authors": ["Jiayuan Rao", "Zifeng Li", "Haoning Wu 0002", "Ya Zhang 0002", "Yanfeng Wang 0001", "Weidi Xie"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755144", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["DeepSeek-v3"], "non_llm_models": {"perception": ["Qwen2.5-VL-7B", "CLIP", "GroundingDINO", "Face Recognition framework", "UniSoccer Action Classifier", "UniSoccer Commentary Generation", "Camera Detection", "Jersey Number Recognition", "Score/Time Recognition", "Replay Grounding", "Jersey Color Recognition", "Foul Recognition"], "generation": [], "execution": []}, "summary": "User submits a multimodal soccer question to DeepSeek-v3 (A_plan), which decomposes the task and plans a chain of specialized tools. DeepSeek-v3 (A_exec) iteratively invokes perception tools (CLIP for frame selection, GroundingDINO for localization, Qwen2.5-VL for visual understanding, UniSoccer for action classification and commentary generation, Face Recognition for player identification) and retrieval tools (SoccerWiki knowledge base). Outputs are accumulated in execution history and aggregated by DeepSeek-v3 to generate the final answer, with dynamic error correction when tools fail."}, {"id": "126386591810", "title": "Twin Co-Adaptive Dialogue for Progressive Image Generation", "authors": ["Jianhui Wang", "Yangfan He", "Yan Zhong 0001", "Xinyuan Song 0002", "Jiayi Su", "Yuheng Feng", "Ruoyu Wang", "Hongyang He", "Wenyu Zhu", "Xinhang Yuan", "Miao Zhang 0010", "Keqin Li", "Jiaqi Chen", "Tianyu Shi 0003", "Xueqian Wang 0001"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755141", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Qwen-VL (7B)", "CLIP"], "generation": ["Stable Diffusion v1.4"], "execution": []}, "summary": "User dialogue history and input are processed by GPT-4 to generate a refined prompt P(t), which conditions Stable Diffusion to produce image I(t). Qwen-VL generates semantic captions from I(t), and CLIP computes an ambiguity score between P(t) and captions. If ambiguity exceeds a threshold, GPT-4 generates clarification questions for the user (Explicit Pathway) or Attend-and-Excite refinement is applied (Implicit Pathway), iterating until alignment converges."}, {"id": "13cf2a755144", "title": "EMO-Avatar: An LLM-Agent-Orchestrated Framework for Multimodal Emotional Support in Human Animation", "authors": ["Keqi Chen", "Wenxin Fu", "Qihang Lu", "Zekai Sun", "Yizhong Geng", "Yi Liu", "Puyuan Guo", "Yingming Gao", "Ya Li 0001"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3762030", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Deepseek-671B"], "non_llm_models": {"perception": ["Qwen2.5-Omni"], "generation": ["OrpheusTTS", "LatentSync"], "execution": []}, "summary": "User video/audio is processed by Qwen2.5-Omni for ASR and affective captioning. Deepseek-671B performs emotional reasoning using Hill's helping-skills theory, generating text responses and multimodal instructions. These instructions guide OrpheusTTS to synthesize expressive speech and trigger video-RAG retrieval of reference clips, which LatentSync uses with the audio to generate lip-synced avatar videos."}, {"id": "0838cd0d79e8", "title": "Learning to Be a Doctor: Searching for Effective Medical Agent Architectures", "authors": ["Yangyang Zhuang", "Wenjia Jiang", "Jiayu Zhang", "Ze Yang 0002", "Joey Tianyi Zhou", "Chi Zhang 0007"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755559", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet", "GPT-4o-mini"], "non_llm_models": {"perception": ["CLIP (ViT-L/14)"], "generation": [], "execution": []}, "summary": "Input medical images are processed by a CLIP-based tool node to retrieve similar cases from a Pinecone vector database. LLM basic nodes within a dynamically evolved graph workflow (featuring conditional branches, parallel execution, and loops) perform diagnostic reasoning over the image and retrieved cases. The system iteratively refines the workflow structure and prompts based on error analysis until diagnostic accuracy converges, outputting ranked disease diagnoses."}, {"id": "17e78baac4d6", "title": "The Eye of Sherlock Holmes: Uncovering User Private Attribute Profiling via Vision-Language Model Agentic Framework", "authors": ["Feiran Liu", "Yuzhe Zhang", "Xinyi Huang", "Yinan Peng", "Xinfeng Li", "Lixu Wang", "Yutong Shen", "Ranjie Duan", "Simeng Qin", "Xiaojun Jia", "Qingsong Wen", "Wei Dong 0007"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755643", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Claude-3.7-Sonnet", "Gemini-2.0-Pro", "Llama-3.1-405B", "QwQ-32B", "Llama-13B"], "non_llm_models": {"perception": ["GPT-4o", "Claude-3.7-Sonnet", "Gemini-2.0-Pro", "Llama-3.1-405B", "QwQ-32B", "Llama-13B"], "generation": [], "execution": []}, "summary": "Personal image collections are first processed by VLM agents to extract intra-image details from individual photos and inter-image relationships from groups of three images. The LLM agent then summarizes these findings to infer initial attributes, identifies any missing information, and generates targeted inquiries. The VLM performs re-extraction based on these inquiries, and the LLM makes the final attribute profiling decision based on all accumulated evidence."}, {"id": "4c70b091f5f8", "title": "I2CR: Intra- and Inter-modal Collaborative Reflections for Multimodal Entity Linking", "authors": ["Ziyan Liu", "Junwen Li", "Kaiwen Li", "Tong Ruan", "Chao Wang 0095", "Xinyan He", "Zongyu Wang", "Xuezhi Cao", "Jingping Liu"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755674", "code": "https://github.com/ziyan-xiaoyu/I2CR", "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Llama3-8B"], "non_llm_models": {"perception": ["CLIP (CLIP-ViT-bigG-14)", "SFR-Embedding-Mistral", "OCR (Azure Cognitive Services)", "Image Captioning (Azure Cognitive Services)", "Dense Captioning (Azure Cognitive Services)", "Image Tagging (Azure Cognitive Services)"], "generation": [], "execution": []}, "summary": "The pipeline takes a mention with text and image context, uses Llama3-8B to select a candidate entity from the knowledge graph, then verifies the selection using SFR-Embedding-Mistral for intra-modal text consistency and CLIP for image-text alignment. If verification fails, Azure image-to-text models extract diverse visual clues (OCR, captions, tags, dense captions) in iterative rounds, feeding these back to the LLM for re-selection until the correct entity is identified or maximum iterations are reached."}, {"id": "c082791d3414", "title": "MMPro: A Decoupled Perception-Thinking-Execution Framework for Secure GUI Agent", "authors": ["Benlong Wu", "Yuang Qi", "Xiuwei Shang", "Weiming Zhang 0001", "Nenghai Yu", "Kejiang Chen"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755553", "code": "https://github.com/Dizzy-K/MMPro", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Deepseek-reasoner", "DeepSeek-R1"], "non_llm_models": {"perception": ["Qwen2-VL"], "generation": [], "execution": ["Qwen2-VL"]}, "summary": "MMPro is a training-free, decoupled framework. A local Qwen2-VL perception module fuses GUI screenshots with the accessibility tree to generate a structured Hybrid Description Language (HDL). The cloud-based Deepseek-reasoner reasons over HDL to decompose tasks and plan steps. A local Qwen2-VL execution module then converts the plan and current GUI state into atomic PyAutoGUI commands, which are deterministically executed. The agent loops through perception, thinking, and execution with local reflection until task completion or failure."}, {"id": "a11f73b8b183", "title": "UAV-ON: A Benchmark for Open-World Object Goal Navigation with Aerial Agents", "authors": ["Jianqiang Xiao", "Yuexuan Sun", "Yixin Shao", "Boxi Gan", "Rongqiang Liu", "Yanjin Wu", "Weili Guan", "Xiang Deng 0002"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3758251", "code": "https://github.com/Kyaren/UAV_ON", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Converge", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o mini"], "non_llm_models": {"perception": ["Qwen-VL", "Depth processing module (min pooling)"], "generation": [], "execution": ["AirSim UAV controller"]}, "summary": "Multi-view RGB observations are processed by Qwen-VL to generate textual captions, while depth images are compressed into 3×3 matrices via min pooling. These perception outputs, combined with pose history and target semantics, are aggregated into a structured prompt for GPT-4o mini, which reasons over the inputs and generates semantic navigation actions with continuous magnitudes (e.g., 'move forward 3 units') that are executed by the UAV controller in the simulator."}, {"id": "784a6da28503", "title": "OpenMap: Instruction Grounding via Open-Vocabulary Visual-Language Mapping", "authors": ["Danyang Li", "Zenghui Yang", "Guangpeng Qi", "Songtao Pang", "Guangyong Shang", "Qiang Ma 0007", "Zheng Yang 0002"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3754887", "code": "https://github.com/openmap-project/OpenMap", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["CLIP ViT-H", "CropFormer", "OVSAM", "GroundingDINO"], "generation": [], "execution": []}, "summary": "RGB-D observations are processed by CropFormer for 2D segmentation and CLIP/OVSAM for feature extraction. The Structural-Semantic Consensus Mapping module aggregates these into a 3D instance-level semantic map (OpenMap). For instruction grounding, GPT-4 first parses the natural language instruction into a target description to retrieve candidate instances from OpenMap, then performs a second reasoning step over the candidates' spatial context to select the final grounded target instance."}, {"id": "439f9647d2c9", "title": "AudioGenie: A Training-Free Multi-Agent Framework for Diverse Multimodality-to-Multiaudio Generation", "authors": ["Yan Rong", "Jinting Wang", "Guangzhi Lei", "Shan Yang 0001", "Li Liu 0036"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755758", "code": "https://github.com/ryysayhi/AudioGenie", "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5-VL-72B-Instruct"], "non_llm_models": {"perception": ["Audio-Reasoner"], "generation": ["MMAudio", "Auffusion", "CosyVoice 2", "FireRedTTS", "InspireMusic", "MusicGen", "DiffRhythm", "AudioSR", "AudioSep"], "execution": []}, "summary": "Multimodal inputs (video/image/text) are processed by Qwen2.5-VL-72B-Instruct to decompose audio requirements into structured JSON events. Domain-specific experts dynamically select suitable generation models from a tool library containing specialized audio generators (TTS, music, sound effects). A supervisor team monitors each stage, and a trial-and-error iterative refinement module constructs a tree-of-thought for each audio event, enabling self-correction and retry with alternative models until satisfactory audio is produced and mixed."}, {"id": "7cff810deeb7", "title": "GraphVideoAgent: Enhancing Long-form Video Understanding with Entity Relation Graphs", "authors": ["Meng Chu", "Yicong Li 0004", "Tat-Seng Chua"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755537", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "Llama3-70B", "Mistral-8x7B"], "non_llm_models": {"perception": ["EVA-CLIP-8B-plus", "LaViLa", "VLM", "CLIP"], "generation": [], "execution": []}, "summary": "GraphVideoAgent processes long videos by first sampling frames and using VLM/LaViLa to generate captions, which populate a dynamic entity-relation graph tracking entities and their temporal interactions. A GPT-4 agent performs multi-round reasoning over this graph with self-reflection on confidence. When confidence is low, CLIP retrieves additional frames to refine the graph iteratively until the LLM achieves sufficient confidence to generate the final text answer."}, {"id": "b5165168ba48", "title": "From Outline to Detail: An Hierarchical End-to-end Framework for Coherent and Consistent Visual Novel Generation and Assembly", "authors": ["Yilin Zhang 0012", "Yanyan Wei", "Zhao Zhang 0001", "Jicong Fan 0001", "Haijun Zhang 0002", "Shuicheng Yan"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755541", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["DeepSeek-R1", "DeepSeek-V3", "Qwen-2.5-72B-Instruct"], "non_llm_models": {"perception": ["Qwen2.5-VL-72B-Instruct", "RMBG (segmentation model)"], "generation": ["Stable Diffusion XL", "Stable Audio"], "execution": []}, "summary": "User theme → DeepSeek-R1 (outline generation) → DeepSeek-V3 (structuring) → Autoregressive plot/script generation (DeepSeek-R1) → Qwen-2.5 (SD prompt generation) → SDXL (image generation) with Qwen2.5-VL self-correction loop and RMBG background removal → DeepSeek-V3 (audio prompt generation) → Stable Audio (audio generation) → Ren'Py assembly with lint validation and LLM-based error correction."}, {"id": "e2ee56c0e76d", "title": "VL-DynaRefine: A Vision-Language Dynamic Refinement Approach for Visual Reasoning", "authors": ["Jing Ma", "Haochen Sun", "Zeyuan Zang", "Fangxiang Feng", "Caixia Yuan", "Lei Ren", "Huixing Jiang", "Wei Chen", "Xiaojie Wang 0006"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755296", "code": "https://github.com/jinaicode/DynaRefine", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["GLIP", "MiDaS"], "generation": [], "execution": []}, "summary": "The planner (GPT-4o) decomposes queries into programmatic action sequences. Actions are executed sequentially via a Python engine calling GLIP for localization or MiDaS for depth. The verifier checks confidence scores and consistency in real-time. Failed actions trigger the refiner module, which performs context-aware local refinement (using multimodal context) or global refinement (using action/visual trajectories) through iterative loops, ultimately producing text answers or bounding boxes."}, {"id": "755fdcb1565c", "title": "AeroDuo: Aerial Duo for UAV-based Vision and Language Navigation", "authors": ["Ruipu Wu", "Yige Zhang", "Jinyu Chen", "Linjiang Huang", "Shifeng Zhang", "Xu Zhou", "Liang Wang 0001", "Si Liu 0001"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3754498", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2-VL"], "non_llm_models": {"perception": ["GroundingDINO"], "generation": [], "execution": ["PPO-based Navigator"]}, "summary": "AeroDuo uses a high-altitude Pilot-LLM (based on Qwen2-VL) to process stitched orthophoto maps, historical trajectories, and language instructions, predicting target probability maps and global depth. The low-altitude UAV computes the probability map centroid and uses an A* planner for waypoint generation, a PPO-trained RL Navigator for collision-free velocity control, and GroundingDINO for target detection; the process iterates until the target is found."}, {"id": "68f111a4d437", "title": "CogDDN: A Cognitive Demand-Driven Navigation with Decision Optimization and Dual-Process Thinking", "authors": ["Yuehao Huang", "Liang Liu 0007", "Shuangming Lei", "Yukai Ma", "Hao Su", "Jianbiao Mei", "Pengxiang Zhao", "Yaqing Gu", "Yong Liu 0007", "Jiajun Lv"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755832", "code": "https://github.com/yuehaohuang/CogDDN", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Reflector", "Coordinator"], "llm_models": ["Qwen2-VL-7B", "GPT-4"], "non_llm_models": {"perception": ["UniMODE"], "generation": [], "execution": ["AI2Thor simulator action controller"]}, "summary": "UniMODE performs 3D object detection from egocentric visual input. Qwen2-VL-7B matches detected objects with human demands to identify targets. The Dual-Process Decision Module then operates: the Heuristic Process (fine-tuned Qwen2-VL) generates rapid navigation actions using Chain-of-Thought reasoning, while the Analytic Process (GPT-4) is invoked upon failures to reflect on errors and update a knowledge base, enabling continuous learning and iterative improvement of navigation strategies in the AI2Thor environment."}, {"id": "a8fc017c3032", "title": "Building Embodied EvoAgent: A Brain-inspired Paradigm for Bridging Multimodal Large Models and World Models", "authors": ["Junyu Gao 0002", "Xuan Yao 0001", "Yong Rui", "Changsheng Xu"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3754880", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["InternVL2.5", "Qwen2.5-VL", "Vicuna"], "non_llm_models": {"perception": ["ViT"], "generation": [], "execution": ["RSSM", "World Model policy network"]}, "summary": "Visual observations are processed by ViT and fed into EC-MLLM (InternVL/Qwen-VL) along with language instructions to generate semantic embeddings. These embeddings pass through Dynamic Communication Slots (CL2W) to PC-WM (RSSM), which maintains latent state dynamics and predicts actions. The WM feeds latent context back to the MLLM via CW2L slots for context-enhanced perception, forming an iterative loop with online slot evolution during task execution."}, {"id": "254f157fd92a", "title": "FineQuest: Adaptive Knowledge-Assisted Sports Video Understanding via Agent-of-Thoughts Reasoning", "authors": ["Haodong Chen", "Haojian Huang", "Xinxiang Yin", "Dian Shao"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3754885", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Verifier"], "llm_models": ["Vicuna-7B", "Video-LLaVA", "LLaVA-Next-Video"], "non_llm_models": {"perception": ["SAM 2", "Long-CLIP", "CLIP-ViT-L-336px", "LanguageBind"], "generation": [], "execution": []}, "summary": "The reactive agent (MLLM) assesses query complexity and either answers simple queries directly or activates deliberative mode. In deliberative mode, SAM 2 segments motion, Key Clip Selector (using VLM) identifies relevant clips via contrastive decoding, VLM generates captions, Fine-grained Matcher (using Long-CLIP and SSGraph) retrieves domain-specific terminology, and LLM (Vicuna) reasons to produce the final answer."}, {"id": "565e73776567", "title": "Human Motion Generation in 3D Scenes from Open-Ended Textual Instructions with MLLM Planning", "authors": ["Siyi Qian", "Jian Fang", "Yuzhou Mao", "Yayun Zou", "Wentao Zhang 0001", "Haiwei Xue"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3754850", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o", "Gemini-2.5-pro"], "non_llm_models": {"perception": ["Scene Encoder", "CLIP-ViT-B/32"], "generation": ["Diffusion model", "SMPL-X"], "execution": ["RRT* path planning tool"]}, "summary": "The MLLM receives open-ended text and a top-view scene map, parses the instruction to plan motion steps and identify start/end positions, calls RRT* for fine-grained trajectory planning, and retrieves relevant motion priors via CLIP. A diffusion model then generates the final human motion sequence conditioned on the planned trajectory constraints, scene features from the Scene Encoder, and retrieved motion-text features, outputting SMPL-X parameterized motions."}, {"id": "ec3fca278028", "title": "HEAR: A Holistic Extraction and Agentic Reasoning Framework for Document Understanding", "authors": ["Longfeng Chen", "Zheng Xiao", "Juyuan Wang", "Zeyu Huang", "Yawen Zeng", "Jin Xu 0014"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3761999", "code": "https://github.com/py-pdf/pypdf", "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5-VL-32B-Instruct", "Qwen2.5-32B-Instruct"], "non_llm_models": {"perception": ["MinerU", "gte-Qwen2-7B-instruct", "colqwen2.5-3b-multilingual-v1.0", "PyPDF2", "BM25"], "generation": [], "execution": []}, "summary": "Raw PDFs are first processed by MinerU and PyPDF2 to extract layout and raw text, then Qwen2.5-VL-32B-Instruct reconciles these into a structured corpus with HTML tables and correct reading order. Multimodal retrieval (dense, sparse, visual) identifies relevant evidence pages. The Coordinator Agent dispatches focused evidence to the Textual Agent (Qwen2.5-32B) and Visual Agent (Qwen2.5-VL-32B) for parallel reasoning. The agents cross-verify their findings, and if contradictions arise, the system iteratively re-queries the corpus with refined sub-queries before the Coordinator synthesizes the final answer."}, {"id": "4e852cf5ae29", "title": "Can I Trust You? Advancing GUI Task Automation with Action Trust Score", "authors": ["Haiyang Mei", "Difei Gao", "Xiaopeng Wei", "Xin Yang 0011", "Mike Zheng Shou"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755618", "code": "https://github.com/showlab/TrustScorer", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier"], "llm_models": ["GPT-4", "GPT-4V", "LLaMA-3", "LLaVA-NeXT"], "non_llm_models": {"perception": ["YOLO-v8", "SAM (LangSAM)", "Google OCR"], "generation": [], "execution": []}, "summary": "GUI screenshots are parsed by perception models (YOLO-v8, LangSAM, Google OCR) into textual representations. An Actor LLM generates action sequences, and a TrustScorer (prompted LLM/VLM or a learned DeBERTa-v3 cross-encoder) predicts a trust score. If the score exceeds θ, the deterministic PyAutoGUI library executes the actions; otherwise, the system requests human intervention."}, {"id": "03a40d2285d2", "title": "Queryable 3D Scene Representation: A Multi-Modal Framework for Semantic Reasoning and Robotic Task Planning", "authors": ["Xun Li 0004", "Rodrigo Santa Cruz", "Mingze Xi", "Hu Zhang 0005", "Madhawa Perera", "Ziwei Wang 0003", "Ahalya Ravendran", "Brandon J. Matthews", "Feng Xu", "Matt Adcock", "Dadong Wang", "Jiajun Liu"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3758177", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "LLama3-8B"], "non_llm_models": {"perception": ["Panoptic Lifting", "Mask2Former", "CLIP", "Molmo-7B-D", "LERF", "DINO", "OpenSeg", "BAAI/bge-large-en-v1.5", "DBSCAN"], "generation": [], "execution": ["Unity AI Navigation", "Stretch 3 robot"]}, "summary": "RGB video is processed by Panoptic Lifting and Mask2Former for 3D reconstruction and panoptic segmentation, generating NeRF representations and segmented point clouds. LLama3-8B creates multi-view captions and constructs a 3D scene graph with object relationships. For user queries, GPT-4o orchestrates retrieval from point clouds (using CLIP), NeRF (using LERF), or scene graphs (using RAG with BGE embeddings). Retrieved object locations and attributes are fed to a robotic task planner, which generates navigation commands executed by the Stretch 3 robot in Unity, with iterative plan refinement via a Critic Agent."}, {"id": "da4f0e9da161", "title": "ScreenSpot-Pro: GUI Grounding for Professional High-Resolution Computer Use", "authors": ["Kaixin Li", "Ziyang Meng", "Hongzhan Lin 0001", "Ziyang Luo", "Yuchen Tian", "Jing Ma 0004", "Zhiyong Huang 0010", "Tat-Seng Chua"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3755688", "code": "https://github.com/likaixin2000/ScreenSpot-Pro-GUI-Grounding", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["OS-Atlas-7B", "UGround-7B", "AriaUI", "ShowUI", "CogAgent", "Qwen2-VL-7B", "MiniCPM-V-8B", "SeeClick-7B"], "generation": [], "execution": []}, "summary": "ScreenSeekeR takes a user instruction and high-resolution screenshot. GPT-4o performs position inference to predict candidate regions and neighboring UI elements. A GUI grounding model (e.g., OS-Atlas-7B) predicts bounding boxes for these candidates, which are then scored and filtered via NMS. The system recursively searches the top-scoring sub-images, with GPT-4o verifying results, until the target bounding box is found."}, {"id": "be4cb0f45d38", "title": "Agent-to-Agent (A2A) Protocol Integrated Digital Twin System with AgentIQ for Multimodal AI Fitness Coaching and Personalized Well-Being", "authors": ["Kamran Gholizadeh HamlAbadi", "Monica (Monireh) Vahdati", "Fedwa Laamarti", "Abdulmotaleb El Saddik"], "venue": "ACMMM", "year": 2025, "url": "https://doi.org/10.1145/3746027.3758176", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Other", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4", "Gemini", "LLaMA-4", "DeepSeek", "Groq"], "non_llm_models": {"perception": ["OpenPose", "Whisper", "openSMILE", "IoT wearables (E4 Watch)"], "generation": ["Audio2Face", "TTS (Text-to-Speech)", "NVIDIA Omniverse"], "execution": []}, "summary": "Multimodal inputs (video, audio, text, wearables) are processed by perception models (OpenPose, Whisper, openSMILE) to extract features, which are stored in hierarchical memory (STM/LTM). The Orchestration Agent infers intent and plans tasks, delegating via the A2A protocol to specialized agents (Recommendation, Nutrition, Embodied Feedback). These agents invoke tools through MCP (various LLMs, databases). Finally, the Synthesis layer generates multimodal feedback: text summaries, voice via TTS, and expressive XR avatars via Audio2Face and Omniverse."}, {"id": "7913cb04ca5c", "title": "Towards Autonomous Tool Utilization in Language Models: A Unified, Efficient and Scalable Framework", "authors": ["Zhi Li", "Yicheng Li 0005", "Hequan Ye", "Yin Zhang 0006"], "venue": "COLING", "year": 2024, "url": "https://aclanthology.org/2024.lrec-main.1427", "code": "https://github.com/facebookresearch/MaskFormer", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Coordinator"], "llm_models": ["Alpaca", "Vicuna", "Llama2Chat", "GPT-3.5", "GPT-4"], "non_llm_models": {"perception": ["BLIP", "DETR", "MaskFormer"], "generation": ["Stable Diffusion", "ControlNet"], "execution": []}, "summary": "The fine-tuned Alpaca LLM treats tool use as a sequential decision-making problem, autoregressively generating whether to invoke a tool, which tool to select, and the API call arguments. For multimodal queries, the execution environment routes calls to learned perception models (BLIP, DETR, MaskFormer) or generation models (Stable Diffusion, ControlNet); for other queries it calls deterministic external APIs (Wolfram Alpha, Bing Search, weather, stock, map, arXiv). The tool output is returned to the LLM, which synthesizes the final response."}, {"id": "70faa6c0c636", "title": "FineRAG: Fine-grained Retrieval-Augmented Text-to-Image Generation", "authors": ["Huaying Yuan", "Ziliang Zhao 0001", "Shuting Wang 0002", "Shitao Xiao", "Minheng Ni", "Zheng Liu 0011", "Zhicheng Dou"], "venue": "COLING", "year": 2025, "url": "https://aclanthology.org/2025.coling-main.741/", "code": "https://github.com/LAION-AI/aesthetic-predictor", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator", "Translator"], "llm_models": ["GPT-4o mini"], "non_llm_models": {"perception": ["CLIP", "BLIP"], "generation": ["GLIGEN (layout-guided Stable Diffusion)"], "execution": []}, "summary": "User text prompt is processed by GPT-4o mini to decompose into atomic search queries and generate a spatial layout. CLIP retrieves candidate images from an external corpus, which are then reranked by BLIP and filtered by GPT-4o mini to select optimal references. GLIGEN generates an initial image conditioned on the text, layout, and retrieved image embeddings. Finally, GPT-4o mini reflects on the output quality, iterating with revised queries if necessary until satisfactory."}, {"id": "abc9f99a3145", "title": "LAW: Legal Agentic Workflows for Custody and Fund Services Contracts", "authors": ["William Watson", "Nicole Cho", "Nishan Srishankar", "Zhen Zeng", "Lucas Cecchi", "Daniel Scott", "Suchetha Siddagangappa", "Rachneet Kaur", "Tucker Balch", "Manuela Veloso"], "venue": "COLING", "year": 2025, "url": "https://aclanthology.org/2025.coling-industry.50/", "code": "https://github.com/rapidfuzz/RapidFuzz", "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["RoBERTa (span detection)", "T5-large (section classification)", "T5-base (title generation)"], "generation": [], "execution": []}, "summary": "User queries are processed by a Code Generation Agent (GPT-3.5-turbo) that generates Python code to orchestrate domain-specific perception tools: RoBERTa extracts dates, T5 models classify/generate section titles, and fuzzy matching extracts parties. Retrieved information is processed by text agents (Summary, Comparison) using the same LLM. A validation framework checks generated code with iterative feedback loops for error correction, producing final text outputs (retrieval results, summaries, or comparisons)."}, {"id": "8961076c2563", "title": "Idea23D: Collaborative LMM Agents Enable 3D Model Generation from Interleaved Multimodal Inputs", "authors": ["Junhao Chen", "Xiang Li 0205", "Xiaojun Ye 0002", "Chao Li", "Zhaoxin Fan", "Hao Zhao 0002"], "venue": "COLING", "year": 2025, "url": "https://aclanthology.org/2025.coling-main.280/", "code": "https://github.com/yisuanwang/Idea23D", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4V", "GPT-4o", "InternVL", "LLaVA", "LLaVA-CoT"], "non_llm_models": {"perception": [], "generation": ["FLUX", "SDXL", "DALLE", "InstantMesh", "Hunyuan3D", "zero123"], "execution": []}, "summary": "The pipeline takes a multimodal IDEA (text, images, 3D models) as input. LMM Agent 1 perceives the input (rendering 3D models to multiview images) and generates N text prompts. Text-to-Image models generate images, which are processed by Image-to-3D models to create draft 3D models. LMM Agent 5 evaluates the drafts via multiview rendering and selects the best candidate. If refinement is needed, LMM Agent 6 generates textual feedback, which is stored in memory and used by Agent 1 to generate revised prompts, creating an iterative refinement loop until the 3D model aligns with the IDEA."}, {"id": "78f9a486daf1", "title": "AutoProteinEngine: A Large Language Model Driven Agent Framework for Multimodal AutoML in Protein Engineering", "authors": ["Yungeng Liu", "Zan Chen", "Yuguang Wang", "Yiqing Shen 0003"], "venue": "COLING", "year": 2025, "url": "https://aclanthology.org/2025.coling-industry.36/", "code": "https://github.com/tsynbio/AutoPE", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Sequential", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["TourSynbio-7B"], "non_llm_models": {"perception": ["ESM series", "AlphaFold series"], "generation": [], "execution": []}, "summary": "AutoPE uses TourSynbio-7B to orchestrate a multimodal AutoML pipeline: the LLM validates natural language tasks, retrieves data from PDB/UniProt via generated queries, selects and configures ESM and AlphaFold models from predefined zoos, performs late fusion of sequence and graph embeddings, and manages hyperparameter optimization (TPE + ASHA via Ray.Tune) and training to produce property predictions with natural language interpretation."}, {"id": "f61d7f19fd5f", "title": "EffiQA: Efficient Question-Answering with Strategic Multi-Model Collaboration on Knowledge Graphs", "authors": ["Zixuan Dong", "Baoyun Peng", "Yufei Wang", "Jia Fu", "Xiaodong Wang", "Xin Zhou", "Yongxue Shan", "Kangchen Zhu", "Weiguo Chen"], "venue": "COLING", "year": 2025, "url": "https://aclanthology.org/2025.coling-main.479/", "code": null, "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "Llama3.1-8B", "Deepseek-V2"], "non_llm_models": {"perception": ["RoBERTa (fine-tuned for entity typing and semantic pruning)"], "generation": [], "execution": []}, "summary": "User question is processed by an LLM for global planning (decomposing into sub-questions and generating exploration instructions with simulated answers). A fine-tuned RoBERTa model then executes efficient KG exploration via semantic pruning and BFS guided by these instructions. The LLM performs self-reflection on the exploration results to verify paths and replan, iterating until a final answer is derived from validated paths."}, {"id": "1ba209BACA", "title": "Agent-DocEdit: Language-Instructed LLM Agent for Content-Rich Document Editing", "authors": ["Te-Lin Wu", "Rajiv Jain", "Yufan Zhou", "Puneet Mathur", "Vlad I Morariu"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=1ba209BACA", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["GLIP", "LLaVA", "PaddleOCR"], "generation": ["Stable Diffusion v1.5"], "execution": ["Document editing API executor"]}, "summary": "User edit request is processed by GPT-4 to generate a Python edit program using pre-defined APIs. GLIP grounds text phrases to document elements (bounding boxes), and PaddleOCR extracts layout information. The Executor runs the program to manipulate the document structure via APIs, calling Stable Diffusion for image generation when needed. LLaVA verifies the before/after results and provides feedback to GPT-4 for iterative program refinement."}, {"id": "NV8yRJRET1", "title": "DiagrammerGPT: Generating Open-Domain, Open-Platform Diagrams via LLM Planning", "authors": ["Abhay Zala", "Han Lin", "Jaemin Cho", "Mohit Bansal"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=NV8yRJRET1", "code": "https://github.com/aszala/DiagrammerGPT", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": [], "generation": ["DiagramGLIGEN", "Stable Diffusion v1.4"], "execution": []}, "summary": "GPT-4 planner generates an initial diagram plan (entities, relationships, 2D bounding boxes) from a text prompt. A GPT-4 auditor then provides corrective feedback on the plan, which the planner uses to iteratively refine the layout. The final plan is passed to DiagramGLIGEN (a layout-guided diffusion model built on Stable Diffusion) to generate the diagram image, followed by explicit rendering of text labels using Pillow."}, {"id": "otKo4zFKmH", "title": "Task Success is not Enough: Investigating the Use of Video-Language Models as Behavior Critics for Catching Undesirable Agent Behaviors", "authors": ["Lin Guan", "Yifan Zhou", "Denis Liu", "Yantian Zha", "Heni Ben Amor", "Subbarao Kambhampati"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=otKo4zFKmH", "code": "https://github.com/GuanSuns/VLMs-Behavior-Critic", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "Gemini Pro"], "non_llm_models": {"perception": ["GPT-4V", "SAM (Segment Anything)", "depth estimation models", "specialized vision grounding models"], "generation": [], "execution": ["robot control primitives"]}, "summary": "GPT-4 synthesizes a control program using Code-as-Policies, which the robot executes while recording video. GPT-4V analyzes the video to identify undesirable behaviors, which are then verified by specialized grounding modules (SAM, depth estimators). Verified critiques are fed back to GPT-4 to refine the policy, forming an iterative closed-loop system."}, {"id": "UPE6WYE8vg", "title": "A Language Agent for Autonomous Driving", "authors": ["Jiageng Mao", "Junjie Ye", "Yuxi Qian", "Marco Pavone", "Yue Wang"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=UPE6WYE8vg", "code": null, "pattern": "LLM + Perception", "domain": "Autonomous_Driving", "flow": "Star", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Reflector", "Coordinator"], "llm_models": ["GPT-3.5-turbo", "Llama-2-7B"], "non_llm_models": {"perception": ["Detection Module", "Prediction Module", "Occupancy Module", "Mapping Module"], "generation": [], "execution": []}, "summary": "Agent-Driver processes sensory inputs through frozen neural perception modules. An LLM orchestrator dynamically invokes these modules via a text-based tool library, queries cognitive memory for commonsense and past experiences, and performs chain-of-thought reasoning, task planning, and fine-tuned motion planning to generate driving trajectories, followed by deterministic collision-check self-reflection."}, {"id": "sKNIjS2brr", "title": "VideoDirectorGPT: Consistent Multi-Scene Video Generation via LLM-Guided Planning", "authors": ["Han Lin", "Abhay Zala", "Jaemin Cho", "Mohit Bansal"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=sKNIjS2brr", "code": "https://github.com/HL-hanlin/VideoDirectorGPT", "pattern": "LLM + Generation", "domain": "Video_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "LLaMA2-7B", "LLaMA2-13B"], "non_llm_models": {"perception": ["CLIP ViT-B/32"], "generation": ["ModelScopeT2V", "Layout2Vid", "unCLIP Prior", "Stable Diffusion"], "execution": []}, "summary": "The user provides a text prompt to GPT-4, which generates a multi-component video plan including scene descriptions, entity bounding box layouts, backgrounds, and consistency groupings. This structured plan is fed into Layout2Vid, which uses ModelScopeT2V with guided 2D attention mechanisms conditioned on entity embeddings (derived via CLIP and unCLIP Prior) to generate temporally consistent multi-scene videos."}, {"id": "6U1FEKP7Ar", "title": "ExoViP: Step-by-step Verification and Exploration with Exoskeleton Modules for Compositional Visual Reasoning", "authors": ["Yuxuan Wang", "Alan Yuille", "Zhuowan Li", "Zilong Zheng"], "venue": "COLM", "year": 2024, "url": "https://openreview.net/pdf?id=6U1FEKP7Ar", "code": "https://github.com/bigai-nlco/ExoViP", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT"], "non_llm_models": {"perception": ["CLIP", "BLIP", "object detectors", "VQA models", "Grounding models"], "generation": [], "execution": ["VISPROG modules", "ViperGPT components"]}, "summary": "GPT generates a visual reasoning program trace. Execution modules (VISPROG/ViperGPT) execute each step using perception models (CLIP, BLIP, detectors) to process visual inputs. Verification modules validate each step's output using an ensemble of sub-verifiers. A tree search algorithm iteratively explores alternative traces based on verification scores and LLM self-correction to select the optimal reasoning path and produce the final output."}, {"id": "7HPuAkgdVm", "title": "VisualTrap: A Stealthy Backdoor Attack on GUI Agents via Visual Grounding Manipulation", "authors": ["Ziang Ye", "Yang Zhang", "Wentao Shi", "Xiaoyu You", "Fuli Feng", "Tat-Seng Chua"], "venue": "COLM", "year": 2025, "url": "https://openreview.net/pdf?id=7HPuAkgdVm", "code": null, "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner"], "llm_models": ["GPT-4o", "Qwen2-VL-2B", "Qwen2-VL-7B", "Qwen2.5-VL", "LLaVA-NeXT"], "non_llm_models": {"perception": ["Qwen2-VL-2B", "Qwen2-VL-7B", "Qwen2.5-VL", "LLaVA-NeXT"], "generation": [], "execution": []}, "summary": "VisualTrap poisons the visual grounding pre-training of LVLMs by injecting stealthy trigger patches into GUI screenshots, causing the model to output trigger coordinates instead of the intended target locations. In downstream evaluation, the compromised LVLM serves either as an end-to-end orchestrator or as a separate grounding module paired with a GPT-4o planner in a modular architecture, with the final action executed via standard GUI environment interaction."}, {"id": "nSV8Depcpx", "title": "Plancraft: an evaluation dataset for planning with LLM agents", "authors": ["Gautier Dagan", "Frank Keller", "Alex Lascarides"], "venue": "COLM", "year": 2025, "url": "https://openreview.net/pdf?id=nSV8Depcpx", "code": "https://github.com/gautierdag/plancraft", "pattern": "LLM + Perception", "domain": "Gaming", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier"], "llm_models": ["Llama 3.1 8B", "Llama 3.1 70B", "GPT-4o-mini", "Gemma 3 12B", "Gemma 3 27B", "Qwen3 30B A3B", "Qwen 2.5 VL 72B"], "non_llm_models": {"perception": ["Faster R-CNN"], "generation": [], "execution": []}, "summary": "For multi-modal observations, a fine-tuned Faster R-CNN extracts item types, quantities, and slot positions from Minecraft GUI images and maps them to a symbolic text format. The LLM orchestrator receives the current inventory state and crafting goal, then plans and emits symbolic actions (move, smelt) or internal actions (think, search, impossible). These are executed in the deterministic Plancraft environment, which returns updated states or error messages, forming an iterative planning loop. A handcrafted DFS solver and exact-match retriever over the Minecraft Wiki are used as deterministic baselines and knowledge sources."}, {"id": "zg5is4GJ3R", "title": "Agent S2: A Compositional Generalist-Specialist Framework for Computer Use Agents", "authors": ["Saaket Agashe", "Kyle Wong", "Vincent Tu", "Jiachen Yang", "Ang Li", "Xin Eric Wang"], "venue": "COLM", "year": 2025, "url": "https://openreview.net/pdf?id=zg5is4GJ3R", "code": "https://github.com/simular-ai/Agent-S", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Reflector", "Coordinator"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet", "Claude-3.7-Sonnet"], "non_llm_models": {"perception": ["UI-TARS-72B-DPO"], "generation": [], "execution": []}, "summary": "Agent S2 uses a Manager LLM to decompose user instructions into subgoals and a Worker LLM to generate natural-language actions. The Worker routes grounding to specialist modules: UI-TARS-72B-DPO (learned visual grounding) predicts pixel coordinates, while Tesseract OCR and the UNO interface (deterministic tools) handle text-span and spreadsheet-cell localization. The Manager iteratively updates the plan after each subgoal based on environmental observations."}, {"id": "Gupta_Visual_Programming_Compositional_Visual_Reasoning_Without_Training", "title": "Visual Programming: Compositional Visual Reasoning Without Training", "authors": ["Tanmay Gupta", "Aniruddha Kembhavi"], "venue": "CVPR", "year": 2023, "url": "https://openaccess.thecvf.com/content/CVPR2023/papers/Gupta_Visual_Programming_Compositional_Visual_Reasoning_Without_Training_CVPR_2023_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-3"], "non_llm_models": {"perception": ["OWL-ViT", "DSFD", "MaskFormer", "CLIP", "ViLT"], "generation": ["Stable Diffusion"], "execution": []}, "summary": "GPT-3 generates a Python-like visual program from natural language instructions via in-context learning. A program interpreter executes this program sequentially, invoking specialized perception modules (for localization, detection, segmentation, and classification) and generation modules (Stable Diffusion for image editing) to produce intermediate outputs and final predictions (text or images), while aggregating step-wise visualizations into an interpretable rationale."}, {"id": "Cai_L-MAGIC_Language_Model_Assisted_Generation_of_Images_with_Coherence", "title": "L-MAGIC: Language Model Assisted Generation of Images with Coherence", "authors": ["zhipeng cai", "Matthias Mueller", "Reiner Birkl", "Diana Wofk", "Shao-Yen Tseng", "JunDa Cheng", "Gabriela Ben Melech Stan", "Vasudev Lal", "Michael Paulitsch"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Cai_L-MAGIC_Language_Model_Assisted_Generation_of_Images_with_Coherence_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Translator"], "llm_models": ["ChatGPT", "ChatGPT-4"], "non_llm_models": {"perception": ["BLIP-2", "Metric3D", "DPT-hybrid"], "generation": ["Stable Diffusion v2"], "execution": []}, "summary": "Input image is first captioned by BLIP-2. ChatGPT generates a global 360° layout (d360) and identifies objects requiring repetition avoidance (drepeat). The system iteratively warps existing views and inpaints novel views using Stable Diffusion guided by LLM-generated prompts. BLIP-2 verifies each inpainted view for duplicate objects, triggering re-inpainting if violations are detected. Finally, super-resolution and multi-view fusion produce the high-resolution panorama, with optional depth estimation enabling 3D point cloud generation."}, {"id": "Khan_Self-Training_Large_Language_Models_for_Improved_Visual_Program_Synthesis_With", "title": "Self-Training Large Language Models for Improved Visual Program Synthesis With Visual Reinforcement", "authors": ["Zaid Khan", "Vijay Kumar BG", "Samuel Schulter", "Yun Fu", "Manmohan Chandraker"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Khan_Self-Training_Large_Language_Models_for_Improved_Visual_Program_Synthesis_With_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["CodeLlama-7B", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["BLIP", "GroundingDINO", "ImagePatch API"], "generation": [], "execution": []}, "summary": "CodeLlama-7B receives an image and text query to synthesize a Python program using the ImagePatch API. The program is executed by calling perception models (BLIP for visual question answering, GroundingDINO for object detection) to extract information and compose answers. Execution results are compared to ground truth to generate binary rewards, which are used to fine-tune the LLM via REINFORCE policy gradient, improving its ability to write accurate visual programs."}, {"id": "Ge_Visual_Fact_Checker_Enabling_High-Fidelity_Detailed_Caption_Generation", "title": "Visual Fact Checker: Enabling High-Fidelity Detailed Caption Generation", "authors": ["Yunhao Ge", "Xiaohui Zeng", "Jacob Huffman", "Tsung-Yi Lin", "Ming-Yu Liu", "Yin Cui"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Ge_Visual_Fact_Checker_Enabling_High-Fidelity_Detailed_Caption_Generation_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4", "Llama-2"], "non_llm_models": {"perception": ["LLaVA-1.5", "Kosmos-2", "InstructBLIP", "Open-vocabulary object detection model", "VQA model (LLaVA-1.5)"], "generation": [], "execution": []}, "summary": "Input image is processed by multiple captioning models (LLaVA-1.5, Kosmos-2, InstructBLIP) to generate initial caption proposals. The LLM summarizes these proposals and creates a verification checklist. An open-vocabulary object detection model verifies object existence, and a VQA model verifies specific attributes. The LLM then synthesizes all results to generate a final high-fidelity caption, filtering out hallucinations based on the verification feedback."}, {"id": "Gao_AssistGUI_Task-Oriented_PC_Graphical_User_Interface_Automation", "title": "AssistGUI: Task-Oriented PC Graphical User Interface Automation", "authors": ["Difei Gao", "Lei Ji", "Zechen Bai", "Mingyu Ouyang", "Peiran Li", "Dongxing Mao", "Qin WU", "Weichen Zhang", "Peiyi Wang", "Xiangwu Guo", "Hengxu Wang", "Luowei Zhou", "Mike Zheng Shou"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Gao_AssistGUI_Task-Oriented_PC_Graphical_User_Interface_Automation_CVPR_2024_paper.pdf", "code": "https://github.com/showlab/assistgui", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Google OCR", "YOLO-v8", "SAM (LangSAM)"], "generation": [], "execution": []}, "summary": "AutoPC first decomposes a user query and instructional video into a hierarchical task tree via a Planner (GPT-4). For each subtask, a GUI Parser invokes learned perception models (Google OCR, YOLO-v8, LangSAM) to convert screenshots into structured textual GUI representations. A Critic (GPT-4) evaluates the previous action by comparing before/after GUI states using DeepDiff, and an Actor (GPT-4) generates PyAutoGUI code to deterministically control the mouse and keyboard, iterating until task completion."}, {"id": "Li_Driving_Everywhere_with_Large_Language_Model_Policy_Adaptation", "title": "Driving Everywhere with Large Language Model Policy Adaptation", "authors": ["Boyi Li", "Yue Wang", "Jiageng Mao", "Boris Ivanovic", "Sushant Veer", "Karen Leung", "Marco Pavone"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Li_Driving_Everywhere_with_Large_Language_Model_Policy_Adaptation_CVPR_2024_paper.pdf", "code": "https://github.com/Boyiliee/LLaDA-AV", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["GPT-4V"], "generation": [], "execution": ["GPT-Driver"]}, "summary": "Driving scenario inputs (images) are processed by GPT-4V to generate scene descriptions, while GPT-Driver generates a nominal trajectory plan. The Traffic Rule Extractor (TRE) uses GPT-4 to retrieve relevant traffic rules from the local driver handbook based on the current scenario. These components feed into the LLM Planner (GPT-4), which adapts the nominal plan to comply with local traffic rules, outputting adapted motion plan instructions that can be executed by GPT-Driver to generate new trajectories."}, {"id": "Shao_LMDrive_Closed-Loop_End-to-End_Driving_with_Large_Language_Models", "title": "LMDrive: Closed-Loop End-to-End Driving with Large Language Models", "authors": ["Hao Shao", "Yuxuan Hu", "Letian Wang", "Guanglu Song", "Steven L. Waslander", "Yu Liu", "Hongsheng Li"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Shao_LMDrive_Closed-Loop_End-to-End_Driving_with_Large_Language_Models_CVPR_2024_paper.pdf", "code": "https://github.com/opendilab/LMDrive", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Converge", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["LLaMA", "LLaMA2", "Vicuna", "Vicuna-v1.5", "LLaVA-v1.5"], "non_llm_models": {"perception": ["ResNet-50", "PointPillars", "BEV Decoder", "Q-Former"], "generation": [], "execution": ["PID Controllers"]}, "summary": "Multi-view camera and LiDAR data are encoded by ResNet-50 and PointPillars, fused by a BEV Decoder, and compressed by Q-Former into visual tokens. These tokens, along with tokenized natural language instructions, are processed by a frozen LLM with trainable adapters to predict future waypoints and instruction completion status. PID controllers then convert the predicted waypoints into vehicle control signals for closed-loop driving."}, {"id": "Min_MoReVQA_Exploring_Modular_Reasoning_Models_for_Video_Question_Answering", "title": "MoReVQA: Exploring Modular Reasoning Models for Video Question Answering", "authors": ["Juhong Min", "Shyamal Buch", "Arsha Nagrani", "Minsu Cho", "Cordelia Schmid"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Min_MoReVQA_Exploring_Modular_Reasoning_Models_for_Video_Question_Answering_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["PaLM-2"], "non_llm_models": {"perception": ["PALI-3", "OWL-ViT", "CLIP"], "generation": [], "execution": []}, "summary": "Input video and question are processed by PaLM-2 in three stages: (1) Event Parsing decomposes the question into events and temporal relations; (2) Grounding uses OWL-ViT and CLIP to localize relevant video frames and verify events, storing results in external memory; (3) Reasoning performs targeted VQA using PALI-3 on grounded frames combined with general video captions to generate the final text answer."}, {"id": "Wu_V_Guided_Visual_Search_as_a_Core_Mechanism_in_Multimodal", "title": "V?: Guided Visual Search as a Core Mechanism in Multimodal LLMs", "authors": ["Penghao Wu", "Saining Xie"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Wu_V_Guided_Visual_Search_as_a_Core_Mechanism_in_Multimodal_CVPR_2024_paper.pdf", "code": "https://github.com/penghao-wu/vstar", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["Vicuna-7B", "LLaVA"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "Visual Search Model (MLLM with localization decoders Dtl/Dcl)", "GroundingDINO", "OWL-ViT"], "generation": [], "execution": []}, "summary": "The VQA LLM first evaluates if the global image features suffice; if not, it identifies target objects to search for. The V* Visual Search model (an MLLM with localization decoders) then performs a recursive, LLM-guided search over image patches to locate targets, using contextual cues when needed. Located target patches and coordinates are stored in the Visual Working Memory (VWM), which the VQA LLM then processes to generate the final text answer."}, {"id": "Zhuang_Vlogger_Make_Your_Dream_A_Vlog", "title": "Vlogger: Make Your Dream A Vlog", "authors": ["Shaobin Zhuang", "Kunchang Li", "Xinyuan Chen", "Yaohui Wang", "Ziwei Liu", "Yu Qiao", "Yali Wang"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Zhuang_Vlogger_Make_Your_Dream_A_Vlog_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Coordinator", "Reasoner"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "OpenCLIP ViT-H/14"], "generation": ["Stable Diffusion XL", "ShowMaker", "Bark"], "execution": []}, "summary": "GPT-4 (Director) progressively decomposes the user story into a detailed script with scene durations and summarizes actors. Stable Diffusion XL generates reference images for these actors. ShowMaker then generates video snippets for each scene using the script text and actor images (encoded via CLIP/OpenCLIP) as conditioning, operating in generation and prediction modes to control duration. Finally, Bark synthesizes audio from the script, and all components are combined into the final vlog."}, {"id": "Zhan_OAKINK2_A_Dataset_of_Bimanual_Hands-Object_Manipulation_in_Complex_Task", "title": "OAKINK2: A Dataset of Bimanual Hands-Object Manipulation in Complex Task Completion", "authors": ["Xinyu Zhan", "Lixin Yang", "Yifei Zhao", "Kangrui Mao", "Hanlin Xu", "Zenan Lin", "Kailin Li", "Cewu Lu"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Zhan_OAKINK2_A_Dataset_of_Bimanual_Hands-Object_Manipulation_in_Complex_Task_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Robot_Manipulation", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["CLIP", "PointBert"], "generation": ["MF-MDM", "TaMF"], "execution": []}, "summary": "GPT-4 decomposes complex task text into a Primitive Dependency Graph (program) specifying execution order. An Oracle retrieves and re-targets object trajectories from the dataset based on the planned primitives. Simultaneously, CLIP and PointBert encode the task text and object geometries. The TaMF model (built on MF-MDM) generates bimanual hand motion trajectories by conditioning on the object trajectories, CLIP text embeddings, and PointBert object features, with final trajectories interpolated to ensure smooth transitions between primitives."}, {"id": "Yang_RILA_Reflective_and_Imaginative_Language_Agent_for_Zero-Shot_Semantic_Audio-Visual", "title": "RILA: Reflective and Imaginative Language Agent for Zero-Shot Semantic Audio-Visual Navigation", "authors": ["Zeyuan Yang", "LIU JIAGENG", "Peihao Chen", "Anoop Cherian", "Tim Marks", "Jonathan Le Roux", "Chuang Gan"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Yang_RILA_Reflective_and_Imaginative_Language_Agent_for_Zero-Shot_Semantic_Audio-Visual_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Converge", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier", "Coordinator"], "llm_models": ["GPT-3.5 (gpt-3.5-turbo)"], "non_llm_models": {"perception": ["GroundingDINO", "ResNet-18", "Pre-trained Audio Classification Model"], "generation": [], "execution": []}, "summary": "Learned perception modules (GroundingDINO for visual object detection, ResNet-18 for audio distance, and an audio classifier for goal object recognition) process sensory inputs into text descriptions and confidence scores. An LLM-based Imaginative Assistant deduces room layouts and provides strategic suggestions. The LLM-based Reflective Planner aggregates these text inputs, reflects on perceptual accuracy, and selects exploration frontiers. Deterministic tools—frontier-based exploration, Dijkstra's algorithm on a semantic map graph, and a deterministic low-level policy—then convert selected waypoints into agent actions."}, {"id": "Wang_ModaVerse_Efficiently_Transforming_Modalities_with_LLMs", "title": "ModaVerse: Efficiently Transforming Modalities with LLMs", "authors": ["Xinyu Wang", "Bohan Zhuang", "Qi Wu"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Wang_ModaVerse_Efficiently_Transforming_Modalities_with_LLMs_CVPR_2024_paper.pdf", "code": "https://github.com/xinke-wang/ModaVerse", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Translator", "Coordinator"], "llm_models": ["Vicuna"], "non_llm_models": {"perception": ["ImageBind"], "generation": ["Stable Diffusion", "AudioLDM", "Text-to-Video models (e.g., Make-A-Video)"], "execution": []}, "summary": "Multimodal inputs (image/video/audio) are encoded by ImageBind and projected via trainable linear layers into Vicuna's text space. The LLM generates a structured meta-response specifying which text-to-x model to invoke and with what prompts. A parser then activates the appropriate external generation model(s) to produce the final output."}, {"id": "Cai_Digital_Life_Project_Autonomous_3D_Characters_with_Social_Intelligence", "title": "Digital Life Project: Autonomous 3D Characters with Social Intelligence", "authors": ["Zhongang Cai", "Jianping Jiang", "Zhongfei Qing", "Xinying Guo", "Mingyuan Zhang", "Zhengyu Lin", "Haiy Mei", "Chen Wei", "Wang Ruisi", "Wanqi Yin", "Liang Pan", "Xiangyu Fan", "Han Du", "Peng Gao", "Zhitao Yang", "Yang Gao", "Jiaqi Li", "Tianxiang Ren", "YuKun Wei", "Xiaogang Wang", "Chen Change Loy", "Lei Yang", "Ziwei Liu"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Cai_Digital_Life_Project_Autonomous_3D_Characters_with_Social_Intelligence_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Gaming", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-based LLM"], "non_llm_models": {"perception": ["Motion Captioning Network", "Sentence Encoder", "CLIP"], "generation": ["ReMoDiffuse-based diffusion model", "Motion Matching system"], "execution": ["3D character motion controller"]}, "summary": "SocioMind (LLM) generates structured behavior text based on psychological states and memories. For human interaction, the Motion Captioning Network perceives human video and converts it to text descriptions. MoMat-MoGen then retrieves high-quality motion priors via motion matching and diversifies them through a ReMoDiffuse-based diffusion model to synthesize interactive 3D motions. Finally, the character controller executes these motions to animate the 3D characters, enabling autonomous social interactions."}, {"id": "Gao_CLOVA_A_Closed-LOop_Visual_Assistant_with_Tool_Usage_and_Update", "title": "CLOVA: A Closed-LOop Visual Assistant with Tool Usage and Update", "authors": ["Zhi Gao", "Yuntao Du.", "Xintong Zhang", "Xiaojian Ma", "Wenjuan Han", "Song-Chun Zhu", "Qing Li"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Gao_CLOVA_A_Closed-LOop_Visual_Assistant_with_Tool_Usage_and_Update_CVPR_2024_paper.pdf", "code": "https://github.com/clova-tool/CLOVA-tool", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5", "GPT-4", "LLaMA2-7B"], "non_llm_models": {"perception": ["OWL-ViT", "BLIP", "MaskFormer", "CLIP", "DSFD"], "generation": ["Stable Diffusion"], "execution": ["Python interpreter (CROP, EVAL, COUNT, etc.)"]}, "summary": "During inference, the LLM generates programs to execute visual tools sequentially (e.g., OWL-ViT for localization, BLIP for VQA, Stable Diffusion for editing). In the reflection phase, the LLM analyzes human feedback and intermediate multimodal results to identify faulty tools. The learning phase automatically collects training data via LLM inference, open-vocabulary datasets, or Internet search, then updates tools using a training-validation prompt tuning scheme while updating the LLM with new in-context examples."}, {"id": "Wei_Editable_Scene_Simulation_for_Autonomous_Driving_via_Collaborative_LLM-Agents", "title": "Editable Scene Simulation for Autonomous Driving via Collaborative LLM-Agents", "authors": ["Yuxi Wei", "Zi Wang", "Yifan Lu", "Chenxin Xu", "Changxing Liu", "Hao Zhao", "Siheng Chen", "Yanfeng Wang"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Wei_Editable_Scene_Simulation_for_Autonomous_Driving_via_Collaborative_LLM-Agents_CVPR_2024_paper.pdf", "code": "https://github.com/yifanlu0227/ChatSim", "pattern": "LLM + Perception + Generation", "domain": "Autonomous_Driving", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["McLight"], "generation": ["McNeRF", "Latent diffusion inpainting model"], "execution": []}, "summary": "A Project Manager GPT-4 agent parses natural-language commands and dispatches structured sub-tasks to specialized editing agents. The background pipeline uses McNeRF to render novel views and a latent diffusion model to inpaint deleted vehicles. The foreground pipeline uses McLight to estimate HDR scene lighting, which a deterministic Blender API uses to render external 3D assets. Vehicle trajectories are generated deterministically via lane-node matching, Bezier-curve fitting, and trajectory tracking. Final foreground and background images are composed into an output video."}, {"id": "Toubal_Modeling_Collaborator_Enabling_Subjective_Vision_Classification_With_Minimal_Human_Effort", "title": "Modeling Collaborator: Enabling Subjective Vision Classification With Minimal Human Effort via LLM Tool-Use", "authors": ["Imad Eddine Toubal", "Aditya Avinash", "Neil Alldrin", "Jan Dlabal", "Wenlei Zhou", "Enming Luo", "Otilia Stretcu", "Hao Xiong", "Chun-Ta Lu", "Howard Zhou", "Ranjay Krishna", "Ariel Fuxman", "Tom Duerig"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Toubal_Modeling_Collaborator_Enabling_Subjective_Vision_Classification_With_Minimal_Human_Effort_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["PaLM 2"], "non_llm_models": {"perception": ["PaLI-X (VQA variant)", "PaLI-X (Captioning variant)", "CLIP", "ALIGN"], "generation": [], "execution": []}, "summary": "User provides a concept name/description to PaLM 2, which generates atomic visual questions and search queries. PaLI-X VQA answers the questions and PaLI-X Captioning generates image descriptions. PaLM 2 then performs chain-of-thought reasoning over these textual outputs to classify images as positive/negative examples, ultimately distilling a lightweight MLP student model for deployment."}, {"id": "Wu_Self-correcting_LLM-controlled_Diffusion_Models", "title": "Self-correcting LLM-controlled Diffusion Models", "authors": ["Tsung-Han Wu", "Long Lian", "Joseph Gonzalez", "Boyi Li", "Trevor Darrell"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Wu_Self-correcting_LLM-controlled_Diffusion_Models_CVPR_2024_paper.pdf", "code": "https://github.com/tsunghan-wu/SLD", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["OWL-ViT v2", "SAM"], "generation": ["Stable Diffusion", "DALL-E 3"], "execution": []}, "summary": "User prompt is parsed by GPT-4 to extract key objects, which OWL-ViT detects in the generated image. GPT-4 controller analyzes discrepancies and plans correction operations (add/delete/reposition). SAM refines object masks, and Stable Diffusion executes latent space editing. This process iterates until the image aligns with the prompt."}, {"id": "Hong_MultiPLY_A_Multisensory_Object-Centric_Embodied_Large_Language_Model_in_3D", "title": "MultiPLY: A Multisensory Object-Centric Embodied Large Language Model in 3D World", "authors": ["Yining Hong", "Zishuo Zheng", "Peihao Chen", "Yian Wang", "Junyan Li", "Chuang Gan"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Hong_MultiPLY_A_Multisensory_Object-Centric_Embodied_Large_Language_Model_in_3D_CVPR_2024_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["LLaVA"], "non_llm_models": {"perception": ["CLIP", "CLAP", "ConceptGraphs", "DiffTactile"], "generation": [], "execution": ["Habitat-sim agent", "pre-defined pathfinder"]}, "summary": "The pipeline begins with encoding the 3D scene into object-centric representations using ConceptGraphs and CLIP, along with ambient sound via CLAP. LLaVA receives the user query and scene context, then generates action tokens (e.g., <SELECT>, <NAVIGATE>, <TOUCH>) to interact with the environment. The Habitat-sim agent executes these actions, and sensory feedback (visual, tactile, thermal, audio) is encoded and appended back to LLaVA via state tokens, enabling iterative reasoning until the task is completed."}, {"id": "Zhao_DiffAgent_Fast_and_Accurate_Text-to-Image_API_Selection_with_Large_Language", "title": "DiffAgent: Fast and Accurate Text-to-Image API Selection with Large Language Model", "authors": ["Lirui Zhao", "Yue Yang", "Kaipeng Zhang", "Wenqi Shao", "Yuxin Zhang", "Yu Qiao", "Ping Luo", "Rongrong Ji"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Zhao_DiffAgent_Fast_and_Accurate_Text-to-Image_API_Selection_with_Large_Language_CVPR_2024_paper.pdf", "code": "https://github.com/OpenGVLab/DiffAgent", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Router", "Reasoner", "Translator"], "llm_models": ["LLaMA-2-7B"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion 1.5", "Stable Diffusion XL", "LoRA models", "Checkpoint models"], "execution": []}, "summary": "Given a user text prompt, the fine-tuned LLaMA-2-7B (DiffAgent) generates a T2I API call specifying a Stable Diffusion model variant (SD 1.5 or SDXL with community LoRA/checkpoint weights) and its generation parameters. The selected generation model then produces the final image. During the SFTA training framework, CLIP, ImageReward, and HPS v2 provide automated image-scoring feedback to align the LLM with human preferences via RRHF, but these scorers are not used at inference time."}, {"id": "Yuan_Visual_Programming_for_Zero-shot_Open-Vocabulary_3D_Visual_Grounding", "title": "Visual Programming for Zero-shot Open-Vocabulary 3D Visual Grounding", "authors": ["Zhihao Yuan", "Jinke Ren", "Chun-Mei Feng", "Hengshuang Zhao", "Shuguang Cui", "Zhen Li"], "venue": "CVPR", "year": 2024, "url": "https://openaccess.thecvf.com/content/CVPR2024/papers/Yuan_Visual_Programming_for_Zero-shot_Open-Vocabulary_3D_Visual_Grounding_CVPR_2024_paper.pdf", "code": "https://github.com/CurryYuan/ZSVG3D", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["Mask3D", "CLIP", "ViLT", "BLIP-2", "PointNet++", "PointNeXt", "PointBERT"], "generation": [], "execution": []}, "summary": "The user provides a text query describing a target object in a 3D scene. The LLM (GPT-4/3.5) generates a visual program (e.g., sequence of LOC, CLOSEST, RIGHT operations) based on in-context examples. A program interpreter executes this DAG-structured program: the LOC module queries Mask3D for 3D geometric proposals and 2D VLMs (CLIP, ViLT, or BLIP-2) for open-vocabulary appearance matching, while spatial relation modules filter candidates based on view-dependent/independent geometric relationships. The final target bounding box is returned after executing the program."}, {"id": "Bai_R2C_Mapping_Room_to_Chessboard_to_Unlock_LLM_As_Low-Level", "title": "R2C: Mapping Room to Chessboard to Unlock LLM As Low-Level Action Planner", "authors": ["Ziyi Bai", "Hanxuan Li", "Bin Fu", "Chuyan Xiong", "Ruiping Wang", "Xilin Chen"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Bai_R2C_Mapping_Room_to_Chessboard_to_Unlock_LLM_As_Low-Level_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "Llama-7B-Chat", "Mistral-7B-Instruct-v0.2"], "non_llm_models": {"perception": ["Instance Segmentation Model"], "generation": [], "execution": ["ALFRED Agent", "LoCoBot Robot Controller"]}, "summary": "RGB-D observations are processed by an instance segmentation model to build a semantic map, which the Environment Filter abstracts into a compact chessboard representation. The LLM first decomposes instructions into high-level subgoals, then uses Chain-of-Thought Decision (CoT-D) to reason over the chessboard state and predict the next grid position. These coordinates are converted into low-level robot actions (e.g., MoveForward, TurnLeft) executed by the robot/agent, with the updated state feeding back into the perception loop."}, {"id": "Xue_PhyT2V_LLM-Guided_Iterative_Self-Refinement_for_Physics-Grounded_Text-to-Video_Generation", "title": "PhyT2V: LLM-Guided Iterative Self-Refinement for Physics-Grounded Text-to-Video Generation", "authors": ["Qiyao Xue", "Xiangyu Yin", "Boyuan Yang", "Wei Gao"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Xue_PhyT2V_LLM-Guided_Iterative_Self-Refinement_for_Physics-Grounded_Text-to-Video_Generation_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "ChatGPT-4o1-preview"], "non_llm_models": {"perception": ["Tarsier"], "generation": ["CogVideoX", "OpenSora", "VideoCrafter"], "execution": []}, "summary": "The pipeline starts with a user prompt, which the LLM analyzes to extract physical rules and objects (Step 1). A T2V diffusion model generates a video from this prompt, which is then captioned by Tarsier (perception). The LLM compares this caption against the original prompt to identify semantic mismatches (Step 2), then performs step-back reasoning to refine the prompt (Step 3). This refined prompt feeds back into the T2V model for the next iteration, continuing until the video adheres to physical rules and quality metrics converge."}, {"id": "Cao_SceneTAP_Scene-Coherent_Typographic_Adversarial_Planner_against_Vision-Language_Models_in_Real-World", "title": "SceneTAP: Scene-Coherent Typographic Adversarial Planner against Vision-Language Models in Real-World Environments", "authors": ["Yue Cao", "Yun Xing", "Jie Zhang", "Di Lin", "Tianwei Zhang", "Ivor Tsang", "Yang Liu", "Qing Guo"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Cao_SceneTAP_Scene-Coherent_Typographic_Adversarial_Planner_against_Vision-Language_Models_in_Real-World_CVPR_2025_paper.pdf", "code": "https://github.com/tsingqguo/scenetap", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o (gpt-4o-2024-08-06)"], "non_llm_models": {"perception": ["Set-of-Mark (SoM) segmentation models"], "generation": ["TextDiffuser"], "execution": []}, "summary": "Input image and question are first processed by Set-of-Mark segmentation to extract object regions and spatial marks. GPT-4o receives the image, question, and segmentation map to perform three-stage planning: generating adversarial text, determining placement via the segmentation map, and creating a detailed prompt for TextDiffuser. TextDiffuser then generates the final adversarial image by seamlessly inserting the text at the specified location. A revisable prompt mechanism allows GPT-4o to review and correct its plan before final image generation."}, {"id": "Mu_RoboTwin_Dual-Arm_Robot_Benchmark_with_Generative_Digital_Twins", "title": "RoboTwin: Dual-Arm Robot Benchmark with Generative Digital Twins", "authors": ["Yao Mu", "Tianxing Chen", "Zanxin Chen", "Shijia Peng", "Zhiqian Lan", "Zeyu Gao", "Zhixuan Liang", "Qiaojun Yu", "Yude Zou", "Mingkun Xu", "Lunkai Lin", "Zhiqiang Xie", "Mingyu Ding", "Ping Luo"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Mu_RoboTwin_Dual-Arm_Robot_Benchmark_with_Generative_Digital_Twins_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["GPT-4V"], "generation": ["Rodin", "SDXL-Turbo", "Stable Diffusion"], "execution": ["MPlib trajectory planner", "Diffusion Policy"]}, "summary": "Real-world 2D images are processed by GPT-4V to generate descriptions, which are varied by an LLM and fed through SDXL-Turbo and Rodin to create diverse 3D assets with spatial annotations transferred via Stable Diffusion features. The LLM decomposes tasks, infers spatial constraints, and generates executable code using MPlib to produce trajectories, with execution errors fed back for iterative refinement until expert demonstrations are successfully generated."}, {"id": "Wu_Chat2SVG_Vector_Graphics_Generation_with_Large_Language_Models_and_Image", "title": "Chat2SVG: Vector Graphics Generation with Large Language Models and Image Diffusion Models", "authors": ["Ronghuan Wu", "Wanchao Su", "Jing Liao"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Wu_Chat2SVG_Vector_Graphics_Generation_with_Large_Language_Models_and_Image_CVPR_2025_paper.pdf", "code": "https://github.com/kingnobro/chat2svg", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Claude-3.5-sonnet"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)"], "generation": ["Stable Diffusion (SDEdit)", "ControlNet", "SVG VAE"], "execution": []}, "summary": "User text prompt undergoes LLM-based prompt expansion and SVG template generation with basic primitives, followed by a visual rectification loop. The rendered template is enhanced via SDEdit with ControlNet to create a target image. SAM segments new decorative elements from this target image. Finally, a dual-stage optimization process refines the SVG using SVG VAE latent optimization and direct point coordinate refinement to produce the final output."}, {"id": "Heiman_FactCheXcker_Mitigating_Measurement_Hallucinations_in_Chest_X-ray_Report_Generation_Models", "title": "FactCheXcker: Mitigating Measurement Hallucinations in Chest X-ray Report Generation Models", "authors": ["Alice Heiman", "Xiaoman Zhang", "Emma Chen", "Sung Eun Kim", "Pranav Rajpurkar"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Heiman_FactCheXcker_Mitigating_Measurement_Hallucinations_in_Chest_X-ray_Report_Generation_Models_CVPR_2025_paper.pdf", "code": "https://github.com/rajpurkarlab/FactCheXcker", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o mini"], "non_llm_models": {"perception": ["ResNet-50+", "CarinaNet+", "ChestX-Det Segmentation Model"], "generation": [], "execution": []}, "summary": "GPT-4o mini first analyzes the input report to generate specific measurement queries. It then generates Python code using a domain-specific API to solve these queries. During execution, the code calls specialized perception models—ResNet-50+ for ETT detection, CarinaNet+ for carina localization, and ChestX-Det for anatomical segmentation—to extract visual features and compute measurements. Finally, a rule-based Report Updater module incorporates these verified measurements into the corrected radiology report."}, {"id": "Chen_SOLVE_Synergy_of_Language-Vision_and_End-to-End_Networks_for_Autonomous_Driving", "title": "SOLVE: Synergy of Language-Vision and End-to-End Networks for Autonomous Driving", "authors": ["Xuesong Chen", "Linjiang Huang", "Tao Ma", "Rongyao Fang", "Shaoshuai Shi", "Hongsheng Li"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Chen_SOLVE_Synergy_of_Language-Vision_and_End-to-End_Networks_for_Autonomous_Driving_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "DAG", "coupling": "Tight", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["LLaVA v1.5", "LLaMA-7B"], "non_llm_models": {"perception": ["SQ-Former", "EVA-02-L", "StreamPETR"], "generation": [], "execution": ["End-to-end planner", "Trajectory adapter"]}, "summary": "Multi-view images are encoded by the shared SQ-Former into visual tokens that simultaneously feed into both the VLM (LLaVA) and the E2E planner. The VLM performs Trajectory Chain-of-Thought reasoning—selecting a coarse trajectory from a predefined bank and refining it—which is stored in a memory buffer. The E2E planner asynchronously retrieves these high-quality VLM trajectories as initialization priors, combining them with current visual features to generate the final real-time planning output."}, {"id": "Ziliotto_TANGO_Training-free_Embodied_AI_Agents_for_Open-world_Tasks", "title": "TANGO: Training-free Embodied AI Agents for Open-world Tasks", "authors": ["Filippo Ziliotto", "Tommaso Campari", "Luciano Serafini", "Lamberto Ballan"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Ziliotto_TANGO_Training-free_Embodied_AI_Agents_for_Open-world_Tasks_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Router"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["BLIP2", "Owlv2", "DETR", "CLIP", "SuperGlue"], "generation": [], "execution": ["PointGoal Navigation policy", "Exploration policy"]}, "summary": "GPT-4o generates a program of high-level primitives based on the user query and in-context examples. The program is executed sequentially: perception modules (Owlv2/DETR for detection, CLIP for classification, BLIP2 for visual QA, SuperGlue for image matching) extract information from observations, and the PointGoal Navigation policy executes physical movements to navigate the 3D environment, while a memory mechanism stores feature maps for lifelong navigation."}, {"id": "Wang_VideoTree_Adaptive_Tree-based_Video_Representation_for_LLM_Reasoning_on_Long", "title": "VideoTree: Adaptive Tree-based Video Representation for LLM Reasoning on Long Videos", "authors": ["Ziyang Wang", "Shoubin Yu", "Elias Stengel-Eskin", "Jaehong Yoon", "Feng Cheng", "Gedas Bertasius", "Mohit Bansal"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Wang_VideoTree_Adaptive_Tree-based_Video_Representation_for_LLM_Reasoning_on_Long_CVPR_2025_paper.pdf", "code": "https://github.com/Ziyang412/VideoTree", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "Mistral-7B", "Mistral-8x7B"], "non_llm_models": {"perception": ["EVA-CLIP-8B", "CogAgent", "LaViLa", "LLaVA1.6-7B"], "generation": [], "execution": []}, "summary": "Input video and query are processed by EVA-CLIP-8B to extract visual features, which are clustered via K-Means. Captioners (CogAgent/LaViLa/LLaVA) generate text descriptions for cluster keyframes. The LLM scores cluster relevance (1-3) in an iterative loop (adaptive breadth expansion) that increases clusters until sufficient relevant information is found. High-relevance clusters undergo depth expansion (hierarchical sub-clustering) to build a tree. Selected leaf nodes are captioned, temporally ordered, and fed to the LLM for final reasoning and answer generation."}, {"id": "Cui_GROVE_A_Generalized_Reward_for_Learning_Open-Vocabulary_Physical_Skill", "title": "GROVE: A Generalized Reward for Learning Open-Vocabulary Physical Skill", "authors": ["Jieming Cui", "Tengyu Liu", "Ziyu Meng", "Jiale Yu", "Ran Song", "Wei Zhang", "Yixin Zhu", "Siyuan Huang"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Cui_GROVE_A_Generalized_Reward_for_Learning_Open-Vocabulary_Physical_Skill_CVPR_2025_paper.pdf", "code": "https://github.com/jiemingcui/GROVE-pytorch", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-o1-preview"], "non_llm_models": {"perception": ["CLIP-ViT-B/32", "Pose2CLIP"], "generation": [], "execution": ["CALM controller", "PPO policy"]}, "summary": "GPT-o1-preview generates reward code combining physical constraints and VLM-based semantic evaluation. Pose2CLIP maps agent poses to CLIP feature space to evaluate motion alignment with instructions. A PPO/CALM policy executes physical actions in simulation, and the LLM iteratively refines the reward based on VLM fitness feedback until convergence."}, {"id": "Wei_From_Words_to_Structured_Visuals_A_Benchmark_and_Framework_for", "title": "From Words to Structured Visuals: A Benchmark and Framework for Text-to-Diagram Generation and Editing", "authors": ["Jingxuan Wei", "Cheng Tan", "Qi Chen", "Gaowei Wu", "Siyuan Li", "Zhangyang Gao", "Linzhuang Sun", "Bihui Yu", "Ruifeng Guo"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Wei_From_Words_to_Structured_Visuals_A_Benchmark_and_Framework_for_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen-72B", "Qwen2.5-Coder-7B", "GPT-4o"], "non_llm_models": {"perception": ["Qwen2-VL-7B"], "generation": [], "execution": ["LaTeX/TikZ compiler", "Graphviz DOT compiler"]}, "summary": "User queries are processed by the Plan Agent (Qwen-72B) which performs query expansion and dispatches tasks to either the Code Agent (Qwen2.5-Coder-7B) for text-to-code generation or the Diagram-to-Code Agent (Qwen2-VL-7B) for vision-to-code conversion. Generated code undergoes iterative verification by the Check Agent (GPT-4o + compiler) to ensure correctness before final compilation into diagram images."}, {"id": "Cai_ROCKET-1_Mastering_Open-World_Interaction_with_Visual-Temporal_Context_Prompting", "title": "ROCKET-1: Mastering Open-World Interaction with Visual-Temporal Context Prompting", "authors": ["Shaofei Cai", "Zihao Wang", "Kewei Lian", "Zhancun Mu", "Xiaojian Ma", "Anji Liu", "Yitao Liang"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Cai_ROCKET-1_Mastering_Open-World_Interaction_with_Visual-Temporal_Context_Prompting_CVPR_2025_paper.pdf", "code": "https://github.com/CraftJarvis/ROCKET-1", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Molmo", "SAM-2"], "generation": [], "execution": ["ROCKET-1"]}, "summary": "GPT-4o decomposes high-level tasks into interaction steps and determines interaction types. Molmo localizes target objects by outputting point coordinates based on GPT-4o's descriptions. SAM-2 generates segmentation masks from these points and tracks objects temporally across frames. ROCKET-1, a transformer-based policy, processes visual observations concatenated with segmentation masks and interaction types to predict mouse and keyboard actions."}, {"id": "Panagopoulou_ViUniT_Visual_Unit_Tests_for_More_Robust_Visual_Programming", "title": "ViUniT: Visual Unit Tests for More Robust Visual Programming", "authors": ["Artemis Panagopoulou", "Honglu Zhou", "Silvio Savarese", "Caiming Xiong", "Chris Callison-Burch", "Mark Yatskar", "Juan Carlos Niebles"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Panagopoulou_ViUniT_Visual_Unit_Tests_for_More_Robust_Visual_Programming_CVPR_2025_paper.pdf", "code": "https://github.com/SalesforceAIResearch/visual-unit-testing", "pattern": "LLM + Perception + Generation + Action", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o-mini", "CodeLlama-7B", "CodeGemma-7B", "Meta-Llama-3-8B-Instruct"], "non_llm_models": {"perception": ["GroundingDINO", "CLIP", "BLIP-2"], "generation": ["Stable Diffusion v1.4", "SDXL", "LM Guided Diffusion"], "execution": ["Python execution engine"]}, "summary": "Given a visual query, LLMs generate candidate Python programs that execute on images using perception models (GroundingDINO, CLIP, BLIP-2). Concurrently, an LLM generates unit tests as caption-answer pairs, which are converted to synthetic test images via diffusion models. Programs are scored by executing them on these test images, and the highest-scoring program is selected or re-prompting is initiated based on threshold performance."}, {"id": "Gao_GENMANIP_LLM-driven_Simulation_for_Generalizable_Instruction-Following_Manipulation", "title": "GENMANIP: LLM-driven Simulation for Generalizable Instruction-Following Manipulation", "authors": ["Ning Gao", "Yilun Chen", "Shuai Yang", "Xinyi Chen", "Yang Tian", "Hao Li", "Haifeng Huang", "Hanqing Wang", "Tai Wang", "Jiangmiao Pang"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Gao_GENMANIP_LLM-driven_Simulation_for_Generalizable_Instruction-Following_Manipulation_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-4V", "GPT-4o", "Claude-3.7-Sonnet", "Gemini-2.0-Flash", "Qwen2.5-VL"], "non_llm_models": {"perception": ["SAM2", "AnyGrasp"], "generation": [], "execution": ["MPlib motion planner", "Primitive manipulation skills (pick/place)", "Trajectory-action chainer"]}, "summary": "User instructions are processed by a Long Horizon Planner (LLM) to decompose tasks. SAM2 generates object masks with Set-of-Mark prompting for visual grounding, and AnyGrasp proposes grasp poses filtered by target masks. A Grid-based Motion Planner (VLM) selects trajectory waypoints, which are executed by primitive manipulation skills via a trajectory-action chainer. A completion check verifies goal state against the task-oriented scene graph (ToSG) and triggers replanning if needed, supporting iterative execution of long-horizon tasks."}, {"id": "Lin_Olympus_A_Universal_Task_Router_for_Computer_Vision_Tasks", "title": "Olympus: A Universal Task Router for Computer Vision Tasks", "authors": ["Yuanze Lin", "Yunsheng Li", "Dongdong Chen", "Weijian Xu", "Ronald Clark", "Philip Torr"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Lin_Olympus_A_Universal_Task_Router_for_Computer_Vision_Tasks_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Phi-2", "Mipha-3B"], "non_llm_models": {"perception": ["SAM", "GroundingDINO", "Depth Estimation Models", "Pose Estimation Models", "Object Detection Models", "Canny Estimation Models", "Normal Estimation Models"], "generation": ["Diffusion Models", "3D Generation Models", "Video Generation Models", "Image Editing Models", "Image Super-Resolution Models"], "execution": []}, "summary": "User instructions are processed by the Olympus MLLM (based on Phi-2/Mipha). For understanding tasks, the MLLM responds directly. For other tasks, the MLLM generates task-specific routing tokens and refined prompts to invoke appropriate specialist models (perception or generation). The specialist models execute their respective tasks, and their outputs are aggregated by the MLLM into a final coherent response delivered to the user."}, {"id": "Chen_Symbolic_Representation_for_Any-to-Any_Generative_Tasks", "title": "Symbolic Representation for Any-to-Any Generative Tasks", "authors": ["Jiaqi Chen", "Xiaoye Zhu", "Yue Wang", "Tianyang Liu", "Xinhui Chen", "Ying Chen", "Chak Tou Leong", "Yifei Ke", "Joseph Liu", "Yiwen Yuan", "Julian McAuley", "Li-jia Li"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Chen_Symbolic_Representation_for_Any-to-Any_Generative_Tasks_CVPR_2025_paper.pdf", "code": "https://github.com/Jiaqi-Chen-00/Any-2-Any", "pattern": "LLM + Perception + Generation + Action", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP", "VAE encoder"], "generation": ["Stable Diffusion (SDXL)", "MVDream", "Zero123", "VAE decoder"], "execution": ["ComfyUI workflow executor"]}, "summary": "User provides natural language task description and multimodal inputs → GPT-4o generates symbolic workflow (A-LANGUAGE) specifying functions, parameters, and DAG topology → Workflow is compiled and executed by ComfyUI executor, orchestrating heterogeneous perception (CLIP, VAE encoder) and generation (SDXL, MVDream, Zero123, VAE decoder) models → Final output is generated with iterative refinement correcting errors if execution fails."}, {"id": "Mall_DiSciPLE_Learning_Interpretable_Programs_for_Scientific_Visual_Discovery", "title": "DiSciPLE: Learning Interpretable Programs for Scientific Visual Discovery", "authors": ["Utkarsh Mall", "Cheng Perng Phoo", "Mia Chiquier", "Bharath Hariharan", "Kavita Bala", "Carl Vondrick"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Mall_DiSciPLE_Learning_Interpretable_Programs_for_Scientific_Visual_Discovery_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator"], "llm_models": ["Llama-3-8b-instruct"], "non_llm_models": {"perception": ["GRAFT"], "generation": [], "execution": []}, "summary": "DiSciPLE uses Llama-3 to perform evolutionary program search, synthesizing Python programs that call GRAFT for open-vocabulary satellite image segmentation and feature extraction. The programs combine these neural features with deterministic mathematical operators and a linear regressor to predict scientific quantities. Generated programs are executed via a Python interpreter, evaluated on training data, and refined through LLM-guided crossover, mutation, critic-based verification, and analytical simplification over multiple generations."}, {"id": "Pan_OmniManip_Towards_General_Robotic_Manipulation_via_Object-Centric_Interaction_Primitives_as", "title": "OmniManip: Towards General Robotic Manipulation via Object-Centric Interaction Primitives as Spatial Constraints", "authors": ["Mingjie Pan", "Jiyao Zhang", "Tianshu Wu", "Yinghao Zhao", "Wenlong Gao", "Hao Dong"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Pan_OmniManip_Towards_General_Robotic_Manipulation_via_Object-Centric_Interaction_Primitives_as_CVPR_2025_paper.pdf", "code": "https://github.com/pmj110119/OmniManip", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["SAM", "GroundingDINO", "Omni6DPose", "GenPose++", "single-view 3D generation network"], "generation": [], "execution": ["6D pose tracking algorithm", "6-DOF grasping model", "trajectory optimizer"]}, "summary": "RGB-D observations are processed by SAM and GroundingDINO for object detection, then GPT-4o decomposes the task. A 3D generation network and Omni6DPose create canonical object representations. GPT-4o extracts interaction primitives and constraints, verified through an iterative RRC loop (rendering and checking). Finally, a trajectory optimizer generates motions executed by the robot with closed-loop 6D pose tracking."}, {"id": "Shi_Chain_of_Semantics_Programming_in_3D_Gaussian_Splatting_Representation_for", "title": "Chain of Semantics Programming in 3D Gaussian Splatting Representation for 3D Vision Grounding", "authors": ["Jiaxin Shi", "Mingyue Xiang", "Hao Sun", "Yixuan Huang", "Zhi Weng"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Shi_Chain_of_Semantics_Programming_in_3D_Gaussian_Splatting_Representation_for_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Verifier", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["3D Gaussian Splatting"], "generation": [], "execution": []}, "summary": "GPT-4o parses the user utterance into a relationship graph and chain of semantics. A 3D Gaussian Splatting model reconstructs the scene and renders novel-view 2D images from LLM-inferred viewpoints. GPT-4o extracts fine-grained 2D semantics from these renders and generates Python code that fuses 3D information, 2D semantics, and the relationship graph to ground the target object. The code is executed by a Python interpreter, and a grounded-aware self-check mechanism verifies the result, triggering iterative re-execution with error feedback if needed."}, {"id": "Xue_ComfyBench_Benchmarking_LLM-based_Agents_in_ComfyUI_for_Autonomously_Designing_Collaborative", "title": "ComfyBench: Benchmarking LLM-based Agents in ComfyUI for Autonomously Designing Collaborative AI Systems", "authors": ["Xiangyuan Xue", "Zeyu Lu", "Di Huang", "Zidong Wang", "Wanli Ouyang", "Lei Bai"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Xue_ComfyBench_Benchmarking_LLM-based_Agents_in_ComfyUI_for_Autonomously_Designing_Collaborative_CVPR_2025_paper.pdf", "code": "https://github.com/xxyQwQ/ComfyBench", "pattern": "LLM + Perception + Generation + Action", "domain": "Benchmark_Evaluation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet", "Llama-3.1-70B", "o1-preview", "o1-mini"], "non_llm_models": {"perception": ["CLIP", "SAM (Segment Anything)", "ControlNet", "InsightFace", "IC-Light"], "generation": ["Stable Diffusion", "VAE", "LoRA", "IP-Adapter"], "execution": ["ComfyUI execution engine"]}, "summary": "ComfyAgent uses a multi-agent framework (PlanAgent, RetrieveAgent, CombineAgent, AdaptAgent, RefineAgent) powered by LLMs to generate code-based workflow representations. These are converted to JSON and executed by the ComfyUI engine, which orchestrates heterogeneous perception, generation, and execution models to produce the desired visual outputs."}, {"id": "Xia_Phoenix_A_Motion-based_Self-Reflection_Framework_for_Fine-grained_Robotic_Action_Correction", "title": "Phoenix: A Motion-based Self-Reflection Framework for Fine-grained Robotic Action Correction", "authors": ["Wenke Xia", "Ruoxuan Feng", "Dong Wang", "Di Hu"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Xia_Phoenix_A_Motion-based_Self-Reflection_Framework_for_Fine-grained_Robotic_Action_Correction_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Translator"], "llm_models": ["LLaVA-v1.5"], "non_llm_models": {"perception": [], "generation": [], "execution": ["Diffusion Policy"]}, "summary": "Visual observations and task descriptions are processed by LLaVA-v1.5, which first generates motion instructions via the Motion Prediction Module. If the Motion Correction Module detects failure, it corrects the instruction through semantic reflection. The final motion instruction is embedded via a learnable motion codebook to condition a Diffusion Policy, which generates 20Hz robotic actions for manipulation."}, {"id": "Shi_Enhancing_Video-LLM_Reasoning_via_Agent-of-Thoughts_Distillation", "title": "Enhancing Video-LLM Reasoning via Agent-of-Thoughts Distillation", "authors": ["Yudi Shi", "Shangzhe Di", "Qirui Chen", "Weidi Xie"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Shi_Enhancing_Video-LLM_Reasoning_via_Agent-of-Thoughts_Distillation_CVPR_2025_paper.pdf", "code": "https://github.com/zhengrongz/AoTD", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["DeepSeek-Coder-Instruct", "GPT-3.5-Turbo", "LLaMA-3.1-8B"], "non_llm_models": {"perception": ["OWL-ViT v2", "UniVTG", "InternVideo2", "GLIP", "LITA", "TimeChat", "Open-VCLIP", "LLaVA-NeXT-Video", "SeViLA", "LLaMA-VID"], "generation": [], "execution": []}, "summary": "The LLM (DeepSeek-Coder-Instruct/GPT-3.5) decomposes video questions into executable Python programs that sequentially invoke specialist perception models (object detection, temporal grounding, action recognition) to extract information. Execution traces are converted to natural language Chain-of-Thoughts by LLaMA-3.1-8B, verified for quality, and distilled into a Video-LLM (LLaVA-NeXT-Video) to generate final answers with step-by-step rationales."}, {"id": "Nath_VILA-M3_Enhancing_Vision-Language_Models_with_Medical_Expert_Knowledge", "title": "VILA-M3: Enhancing Vision-Language Models with Medical Expert Knowledge", "authors": ["Vishwesh Nath", "Wenqi Li", "Dong Yang", "Andriy Myronenko", "Mingxin Zheng", "Yao Lu", "Zhijian Liu", "Hongxu Yin", "Yee Man Law", "Yucheng Tang", "Pengfei Guo", "Can Zhao", "Ziyue Xu", "Yufan He", "Stephanie Harmon", "Benjamin Simon", "Greg Heinrich", "Stephen Aylward", "Marc Edgar", "Michael Zephyr", "Pavlo Molchanov", "Baris Turkbey", "Holger Roth", "Daguang Xu"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Nath_VILA-M3_Enhancing_Vision-Language_Models_with_Medical_Expert_Knowledge_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["VILA-M3 (Vicuna-based 3B/13B)", "VILA-M3 (Llama-3 8B)", "VILA-M3 (Yi-34B 40B)"], "non_llm_models": {"perception": ["VISTA3D", "MONAI BRATS", "TorchXRayVision (CNN ensemble)"], "generation": [], "execution": []}, "summary": "Medical images and queries are first processed by VILA-M3 to determine which expert model to trigger (VISTA3D for CT, BRATS for MRI, or TorchXRayVision for X-ray). The selected expert performs segmentation or classification, and the results are converted to textual descriptions and fed back to VILA-M3. The VLM then integrates this expert knowledge with visual features from its CLIP-L encoder to generate the final text output (report, classification, or VQA answer)."}, {"id": "Gan_StageDesigner_Artistic_Stage_Generation_for_Scenography_via_Theater_Scripts", "title": "StageDesigner: Artistic Stage Generation for Scenography via Theater Scripts", "authors": ["Zhaoxing Gan", "Mengtian Li", "Ruhua Chen", "Zhongxia Ji", "Sichen Guo", "Huanling Hu", "Guangnan Ye", "Zuo Hu"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Gan_StageDesigner_Artistic_Stage_Generation_for_Scenography_via_Theater_Scripts_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Star", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP (OpenCLIP ViT-L-14)", "Sentence-BERT"], "generation": ["ReCo (Layout-Controlled Diffusion Model)"], "execution": []}, "summary": "Input theater script is processed by GPT-4o to extract scene and imagery descriptions. GPT-4o then generates anchor and non-anchor entities with spatial coordinates, validated by a Multi-level Collision Map to prevent overlaps. CLIP and Sentence-BERT retrieve matching 3D assets from Objaverse. The Foreground Projection module calculates occlusion intervals to preserve audience sightlines. Finally, ReCo generates a layout-controlled background image avoiding occluded regions, producing a final 3D stage with placed foreground entities and a thematic 2D background."}, {"id": "Li_Robotic_Visual_Instruction", "title": "Robotic Visual Instruction", "authors": ["Yanbang Li", "Ziyang Gong", "Haoyang Li", "Xiaoqi Huang", "Haolan Kang", "Guangping Bai", "Xianzheng Ma"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Li_Robotic_Visual_Instruction_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Translator", "Coordinator"], "llm_models": ["GPT-4o", "LLaVA-13B", "LLaVA-7B"], "non_llm_models": {"perception": ["YOLOv8", "AnyGrasp", "RGB-D camera"], "generation": [], "execution": ["Keypoint-conditioned low-level policy"]}, "summary": "Hand-drawn RoVI visual instructions and initial observation images are input to a VLM (GPT-4o or LLaVA) which generates hierarchical language plans and executable Python code. Simultaneously, a YOLOv8 keypoint module extracts spatial constraints (starting points, waypoints, endpoints) from the RoVI drawing. The low-level policy executes the generated code by combining it with the extracted keypoints and grasp poses from AnyGrasp (filtered by spatial proximity to keypoints) to control a robotic arm through cost function minimization."}, {"id": "Li_DyFo_A_Training-Free_Dynamic_Focus_Visual_Search_for_Enhancing_LMMs", "title": "DyFo: A Training-Free Dynamic Focus Visual Search for Enhancing LMMs in Fine-Grained Visual Understanding", "authors": ["Geng Li", "Jinglin Xu", "Yunzhen Zhao", "Yuxin Peng"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Li_DyFo_A_Training-Free_Dynamic_Focus_Visual_Search_for_Enhancing_LMMs_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["LLaVA-1.5", "Qwen2-VL"], "non_llm_models": {"perception": ["Lang-Segment-Anything", "Grounding DINO", "SAM (Segment Anything Model)"], "generation": [], "execution": []}, "summary": "The pipeline accepts an image and question as input. The LMM initializes a focus state, then engages in bidirectional interaction with visual experts via MCTS-based Focus Tree Search. The LMM generates text cues to guide the visual expert in extracting relevant image regions, while the expert's output directs the LMM to adjust its textual focus. This iterative process continues through Semantic Focus and Scatter actions until terminal nodes are reached, followed by multi-grained voting to produce the final text answer."}, {"id": "Zhou_Feature4X_Bridging_Any_Monocular_Video_to_4D_Agentic_AI_with", "title": "Feature4X: Bridging Any Monocular Video to 4D Agentic AI with Versatile Gaussian Feature Fields", "authors": ["Shijie Zhou", "Hui Ren", "Yijia Weng", "Shuwang Zhang", "Zhen Wang", "Dejia Xu", "Zhiwen Fan", "Suya You", "Zhangyang Wang", "Leonidas Guibas", "Achuta Kadambi"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Zhou_Feature4X_Bridging_Any_Monocular_Video_to_4D_Agentic_AI_with_CVPR_2025_paper.pdf", "code": "https://github.com/ShijieZhou-UCLA/Feature4X", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["SAM2", "CLIP-LSeg", "InternVideo2", "MoSca", "4D Gaussian Feature Field"], "generation": ["4D Gaussian Splatting"], "execution": []}, "summary": "Input monocular video is reconstructed into a 4D Gaussian scene with unified latent features distilled from SAM2, CLIP-LSeg, and InternVideo2. GPT-4o interprets language prompts to plan tasks, optimizes parameters via iterative feedback on rendered outputs, and executes segmentation, editing, or VQA through the feature field decoders."}, {"id": "Xie_FilmComposer_LLM-Driven_Music_Production_for_Silent_Film_Clips", "title": "FilmComposer: LLM-Driven Music Production for Silent Film Clips", "authors": ["Zhifeng Xie", "Qile He", "Youjia Zhu", "Qiwei He", "Mengtian Li"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Xie_FilmComposer_LLM-Driven_Music_Production_for_Silent_Film_Clips_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Audio_Speech", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-4V"], "non_llm_models": {"perception": ["GPT-4V", "CRT (Controllable Rhythm Transformer)", "optical flow algorithms", "Musicnn", "Madmom", "ImageBind"], "generation": ["Rhythm-Controllable MusicGen", "MT3", "Midi2abc", "T5"], "execution": ["Reaper DAW"]}, "summary": "Film clips are processed by GPT-4V and optical flow to extract visual attributes and motion, while CRT extracts rhythm spots. Rhythm-Controllable MusicGen generates waveform music conditioned on these inputs, which is transcribed to MIDI/ABC notation. A multi-agent system (AutoGen-based) assesses musicality, regenerating if needed, then plans arrangement and mixing schemes. Finally, an Execution Agent controls Reaper DAW to execute the arrangement and output cinematic-quality music."}, {"id": "Ma_DrVideo_Document_Retrieval_Based_Long_Video_Understanding", "title": "DrVideo: Document Retrieval Based Long Video Understanding", "authors": ["Ziyu Ma", "Chenhui Gou", "Hengcan Shi", "Bin Sun", "Shutao Li", "Hamid Rezatofighi", "Jianfei Cai"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Ma_DrVideo_Document_Retrieval_Based_Long_Video_Understanding_CVPR_2025_paper.pdf", "code": "https://github.com/Upper9527/DrVideo", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "DeepSeek", "Mistral-8x7B"], "non_llm_models": {"perception": ["LLaVA-NeXT", "LaViLa", "BLIP-2", "OpenAI Embedding Model"], "generation": [], "execution": []}, "summary": "Raw video is densely sampled and converted to an initial text document using VLMs (LLaVA-NeXT/LaViLa/BLIP-2). An embedding-based retrieval module identifies top-K key frames, which are augmented with detailed descriptions. A multi-stage agent loop (Planning Agent checks sufficiency, Interaction Agent finds missing frames) iteratively refines the document via VLM calls until the Answering Module performs chain-of-thought reasoning to generate the final answer."}, {"id": "Lin_ChatHuman_Chatting_about_3D_Humans_with_Tools", "title": "ChatHuman: Chatting about 3D Humans with Tools", "authors": ["Jing Lin", "Yao Feng", "Weiyang Liu", "Michael J. Black"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Lin_ChatHuman_Chatting_about_3D_Humans_with_Tools_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["LLaVA-1.5", "GPT-4", "Vicuna"], "non_llm_models": {"perception": ["HMR 2.0", "SAM", "GroundingDINO", "DECA", "CLIFF-BEDLAM", "DECO", "CLIP", "Whisper", "INSTRUCTOR"], "generation": ["PoseScript", "Stable Diffusion", "text-to-motion generation model", "image-to-video generation model"], "execution": []}, "summary": "User queries (text/image/3D) are processed by LLaVA with retrieved tool documentation via RAG. The LLM plans a tool graph (node, chain, or DAG) and invokes specialist perception or generation tools. Tool outputs (meshes, parameters) are transformed into visual/textual formats via a transformation module. The LLM discriminates between multiple tool results when available, selects the best output, and generates an integrated final response combining tool results with world knowledge."}, {"id": "Yang_3D-Mem_3D_Scene_Memory_for_Embodied_Exploration_and_Reasoning", "title": "3D-Mem: 3D Scene Memory for Embodied Exploration and Reasoning", "authors": ["Yuncong Yang", "Han Yang", "Jiachen Zhou", "Peihao Chen", "Hongxin Zhang", "Yilun Du", "Chuang Gan"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Yang_3D-Mem_3D_Scene_Memory_for_Embodied_Exploration_and_Reasoning_CVPR_2025_paper.pdf", "code": "https://github.com/UMass-Foundation-Model/3D-Mem", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "LLaVA-7B"], "non_llm_models": {"perception": ["ConceptGraph", "SAM", "CLIP"], "generation": [], "execution": ["Habitat-sim Pathfinder"]}, "summary": "RGB-D observations are processed by ConceptGraph (using SAM for segmentation and CLIP for features) to incrementally build Memory Snapshots (co-visible object clusters) and Frontier Snapshots (unexplored regions). A VLM (GPT-4o or LLaVA) retrieves relevant snapshots via symbolic prefiltering, reasons over the visual memory to decide whether to answer or explore, and navigates to selected frontiers using a pathfinder until the task is completed."}, {"id": "Yin_UniGoal_Towards_Universal_Zero-shot_Goal-oriented_Navigation", "title": "UniGoal: Towards Universal Zero-shot Goal-oriented Navigation", "authors": ["Hang Yin", "Xiuwei Xu", "Linqing Zhao", "Ziwei Wang", "Jie Zhou", "Jiwen Lu"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Yin_UniGoal_Towards_Universal_Zero-shot_Goal-oriented_Navigation_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaMA-2-7B"], "non_llm_models": {"perception": ["LLaVA-v1.6-Mistral-7B", "CLIP", "LightGlue"], "generation": [], "execution": ["Deterministic local policy"]}, "summary": "RGB-D observations are processed by LLaVA and CLIP to construct an online scene graph. The goal is converted to a uniform graph representation. Graph matching determines the matching state (zero/partial/perfect). LLaMA-2-7B plans exploration strategies based on the matching state: decomposing the goal graph for frontier selection (Stage 1), coordinate projection and anchor pair alignment (Stage 2), or scene graph correction and verification (Stage 3). A deterministic local policy executes the low-level actions, while a blacklist mechanism prevents repeated exploration of failed matches."}, {"id": "Zhou_Code-as-Monitor_Constraint-aware_Visual_Programming_for_Reactive_and_Proactive_Robotic_Failure", "title": "Code-as-Monitor: Constraint-aware Visual Programming for Reactive and Proactive Robotic Failure Detection", "authors": ["Enshen Zhou", "Qi Su", "Cheng Chi", "Zhizheng Zhang", "Zhongyuan Wang", "Tiejun Huang", "Lu Sheng", "He Wang"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Zhou_Code-as-Monitor_Constraint-aware_Visual_Programming_for_Reactive_and_Proactive_Robotic_Failure_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["ConSeg", "CoTracker", "SAM", "LLaVA"], "generation": [], "execution": ["CLIPort", "ReKep", "ARP", "DexGraspNet 2.0"]}, "summary": "GPT-4o generates subgoals and textual constraints from task instructions. ConSeg extracts geometric constraint elements (points/lines/surfaces) from multi-view RGB-D. GPT-4o then generates Python monitor code visually prompted by these elements. During execution, CoTracker tracks elements in real-time, and the monitor code evaluates constraint satisfaction. If violations are detected, feedback loops back to GPT-4o for re-planning while robot policies execute the physical actions."}, {"id": "Lin_JarvisIR_Elevating_Autonomous_Driving_Perception_with_Intelligent_Image_Restoration", "title": "JarvisIR: Elevating Autonomous Driving Perception with Intelligent Image Restoration", "authors": ["Yunlong Lin", "Zixu Lin", "Haoyu Chen", "Panwang Pan", "Chenxin Li", "Sixiang Chen", "Kairun Wen", "Yeying Jin", "Wenbo Li", "Xinghao Ding"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Lin_JarvisIR_Elevating_Autonomous_Driving_Perception_with_Intelligent_Image_Restoration_CVPR_2025_paper.pdf", "code": "https://github.com/LYL1015/JarvisIR", "pattern": "LLM + Perception + Generation", "domain": "Autonomous_Driving", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Llava-Llama3-8b"], "non_llm_models": {"perception": ["Q-instruct", "MUSIQ", "MANIQA"], "generation": ["SCUnet", "StableSR-turbo", "Real-ESRGAN", "IDT", "UDR-S2Former", "Img2img-turbo", "RIDCP", "KANet", "HVI-CIDNet", "LightenDiff", "Snowformer"], "execution": []}, "summary": "The user inputs a degraded image to Llava-Llama3, which assesses the degradation type and severity, generates a chain-of-thought rationale, and plans a task sequence selecting specific expert restoration models. The selected generation models (e.g., Real-ESRGAN for super-resolution, SCUnet for denoising) process the image sequentially. The VLM then integrates the restoration results and outputs the final restored image."}, {"id": "Long_CheckManual_A_New_Challenge_and_Benchmark_for_Manual-based_Appliance_Manipulation", "title": "CheckManual: A New Challenge and Benchmark for Manual-based Appliance Manipulation", "authors": ["Yuxing Long", "Jiyao Zhang", "Mingjie Pan", "Tianshu Wu", "Taewhan Kim", "Hao Dong"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Long_CheckManual_A_New_Challenge_and_Benchmark_for_Manual-based_Appliance_Manipulation_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Grounding-DINO", "SAM", "Paddle OCR", "FoundationPose"], "generation": [], "execution": ["AnyGrasp", "VoxPoser", "Franka Panda flying gripper"]}, "summary": "The ManualPlan framework first extracts text from PDF manuals using Paddle OCR and parses visual elements using GPT-4o. GPT-4o then plans manipulation steps and aligns detected parts (via Grounding-DINO and SAM) with manual descriptions using Set-of-Mark prompting. FoundationPose estimates 6-DoF object pose, and execution is performed by AnyGrasp or VoxPoser controlling a Franka Panda gripper to manipulate appliance parts."}, {"id": "Yue_V-Stylist_Video_Stylization_via_Collaboration_and_Reflection_of_MLLM_Agents", "title": "V-Stylist: Video Stylization via Collaboration and Reflection of MLLM Agents", "authors": ["Zhengrong Yue", "Shaobin Zhuang", "Kunchang Li", "Yanbo Ding", "Yali Wang"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Yue_V-Stylist_Video_Stylization_via_Collaboration_and_Reflection_of_MLLM_Agents_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "DAG", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2-VL", "Mistral8x7B"], "non_llm_models": {"perception": ["AutoShot"], "generation": ["Stable Diffusion v1.5", "AnimateDiff", "ControlNet v1.1", "Tile ControlNet", "Depth ControlNet", "Softedge ControlNet", "Lineart ControlNet"], "execution": []}, "summary": "Input video is first processed by AutoShot to detect shots and Qwen2-VL to generate shot captions. Mistral8x7B translates captions to prompts and performs tree-of-thought search to select a style model. The Style Artist then uses Stable Diffusion with AnimateDiff and multiple ControlNets to render stylized shots. Qwen2-VL scores the output, triggering iterative weight refinement via reflection until quality thresholds are met."}, {"id": "Zhu_SegAgent_Exploring_Pixel_Understanding_Capabilities_in_MLLMs_by_Imitating_Human", "title": "SegAgent: Exploring Pixel Understanding Capabilities in MLLMs by Imitating Human Annotator Trajectories", "authors": ["Muzhi Zhu", "Yuzhuo Tian", "Hao Chen", "Chunluan Zhou", "Qingpei Guo", "Yang Liu", "Ming Yang", "Chunhua Shen"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Zhu_SegAgent_Exploring_Pixel_Understanding_Capabilities_in_MLLMs_by_Imitating_Human_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaVA-v1.5-7B", "Qwen-VL-7B"], "non_llm_models": {"perception": [], "generation": [], "execution": ["SAM (Segment Anything Model)", "SimpleClick"]}, "summary": "The user provides an image and text prompt. The MLLM receives the image with the current mask overlaid and generates text-based click coordinates (actions). These are executed by SAM or SimpleClick to update the mask state, which is fed back to the MLLM. This iterative MDP continues with PRM-guided tree search for robust multi-step decision-making until the segmentation converges."}, {"id": "Ge_AutoPresent_Designing_Structured_Visuals_from_Scratch", "title": "AutoPresent: Designing Structured Visuals from Scratch", "authors": ["Jiaxin Ge", "Zora Zhiruo Wang", "Xuhui Zhou", "Yi-Hao Peng", "Sanjay Subramanian", "Qinyue Tan", "Maarten Sap", "Alane Suhr", "Daniel Fried", "Graham Neubig", "Trevor Darrell"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Ge_AutoPresent_Designing_Structured_Visuals_from_Scratch_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaMA-3.1-8B", "GPT-4o", "DeepseekCoder-7B", "CodeLlama-7B"], "non_llm_models": {"perception": ["GPT-4o (vision)", "LLaVA-1.5"], "generation": ["DALL-E 3", "Stable Diffusion 2"], "execution": ["python-pptx", "Google Chrome (browser automation)", "Bing Image Search API"]}, "summary": "User provides a natural language instruction. The LLM generates Python code using the SLIDESLIB library, which is then executed to create a PPTX slide. During execution, the code calls image generation models (DALL-E 3) or search APIs to obtain visuals. In an optional refinement loop, GPT-4o perceives the rendered slide image and feeds back to the LLM to regenerate improved code."}, {"id": "Huang_PEACE_Empowering_Geologic_Map_Holistic_Understanding_with_MLLMs", "title": "PEACE: Empowering Geologic Map Holistic Understanding with MLLMs", "authors": ["Yangyu Huang", "Tianyi Gao", "Haoran Xu", "Qihao Zhao", "Yang Song", "Zhipeng Gui", "Tengchao Lv", "Hao Chen", "Lei Cui", "Scarlett Li", "Furu Wei"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Huang_PEACE_Empowering_Geologic_Map_Holistic_Understanding_with_MLLMs_CVPR_2025_paper.pdf", "code": "https://github.com/microsoft/PEACE", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Map component detector", "Legend unit detector"], "generation": [], "execution": []}, "summary": "The HIE module uses vision detectors to localize map components and legend units, then GPT-4o extracts local information from cropped regions to build global metadata. The DKI module routes queries to domain experts (geologist/K2, geographer/GEE APIs, seismologist/earthquake databases) to retrieve external knowledge. Finally, the PEQA module combines metadata, external knowledge, and relevant image crops for GPT-4o to generate the final text answer."}, {"id": "Marsili_Visual_Agentic_AI_for_Spatial_Reasoning_with_a_Dynamic_API", "title": "Visual Agentic AI for Spatial Reasoning with a Dynamic API", "authors": ["Damiano Marsili", "Rohun Agrawal", "Yisong Yue", "Georgia Gkioxari"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Marsili_Visual_Agentic_AI_for_Spatial_Reasoning_with_a_Dynamic_API_CVPR_2025_paper.pdf", "code": "https://github.com/damianomarsili/VADAR", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Molmo", "GroundingDINO", "SAM", "UniDepth"], "generation": [], "execution": []}, "summary": "VADAR dynamically generates a Python API via LLM agents (Signature, Implementation) verified by a Python interpreter, then synthesizes programs that call learned vision specialists—Molmo, GroundingDINO, SAM, and UniDepth—to extract spatial information and compute answers deterministically."}, {"id": "Liu_ReasonGrounder_LVLM-Guided_Hierarchical_Feature_Splatting_for_Open-Vocabulary_3D_Visual_Grounding", "title": "ReasonGrounder: LVLM-Guided Hierarchical Feature Splatting for Open-Vocabulary 3D Visual Grounding and Reasoning", "authors": ["Zhenyang Liu", "Yikai Wang", "Sixiao Zheng", "Tongying Pan", "Longfei Liang", "Yanwei Fu", "Xiangyang Xue"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Liu_ReasonGrounder_LVLM-Guided_Hierarchical_Feature_Splatting_for_Open-Vocabulary_3D_Visual_Grounding_CVPR_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Translator", "Coordinator"], "llm_models": ["LLaVA 1.5"], "non_llm_models": {"perception": ["SAM (ViT-H)", "CLIP (OpenCLIP ViT-B/16)", "3D Gaussian Splatting"], "generation": [], "execution": []}, "summary": "The user provides a text query and top-down view to LLaVA, which reasons about the target object and generates an explanation. CLIP then selects the most relevant reference view from training images. SAM extracts 2D masks that are projected into a 3D Gaussian Splatting field with depth-based physical scales. Hierarchical feature splatting groups Gaussians by scale and selects the appropriate group via clustering to localize the target object, enabling amodal perception even under occlusion."}, {"id": "Deng_Motion-Grounded_Video_Reasoning_Understanding_and_Perceiving_Motion_at_Pixel_Level", "title": "Motion-Grounded Video Reasoning: Understanding and Perceiving Motion at Pixel Level", "authors": ["Andong Deng", "Tongjia Chen", "Shoubin Yu", "Taojiannan Yang", "Lincoln Spencer", "Yapeng Tian", "Ajmal Saeed Mian", "Mohit Bansal", "Chen Chen"], "venue": "CVPR", "year": 2025, "url": "https://openaccess.thecvf.com/content/CVPR2025/papers/Deng_Motion-Grounded_Video_Reasoning_Understanding_and_Perceiving_Motion_at_Pixel_Level_CVPR_2025_paper.pdf", "code": "https://github.com/dengandong/GroundMoRe", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaVA"], "non_llm_models": {"perception": ["CLIP", "Spatiotemporal Pooling mechanism"], "generation": ["SAM (Segment Anything Model)", "Temporal Localization Head (MLP)"], "execution": []}, "summary": "Video frames are first encoded by CLIP with spatiotemporal pooling to extract visual features. These features along with the input question are processed by LLaVA, which performs reasoning and generates special [SEG] and [LOC] tokens. The [SEG] tokens are decoded by SAM to produce spatial segmentation masks, while the [LOC] tokens are decoded by an MLP to generate binary temporal masks, together forming the final spatiotemporal segmentation output."}, {"id": "12578", "title": "BlenderAlchemy: Editing 3D Graphics with Vision-Language Models", "authors": ["Ian Huang", "Guandao Yang", "Leonidas Guibas"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/12578.pdf", "code": null, "pattern": "LLM + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Tight", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": [], "generation": ["DALL-E 3"], "execution": []}, "summary": "GPT-4V orchestrates an iterative loop that generates candidate Blender Python program edits, executes them via Blender's deterministic Python runtime to produce rendered images, and evaluates the results to refine the program. DALL-E 3 optionally generates reference images to ground abstract text prompts. No learned action or perception models are involved beyond the orchestrating VLM."}, {"id": "3276", "title": "Responsible Visual Editing", "authors": ["Minheng Ni", "Yeli Shen", "Yabin Zhang", "Wangmeng Zuo"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/03276.pdf", "code": "https://github.com/kodenii/Responsible-Visual-Editing", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": ["Semantic-SAM"], "generation": ["Stable Diffusion Inpainting"], "execution": []}, "summary": "CoEditor employs a two-stage process: (1) Perceptual Cognitive Process (PCP) where GPT-4V coordinates with Semantic-SAM to locate editable regions in the risky image using visual and language prompts, and (2) Behavioral Cognitive Process (BCP) where GPT-4V plans the editing strategy and generates target descriptions, which are then fed to Stable Diffusion Inpainting to produce the final responsible image."}, {"id": "2965", "title": "Propose, Assess, Search: Harnessing LLMs for Goal-Oriented Planning in Instructional Videos", "authors": ["Mohaiminul Islam", "Tushar Nagarajan", "Huiyu Wang", "FU-JEN CHU", "Kris Kitani", "Gedas Bertasius", "Xitong Yang"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/02965.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Llama-2-70B"], "non_llm_models": {"perception": ["VideoCLIP", "CLIP", "Sentence-BERT"], "generation": [], "execution": []}, "summary": "VideoCLIP processes video history and CLIP processes goal images to generate text descriptions of observations. Llama-2 proposes K candidate subsequent actions, which are assessed by four value functions measuring generation likelihood, embedding similarity to admissible actions (via Sentence-BERT), LLM-based partial plan evaluation, and task graph coherence. A breadth-first search algorithm with pruning and backtracking selects the optimal action plan."}, {"id": "2711", "title": "CoReS: Orchestrating the Dance of Reasoning and Segmentation", "authors": ["Xiaoyi Bao", "Siyang Sun", "Shuailei Ma", "Kecheng Zheng", "Yuxin Guo", "Guosheng Zhao", "Yun Zheng", "Xingang Wang"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/02711.pdf", "code": "https://github.com/baoxiaoyi/CoReS", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaVA-7B-v0"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "SAM-ViT-H image encoder"], "generation": ["SAM mask decoder"], "execution": []}, "summary": "CoReS employs a dual-chain structure where LLaVA generates a chain-of-reasoning with hierarchical [LOC] and [SEG] tokens based on the image and complex query. The embeddings of these tokens are iteratively refined using mask features from the previous segmentation step (via a Token Refiner with cross-attention) and fed into SAM's mask decoder to progressively generate the final fine-grained segmentation mask."}, {"id": "11877", "title": "O2V-Mapping: Online Open-Vocabulary Mapping with Neural Implicit Representation", "authors": ["Muer Tie", "Julong Wei", "Zhengjun Wang", "Ke Wu", "Shanshuai Yuan", "Kaizhao Zhang", "Jie Jia", "Jieru Zhao", "Zhongxue Gan", "Wenchao Ding"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/11877.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["LLM (Large Language Model)"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)", "CLIP", "VLM (Vision Language Model)"], "generation": [], "execution": []}, "summary": "RGBD streams are processed by SAM for instance segmentation and CLIP for object-level language feature extraction, which are fused into an online voxel-based neural implicit representation (O2V Field) with MLP decoders. The LLM acts as a central agent that queries the O2V Field for grounded object localization and planning via tree search, and invokes VLM to caption rendered views when semantic content requires visual interpretation."}, {"id": "6341", "title": "LLaVA-Plus: Learning to Use Tools for Creating Multimodal Agents", "authors": ["Shilong Liu", "Hao Cheng", "Haotian Liu", "Hao Zhang", "Feng Li", "Tianhe Ren", "Xueyan Zou", "Jianwei Yang", "Hang Su", "Jun Zhu", "Lei Zhang", "Jianfeng Gao", "Chunyuan Li"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/06341.pdf", "code": "https://github.com/LLaVA-VL/LLaVA-Plus-Codebase", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["LLaVA"], "non_llm_models": {"perception": ["Grounding DINO", "SAM", "OpenSeeD", "BLIP2", "RAM", "EasyOCR", "SEEM", "Semantic SAM", "CLIP"], "generation": ["Stable Diffusion", "ControlNet", "Instruct-Pix2Pix"], "execution": []}, "summary": "The user provides a multimodal query (image + text) to LLaVA, which analyzes the intent and generates JSON API calls to select and invoke appropriate tools from the skill repository. Perception tools (for detection, segmentation, OCR) or generation tools (Stable Diffusion, ControlNet for image synthesis/editing) execute and return structured outputs (bounding boxes, masks, or generated images) back to LLaVA. LLaVA then aggregates these tool execution results with the original query context to produce the final natural language response and/or present the generated visual content."}, {"id": "5554", "title": "LLMGA: Multimodal Large Language Model based Generation Assistant", "authors": ["Bin Xia", "Shiyin Wang", "Yingfan Tao", "Yitong Wang", "Jiaya Jia"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/05554.pdf", "code": "https://github.com/dvlab-research/LLMGA", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Translator", "Coordinator"], "llm_models": ["LLaVA (Vicuna-based)"], "non_llm_models": {"perception": ["CLIP"], "generation": ["Stable Diffusion 1.5", "ControlNet", "DiffRIR"], "execution": []}, "summary": "Input images are encoded by CLIP and fed into the MLLM along with text instructions. The MLLM generates detailed text prompts (marked with special tokens) based on its reasoning, which are then processed by Stable Diffusion to generate or edit images. For inpainting and outpainting tasks, DiffRIR optionally post-processes the output to correct texture, brightness, and contrast disparities between generated and preserved regions."}, {"id": "3012", "title": "HYDRA: A Hyper Agent for Dynamic Compositional Visual Reasoning", "authors": ["Fucai Ke", "Zhixi Cai", "Simindokht Jahangard", "Weiqing Wang", "Pari Delir Haghighi", "Hamid Rezatofighi"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/03012.pdf", "code": "https://github.com/haotian-liu/LLaVA", "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["ChatGPT"], "non_llm_models": {"perception": ["GLIP", "BLIP2", "LLaVA-1.5", "MiDaS", "XVLM"], "generation": [], "execution": ["DQN-based RL Agent"]}, "summary": "ChatGPT serves as a planner to generate diverse instruction samples and as a reasoner to synthesize Python code. A DQN-based RL agent controller evaluates instruction validity and selects the best sample or requests alternatives. The Python code is executed by an interpreter calling visual foundation models (GLIP, BLIP2, LLaVA-1.5, MiDaS, XVLM) for perception. Results are textualized and accumulated in a State Memory Bank, enabling iterative refinement."}, {"id": "1267", "title": "ScanReason: Empowering 3D Visual Grounding with Reasoning Capabilities", "authors": ["CHENMING ZHU", "Tai Wang", "Wenwei Zhang", "Kai Chen", "Xihui Liu"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/01267.pdf", "code": "https://github.com/ZCMax/ScanReason", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["3D-LLM (FlanT5XL-3B)"], "non_llm_models": {"perception": ["3D point cloud encoder", "BLIP2 (2D image encoder)"], "generation": [], "execution": []}, "summary": "The pipeline takes a 3D scene and implicit question as input. The 3D-LLM performs visual-centric reasoning over scene features (extracted by 2D/3D perception encoders) and generates a <LOC> token. The Query Selection Module uses the token's embedding (hloc) to retrieve relevant features from the 3D point cloud encoder, which the 3D Box Decoder uses to predict 3D bounding boxes. The Chain-of-Grounding mechanism enables iterative refinement by feeding grounded object information back to the LLM to update the query for subsequent rounds."}, {"id": "1143", "title": "NavGPT-2: Unleashing Navigational Reasoning Capability for Large Vision-Language Models", "authors": ["Gengze Zhou", "Yicong Hong", "Zun Wang", "Xin Eric Wang", "Qi Wu"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/01143.pdf", "code": "https://github.com/GengzeZhou/NavGPT-2", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["FlanT5-XL", "FlanT5-XXL", "Vicuna-7B", "Vicuna-13B"], "non_llm_models": {"perception": ["ViT-g/14", "Q-former"], "generation": [], "execution": ["Graph-based navigation policy network (cross-modal transformer with GASA)"]}, "summary": "Multi-view visual observations and instructions are processed by the Q-former and ViT-g/14 to extract visual tokens, which are fed into a frozen LLM to generate navigational reasoning and produce latent representations. These VLM latents are then passed to a graph-based navigation policy network that performs cross-modal encoding and graph-aware self-attention over the topological map to predict the next navigable node, enabling topological navigation with backtracking capabilities."}, {"id": "3241", "title": "VideoAgent: A Memory-augmented Multimodal Agent for Video Understanding", "authors": ["Yue Fan", "Xiaojian Ma", "Rujie Wu", "yuntao du", "Jiaqi Li", "Zhi Gao", "Qing Li"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/03241.pdf", "code": "https://github.com/YueFan1014/VideoAgent", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["LaViLa", "ViCLIP", "RT-DETR", "ByteTrack", "CLIP", "DINOv2", "Video-LLaVA", "text-embedding-3-large"], "generation": [], "execution": []}, "summary": "Input videos are processed into temporal memory (LaViLa captions, ViCLIP features) and object memory (RT-DETR + ByteTrack detection/tracking with CLIP/DINOv2 re-ID). Given a query, GPT-4 decomposes it and interactively invokes tools (caption retrieval, segment localization, visual question answering, object memory querying) to gather information from the unified memory, iterating until producing a final text answer."}, {"id": "7826", "title": "Situated Instruction Following", "authors": ["So Yeon Min", "Xavier Puig", "Devendra Singh Chaplot", "Tsung-Yen Yang", "Priyam Parashar", "Akshara Rai", "Ruslan Salakhutdinov", "Yonatan Bisk", "Roozbeh Mottaghi"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/07826.pdf", "code": "https://github.com/soyeonm/SIF_github", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "GPT-3.5"], "non_llm_models": {"perception": ["Detic"], "generation": [], "execution": ["Navigation tools (Go to Room, Explore Room, Follow Human)", "Manipulation tools (Grab Obj, Put Obj, Give Obj to Human)"]}, "summary": "Egocentric RGB-D observations are processed by Detic to update an allocentric semantic map. The map, instruction, and action history are converted to text prompts and fed to GPT-4o, which reasons about ambiguous situated language and plans high-level actions. These actions are executed by algorithmic navigation and manipulation tools in Habitat 3.0, with execution outcomes and new observations feeding back to update the map and inform subsequent LLM planning iterations."}, {"id": "5917", "title": "Recursive Visual Programming", "authors": ["Jiaxin Ge", "Sanjay Subramanian", "Baifeng Shi", "Roei Herzig", "Trevor Darrell"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/05917.pdf", "code": "https://github.com/para-lost/RVP", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["ViperGPT vision models", "CLIP", "BLIP", "GroundingDINO", "SAM"], "generation": [], "execution": []}, "summary": "GPT-3.5-turbo acts as a central hub generating recursive Python code for visual questions. The code executor runs this code, which calls ViperGPT vision APIs (find, verify_property, simple_query, etc.) to perceive image content. When encountering complex sub-problems, the recursive_query mechanism triggers nested LLM calls to generate modular sub-functions, with return values propagating back through the call stack to produce the final aggregated text answer."}, {"id": "6117", "title": "V-IRL: Grounding Virtual Intelligence in Real Life", "authors": ["Jihan YANG", "Runyu Ding", "Ellis L Brown", "Qi Xiaojuan", "Saining Xie"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/06117.pdf", "code": "https://github.com/VIRL-Platform/VIRL", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "Llama 2"], "non_llm_models": {"perception": ["GroundingDINO", "GLIP", "Owl-ViT", "CLIP", "EVA-02-CLIP", "LLaVA-1.5", "BLIP-2", "InstructBLIP", "PP-OCR", "OpenSeeD", "SigLIP"], "generation": [], "execution": ["V-IRL Environment APIs", "Google Maps Platform"]}, "summary": "Agents receive user intentions and background metadata, which the LLM uses to plan tasks. Vision models process street view imagery to detect objects, landmarks, and text. The LLM reasons over these perceptual outputs and environmental data to make navigation decisions, which are executed via geospatial movement APIs. This loop iterates until the agent reaches its destination or completes the task."}, {"id": "5515", "title": "Idea2Img: Iterative Self-Refinement with GPT-4V for Automatic Image Design and Generation", "authors": ["Zhengyuan Yang", "Jianfeng Wang", "Linjie Li", "Kevin Lin", "Chung-Ching Lin", "Zicheng Liu", "Lijuan Wang"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/05515.pdf", "code": "https://github.com/zyang-ur/Idea2Img", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4V", "GPT-4V(ision)"], "non_llm_models": {"perception": [], "generation": ["SDXL", "DeepFloyd IF", "Stable Diffusion", "DALL-E 3", "SDEdit"], "execution": []}, "summary": "GPT-4V receives a multimodal IDEA (interleaved image-text) and generates N initial T2I prompts. These are sent to a T2I model (e.g., SDXL) to generate draft images. GPT-4V then selects the best draft by comparing images to the IDEA, reflects on errors to produce text feedback, and revises prompts using a memory of past iterations. This iterative loop continues for T rounds to produce the final optimized image."}, {"id": "8538", "title": "OmniACT: A Dataset and Benchmark for Enabling Multimodal Generalist Autonomous Agents for Desktop and Web", "authors": ["Raghav Kapoor", "Yash Parag Butala", "Melisa A Russak", "Jing Yu Koh", "Kiran Kamble", "Waseem AlShikh", "Ruslan Salakhutdinov"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/08538.pdf", "code": null, "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo-0613", "LLaVA-v1.5-7B", "LLaVA-v1.5-13B", "Gemini-Pro", "Vicuna-1.5", "LLaMA-2", "CodeLLaMA-34B", "Palmyra-Instruct-30B", "Palmyra-X 43B"], "non_llm_models": {"perception": ["EasyOCR", "SAM (Segment Anything Model)"], "generation": [], "execution": []}, "summary": "DetACT extracts UI signals from a screenshot by running EasyOCR and SAM in parallel, followed by deterministic SSIM-based icon matching and RGB color bucketing. An LLM filters the resulting element list for task relevance and generates a PyAutoGUI action script, which is then executed by the deterministic PyAutoGUI library to perform mouse and keyboard operations."}, {"id": "10348", "title": "Constructing Concept-based Models to Mitigate Spurious Correlations with Minimal Human Effort", "authors": ["Jeeyung Kim", "Ze Wang", "Qiang Qiu"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/10348.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Verifier"], "llm_models": ["GPT-3"], "non_llm_models": {"perception": ["LLaVA", "BLIP-2", "Grounding DINO", "SAM", "CLIP"], "generation": [], "execution": []}, "summary": "GPT-3 first generates concept pools from class labels and uses LLaVA to filter spurious concepts via correlation analysis. LLaVA then performs binary concept annotation via visual question answering. An optional refinement chain orchestrated by GPT-3 uses BLIP-2 for object identification, Grounding DINO for bounding boxes, and SAM for segmentation to remove backgrounds before re-querying LLaVA for corrected annotations. The final annotations train a ResNet-50 concept bottleneck model."}, {"id": "5851", "title": "Chat-Edit-3D: Interactive 3D Scene Editing via Text Prompts", "authors": ["Shuangkang Fang", "Yufeng Wang", "Yi-Hsuan Tsai", "Yi Yang", "Wenrui Ding", "Shuchang Zhou", "Ming-Hsuan Yang"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/05851.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["VQA", "SAM", "depth estimator", "edge detector", "pose estimator", "normal map predictor", "line detector", "segmentation model", "image captioning model"], "generation": ["Stable Diffusion", "ControlNet", "Instruct-P2P", "BLIP-diffusion", "ProPainter", "Super-Resolution", "TensoRF", "Gaussian-Splatting"], "execution": []}, "summary": "User text query is parsed by ChatGPT to determine required visual tools and parameters. The Backend Executor retrieves scene atlases via the Hash-Atlas network. Perception models analyze scene content (e.g., segmentation, depth), while generation models edit the 2D atlases (e.g., object replacement, style transfer). The Hash-Atlas maps edited atlases back to 3D views, and ChatGPT formulates the natural language response with the resulting scene file."}, {"id": "1838", "title": "ControlLLM: Augment Language Models with Tools by Searching on Graphs", "authors": ["Zhaoyang Liu", "Zeqiang Lai", "Zhangwei Gao", "erfei cui", "Ziheng Li", "Xizhou Zhu", "Lewei Lu", "Qifeng Chen", "Yu Qiao", "Jifeng Dai", "Wenhai Wang"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/01838.pdf", "code": "https://github.com/OpenGVLab/ControlLLM", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["ChatGPT-3.5", "GPT-4", "LLaMA-7B", "Llama 2-13B"], "non_llm_models": {"perception": ["SAM (Segment Anything)", "CLIP", "Whisper", "object detection models", "image classification models", "VQA models", "image captioning models", "video captioning models", "video tagging models"], "generation": ["Stable Diffusion", "text-to-image models", "image-to-image models", "text-to-music models", "video-editing models"], "execution": []}, "summary": "ControlLLM first prompts an LLM to decompose a user request into subtasks. The Thoughts-on-Graph (ToG) module then runs depth-first search over a pre-built tool graph, using the LLM to score tool relevance and identify valid solution paths. A deterministic execution engine schedules the resulting tool calls—invoking learned perception and generation models via local or remote APIs, parallelizing independent branches—and finally prompts the LLM to aggregate outputs into a user-friendly response."}, {"id": "10325", "title": "VideoAgent: Long-form Video Understanding with Large Language Model as Agent", "authors": ["Xiaohan Wang", "Yuhui Zhang", "Orr Zohar", "Serena Yeung-Levy"], "venue": "ECCV", "year": 2024, "url": "https://www.ecva.net/papers/eccv_2024/papers_ECCV/papers/10325.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator"], "llm_models": ["GPT-4 (gpt-4-1106-preview)"], "non_llm_models": {"perception": ["CLIP (EVA-CLIP-8B-plus)", "LaViLa", "CogAgent", "BLIP-2", "OpenCLIP ViT-G"], "generation": [], "execution": []}, "summary": "The pipeline begins with uniform frame sampling and VLM captioning to initialize the state. GPT-4 then iteratively predicts answers and self-reflects on confidence. If confidence is insufficient, GPT-4 plans segment-specific queries, CLIP retrieves relevant frames, and VLM generates new captions. The LLM updates its state with new observations and repeats until confident, outputting a final text answer."}, {"id": "2023.emnlp-main.157", "title": "Analyzing Modular Approaches for Visual Question Decomposition", "authors": ["Apoorv Khandelwal", "Ellie Pavlick", "Chen Sun"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.emnlp-main.157.pdf", "code": "https://github.com/brown-palm/visual-question-decomposition", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Codex", "InstructGPT"], "non_llm_models": {"perception": ["BLIP-2", "GLIP", "MiDaS", "X-VLM"], "generation": [], "execution": []}, "summary": "The paper analyzes ViperGPT, where Codex generates Python programs that orchestrate calls to perception modules (BLIP-2, GLIP, MiDaS, X-VLM) via a Python interpreter augmented with symbolic algorithms. It also proposes Successive Prompting, where InstructGPT iteratively decomposes visual questions into natural language sub-questions that are answered by BLIP-2."}, {"id": "2023.findings-emnlp.824", "title": "Can Foundation Models Watch, Talk and Guide You Step by Step to Make a Cake?", "authors": ["Yuwei Bao", "Keunwoo Yu", "Yichi Zhang", "Shane Storks", "Itamar Bar-Yossef", "Alex de la Iglesia", "Megan Su", "Xiao Zheng", "Joyce Chai"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.findings-emnlp.824.pdf", "code": "https://github.com/microsoft/psi", "pattern": "LLM + Perception", "domain": "Other", "flow": "Converge", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["ChatGPT (GPT-3.5-turbo-0301)"], "non_llm_models": {"perception": ["BLIP-2", "EgoHOS", "CLIP"], "generation": [], "execution": []}, "summary": "Egocentric video frames are processed by perception models—either BLIP-2 for scene description or EgoHOS for hand/object segmentation combined with CLIP for object/state classification—to extract visual context as natural language text. This visual information converges with dialog history and task recipes in a prompt template, which ChatGPT processes to predict user intent, detect current recipe steps, identify mistakes, and generate appropriate natural language guidance for the user."}, {"id": "2023.findings-emnlp.189", "title": "Filling the Image Information Gap for VQA: Prompting Large Language Models to Proactively Ask Questions", "authors": ["Ziyue Wang", "Chi Chen", "Peng Li", "Yang Liu"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.findings-emnlp.189.pdf", "code": "https://github.com/Yushi-Hu/PromptCap", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-3 (text-davinci-002)", "LLaMA-7B", "LLaMA-13B", "gpt-3.5-turbo-0301"], "non_llm_models": {"perception": ["BLIP-2", "VinVL", "OFA", "CLIP"], "generation": [], "execution": []}, "summary": "The LLM first generates targeted sub-questions to identify missing image information needed to answer the original question. A VLM (BLIP-2) answers these questions using the image. A refinement module then filters the noisy QA pairs using CLIP-based relevance scoring. Finally, the LLM synthesizes the final answer by reasoning over the refined information combined with the initial image caption."}, {"id": "2023.findings-emnlp.226", "title": "Open-Ended Instructable Embodied Agents with Memory-Augmented Large Language Models", "authors": ["Gabriel Sarch", "Yue Wu", "Michael Tarr", "Katerina Fragkiadaki"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.findings-emnlp.226.pdf", "code": "https://github.com/Gabesarch/HELPER", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4", "text-embedding-ada-002"], "non_llm_models": {"perception": ["ALIGN (VLM)", "SOLQ (object detector)", "ZoeDepth (depth estimation)"], "generation": [], "execution": ["Executor module (navigation and manipulation primitives)"]}, "summary": "User dialogue is embedded to retrieve relevant language-program pairs from memory. GPT-4 generates a Python program over visuomotor primitives using retrieved in-context examples. The Executor executes the program using SOLQ and ZoeDepth for perception. Upon failure, ALIGN diagnoses the visual scene and feeds the failure description back to GPT-4 for re-planning. Successful executions are stored in memory for future retrieval."}, {"id": "2023.findings-emnlp.755", "title": "IdealGPT: Iteratively Decomposing Vision and Language Reasoning via Large Language Models", "authors": ["Haoxuan You", "Rui Sun", "Zhecan Wang", "Long Chen", "Gengyu Wang", "Hammad Ayyubi", "Kai-Wei Chang", "Shih-Fu Chang"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.findings-emnlp.755.pdf", "code": "https://github.com/Hxyou/IdealGPT", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["ChatGPT", "GPT-4"], "non_llm_models": {"perception": ["BLIP-2", "MiniGPT4", "LLaVA"], "generation": [], "execution": []}, "summary": "Image and main question are input to a VLM for caption generation to provide context. ChatGPT Questioner decomposes the main question into sub-questions using the caption. VLM Answerer processes the image to answer sub-questions. ChatGPT Reasoner analyzes sub-answers to determine confidence. If confident, it outputs the final text answer; otherwise, it provides feedback to the Questioner for another iteration with additional sub-questions."}, {"id": "2023.emnlp-industry.23", "title": "WordArt Designer: User-Driven Artistic Typography Synthesis using Large Language Models", "authors": ["Jun-Yan He", "Zhi-Qi Cheng", "Chenyang Li", "Jingdong Sun", "Wangmeng Xiang", "Xianhui Lin", "Xiaoyang Kang", "Zengke Jin", "Yusen Hu", "Bin Luo", "Yifeng Geng", "Xuansong Xie"], "venue": "EMNLP", "year": 2023, "url": "https://aclanthology.org/2023.emnlp-industry.23.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5", "TongYi QianWen 14b"], "non_llm_models": {"perception": ["CLIP", "ResNet18"], "generation": ["Stable Diffusion", "ControlNet", "DiffVG"], "execution": []}, "summary": "User text input is parsed by GPT-3.5 into structured prompts. The SemTypo module uses DiffVG and CLIP to generate semantic typography layouts. The StyTypo module applies Stable Diffusion (depth2image) for stylization, with outputs filtered by a ResNet18 ranking model. The TexTypo module uses ControlNet for final texture rendering. A feedback loop allows the LLM to verify quality and restart the pipeline if results are unsatisfactory."}, {"id": "2024.emnlp-industry.75", "title": "OMG-QA: Building Open-Domain Multi-Modal Generative Question Answering Systems", "authors": ["Linyong Nan", "Weining Fang", "Aylin Rasteh", "Pouya Lahabi", "Weijin Zou", "Yilun Zhao", "Arman Cohan"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-industry.75.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-Turbo", "Llama-3-8b", "Llama-3-70b", "Mistral-7b", "Mistral-8x7b", "GritLM-7b", "GritLM-8x7b"], "non_llm_models": {"perception": ["CLIP", "GTE", "SFR", "text-embedding-ada-002", "snowflake-arctic-embed-l"], "generation": [], "execution": []}, "summary": "User query is rewritten by LLM and sent to document retrievers (Wikipedia/DuckDuckGo APIs). Retrieved documents are parsed and indexed by modality (text, tables, images). Evidence retrievers using CLIP (images) and dense embeddings (text/tables) retrieve candidate evidence. Non-textual evidence is translated to text for reranking. LLM synthesizes final answer with citations. Multi-round retrieval with memory and self-reflection allows iterative refinement."}, {"id": "2024.emnlp-main.268", "title": "Retrospex: Language Agent Meets Offline Reinforcement Learning Critic", "authors": ["Yufei Xiang", "Yiqun Shen", "Yeqin Zhang", "Nguyen Cam-Tu"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.268.pdf", "code": "https://github.com/Yufei-Xiang/Retrospex", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Flan-T5-large", "LLaMA3-8B-Instruct"], "non_llm_models": {"perception": [], "generation": [], "execution": ["GRU Q-network (RL Critic)", "Sentence Transformer (for action space mapping)"]}, "summary": "The LLM generates top-k action candidates based on text observations and task descriptions. Invalid candidates are mapped to valid actions using a Sentence Transformer. A GRU-based RL Critic (trained offline with IQL on past experiences) estimates Q-values for each candidate. A dynamic rescoring mechanism combines LLM likelihoods and Q-values with step-dependent weight α(t) to select the highest-scoring action for execution in the environment."}, {"id": "2024.emnlp-main.38", "title": "MSI-Agent: Incorporating Multi-Scale Insight into Embodied Agents for Superior Planning and Decision-Making", "authors": ["Dayuan Fu", "Biqing Qi", "Yihuai Gao", "Che Jiang", "Guanting Dong", "Bowen Zhou"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.38.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5 (gpt-3.5-turbo-1106)", "GPT-4 (gpt-4-1106-preview)", "text-embedding-ada-002"], "non_llm_models": {"perception": ["VLM (Vision-Language Model)"], "generation": [], "execution": ["HELPER framework", "AgentBench framework"]}, "summary": "The system first generates multi-scale insights offline from historical experiences using GPT-4 and stores them in a database. During task execution, GPT-3.5 retrieves relevant insights via the Insight Selector and generates action plans. The HELPER or AgentBench framework executes these plans as atomic actions in the environment. If execution fails, the VLM analyzes visual feedback to provide failure reasons, enabling the LLM to replan and retry."}, {"id": "2024.emnlp-main.790", "title": "Tools Fail: Detecting Silent Errors in Faulty Tools", "authors": ["Jimin Sun", "So Yeon Min", "Yingshan Chang", "Yonatan Bisk"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.790.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "Gemini-1.5", "Command-R", "Command-R+", "GPT-4o"], "non_llm_models": {"perception": ["MaskRCNN"], "generation": [], "execution": []}, "summary": "The paper investigates LLM-based detection of silent errors in faulty tools across two settings. In the calculator setting, an LLM evaluates outputs from a deterministic calculator API. In the ALFRED embodied setting, a VLM orchestrator (GPT-4o or Gemini) evaluates outputs from a learned MaskRCNN object detector and a deterministic Fast Marching Method action planner, performing binary accept/reject classification via in-context interventions such as disclaimers and checklists."}, {"id": "2024.findings-emnlp.510", "title": "MMedAgent: Learning to Use Medical Tools with Multi-modal Agent", "authors": ["Binxu Li", "Tiankai Yan", "Yuanting Pan", "Jie Luo", "Ruiyang Ji", "Jiayuan Ding", "Zhe Xu", "Shilong Liu", "Haoyu Dong", "Zihao Lin", "Yixin Wang"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.510.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator", "Reasoner"], "llm_models": ["LLaVA-Med"], "non_llm_models": {"perception": ["Grounding DINO", "MedSAM", "BiomedCLIP"], "generation": ["ChatCAD", "ChatCAD+"], "execution": []}, "summary": "User provides a medical image and query to LLaVA-Med, which acts as an action planner to select the appropriate medical tool (from grounding, segmentation, classification, or report generation tools). The LLM generates an API call to execute the selected tool, receives the tool's output, and then aggregates this result with the original query to generate the final medical response."}, {"id": "2024.findings-emnlp.487", "title": "Learning to Ask Denotative and Connotative Questions for Knowledge-based VQA", "authors": ["Xiaoying Xing", "Peixi Xiong", "Lei Fan", "Yunxuan Li", "Ying Wu"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.487.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["YOLO", "BLIP-2 FlanT5XL"], "generation": [], "execution": []}, "summary": "The pipeline extracts object tags from images using YOLO and selects inspiring words using a lightweight policy network. GPT-3.5-turbo generates denotative and connotative questions based on these inputs. BLIP-2 answers these questions using the image, and GPT-3.5-turbo evaluates the relevance of each Q&A pair via information gain before integrating the weighted information to produce the final text answer."}, {"id": "2024.emnlp-main.284", "title": "From the Least to the Most: Building a Plug-and-Play Visual Reasoner via Data Synthesis", "authors": ["Chuanqi Cheng", "Jian Guan", "Wei Wu", "Rui Yan"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.284.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["LLaVA-1.5", "LLaMA-3-8B-Instruct"], "non_llm_models": {"perception": ["GroundingDINO", "PaddleOCR", "Deformable DETR", "BLIP-2", "InstructBLIP", "Qwen-VL", "LLaVA", "BLIP"], "generation": [], "execution": []}, "summary": "The user provides an image and question to the LLaVA-1.5 Reasoner, which decomposes the question into sub-questions. Iteratively, the Reasoner selects and invokes perception tools (GroundingDINO for object localization, PaddleOCR for text recognition, or a VLM for visual inference) to resolve each sub-question. Intermediate results (text or cropped images) are passed back to the Reasoner, which aggregates them to produce the final text answer."}, {"id": "2024.findings-emnlp.575", "title": "VDebugger: Harnessing Execution Feedback for Debugging Visual Programs", "authors": ["Xueqing Wu", "Zongyu Lin", "Songyan Zhao", "Te-Lin Wu", "Pan Lu", "Nanyun Peng", "Kai-Wei Chang"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.575.pdf", "code": "https://github.com/shirley-wu/vdebugger", "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["CodeLlama", "GPT-3.5"], "non_llm_models": {"perception": ["foundation VLMs", "object detection models"], "generation": [], "execution": ["visual program execution engine"]}, "summary": "User query → LLM (CodeLlama/GPT-3.5) generates visual program → Execution engine runs program step-by-step, invoking foundation VLMs for perception → Execution feedback (variable states, errors) collected → VDebugger critic identifies error location → VDebugger refiner corrects code → Iterate until program passes critic verification → Final answer returned."}, {"id": "2024.emnlp-main.470", "title": "Pelican: Correcting Hallucination in Vision-LLMs via Claim Decomposition and Program of Thought Verification", "authors": ["Pritish Sahu", "Karan Sikka", "Ajay Divakaran"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.470.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["YOLO", "Grounding-DINO", "LLaVA-v1.6"], "generation": [], "execution": []}, "summary": "Pelican converts an LVLM answer into a visual claim and constructs a visual table using YOLO and Grounding-DINO. GPT-4 decomposes the claim into a DAG of predicate-based sub-claims and generates Python code (Program-of-Thought) to answer them. A Python interpreter executes the code, flexibly composing the LLaVA-v1.6 VQA tool and the visual table with shared computations across dependent nodes. Finally, GPT-4 synthesizes the sub-claim answers to verify correctness, detect hallucinations, and rewrite the claim."}, {"id": "2024.emnlp-main.367", "title": "EPO: Hierarchical LLM Agents with Environment Preference Optimization", "authors": ["Qi Zhao", "Haotian Fu", "Chen Sun", "George Konidaris"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.367.pdf", "code": "https://github.com/kevinz8866/EPO", "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector"], "llm_models": ["Llama2-7B"], "non_llm_models": {"perception": ["RCNN", "Mask-RCNN", "BLIP-2"], "generation": [], "execution": []}, "summary": "Pretrained RCNN, Mask-RCNN, and BLIP-2 process egocentric RGB observations from the ALFRED simulator to produce symbolic visual and interaction feedback. A high-level Llama2 policy decomposes natural language instructions into subgoals, and a low-level Llama2 policy autoregressively generates discrete actions to execute them. A Llama2 reward model scores candidate outputs against environment feedback to build preference pairs, which are used to train both policies via Environment Preference Optimization (EPO)."}, {"id": "2024.emnlp-main.559", "title": "OmAgent: A Multi-modal Agent Framework for Complex Video Understanding with Task Divide-and-Conquer", "authors": ["Lu Zhang", "Tiancheng Zhao", "Heting Ying", "Yibo Ma", "Kyusong Lee"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.559.pdf", "code": "https://github.com/om-ai-lab/OmAgent", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Whisper", "Face recognition model", "MLLM (scene captioning)"], "generation": [], "execution": []}, "summary": "OmAgent first preprocesses video via Video2RAG: scene detection, Whisper ASR, speaker diarization, face recognition, and an MLLM generate dense scene captions that are vectorized and stored. At inference, a text encoder embeds the query to retrieve relevant segments. The DnC Loop (powered by GPT-4) recursively plans and executes tasks, invoking deterministic tools such as a rewinder for timestamp-based frame extraction, web search, and file I/O. A Rescuer handles execution errors, and Conclusive Synthesis produces the final answer."}, {"id": "2024.findings-emnlp.98", "title": "UrbanLLM: Autonomous Urban Activity Planning and Management with Large Language Models", "authors": ["Yue Jiang", "Qin Chao", "Yile Chen", "Xiucheng Li", "Shuai Liu", "Gao Cong"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.98.pdf", "code": "https://github.com/JIANGYUE61610306/UrbanLLM", "pattern": "LLM + Perception", "domain": "Other", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Llama-2-7B"], "non_llm_models": {"perception": ["time_series_prediction", "trajectory_prediction", "arrival_time_estimation", "map_mapping", "spatio-temporal_forecasting", "event_prediction", "trajectory_completion", "time_series_anomaly_detection", "time_series_imputation", "trajectory_forecasting", "spatial_relationship_inference", "bus_arrival", "taxi_availability", "recommendation"], "generation": [], "execution": []}, "summary": "User queries are processed by the fine-tuned Llama-2-7B (UrbanLLM) which decomposes them into JSON sub-tasks with dependency relationships (DAG). The LLM then matches each sub-task to appropriate spatio-temporal models from a model zoo based on their descriptions. The selected perception models execute in dependency order to extract information (predictions, estimations, mappings) from urban data APIs. Finally, UrbanLLM synthesizes the model outputs into a comprehensive natural language response."}, {"id": "2024.findings-emnlp.384", "title": "VideoINSTA: Zero-shot Long Video Understanding via Informative Spatial-Temporal Reasoning with LLMs", "authors": ["Ruotong Liao", "Max Erler", "Huiyu Wang", "Guangyao Zhai", "Gengyuan Zhang", "Yunpu Ma", "Volker Tresp"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.384.pdf", "code": "https://github.com/mayhugotong/VideoINSTA", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "Llama-3-8B"], "non_llm_models": {"perception": ["CLIP", "UniVTG", "LaViLa", "CogAgent", "LLaVA-1.5"], "generation": [], "execution": []}, "summary": "Video frames are encoded by CLIP and segmented into events using C-DPCKNN. UniVTG provides temporal grounding relevance, while LaViLa and CogAgent extract action captions and object detections respectively. The LLM summarizes this spatial-temporal information and performs iterative self-reflective question answering, merging clips progressively based on confidence and sufficiency scores until producing a final text answer."}, {"id": "2024.emnlp-main.544", "title": "TraveLER: A Modular Multi-LMM Agent Framework for Video Question-Answering", "authors": ["Chuyi Shang", "Amos You", "Sanjay Subramanian", "Trevor Darrell", "Roei Herzig"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.emnlp-main.544.pdf", "code": "https://github.com/traveler-framework/TraveLER", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5", "Llama 3"], "non_llm_models": {"perception": ["LLaVA-1.6", "GPT-4V", "BLIP-2"], "generation": [], "execution": []}, "summary": "The Planner creates a traversal plan based on the question and memory bank. The Retriever selects video timestamps to examine. The Extractor generates questions using an LLM and answers them using an LMM that perceives the selected frames, storing Q&A pairs in memory. The Evaluator verifies if sufficient information exists to answer; if yes, it outputs the answer, otherwise it feeds back to the Planner for replanning."}, {"id": "2024.findings-emnlp.483", "title": "PropTest: Automatic Property Testing for Improved Visual Programming", "authors": ["Jaywon Koo", "Ziyan Yang", "Paola Cascante-Bonilla", "Baishakhi Ray", "Vicente Ordonez"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.483.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["Llama3", "CodeLlama", "GPT-4o"], "non_llm_models": {"perception": ["BLIP-2", "GLIP", "object detectors", "depth estimators"], "generation": [], "execution": ["Python code execution engine"]}, "summary": "Given an image and question, the LLM first generates property test cases checking data type, syntax, and semantic constraints. These tests are fed into a second LLM call to generate Python code. The code is executed, invoking perception models (BLIP-2, GLIP, etc.) as needed. If the output passes all property tests, it is returned; otherwise, the system falls back to a VLM."}, {"id": "2024.findings-emnlp.708", "title": "Stark: Social Long-Term Multi-Modal Conversation with Persona Commonsense Knowledge", "authors": ["Young-Jun Lee", "Dokyong Lee", "Junyoung Youn", "Kyeong-Jin Oh", "Byungsoo Ko", "Jonghwan Hyeon", "Ho-Jin Choi"], "venue": "EMNLP", "year": 2024, "url": "https://aclanthology.org/2024.findings-emnlp.708.pdf", "code": "https://github.com/passing2961/Stark", "pattern": "LLM + Perception + Generation", "domain": "Other", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["ChatGPT (gpt-3.5-turbo-0125)", "LLaMA-3 8B"], "non_llm_models": {"perception": ["CLIP (ViT-L/14@336px)"], "generation": ["PhotoMaker", "SDXL-Lightning"], "execution": []}, "summary": "Demographics are processed by ChatGPT to generate social personas, commonsense knowledge, and personal narratives. ChatGPT then creates temporal event sequences and image descriptions. The Plan-and-Execute image aligner uses ChatGPT as a central hub to select between PhotoMaker (personalized generation), CLIP (image retrieval), or Web Search. The selected module generates or retrieves images, which are filtered and aligned to the dialogue to produce the STARK dataset. ULTRON is subsequently trained on this data for dialogue-to-image retrieval."}, {"id": "2025.emnlp-industry.57", "title": "DASR: Distributed Adaptive Scene Recognition - A Multi-Agent Cloud-Edge Framework for Language-Guided Scene Detection", "authors": ["Can Cui", "Yongkang Liu", "Seyhan Ucar", "Juntong Peng", "Ahmadreza Moradipari", "Maryam Khabazi", "Ziran Wang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-industry.57.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Autonomous_Driving", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o", "Qwen2-VL-2B"], "non_llm_models": {"perception": ["YOLOv10-base", "MiDas-v3.1-Hybrid", "OpenWeather API", "CAN Bus & IMU processors", "GPS & TomTom API"], "generation": [], "execution": []}, "summary": "Developer prompts are sent to cloud-based GPT-4o, which performs hierarchical task classification to select relevant specialist tools and sensor data specifications. The edge toolbox (YOLOv10, MiDas, weather/dynamics APIs) extracts supplementary features from vehicle sensors and video streams. The edge-deployed Qwen2-VL-2B processes the video combined with these tool outputs to make binary relevance decisions, triggering storage of relevant scenes and specified sensor data in the vehicle's limited buffer."}, {"id": "2025.emnlp-industry.19", "title": "ECom-Bench: Can LLM Agent Resolve Real-World E-commerce Customer Support Issues?", "authors": ["Haoxin Wang", "Xianhan Peng", "Huang Cheng", "Yizhe Huang", "Ming Gong", "Chenghan Yang", "Yang Liu", "Jiang Lin"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-industry.19.pdf", "code": "https://github.com/XiaoduoAILab/ECom-Bench", "pattern": "LLM + Perception + Action", "domain": "Benchmark_Evaluation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o", "DeepSeek-V3", "Doubao-1.5-Pro-32k", "Qwen-Max", "Moonshot-V1-32k"], "non_llm_models": {"perception": ["Moonshot-V1-128k-Vision-Preview", "Qwen-VL-Max", "Doubao-Pro-Vision"], "generation": [], "execution": ["MCP tools (order management)", "MCP tools (database operations)", "MCP tools (product inquiry)"]}, "summary": "A simulated user persona generates a customer query (potentially with images). The LLM agent receives the query and uses ReAct to plan responses, dispatching to vision models for image analysis or to database/MCP tools for retrieving/modifying order and product information. The LLM aggregates tool outputs and generates the final customer service response, executing necessary actions (e.g., refunds, order modifications) through the tools to resolve the issue."}, {"id": "2025.emnlp-main.564", "title": "LATTE: Learning to Think with Vision Specialists", "authors": ["Zixian Ma", "Jianguo Zhang", "Zhiwei Liu", "Jieyu Zhang", "Juntao Tan", "Manli Shu", "Juan Carlos Niebles", "Shelby Heinecke", "Huan Wang", "Caiming Xiong", "Ranjay Krishna", "Silvio Savarese"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.564.pdf", "code": "https://github.com/SalesforceAIResearch/LATTE", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Mantis-8B", "LLaVA-OneVision-7B", "Qwen2.5VL-7B", "InternVL3-8B"], "non_llm_models": {"perception": ["GroundingDINO", "DepthAnything", "EasyOCR", "CLIP", "GETOBJECTS", "DETECTFACES"], "generation": [], "execution": []}, "summary": "The VLM receives an image and question, then generates a reasoning trace consisting of interleaved thoughts and actions (tool calls). Actions invoke specific vision specialists (e.g., OCR for text, GroundingDINO for localization, DepthAnything for depth) which return structured observations. The VLM reasons over these observations in subsequent steps, iterating this process until it generates a final text answer via a TERMINATE action."}, {"id": "2025.emnlp-main.1339", "title": "GraphAgent: Agentic Graph Language Assistant", "authors": ["Yuhao Yang", "Jiabin Tang", "Lianghao Xia", "Xingchen Zou", "Yuxuan Liang", "Chao Huang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1339.pdf", "code": "https://github.com/HKUDS/GraphAgent", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-3.5-Turbo", "Llama-3-8B"], "non_llm_models": {"perception": ["GNN (heterogeneous graph model)", "Sentence-BERT (all-mpnet-base-v2)"], "generation": [], "execution": []}, "summary": "User queries are first processed by a Task Planning Agent (GPT-3.5-Turbo) to parse intent and ground graph data. If needed, a Graph Generation Agent (GPT-3.5-Turbo) constructs Semantic Knowledge Graphs from text via iterative extraction. The Task Execution Agent then encodes both explicit and generated graphs using Sentence-BERT and a GNN, projects these embeddings through a learnable linear layer into Llama-3-8B, which performs the final predictive or generative reasoning task."}, {"id": "2025.findings-emnlp.162", "title": "Visual Program Distillation with Template-Based Augmentation", "authors": ["Michal Shlapentokh-Rothman", "Yu-Xiong Wang", "Derek Hoiem"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.162.pdf", "code": "https://github.com/michalsr/vp_distill_", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o-Mini", "Qwen2.5-Coder", "Llama-3.2-1B", "CodeT5"], "non_llm_models": {"perception": ["InstructBLIP", "Owl-ViT2", "CLIP"], "generation": [], "execution": []}, "summary": "Given a visual question, the LLM generates a Python program using a visual programming API. An execution engine interprets this program and sequentially invokes perception models (InstructBLIP, Owl-ViT2, CLIP) to extract relevant information from the image. The execution engine aggregates the perception results to produce the final text answer."}, {"id": "2025.emnlp-main.1614", "title": "ProReason: Multi-Modal Proactive Reasoning with Decoupled Eyesight and Wisdom", "authors": ["Jingqi Zhou", "Sheng Wang", "Jingwei Dong", "Kai Liu", "Lei Li", "Jiahui Gao", "Jiyue Jiang", "Lingpeng Kong", "Chuan Wu"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1614.pdf", "code": "https://github.com/lian-tian-mo-zun/Pro_Reason", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o-mini", "Qwen2.5-72B-Instruct", "Qwen3-32B"], "non_llm_models": {"perception": ["LLaVA-NeXT-8B", "Qwen2.5-VL-7B-Instruct"], "generation": [], "execution": []}, "summary": "Given an image and question, the Dispatcher (LLM) selects either the Vision Expert (LVLM) to extract visual details or the Insight Expert (LLM) to draw inferences, storing results in textual Memory. The Referee (LLM) checks if Memory content is sufficient; if not, the process iterates. Once sufficient, the Summarizer (LLM) generates the final answer."}, {"id": "2025.findings-emnlp.1233", "title": "MEXA: Towards General Multimodal Reasoning with Dynamic Multi-Expert Aggregation", "authors": ["Shoubin Yu", "Yue Zhang", "Ziyang Wang", "Jaehong Yoon", "Mohit Bansal"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.1233.pdf", "code": "https://github.com/Yui010206/MEXA", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Router", "Reasoner", "Coordinator", "Planner"], "llm_models": ["GPT-4o", "DeepSeek"], "non_llm_models": {"perception": ["NVILA-8B", "Qwen-2.5-Omni", "LEO-Vicuna7B", "Spartun3D-Vicuna7B", "OmniCaptioner-Qwen2-5-7B"], "generation": [], "execution": []}, "summary": "User query and multimodal input are first processed by GPT-4o (router) to dynamically select relevant perception experts based on required modalities and skills. Selected experts (video, audio, 3D, medical, OCR, etc.) generate textual descriptions/captions from their respective inputs. These text outputs are then fed to DeepSeek (aggregator), which performs long-context reasoning over the combined expert outputs to produce the final text answer."}, {"id": "2025.emnlp-main.939", "title": "Med-VRAgent: A Framework for Medical Visual Reasoning-Enhanced Agents", "authors": ["Guangfu Guo", "Xiaoqian Lu", "Yue Feng"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.939.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["DeepSeek-VL-7B", "LLaVA-Med", "MiniCPM-V2"], "non_llm_models": {"perception": ["Grounding DINO", "ResNet-50", "BioClinical-BERT"], "generation": [], "execution": []}, "summary": "Grounding DINO extracts ROIs from medical images, enhanced via Visual Token Edit. A Teacher VLM generates step-by-step guidance, a Student VLM produces answers, and an Assessor VLM provides reward/feedback. MCTS coordinates exploration of reasoning paths, with a Reflection module retrieving external knowledge to refine answers, ultimately outputting medical reports or VQA answers."}, {"id": "2025.findings-emnlp.720", "title": "OAgents: An Empirical Study of Building Effective Agents", "authors": ["He Zhu", "Tianrui Qin", "King Zhu", "Heyuan Huang", "Yeyi Guan", "Jinxiang Xia", "Hanhao Li", "Yi Yao", "Ningning Wang", "Pai Liu", "Tianhao Peng", "Xin Gui", "Li Xiaowan", "Yuhui Liu", "Xiangru Tang", "Jian Yang", "Ge Zhang", "Xitong Gao", "Yuchen Eleanor Jiang", "Changwang Zhang", "Jun Wang", "Jiaheng Liu", "Wangchunshu Zhou"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.720.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Benchmark_Evaluation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "Claude-3-7", "GPT-4o", "OpenAI-o1", "Gemini-2.5", "DeepSeek-R1", "GPT-4.1"], "non_llm_models": {"perception": ["Whisper-1", "Vision-Language Models"], "generation": [], "execution": []}, "summary": "OAGENTS uses an LLM orchestrator to dynamically plan and decompose tasks. It invokes learned perception models (Whisper-1 for audio, VLMs for image/video) alongside deterministic tools including multi-source web search APIs, crawlers, browser automation, and document parsers to gather and process information. A hierarchical memory module with vectorized retrieval and test-time scaling strategies (reflection, best-of-N voting) support iterative reasoning and answer selection."}, {"id": "2025.emnlp-main.1133", "title": "Orchestrating Audio: Multi-Agent Framework for Long-Video Audio Synthesis", "authors": ["Yehang Zhang", "Xinli Xu", "Xiaojie Xu", "Doudou Zhang", "Li Liu", "Ying-Cong Chen"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1133.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen-max", "Qwen-plus"], "non_llm_models": {"perception": ["Qwen2.5-VL"], "generation": ["MMAudio", "V2A", "T2A"], "execution": []}, "summary": "Multi-shot video is processed by the Storyboarder (scene detection) and Scriptwriter (visual captioning using Qwen2.5-VL) collaborating via Decision-Correction to produce a structured video script. The Designer then creates audio annotations (foreground/background sounds, volume) and collaborates with the Generator through a GRO loop, where the Generator retrieves audio labels via RAG and synthesizes audio using MMAudio/V2A/T2A models, followed by hierarchical mixing and volume adjustment to produce synchronized long-form audio."}, {"id": "2025.emnlp-main.728", "title": "PPTAgent: Generating and Evaluating Presentations Beyond Text-to-Slides", "authors": ["Hao Zheng", "Xinyan Guan", "Hao Kong", "Wenkai Zhang", "Jia Zheng", "Weixiang Zhou", "Hongyu Lin", "Yaojie Lu", "Xianpei Han", "Le Sun"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.728.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o-2024-08-06", "Qwen2.5-72B-Instruct", "Qwen2-VL-72B-Instruct"], "non_llm_models": {"perception": ["Qwen2-VL-72B-Instruct"], "generation": [], "execution": ["Python REPL environment"]}, "summary": "Stage I: Qwen2-VL analyzes reference presentation images to cluster slides and extract content schemas. Stage II: The LLM generates a presentation outline based on the input document and schemas, then produces editing actions (API calls) to modify HTML-rendered reference slides. A Python REPL executes these actions, with a self-correction loop that feeds execution errors back to the LLM for iterative refinement until the final presentation is generated."}, {"id": "2025.findings-emnlp.567", "title": "“Where Does This Strange Smell Come from?”: Enabling Conversational Interfaces for Artificial Olfaction", "authors": ["Xueyi Zhou", "Qi Lu", "Dong-Kyu Chae"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.567.pdf", "code": "https://github.com/HokyeeJau/CIAO", "pattern": "LLM + Perception", "domain": "Other", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o", "Qwen-Plus", "DeepSeek-V3", "Gemini-2.0-Flash", "ChatGPT-4.1"], "non_llm_models": {"perception": ["MLSTM-FCN", "DenseNet"], "generation": [], "execution": []}, "summary": "User queries are processed by an LLM acting as an MCP client, which selects appropriate tools (AO API, Beer Intro API, Hardware Intro API). The AO API invokes MLSTM-FCN and DenseNet classifiers to process multivariate time-series data from distributed e-nose sensors. A majority-voting mechanism aggregates results from multiple sensors to determine odor type and location, which the LLM then uses to generate contextual conversational responses."}, {"id": "2025.emnlp-main.1252", "title": "MERMAID: Multi-perspective Self-reflective Agents with Generative Augmentation for Emotion Recognition", "authors": ["Zhongyu Yang", "Junhao Song", "Siyang Song", "Wei Pang", "Yingfang Yuan"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1252.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Qwen2-VL", "LLaVA-1.5", "LLaVA-NeXT", "InstructBLIP"], "non_llm_models": {"perception": ["CLIP", "Q-Former"], "generation": ["InstructPix2Pix", "Stable Diffusion", "Flux", "ControlNet"], "execution": []}, "summary": "Input image and query are processed by a Decision Agent (MLLM) to generate an initial emotion prediction. A Textual Self-reflection Agent evaluates this prediction and provides feedback for refinement. Then, an Augmentation Agent uses diffusion models (e.g., Stable Diffusion) guided by Q-Former/CLIP to generate emotion-conditioned images. A Visual Self-reflection Agent compares these augmented images with the input to provide visual feedback. The Decision Agent iteratively refines its prediction based on alternating textual and visual feedback until the prediction converges or reaches maximum iterations."}, {"id": "2025.findings-emnlp.1350", "title": "AMANDA: Agentic Medical Knowledge Augmentation for Data-Efficient Medical Visual Question Answering", "authors": ["Ziqing Wang", "Chengsheng Mao", "Xiaole Wen", "Yuan Luo", "Kaize Ding"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.1350.pdf", "code": "https://github.com/REAL-Lab-NU/AMANDA", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "GPT-4o-mini", "DeepSeek-R1-Distill-Qwen-32B"], "non_llm_models": {"perception": ["LLaVA-Med", "Med-InstructBLIP", "Med-BLIVA", "PubMed-CLIP"], "generation": [], "execution": []}, "summary": "Medical images and questions are first processed by the Perceiver (Med-MLLM) to generate captions and initial answers. The Reasoner (GPT-4o) synthesizes a refined answer, which the Evaluator checks for confidence. If insufficient, the Explorer performs coarse-to-fine question decomposition to extract deeper visual details from the Perceiver, or the Retriever queries the SPOKE biomedical knowledge graph for external grounding, with results fed back iteratively until a confident final answer is produced."}, {"id": "2025.findings-emnlp.564", "title": "AgentThink: A Unified Framework for Tool-Augmented Chain-of-Thought Reasoning in Vision-Language Models for Autonomous Driving", "authors": ["Kangan Qian", "Sicong Jiang", "Yang Zhong", "Ziang Luo", "Zilin Huang", "Tianze Zhu", "Kun Jiang", "Mengmeng Yang", "Zheng Fu", "Jinyu Miao", "Yining Shi", "He Zhe Lim", "Li Liu", "Tianbao Zhou", "Hongyi Wang", "Huang Yu", "Yifei Hu", "Guang Li", "Guang Chen", "Hao Ye", "Lijun Sun", "Diange Yang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.564.pdf", "code": "https://github.com/curryqka/AgentThink", "pattern": "LLM + Perception", "domain": "Autonomous_Driving", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL-7B"], "non_llm_models": {"perception": ["open-vocabulary detector", "depth estimator", "object detection model", "motion prediction model", "occupancy model", "mapping model"], "generation": [], "execution": []}, "summary": "Multi-view visual input and driving questions are processed by Qwen2.5-VL-7B, which generates chain-of-thought reasoning with dynamic tool calls to an autonomous driving tool library (containing perception and prediction models). External tools return structured outputs (detections, depth, trajectories, occupancy), which the VLM integrates to verify intermediate reasoning steps and generate the final driving decision or answer."}, {"id": "2025.emnlp-main.473", "title": "CARD: Cross-modal Agent Framework for Generative and Editable Residential Design", "authors": ["Pengyu Zeng", "Jun Yin", "Miao Zhang", "Yuqin Dai", "Jizhizi Li", "ZhanXiang Jin", "Shuai Lu"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.473.pdf", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": [], "generation": ["Text2FloorEdit", "RL-Net", "WD-Net", "3D Modeler"], "execution": []}, "summary": "User free-text input is converted by GPT-4 (Product Manager) into structured CMI-P point representations. Text2FloorEdit uses RL-Net to generate the residential layout and WD-Net to add doors/windows/walls, producing a floor plan image. GPT-4 Auditor agents verify compliance with building codes and user requirements; if rejected, the Assistant Designer agent revises specifications for iterative regeneration. Once approved, the 3D Modeler renders the final visualization."}, {"id": "2025.findings-emnlp.49", "title": "GenPilot: A Multi-Agent System for Test-Time Prompt Optimization in Image Generation", "authors": ["Wen Ye", "Zhaocheng Liu", "Gui Yuwei", "Tingyu Yuan", "Yunyue Su", "Bowen Fang", "Chaoyang Zhao", "Qiang Liu", "Liang Wang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.49.pdf", "code": "https://github.com/27yw/GenPilot", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Qwen2-VL-72B-Instruct"], "non_llm_models": {"perception": ["BLIP-2", "MiniCPM-V 2.0"], "generation": ["DALL-E 3", "FLUX.1", "Stable Diffusion v1.4", "Stable Diffusion v2.1", "Stable Diffusion 3", "Sana-1.0", "PixArt-α"], "execution": []}, "summary": "The pipeline begins with an initial prompt and image generation. In Stage 1 (Error Analysis), the LLM decomposes the prompt and uses perception capabilities (VQA and captioning) to detect and localize semantic inconsistencies, integrating errors into a mapped list. In Stage 2 (Test-Time Optimization), a refinement agent generates candidate prompts, which are evaluated by an MLLM scorer via VQA and rating. Candidates are clustered using K-Means with Bayesian updates to select the optimal cluster, and the memory module is updated with feedback for iterative refinement until convergence."}, {"id": "2025.emnlp-main.603", "title": "LIDDIA: Language-based Intelligent Drug Discovery Agent", "authors": ["Reza Averly", "Frazier N. Baker", "Ian A Watson", "Xia Ning"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.603.pdf", "code": "https://github.com/ninglab/LIDDiA", "pattern": "LLM + Perception + Generation", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Claude 3.5 Sonnet", "DeepSeek-R1"], "non_llm_models": {"perception": ["AutoDock Vina (docking simulation)", "QED property predictor", "SAS predictor", "Lipinski's Rule predictor", "Morgan fingerprint novelty calculator"], "generation": ["Pocket2Mol", "GraphGA"], "execution": []}, "summary": "User provides a protein target and property requirements to the REASONER (LLM), which plans actions (GENERATE, OPTIMIZE, or SCREEN). The EXECUTOR invokes Pocket2Mol for de novo molecular generation or GraphGA for molecular optimization. The EVALUATOR assesses generated molecules using docking simulation and property prediction tools, computing binding affinity (Vina), drug-likeness (QED), synthetic accessibility (SAS), and novelty. Results are stored in MEMORY and fed back to the REASONER, which iteratively refines the strategy until diverse, high-quality candidates satisfying all requirements are identified."}, {"id": "2025.findings-emnlp.42", "title": "FairCoT: Enhancing Fairness in Text-to-Image Generation via Chain of Thought Reasoning with Multimodal Large Language Models", "authors": ["Zahraa Al Sahili", "Ioannis Patras", "Matthew Purver"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.42.pdf", "code": "https://github.com/zahraaalsahili/FairCoT", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "LLaMA V3.2 11B Instruct"], "non_llm_models": {"perception": ["CLIP"], "generation": ["DALL-E", "Stable Diffusion v1.5", "Stable Diffusion v2.1", "SDXL-turbo"], "execution": []}, "summary": "User query/profession → MLLM generates initial Chain-of-Thought (CoT) and fairness-aware prompts → T2I model generates images → CLIP classifies demographic attributes → Calculate bias (normalized entropy) and semantic alignment → MLLM iteratively refines CoT until fairness converges → Archive to demonstration pool for inference on new tasks."}, {"id": "2025.findings-emnlp.367", "title": "MADD: Multi-Agent Drug Discovery Orchestra", "authors": ["Gleb Vitalevich Solovev", "Alina Borisovna Zhidkovskaya", "Anastasia Orlova", "Nina Gubina", "Anastasia Vepreva", "Rodion Golovinskii", "Ilya Tonkii", "Ivan Dubrovsky", "Ivan Gurev", "Dmitry Gilemkhanov", "Denis Chistiakov", "Timur A. Aliev", "Ivan Poddiakov", "Galina Zubkova", "Ekaterina V. Skorb", "Vladimir Vinogradov", "Alexander Boukhanovsky", "Nikolay Nikitin", "Andrei Dmitrenko", "Anna Kalyuzhnaya", "Andrey Savchenko"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.367.pdf", "code": "https://github.com/ITMO-NSS-team/MADD", "pattern": "LLM + Perception + Generation", "domain": "Scientific_Discovery", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Llama-3.1-70b"], "non_llm_models": {"perception": ["FEDOT", "RDKit-based ML models", "IC50 predictors", "docking score predictors"], "generation": ["LSTM-GAN", "Transformer-CVAE"], "execution": []}, "summary": "User queries are processed by a Decomposer agent (subtask decomposition), then passed to an Orchestrator agent that plans actions and routes to specialized tools. The Orchestrator calls molecular generation models (LSTM-GAN/Transformer-CVAE) to create candidate molecules and property prediction models (FEDOT, RDKit, IC50/docking predictors) to evaluate them. Results are compiled by a Summarizer agent into structured outputs with candidate molecules and calculated properties."}, {"id": "2025.emnlp-main.717", "title": "MMAPG: A Training-Free Framework for Multimodal Multi-hop Question Answering via Adaptive Planning Graphs", "authors": ["Yiheng Hu", "Xiaoyang Wang", "Qing Liu", "Xiwei Xu", "Qian Fu", "Wenjie Zhang", "Liming Zhu"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.717.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["LLM"], "non_llm_models": {"perception": ["Vision-Language Model (Mvl)", "Text Embedding Model (ftext)", "Image Embedding Model (fimg)"], "generation": [], "execution": []}, "summary": "User queries are processed by an LLM-based planning module that constructs an Adaptive Planning Graph. The planner dispatches retrieval tasks to modality-specific modules using text/image embedding models for candidate retrieval and a Vision-Language Model for image examination. Retrieved information is verified and integrated back into the graph as nodes, with the planner iteratively determining next actions until sufficient information is gathered for the reasoning module to generate the final answer."}, {"id": "2025.emnlp-main.214", "title": "BannerAgency: Advertising Banner Design with Multimodal LLM Agents", "authors": ["Heng Wang", "Yotaro Shimose", "Shingo Takamatsu"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.214.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet"], "non_llm_models": {"perception": ["TextChecker"], "generation": ["FLUX.1-schnell", "DALL-E3"], "execution": []}, "summary": "User provides logo and banner request → Strategist (MLLM) analyzes brand identity and campaign objectives → Background Designer (MLLM) generates text-free backgrounds via FLUX.1-schnell/DALL-E3 with TextChecker validation → Foreground Designer (MLLM) creates JSON blueprints for foreground elements, iteratively refining with Design Reviewer feedback → Developer (MLLM) renders final designs as editable SVG or Figma plugin code."}, {"id": "2025.emnlp-main.913", "title": "Iterative Prompt Refinement for Safer Text-to-Image Generation", "authors": ["Jinwoo Jeon", "JunHyeok Oh", "Hayeong Lee", "Byung-Jun Lee"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.913.pdf", "code": "https://github.com/ku-dmlab/IPR", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Coordinator"], "llm_models": ["Qwen2.5-VL (3B/7B)"], "non_llm_models": {"perception": ["Q16 classifier", "NudeNet", "CLIP"], "generation": ["Stable Diffusion v1.4/v2.0/v2.1", "DALL-E 3", "SDXL 1.0"], "execution": []}, "summary": "The user prompt is first used to generate an initial image via a T2I model (Stable Diffusion/DALL-E/SDXL). The Qwen2.5-VL-based prompt refiner evaluates this image using perception models (Q16 and NudeNet for toxicity, CLIP for alignment) to assess safety and intent alignment. Based on this evaluation, the VLM either outputs the safe image or generates a refined prompt, triggering another generation iteration. This closed-loop process continues until the image meets safety criteria or a maximum iteration limit is reached."}, {"id": "2025.emnlp-main.1111", "title": "VistaWise: Building Cost-Effective Agent with Cross-Modal Knowledge Graph for Minecraft", "authors": ["Honghao Fu", "Junlong Ren", "Qi Chai", "Deheng Ye", "Yujun Cai", "Hao Wang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1111.pdf", "code": "https://github.com/PrismarineJS/mineflayer", "pattern": "LLM + Perception", "domain": "Gaming", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["YOLOv10-L"], "generation": [], "execution": []}, "summary": "YOLOv10-L detects Minecraft entities and extracts visual attributes, which are embedded into a cross-modal knowledge graph combining external textual dependencies. A retrieval-based pooling strategy extracts task-relevant subgraphs, and GPT-4o integrates this structured knowledge with memory and Chain-of-Thought reasoning to select skills and generate parameters. The resulting commands are executed deterministically via a PyAutoGUI-based desktop skill library that sends mouse and keyboard inputs to the Minecraft client."}, {"id": "2025.findings-emnlp.11", "title": "ReAL: How Can LLMs Simulate the Real Teacher? Retrieval-enhanced Agent for Adaptive Learning", "authors": ["Rui Lv", "Qi Liu", "Weibo Gao", "Jiatong Li", "Kai Zhang", "Shiwei Tong"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.11.pdf", "code": "https://github.com/karin0018/ReAL", "pattern": "LLM + Perception", "domain": "Other", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo", "Llama2-7B", "Llama3-8B"], "non_llm_models": {"perception": ["Deep Knowledge Tracing (DKT)", "Knowledge Graph (educational hierarchy)"], "generation": [], "execution": []}, "summary": "Learner logs and goals feed into the Planner (LLM), which uses educational tools to generate candidate exercises. The Actor retrieves similar learners via DKT state vectors and votes to select the next exercise. The learner attempts the exercise, and the Reflector (LLM) analyzes the feedback to update the Planner's strategy, iterating this process to construct the complete learning path."}, {"id": "2025.emnlp-main.630", "title": "CityEQA: A Hierarchical LLM Agent on Embodied Question Answering Benchmark in City Space", "authors": ["Yong Zhao", "Kai Xu", "Zhengqiu Zhu", "Yue Hu", "Zhiheng Zheng", "Yingfeng Chen", "Yatai Ji", "Chen Gao", "Yong Li", "Jincai Huang"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.630.pdf", "code": "https://github.com/tsinghua-fib-lab/CityEQA.git", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "GPT-4o"], "non_llm_models": {"perception": ["Ground-SAM"], "generation": [], "execution": []}, "summary": "PMA is a hierarchical agent where GPT-4 (Planner) parses questions into sub-tasks, GPT-4o (Manager) maintains an object-centric cognitive map using Ground-SAM for visual grounding and segmentation, and the Actor module executes navigation with A* path planning, exploration with deterministic policies, and collection with VLM-based verification. The system operates in the EmbodiedCity simulator with deterministic navigation and exploration policies, not learned action models."}, {"id": "2025.emnlp-main.810", "title": "VisEscape: A Benchmark for Evaluating Exploration-driven Decision-making in Virtual Escape Rooms", "authors": ["Seungwon Lim", "Sungwoong Kim", "Jihwan Yu", "Sungjae Lee", "Jiwan Chung", "Youngjae Yu"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.810.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator", "Verifier", "Translator"], "llm_models": ["Claude 3.5 Sonnet", "GPT-4o", "GPT-4o-mini", "Gemini-1.5-Pro", "Gemini-2.0-Flash", "Qwen-32B-Instruct", "Deepseek-R1-Distill-Qwen-32B"], "non_llm_models": {"perception": ["InternVL2.5-38B", "InternVL2-40B", "LLaVA-v1.6-34B", "LLaVA-OneVision-7B", "Qwen2.5VL-32B"], "generation": [], "execution": ["VisEscape game agent/environment", "Finite State Machine (FSM) game engine"]}, "summary": "Visual observations from the escape room are processed by VLMs or MLLMs (either directly or via caption generation for memory efficiency). The Memory Management module compresses spatial and action history into structured representations. The Reasoning module performs pre-action hypothesis formulation and post-action verification. The LLM/MLLM selects executable actions (movement, object interaction, or quiz answers), which the game agent executes in the VisEscape environment, triggering state transitions in the underlying Finite State Machine. This process iterates until the agent escapes or reaches the step limit."}, {"id": "2025.findings-emnlp.69", "title": "From Grounding to Manipulation: Case Studies of Foundation Model Integration in Embodied Robotic Systems", "authors": ["Xiuchao Sui", "Daiying Tian", "Qi Sun", "Ruirui Chen", "Dongkyu Choi", "Kenneth Kwok", "Soujanya Poria"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.69.pdf", "code": "https://github.com/xiuchao/InstructionGrounding", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-5", "Gemini 2.5", "LLaMA 3.2 Vision", "GPT-4.5", "GPT-4o", "o4-mini"], "non_llm_models": {"perception": ["GroundingDINO", "SAM", "CLIP", "DinoV2", "SigLIP"], "generation": [], "execution": ["OpenVLA", "π0", "NORA", "RT-1", "Diffusion Policy", "ACT", "Octo"]}, "summary": "The paper compares three integration paradigms for robotic manipulation: (1) end-to-end VLAs (OpenVLA, π0, NORA) that directly map visual observations and language to low-level control tokens; (2) modular pipelines where specialist perception models (GroundingDINO/SAM/CLIP) extract symbolic scene representations fed to task-specific controllers; and (3) MLLM agents (GPT-4/Gemini/LLaMA 3.2 Vision) that act as cognitive hubs, selectively invoking vision tools via function calls and issuing high-level action primitives to low-level robot controllers."}, {"id": "2025.emnlp-main.1144", "title": "Follow the Flow: Fine-grained Flowchart Attribution with Neurosymbolic Agents", "authors": ["Manan Suri", "Puneet Mathur", "Nedim Lipka", "Franck Dernoncourt", "Ryan A. Rossi", "Vivek Gupta", "Dinesh Manocha"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1144.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4V", "GPT-4o"], "non_llm_models": {"perception": ["FlowMask2Former (fine-tuned Mask2Former)", "Flow2Mermaid VLM (fine-tuned Qwen2-VL)"], "generation": [], "execution": []}, "summary": "The pipeline first segments the flowchart using FlowMask2Former to generate labeled regions. Flow2Mermaid VLM then converts the visual flowchart into symbolic Mermaid code, which is parsed into a graph structure. A neurosymbolic agent (VLM-based) iteratively interacts with this graph using symbolic tools (get_descendants, path_between, BFS, etc.) to select relevant nodes and trace attribution paths, finally mapping the attributed path back to the original image regions."}, {"id": "2025.findings-emnlp.848", "title": "DrAgent: Empowering Large Language Models as Medical Agents for Multi-hop Medical Reasoning", "authors": ["Fenglin Liu", "Zheng Li", "Hongjian Zhou", "Qingyu Yin", "Jingfeng Yang", "Xin Liu", "Zhengyang Wang", "Xianfeng Tang", "Shiyang Li", "Xiang He", "Ruijie Wang", "Bing Yin", "Xiao Gu", "Lei Clifton", "David A. Clifton"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.848.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Self_Correction", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["Phi-3.5-mini-instruct"], "non_llm_models": {"perception": ["BioLinkBERT"], "generation": ["Transformer (Vaswani et al., 2017)"], "execution": ["Physical Examinations", "Laboratory Tests", "Microbiology Tests", "Radiology Tests", "NHS Health API", "NHS Medicine API"]}, "summary": "Phi-3.5-mini receives a medical case and generates a Thought analyzing the case and selecting a medical tool. The Action component invokes the selected tool (e.g., BioLinkBERT for QA, simulated lab tests, or NHS APIs), and the Observation returns results to the LLM. This cycle repeats for multiple hops until sufficient information is gathered to generate a final treatment recommendation or answer."}, {"id": "2025.findings-emnlp.365", "title": "Beyond the Textual: Generating Coherent Visual Options for MCQs", "authors": ["Wanqiang Wang", "Longzhu He", "Wei Zheng"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.findings-emnlp.365.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5-VL-72B", "Qwen2.5-VL-7B-Instruct", "Qwen2.1-Turbo"], "non_llm_models": {"perception": ["FARE encoder"], "generation": ["FLUX-SCHNELL", "DALLE-3", "Stable Diffusion-XL", "Wanx2.1-plus"], "execution": []}, "summary": "The pipeline takes multimodal input (text, image, answer) and uses the FARE encoder to retrieve exemplars. The MLLM discriminates content convertibility and generates candidate questions/reasons via MCoT. The OQRM module selects the optimal pair using embedding similarity. Option descriptions are generated and used to retrieve template images from a database. T2I models generate visual options, which the MLLM evaluates and iteratively refines (up to 3 rounds) until meeting a quality threshold, outputting the final MCQ with coherent visual options."}, {"id": "2025.emnlp-main.1353", "title": "3MDBench: Medical Multimodal Multi-agent Dialogue Benchmark", "authors": ["Ivan Sviridov", "Amina Miftakhova", "Artemiy Tereshchenko", "Galina Zubkova", "Pavel Blinov", "Andrey Savchenko"], "venue": "EMNLP", "year": 2025, "url": "https://aclanthology.org/2025.emnlp-main.1353.pdf", "code": "https://github.com/univanxx/3mdbench", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o-mini", "Llama-3.2-Vision", "Qwen2-VL", "MedGemma-4B", "MedGemma-27B", "Gemma-27B", "Llama-3-8B", "Llava-OneVision-Qwen2-72b"], "non_llm_models": {"perception": ["EfficientNetV2-XL"], "generation": [], "execution": []}, "summary": "The Patient Agent (temperament-driven LLM) engages in multi-turn dialogue with the Doctor Agent (LVLM). The Doctor Agent analyzes medical images and optionally incorporates top-3 diagnostic predictions from a fine-tuned EfficientNetV2-XL ConvNet as external cues. The Assessor Agent (separate LVLM) evaluates the diagnostic accuracy and consultation quality of the Doctor Agent based on the complete dialogue and final diagnosis."}, {"id": "Song_LLM-Planner_Few-Shot_Grounded_Planning_for_Embodied_Agents_with_Large_Language", "title": "LLM-Planner: Few-Shot Grounded Planning for Embodied Agents with Large Language Models", "authors": ["Chan Hee Song", "Jiaman Wu", "Clayton Washington", "Brian M Sadler", "Wei-Lun Chao", "Yu Su"], "venue": "ICCV", "year": 2023, "url": "https://openaccess.thecvf.com/content/ICCV2023/papers/Song_LLM-Planner_Few-Shot_Grounded_Planning_for_Embodied_Agents_with_Large_Language_ICCV_2023_paper.pdf", "code": "https://github.com/OSU-NLP-Group/LLM-Planner", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-3 (text-davinci-003)"], "non_llm_models": {"perception": ["Object Detector (HLSM)", "Depth model"], "generation": [], "execution": ["Low-level planner (HLSM)", "Navigation model (HLSM)"]}, "summary": "GPT-3 generates high-level plans (HLP) from instructions using kNN-retrieved in-context examples and logit biases. The HLSM low-level planner executes subgoals via navigation and interaction actions. When execution fails or takes too long, the object detector provides visible objects to GPT-3, which performs grounded re-planning to update the HLP dynamically."}, {"id": "Suris_ViperGPT_Visual_Inference_via_Python_Execution_for_Reasoning", "title": "ViperGPT: Visual Inference via Python Execution for Reasoning", "authors": ["Dídac Surís", "Sachit Menon", "Carl Vondrick"], "venue": "ICCV", "year": 2023, "url": "https://openaccess.thecvf.com/content/ICCV2023/papers/Suris_ViperGPT_Visual_Inference_via_Python_Execution_for_Reasoning_ICCV_2023_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Translator"], "llm_models": ["Codex", "GPT-3"], "non_llm_models": {"perception": ["GLIP", "X-VLM", "MiDaS", "BLIP-2"], "generation": [], "execution": []}, "summary": "Given a visual input and text query, Codex generates a Python program using a provided API specification. The Python interpreter executes this code, which calls perception models (GLIP for detection, X-VLM for verification, MiDaS for depth, BLIP-2 for simple queries) and GPT-3 for external knowledge. The interpreter performs logical operations and returns the final text answer."}, {"id": "Taioli_Collaborative_Instance_Object_Navigation_Leveraging_Uncertainty-Awareness_to_Minimize_Human-Agent_Dialogues", "title": "Collaborative Instance Object Navigation: Leveraging Uncertainty-Awareness to Minimize Human-Agent Dialogues", "authors": ["Francesco Taioli", "Edoardo Zorzi", "Gianni Franchi", "Alberto Castellini", "Alessandro Farinelli", "Marco Cristani", "Yiming Wang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Taioli_Collaborative_Instance_Object_Navigation_Leveraging_Uncertainty-Awareness_to_Minimize_Human-Agent_Dialogues_ICCV_2025_paper.pdf", "code": "https://github.com/intelligolabs/CoIN", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Grounding-DINO", "BLIP-2", "LLaVA 1.6"], "generation": [], "execution": ["VLFM policy"]}, "summary": "The VLFM navigation policy (using BLIP-2 for semantic value mapping and Grounding-DINO for detection) navigates the 3D environment. Upon object detection, the Self-Questioner module initiates an iterative self-dialogue between GPT-4o and LLaVA to refine the object description with uncertainty-aware filtering. The Interaction Trigger (GPT-4o) then evaluates alignment with known target facts to decide whether to ask the user, continue navigation, or stop."}, {"id": "Cheng_AnimeGamer_Infinite_Anime_Life_Simulation_with_Next_Game_State_Prediction", "title": "AnimeGamer: Infinite Anime Life Simulation with Next Game State Prediction", "authors": ["Junhao Cheng", "Yuying Ge", "Yixiao Ge", "Jing Liao", "Ying Shan"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Cheng_AnimeGamer_Infinite_Anime_Life_Simulation_with_Next_Game_State_Prediction_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Gaming", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Mistral-7B"], "non_llm_models": {"perception": ["CLIP", "T5", "InternVL", "Animation Shot Encoder"], "generation": ["CogvideoX", "Animation Shot Decoder"], "execution": []}, "summary": "User instructions and historical action-aware multimodal representations are processed by Mistral-7B to predict next game state representations (including character states and motion scope). These representations are then decoded by the Animation Shot Decoder (based on CogvideoX) into dynamic animation shot videos, enabling consistent multi-turn anime life simulation."}, {"id": "Yang_Medical_World_Model", "title": "Medical World Model", "authors": ["Yijun Yang", "Zhao-Yang Wang", "Qiuping Liu", "Shuwen Sun", "Kang Wang", "Rama Chellappa", "Zongwei Zhou", "Alan Yuille", "Lei Zhu", "Yu-Dong Zhang", "Jieneng Chen"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Yang_Medical_World_Model_ICCV_2025_paper.pdf", "code": "https://github.com/scott-yjyang/MeWM", "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Deepseek-R1"], "non_llm_models": {"perception": ["nnUNet", "3D ResNet", "CLIP"], "generation": ["Latent Diffusion Model"], "execution": []}, "summary": "Pre-treatment CT scans are analyzed by perception models (nnUNet segments tumors, 3D ResNet extracts features). GPT-4o/Deepseek-R1 generates candidate TACE protocols, which are encoded by CLIP to condition a Latent Diffusion Model for generating post-treatment tumor simulations. An inverse dynamics model (3D ResNet with nnUNet) predicts survival risk scores from simulated outcomes, and an iterative tree search selects the optimal protocol with the lowest risk."}, {"id": "Li_Towards_Long-Horizon_Vision-Language-Action_System_Reasoning_Acting_and_Memory", "title": "Towards Long-Horizon Vision-Language-Action System: Reasoning, Acting and Memory", "authors": ["Daixun Li", "Yusi Zhang", "Mingxiang Cao", "Donglai Liu", "Weiying Xie", "Tianlin Hui", "Lunkai Lin", "Zhiqiang Xie", "Yunsong Li"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Li_Towards_Long-Horizon_Vision-Language-Action_System_Reasoning_Acting_and_Memory_ICCV_2025_paper.pdf", "code": "https://github.com/trantor2nd/MindExplore", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Verifier"], "llm_models": ["Qwen2-VL-7B-Instruct"], "non_llm_models": {"perception": ["R3M", "Pyramid Convolutional Encoder", "DistilBERT", "SAM", "SigLIP"], "generation": [], "execution": ["Multimodal Diffusion Policy (MMDP) - Base Expert", "Multimodal Diffusion Policy (MMDP) - Arm Expert"]}, "summary": "Multi-view RGB-D-LiDAR inputs are encoded by perception models (R3M, Pyramid Convolutional Encoder) and fed into Qwen2-VL-7B, which generates structured Chain-of-Thought meta-action sequences. The Memory Mechanism routes each meta-action to the appropriate MMDP expert (Base or Arm), which fuses multimodal features to generate robot control parameters. Execution feedback loops back through the Memory Mechanism to enable adaptive replanning upon failure."}, {"id": "Xu_Automated_Red_Teaming_for_Text-to-Image_Models_through_Feedback-Guided_Prompt_Iteration", "title": "Automated Red Teaming for Text-to-Image Models through Feedback-Guided Prompt Iteration with Vision-Language Models", "authors": ["Wei Xu", "Kangjie Chen", "Jiawei Qiu", "Yuyang Zhang", "Run Wang", "Jin Mao", "Tianwei Zhang", "Lina Wang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Xu_Automated_Red_Teaming_for_Text-to-Image_Models_through_Feedback-Guided_Prompt_Iteration_ICCV_2025_paper.pdf", "code": "https://github.com/Weiww-Xu/FGPI", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaVA-1.6-Mistral-7B"], "non_llm_models": {"perception": ["Q16 detector", "NSFW image detector", "multi-head safety detector"], "generation": ["Stable Diffusion", "FLUX.1-dev", "DeepFloyd IF", "DALL·E 3"], "execution": []}, "summary": "The red-teaming VLM (LLaVA) generates or rewrites text prompts and sends them to target T2I models to generate images. Safety detectors analyze the generated images and prompts for compliance. The VLM receives these evaluation results, performs chain-of-thought reasoning to analyze alignment with attack objectives, and iteratively refines prompts through feedback-guide-rewrite stages until achieving a safe prompt that induces unsafe image generation."}, {"id": "Balazadeh_Physics_Context_Builders_A_Modular_Framework_for_Physical_Reasoning_in", "title": "Physics Context Builders: A Modular Framework for Physical Reasoning in Vision-Language Models", "authors": ["Vahid Balazadeh", "Mohammadmehdi Ataei", "Hyunmin Cheong", "Amir Hosein Khasahmadi", "Rahul G. Krishnan"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Balazadeh_Physics_Context_Builders_A_Modular_Framework_for_Physical_Reasoning_in_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o", "GPT-4o-mini", "Gemini-1.5-Pro"], "non_llm_models": {"perception": ["PaliGemma-3B (fine-tuned as PCB)"], "generation": [], "execution": []}, "summary": "User query and visual input are first analyzed by a Triage Agent (LLM) to select the appropriate Physics Context Builder (PCB). The selected PCB (fine-tuned PaliGemma-3B) generates a detailed physical scene description (Human-like Narration or Structured Physics). This description, along with the original query, is provided to a Foundation Model (GPT-4o or Gemini) which performs the final reasoning to generate an answer."}, {"id": "Zhang_VTimeCoT_Thinking_by_Drawing_for_Video_Temporal_Grounding_and_Reasoning", "title": "VTimeCoT: Thinking by Drawing for Video Temporal Grounding and Reasoning", "authors": ["Jinglei Zhang", "Yuanfan Guo", "Rolandos Alexandros Potamias", "Jiankang Deng", "Hang Xu", "Chao Ma"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhang_VTimeCoT_Thinking_by_Drawing_for_Video_Temporal_Grounding_and_Reasoning_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Qwen2VL-7B"], "non_llm_models": {"perception": ["VideoCLIP-XL"], "generation": [], "execution": ["OpenCV-based progress bar tool", "OpenCV-based highlight tool"]}, "summary": "The pipeline takes a raw video and text question as input. The MLLM generates reasoning thoughts and Python code to invoke external tools. VideoCLIP-XL performs moment retrieval via video-text similarity (perception), while OpenCV-based tools execute drawing operations to overlay a temporal progress bar and highlight key segments on the video frames (execution). The annotated video is fed back to the MLLM, which iteratively reasons over the visual temporal cues to derive and output a final text answer."}, {"id": "Jiang_Multimodal_LLM_Guided_Exploration_and_Active_Mapping_using_Fisher_Information", "title": "Multimodal LLM Guided Exploration and Active Mapping using Fisher Information", "authors": ["Wen Jiang", "Boshu Lei", "Katrina Ashton", "Kostas Daniilidis"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Jiang_Multimodal_LLM_Guided_Exploration_and_Active_Mapping_using_Fisher_Information_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4o", "LLaVA-7b"], "non_llm_models": {"perception": ["3D Gaussian Splatting (3DGS)"], "generation": [], "execution": []}, "summary": "The system uses an online-learned 3D Gaussian Splatting (3DGS) representation to render bird's-eye-view maps of the environment. A multimodal LLM (GPT-4o) performs zero-shot long-horizon planning by analyzing these renderings and selecting exploration goals from detected frontiers. Short-term paths to the selected goals are generated deterministically using A* search on an occupancy map, and the best path is chosen by balancing Expected Information Gain (computed via Fisher Information from 3DGS) against localization uncertainty (Cramér-Rao bound). The robot executes discrete actions (move/turn) in the Habitat simulator, and the process iterates."}, {"id": "Liu_CoLMDriver_LLM-based_Negotiation_Benefits_Cooperative_Autonomous_Driving", "title": "CoLMDriver: LLM-based Negotiation Benefits Cooperative Autonomous Driving", "authors": ["Changxing Liu", "Genjia Liu", "Zijun Wang", "Jinchang Yang", "Siheng Chen"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Liu_CoLMDriver_LLM-based_Negotiation_Benefits_Cooperative_Autonomous_Driving_ICCV_2025_paper.pdf", "code": "https://github.com/cxliu0314/CoLMDriver", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-3B"], "non_llm_models": {"perception": ["PointPillars", "InternVL2-4B"], "generation": [], "execution": ["Transformer waypoint planner"]}, "summary": "Sensor data is processed by PointPillars (BEV perception) and InternVL2-4B (visual intention planning). Qwen2.5-3B performs multi-round language-based negotiation with critic-feedback to reach consensus on driving intentions. These intentions guide a Transformer waypoint planner that fuses BEV features and high-level guidance to generate executable waypoints and control signals."}, {"id": "Chen_Rethinking_Layered_Graphic_Design_Generation_with_a_Top-Down_Approach", "title": "Rethinking Layered Graphic Design Generation with a Top-Down Approach", "authors": ["Jingye Chen", "Zhaowen Wang", "Nanxuan Zhao", "Li Zhang", "Difan Liu", "Jimei Yang", "Qifeng Chen"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Chen_Rethinking_Layered_Graphic_Design_Generation_with_a_Top-Down_Approach_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["LLaVA-1.5-7B"], "non_llm_models": {"perception": ["SAM", "PaddleOCR"], "generation": ["Flux", "Stable Diffusion 1.5", "ControlNet", "removal models"], "execution": []}, "summary": "User intention/sketch is processed by LLaVA-1.5 to generate prompts for Flux to create a reference image. LLaVA-1.5 then creates a design plan using OCR-extracted text, specifying layer attributes. SAM extracts objects and ControlNet-based removal models fill backgrounds, with LLaVA-1.5 selecting the best removal results from multiple candidates to assemble the final layered design."}, {"id": "Liu_Preacher_Paper-to-Video_Agentic_System", "title": "Preacher: Paper-to-Video Agentic System", "authors": ["Jingwei Liu", "Ling Yang", "Hao Luo", "Fan Wang", "Hongyan Li", "Mengdi Wang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Liu_Preacher_Paper-to-Video_Agentic_System_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Generation", "domain": "Video_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Gemini-2.0-flash", "Llama"], "non_llm_models": {"perception": [], "generation": ["Wan-2.1-t2i-turbo", "Luma", "Tavus", "CosyVoice2"], "execution": []}, "summary": "Preacher is a multi-agent system where LMMs (GPT-4o, Gemini-2.0-flash, Llama) decompose a research paper into structured key scenes via Progressive Chain-of-Thought planning with iterative reflection. A Video Generation Agent then routes each scene to appropriate learned generative models—Wan-2.1 for images, Luma for video, Tavus for talking heads, and CosyVoice2 for audio—or to deterministic Python tools (manim, python-pptx, Pymol) for specialized scientific visualizations. Reflection agents verify outputs before final assembly."}, {"id": "Ji_Instruction-based_Image_Editing_with_Planning_Reasoning_and_Generation", "title": "Instruction-based Image Editing with Planning, Reasoning, and Generation", "authors": ["Liya Ji", "Chenyang Qi", "Qifeng Chen"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Ji_Instruction-based_Image_Editing_with_Planning_Reasoning_and_Generation_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["DeepSeek"], "non_llm_models": {"perception": ["LLaVA-7b", "SAM"], "generation": ["Stable Diffusion", "InstructPix2Pix", "Flux"], "execution": []}, "summary": "User provides an image and editing instruction. DeepSeek (LLM) performs Chain-of-Thought planning to decompose the instruction into sub-instructions. For each sub-instruction, LLaVA-7b and SAM perceive the current image to reason and generate an editing mask. A hint-guided diffusion model (InstructPix2Pix or Flux) then generates the edited image conditioned on the mask and sub-instruction. This process iterates through all sub-instructions to produce the final edited image."}, {"id": "Wu_Human-Object_Interaction_from_Human-Level_Instructions", "title": "Human-Object Interaction from Human-Level Instructions", "authors": ["Zhen Wu", "Jiaman Li", "Pei Xu", "C. Karen Liu"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Wu_Human-Object_Interaction_from_Human-Level_Instructions_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP"], "generation": ["CoarseNet", "RefineNet", "FingerNet", "DexGraspNet", "conditional diffusion models"], "execution": ["PPO-based physics tracker"]}, "summary": "GPT-4o interprets human-level instructions and scene descriptions to generate a scene map (target object poses) and execution plan (sequence of actions). This guides CoarseNet to synthesize coarse human and object motions, followed by DexGraspNet for grasp pose generation and RefineNet to align motions with the grasp. FingerNet then generates detailed finger motions for approach and release. Finally, a PPO-based physics tracker executes the kinematic motion in a simulator to produce physically plausible interactions."}, {"id": "Tao_RoboPearls_Editable_Video_Simulation_for_Robot_Manipulation", "title": "RoboPearls: Editable Video Simulation for Robot Manipulation", "authors": ["Tang Tao", "Likui Zhang", "Youpeng Wen", "Kaidong Zhang", "Jia-Wang Bian", "Xia Zhou", "Tianyi Yan", "Kun Zhan", "Peng Jia", "Hefeng Wu", "Liang Lin", "Xiaodan Liang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Tao_RoboPearls_Editable_Video_Simulation_for_Robot_Manipulation_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["SAM", "GroundingDINO", "VGG16", "GPT-4V"], "generation": ["3D Gaussian Splatting", "LAMA", "GRM", "LGM", "libcom"], "execution": []}, "summary": "User natural language commands are processed by multiple collaborative LLM agents (Simulation Manager, Grounding, Scene Operation, etc.) which orchestrate perception models (SAM, GroundingDINO) to locate objects and generation models (3DGS, LAMA, GRM) to perform editing operations (removal, insertion, texture/color modification). The Scene Renderer outputs the final simulation video. A VLM analyzes downstream robot learning failures to generate new simulation demands, creating a closed feedback loop for iterative improvement."}, {"id": "Cao_CogNav_Cognitive_Process_Modeling_for_Object_Goal_Navigation_with_LLMs", "title": "CogNav: Cognitive Process Modeling for Object Goal Navigation with LLMs", "authors": ["Yihan Cao", "Jiazhao Zhang", "Zhinan Yu", "Shuzhen Liu", "Zheng Qin", "Qin Zou", "Bo Du", "Kai Xu"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Cao_CogNav_Cognitive_Process_Modeling_for_Object_Goal_Navigation_with_LLMs_ICCV_2025_paper.pdf", "code": "https://github.com/yhanCao/CogNav_ObjNav", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-3"], "non_llm_models": {"perception": ["OpenSEED", "GPT-4v"], "generation": [], "execution": []}, "summary": "CogNav uses OpenSEED and GPT-4v to incrementally build a heterogeneous cognitive map (scene graph, occupancy map, landmark graph) from RGB-D input. GPT-3 reasons over prompted map information to determine cognitive states and select high-level navigation landmarks. A deterministic local planner and the Fast Marching Method then compute paths to these landmarks, while the map is iteratively updated online."}, {"id": "Chen_T2I-Copilot_A_Training-Free_Multi-Agent_Text-to-Image_System_for_Enhanced_Prompt_Interpretation", "title": "T2I-Copilot: A Training-Free Multi-Agent Text-to-Image System for Enhanced Prompt Interpretation and Interactive Generation", "authors": ["Chieh-Yun Chen", "Min Shi", "Gong Zhang", "Humphrey Shi"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Chen_T2I-Copilot_A_Training-Free_Multi-Agent_Text-to-Image_System_for_Enhanced_Prompt_Interpretation_ICCV_2025_paper.pdf", "code": "https://github.com/SHI-Labs/T2I-Copilot", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o-mini"], "non_llm_models": {"perception": ["Grounding-SAM2"], "generation": ["FLUX.1-dev", "PowerPaint"], "execution": []}, "summary": "User input is processed by the Input Interpreter (GPT-4o-mini) to resolve ambiguities and generate a structured Analysis Report. The Generation Engine (GPT-4o-mini) routes the task to either FLUX.1-dev (for generation) or PowerPaint (for editing), invoking Grounding-SAM2 for segmentation masks when object-specific modifications are needed. The Quality Evaluator (GPT-4o-mini) then assesses the output; if scores are below threshold, the system iteratively refines the generation with feedback."}, {"id": "Boudjoghra_ScanEdit_Hierarchically-Guided_Functional_3D_Scan_Editing", "title": "ScanEdit: Hierarchically-Guided Functional 3D Scan Editing", "authors": ["Mohamed El Amine Boudjoghra", "Ivan Laptev", "Angela Dai"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Boudjoghra_ScanEdit_Hierarchically-Guided_Functional_3D_Scan_Editing_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Translator", "Coordinator"], "llm_models": ["LLM (unspecified, e.g., GPT-4)"], "non_llm_models": {"perception": ["VLM (Vision-Language Model)"], "generation": [], "execution": []}, "summary": "First, a VLM annotates object attributes (color, material, description) from rasterized RGB-D masks to construct a hierarchical scene graph. An LLM agent then filters the relevant subgraph for the input instruction. A planner LLM decomposes the high-level instruction into localized per-object commands with hypothesis validation. A placement LLM hierarchically generates object transformations (positions/orientations). Finally, a joint optimization combines LLM-generated constraints with physical 3D constraints (collision, boundary, support surface losses) to produce the edited scene."}, {"id": "Zhu_PASG_A_Closed-Loop_Framework_for_Automated_Geometric_Primitive_Extraction_and", "title": "PASG: A Closed-Loop Framework for Automated Geometric Primitive Extraction and Semantic Anchoring in Robotic Manipulation", "authors": ["Zhihao Zhu", "Yifan Zheng", "Siyu Pan", "Yaohui Jin", "Yao Mu"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhu_PASG_A_Closed-Loop_Framework_for_Automated_Geometric_Primitive_Extraction_and_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5VL", "GPT-4o"], "non_llm_models": {"perception": ["Semantic SAM", "SAM", "DINOv2"], "generation": [], "execution": []}, "summary": "Multi-view object images are processed by Semantic SAM and geometric-topological analysis to extract keypoints and axes. These geometric primitives are fed to VLMs (Qwen2.5VL or GPT-4o) for task-oriented semantic anchoring, which aligns primitives with functional affordances and task descriptions. A closed-loop verification mechanism detects low-confidence matches and iteratively refines them by triggering resampling from the perception models at finer segmentation granularities, outputting semantically annotated primitives for downstream robotic manipulation."}, {"id": "Zhang_AdaDrive_Self-Adaptive_Slow-Fast_System_for_Language-Grounded_Autonomous_Driving", "title": "AdaDrive: Self-Adaptive Slow-Fast System for Language-Grounded Autonomous Driving", "authors": ["Ruifei Zhang", "Junlin Xie", "Wei Zhang", "Weikai Chen", "Xiao Tan", "Xiang Wan", "Guanbin Li"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhang_AdaDrive_Self-Adaptive_Slow-Fast_System_for_Language-Grounded_Autonomous_Driving_ICCV_2025_paper.pdf", "code": "https://github.com/ReaFly/AdaDrive", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Converge", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["TinyLLaMA (1.1B)"], "non_llm_models": {"perception": ["Visual Encoder (LMDrive)", "LS-Qformer (Long-Short Q-former)"], "generation": [], "execution": ["4-layer Transformer Planner", "PID controllers"]}, "summary": "Streaming multi-view camera and LiDAR data are processed by a frozen Visual Encoder and LS-Qformer for temporal feature aggregation. The system operates two parallel paths: a fast path where a lightweight transformer planner generates waypoints from current frame features, and a slow path where TinyLLaMA processes navigation instructions and historical context from a Streaming Memory Buffer. Connector-W adaptively activates the LLM based on scene confidence, and Connector-H fuses LLM features with planner features using dynamic weighting. The final waypoints are converted to steering and acceleration commands via PID controllers."}, {"id": "Zhou_LIRA_Reasoning_Reconstruction_via_Multimodal_Large_Language_Models", "title": "LIRA: Reasoning Reconstruction via Multimodal Large Language Models", "authors": ["Zhen Zhou", "Tong Wang", "Yunkai Ma", "Xiao Tan", "Fengshui Jing"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhou_LIRA_Reasoning_Reconstruction_via_Multimodal_Large_Language_Models_ICCV_2025_paper.pdf", "code": "https://github.com/zhen6618/LIRA", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaVA-7B/13B", "ChatGPT-4o", "Qwen2.5"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)", "VLM Vision Encoder"], "generation": [], "execution": ["TIFF (Text-enhanced Instance Fusion module)", "Geometric Reconstruction Module (TSDF integration)", "Mask Decoder (SAM component)"]}, "summary": "RGB-D sequences and implicit language instructions are processed in three stages: (1) A MLLM (LLaVA) reasons about the instruction and segments 2D candidate instances via SAM; (2) Candidates are back-projected into a 3D TSDF map and fused using TIFF, which aggregates voxel, text, and bounding box features within Fragment Bounding Volumes; (3) A separate LLM (ChatGPT-4o/Qwen) performs global reasoning over fused candidate attributes to infer final target instances."}, {"id": "Zhang_RoBridge_A_Hierarchical_Architecture_Bridging_Cognition_and_Execution_for_General", "title": "RoBridge: A Hierarchical Architecture Bridging Cognition and Execution for General Robotic Manipulation", "authors": ["Kaidong Zhang", "Rongtao Xu", "Pengzhen Ren", "Junfan Lin", "Hefeng Wu", "Liang Lin", "Xiaodan Liang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhang_RoBridge_A_Hierarchical_Architecture_Bridging_Cognition_and_Execution_for_General_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["GroundingDINO", "SAM", "Track-Anything"], "generation": [], "execution": ["GEA", "DRQ-v2"]}, "summary": "GPT-4o (HCP) decomposes natural language instructions into primitive actions and generates Invariant Operable Representations (IOR) by calling GroundingDINO and SAM for object segmentation. The GEA (RL policy) consumes IOR to execute low-level robot actions. Track-Anything updates masks at high frequency for dynamic tracking, while GPT-4o performs closed-loop verification at low frequency, regenerating IOR upon failure detection to iteratively refine execution."}, {"id": "Liang_Towards_Human-like_Virtual_Beings_Simulating_Human_Behavior_in_3D_Scenes", "title": "Towards Human-like Virtual Beings: Simulating Human Behavior in 3D Scenes", "authors": ["Chen Liang", "Wenguan Wang", "Yi Yang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Liang_Towards_Human-like_Virtual_Beings_Simulating_Human_Behavior_in_3D_Scenes_ICCV_2025_paper.pdf", "code": "https://github.com/leonnnop/BehaviorHub", "pattern": "LLM + Perception + Generation + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["heuristic-based environmental perception modules"], "generation": ["conditional motion generation models", "grasp estimation model", "trajectory estimation model"], "execution": ["Habitat-Sim simulator"]}, "summary": "The agent perceives the 3D environment via heuristic modules and feeds linguistic descriptions to an LLM controller. The LLM performs value-driven MCTS planning to decompose goals into behavior trees, then invokes conditional motion generation models (with grasp/trajectory estimation) to produce 3D human motion sequences, which are executed in the Habitat-Sim simulator."}, {"id": "Yin_ToolVQA_A_Dataset_for_Multi-step_Reasoning_VQA_with_External_Tools", "title": "ToolVQA: A Dataset for Multi-step Reasoning VQA with External Tools", "authors": ["Shaofeng Yin", "Ting Lei", "Yang Liu"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Yin_ToolVQA_A_Dataset_for_Multi-step_Reasoning_VQA_with_External_Tools_ICCV_2025_paper.pdf", "code": "https://github.com/Fugtemypt123/ToolVQA-release", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["LLaVA-7B", "GPT-4o"], "non_llm_models": {"perception": ["ImageCaption", "OCR", "ObjectDetection", "RegionDescription"], "generation": ["TextToImage"], "execution": []}, "summary": "An LLM controller (LLaVA-7B or GPT-4o) plans a multi-step reasoning trajectory for VQA and sequentially invokes external tools. Learned perception models (ImageCaption, OCR, ObjectDetection, RegionDescription) extract visual information, TextToImage generates images, and deterministic tools (GoogleSearch, Calculator, Plot, ItemCount, DrawBox) provide external knowledge and drawing operations. The LLM aggregates intermediate tool outputs to derive the final answer."}, {"id": "Ke_DWIM_Towards_Tool-aware_Visual_Reasoning_via_Discrepancy-aware_Workflow_Generation_", "title": "DWIM: Towards Tool-aware Visual Reasoning via Discrepancy-aware Workflow Generation & Instruct-Masking Tuning", "authors": ["Fucai Ke", "Vijay Kumar B G", "Xingjian Leng", "Zhixi Cai", "Zaid Khan", "Weiqing Wang", "Pari Delir Haghighi", "Hamid Rezatofighi", "Manmohan Chandraker"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Ke_DWIM_Towards_Tool-aware_Visual_Reasoning_via_Discrepancy-aware_Workflow_Generation__ICCV_2025_paper.pdf", "code": "https://github.com/pokerme7777/DWIM", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Reflector", "Coordinator", "Verifier"], "llm_models": ["LLaMa-3.1-8B-Instruct", "GPT-4o"], "non_llm_models": {"perception": ["BLIP2", "LLaVA-1.5", "GroundingDINO", "YOLO-world"], "generation": [], "execution": []}, "summary": "Visual input and text query are processed by LLaMa-3.1-8B, which generates reasoning thoughts and Python code to call perception tools (BLIP2, LLaVA-1.5, GroundingDINO, YOLO-world). The LLM receives environmental feedback from tool outputs, detects discrepancies/errors, and generates 'Rethink' actions to iteratively refine tool usage until producing the final text answer."}, {"id": "Qu_IGD_Instructional_Graphic_Design_with_Multimodal_Layer_Generation", "title": "IGD: Instructional Graphic Design with Multimodal Layer Generation", "authors": ["Yadong Qu", "Shancheng Fang", "Yuxin Wang", "Xiaorui Wang", "Zhineng Chen", "Hongtao Xie", "Yongdong Zhang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Qu_IGD_Instructional_Graphic_Design_with_Multimodal_Layer_Generation_ICCV_2025_paper.pdf", "code": "https://github.com/penpot/penpot", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Tight", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen2.5"], "non_llm_models": {"perception": ["CLIP ViT-L/14"], "generation": ["Stable Diffusion"], "execution": []}, "summary": "User instructions (text and optional images) are processed by Qwen2.5, which autoregressively predicts layer attributes in a standardized format. When image generation is needed, the MLLM outputs condition queries that are projected and fed to Stable Diffusion; the generated image is then appended back to the MLLM context for subsequent layer prediction. Finally, the complete layer specification is rendered by the Penpot engine into an editable design file."}, {"id": "Gao_MMAT-1M_A_Large_Reasoning_Dataset_for_Multimodal_Agent_Tuning", "title": "MMAT-1M: A Large Reasoning Dataset for Multimodal Agent Tuning", "authors": ["Tianhong Gao", "Yannian Fu", "Weiqun Wu", "Haixiao Yue", "Shanshan Liu", "Gang Zhang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Gao_MMAT-1M_A_Large_Reasoning_Dataset_for_Multimodal_Agent_Tuning_ICCV_2025_paper.pdf", "code": "https://github.com/VIS-MPU-Agent/MMAT-1M", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["InternVL2.5", "Llama-3.2-11B-Vision-Instruct", "MiniCPM-V-2.6"], "non_llm_models": {"perception": ["Grounding DINO", "PaddleOCR", "deepface", "Scene Graph Captioning model"], "generation": [], "execution": []}, "summary": "The MLLM receives an image and question, generates Chain-of-Thought reasoning, dynamically invokes perception tools (OCR, detection, captioning) or RAG via API calls based on reasoning needs, integrates the tool outputs into its context, applies reflection to detect and correct reasoning errors, and generates the final text answer."}, {"id": "Mallis_CAD-Assistant_Tool-Augmented_VLLMs_as_Generic_CAD_Task_Solvers", "title": "CAD-Assistant: Tool-Augmented VLLMs as Generic CAD Task Solvers", "authors": ["Dimitrios Mallis", "Ahmet Serda Karadeniz", "Sebastian Cavada", "Danila Rukhovich", "Niki Foteinopoulou", "Kseniya Cherenkova", "Anis Kacem", "Djamila Aouada"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Mallis_CAD-Assistant_Tool-Augmented_VLLMs_as_Generic_CAD_Task_Solvers_ICCV_2025_paper.pdf", "code": "https://github.com/dimitrismallis/CAD-", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Davinci sketch parameterizer [21]"], "generation": [], "execution": []}, "summary": "CAD-Assistant uses GPT-4o as a planner that iteratively generates Python code actions. Code is executed in a Python interpreter equipped with the FreeCAD API. For hand-drawn sketches, a learned Davinci parameterizer [21] extracts structured CAD primitives and constraints. Deterministic tools (sketch/solid recognizers, constraint checker, cross-section extractor) render and serialize CAD state to provide multimodal feedback for iterative refinement."}, {"id": "Shen_Online_Reasoning_Video_Segmentation_with_Just-in-Time_Digital_Twins", "title": "Online Reasoning Video Segmentation with Just-in-Time Digital Twins", "authors": ["Yiqing Shen", "Bohan Liu", "Chenjia Li", "Lalithkumar Seenivasan", "Mathias Unberath"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Shen_Online_Reasoning_Video_Segmentation_with_Just-in-Time_Digital_Twins_ICCV_2025_paper.pdf", "code": "https://github.com/yiqings/jitbench", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o", "GPT-4o-mini"], "non_llm_models": {"perception": ["SAM-2", "DepthAnything-2", "OWLv2", "DINO-2"], "generation": [], "execution": []}, "summary": "Given an implicit text query, an LLM planner constructs a directed acyclic graph (DAG) execution plan and selects query-specific specialist vision models. Perception nodes (SAM-2, DepthAnything-2, OWLv2, DINO-2) process incoming video frames to build and maintain a just-in-time digital twin (dynamic scene graph with temporal integration). Reasoning nodes then operate on this digital twin—using a base LLM for semantic reasoning and an LLM-coder for spatial/temporal operations—to identify target objects and generate final segmentation masks via SAM-2."}, {"id": "Li_LLM_Thought_Divergence_and_Convergence_for_Dialogue-Based_Image_Generation_Control", "title": "LLM Thought Divergence and Convergence for Dialogue-Based Image Generation Control", "authors": ["Hui Li"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Li_LLM_Thought_Divergence_and_Convergence_for_Dialogue-Based_Image_Generation_Control_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4o-mini", "Deepseek-R1", "Llama3.3"], "non_llm_models": {"perception": ["Multimodal LLM (GPT-4o-mini)"], "generation": ["Stable Diffusion", "Janus-Pro"], "execution": []}, "summary": "The LTDC framework takes dialogue input and uses an LLM to generate multiple tree-structured reasoning chains (divergence). For each node, a prompt generation LLM converts the reasoning steps into structured prompts, which are fed to Stable Diffusion or Janus-Pro to generate images. A multimodal LLM then evaluates each image against the original dialogue to calculate coherence scores, and the system selects the highest-scoring image as the final output (convergence)."}, {"id": "Jiang_Beyond_the_Destination_A_Novel_Benchmark_for_Exploration-Aware_Embodied_Question", "title": "Beyond the Destination: A Novel Benchmark for Exploration-Aware Embodied Question Answering", "authors": ["Kaixuan Jiang", "Yang Liu", "Weixing Chen", "Jingzhou Luo", "Ziliang Chen", "Ling Pan", "Guanbin Li", "Liang Lin"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Jiang_Beyond_the_Destination_A_Novel_Benchmark_for_Exploration-Aware_Embodied_Question_ICCV_2025_paper.pdf", "code": "https://github.com/HCPLab-SYSU/EXPRESS-Bench", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "GPT-4o-mini"], "non_llm_models": {"perception": ["Prismatic VLMs (Prism-DINOSigLIP 7B)"], "generation": [], "execution": []}, "summary": "Fine-EQA uses GPT-4 to parse the question and identify task-relevant functional regions. A Prismatic VLM processes RGB observations to build and update global and functional-region semantic maps. The agent's movement is controlled by deterministic algorithmic strategies: frontier-based exploration for coarse coverage and goal-oriented exploration via masked semantic map argmax for fine-grained investigation. GPT-4o-mini decides when to terminate exploration and generates the final answer based on the latest observation."}, {"id": "Zhang_Adaptive_Articulated_Object_Manipulation_On_The_Fly_with_Foundation_Model", "title": "Adaptive Articulated Object Manipulation On The Fly with Foundation Model Reasoning and Part Grounding", "authors": ["Xiaojie Zhang", "Yuanfei Wang", "Ruihai Wu", "Kunqi Xu", "Yu Li", "Liuyu Xiang", "Hao Dong", "Zhaofeng He"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Zhang_Adaptive_Articulated_Object_Manipulation_On_The_Fly_with_Foundation_Model_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["GroundingDINO", "SAM (Segment Anything Model)", "PointNet++"], "generation": [], "execution": ["Primitive manipulation skills (grasp, pull, rotate)", "Franka Emika Panda robot controller"]}, "summary": "RGB images are first processed by GPT-4o to generate part descriptions, which guide GroundingDINO and SAM to segment the target part. The segmented part's point cloud is processed by PointNet++ to predict affordance scores. GPT-4o then reasons about the object's mechanism and generates Python code that invokes primitive skills (grasp, pull, rotate) on the robot arm, using success flags from execution to adaptively retry actions until the task is completed."}, {"id": "Fu_ORION_A_Holistic_End-to-End_Autonomous_Driving_Framework_by_Vision-Language_Instructed", "title": "ORION: A Holistic End-to-End Autonomous Driving Framework by Vision-Language Instructed Action Generation", "authors": ["Haoyu Fu", "Diankun Zhang", "Zongchuang Zhao", "Jianfeng Cui", "Dingkang Liang", "Chong Zhang", "Dingyuan Zhang", "Hongwei Xie", "Bing Wang", "Xiang Bai"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Fu_ORION_A_Holistic_End-to-End_Autonomous_Driving_Framework_by_Vision-Language_Instructed_ICCV_2025_paper.pdf", "code": "https://github.com/xiaomi-mlab/Orion", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Sequential", "coupling": "Tight", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Vicuna v1.5"], "non_llm_models": {"perception": ["EVA-02-L", "QT-Former"], "generation": [], "execution": ["VAE-based generative planner"]}, "summary": "Multi-view camera images are encoded by EVA-02-L and processed by QT-Former, which aggregates long-term temporal context via a memory bank and detects traffic elements to produce scene and history tokens. These tokens are fed into Vicuna LLM along with text instructions for driving scenario reasoning, generating a planning token. A VAE-based generative planner then decodes this token into multi-modal trajectories, aligning the reasoning and action spaces for end-to-end optimization."}, {"id": "Lee_Perspective-Aware_Reasoning_in_Vision-Language_Models_via_Mental_Imagery_Simulation", "title": "Perspective-Aware Reasoning in Vision-Language Models via Mental Imagery Simulation", "authors": ["Phillip Y. Lee", "Jihyeon Je", "Chanho Park", "Mikaela Angelina Uy", "Leonidas Guibas", "Minhyuk Sung"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Lee_Perspective-Aware_Reasoning_in_Vision-Language_Models_via_Mental_Imagery_Simulation_ICCV_2025_paper.pdf", "code": "https://github.com/KAIST-Visual-AI-Group/APC-VLM", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen2.5-VL"], "non_llm_models": {"perception": ["GroundingDINO", "SAM", "DepthPro", "OrientAnything"], "generation": [], "execution": []}, "summary": "The VLM first parses the question to identify objects of interest and the reference perspective. Vision foundation models (GroundingDINO for detection, SAM for segmentation, DepthPro for depth, OrientAnything for orientation) extract 3D spatial information to construct a scene abstraction. The abstraction is transformed into the reference viewer's egocentric coordinate frame, then fed back to the VLM as either numerical coordinates or a rendered visual prompt (colored cubes) for final perspective-aware reasoning."}, {"id": "Yasuki_GeoProg3D_Compositional_Visual_Reasoning_for_City-Scale_3D_Language_Fields", "title": "GeoProg3D: Compositional Visual Reasoning for City-Scale 3D Language Fields", "authors": ["Shunsuke Yasuki", "Taiki Miyanishi", "Nakamasa Inoue", "Shuhei Kurita", "Koya Sakamoto", "Daichi Azuma", "Masato Taki", "Yutaka Matsuo"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Yasuki_GeoProg3D_Compositional_Visual_Reasoning_for_City-Scale_3D_Language_Fields_ICCV_2025_paper.pdf", "code": "https://github.com/snskysk/GeoProg3D", "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-3.5 (gpt-3.5-turbo-instruct)"], "non_llm_models": {"perception": ["GCLF (Geography-aware City-scale 3D Language Field)", "CLIP", "SAM (Segment Anything Model)", "GroundingDINO"], "generation": [], "execution": ["Python execution engine", "GV-APIs (Geographical Vision APIs)"]}, "summary": "Given a natural language query, GPT-3.5 generates a Python program using in-context examples of GV-APIs. The Python execution engine runs this program, which calls GV-APIs (e.g., GetLandmarkSeg, GetObjectSeg, MeasureDist) that operate on the pre-trained GCLF. The GCLF uses CLIP embeddings and SAM/GroundingDINO for 3D localization and segmentation. Results are aggregated to produce the final text answer."}, {"id": "Wu_CATP-LLM_Empowering_Large_Language_Models_for_Cost-Aware_Tool_Planning", "title": "CATP-LLM: Empowering Large Language Models for Cost-Aware Tool Planning", "authors": ["Duo Wu", "Jinghe Wang", "Yuan Meng", "Yanning Zhang", "Le Sun", "Zhi Wang"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Wu_CATP-LLM_Empowering_Large_Language_Models_for_Cost-Aware_Tool_Planning_ICCV_2025_paper.pdf", "code": "https://github.com/duowuyms/OpenCATP-LLM", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Router", "Coordinator", "Reasoner"], "llm_models": ["Llama2-7B", "GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["object detection models", "image captioning models"], "generation": ["super resolution models", "colorization models", "deblurring models", "machine translation models"], "execution": []}, "summary": "Given a task description and input attributes, CATP-LLM (fine-tuned Llama2-7B) generates a DAG tool plan using Tool Planning Language (TPL) tokens. A plan executor then schedules the heterogeneous vision models (perception and generation models) according to the DAG dependencies for parallel or sequential execution, producing the final task output (image or text)."}, {"id": "Qin_RoboFactory_Exploring_Embodied_Agent_Collaboration_with_Compositional_Constraints", "title": "RoboFactory: Exploring Embodied Agent Collaboration with Compositional Constraints", "authors": ["Yiran Qin", "Li Kang", "Xiufeng Song", "Zhenfei Yin", "Xiaohong Liu", "Xihui Liu", "Ruimao Zhang", "Lei Bai"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Qin_RoboFactory_Exploring_Embodied_Agent_Collaboration_with_Compositional_Constraints_ICCV_2025_paper.pdf", "code": "https://github.com/MARS-EAI/RoboFactory", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Depth estimation models"], "generation": [], "execution": ["Diffusion Policy", "Motion primitives"]}, "summary": "GPT-4o (RoboBrain) receives task instructions and RGB observations, generates sub-goals and textual compositional constraints (logical, spatial, temporal), and invokes motion primitives to create trajectories. RoboChecker validates these trajectories against 3D occupancy and interaction constraints using depth estimation; constraint violations trigger re-planning feedback to RoboBrain. Validated trajectories form a dataset for training Diffusion Policy, which executes the final robotic actions."}, {"id": "Cai_NAVER_A_Neuro-Symbolic_Compositional_Automaton_for_Visual_Grounding_with_Explicit", "title": "NAVER: A Neuro-Symbolic Compositional Automaton for Visual Grounding with Explicit Logic Reasoning", "authors": ["Zhixi Cai", "Fucai Ke", "Simindokht Jahangard", "Maria Garcia de la Banda", "Reza Haffari", "Peter J. Stuckey", "Hamid Rezatofighi"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Cai_NAVER_A_Neuro-Symbolic_Compositional_Automaton_for_Visual_Grounding_with_Explicit_ICCV_2025_paper.pdf", "code": "https://github.com/ControlNet/NAVER", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Translator", "Reflector", "Coordinator"], "llm_models": ["GPT-4o Mini"], "non_llm_models": {"perception": ["Florence2-L", "SAM", "InternVL2-8B", "DepthAnythingV2", "XVLM", "GroundingDINO", "GLIP", "GLaMM"], "generation": [], "execution": []}, "summary": "The system processes an image and text query through a finite-state automaton: (1) Perception state extracts entities, attributes, and relations using VLMs and grounding models; (2) Logic Generation state uses the LLM to convert visual facts and query into ProbLog code; (3) Logic Reasoning state executes probabilistic inference via Scallop interpreter to rank candidates; (4) Answering state validates the top candidate using a VLM. If validation fails, the system iteratively loops back to previous states for correction before returning the final target."}, {"id": "Xie_Are_VLMs_Ready_for_Autonomous_Driving_An_Empirical_Study_from", "title": "Are VLMs Ready for Autonomous Driving? An Empirical Study from the Reliability, Data and Metric Perspectives", "authors": ["Shaoyuan Xie", "Lingdong Kong", "Yuhao Dong", "Chonghao Sima", "Wenwei Zhang", "Qi Alfred Chen", "Ziwei Liu", "Liang Pan"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Xie_Are_VLMs_Ready_for_Autonomous_Driving_An_Empirical_Study_from_ICCV_2025_paper.pdf", "code": "https://github.com/ldkong1205/Robo3D", "pattern": "LLM + Perception + Generation", "domain": "Autonomous_Driving", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Router", "Coordinator"], "llm_models": ["InternVL2"], "non_llm_models": {"perception": ["DETR3D", "BEVFormer"], "generation": ["corruption-specific denoising models"], "execution": []}, "summary": "Camera images are first analyzed by InternVL2 to identify the type of visual corruption present. Based on this identification, InternVL2 acts as a router to select and invoke the appropriate corruption-specific denoising model, which generates a restored clean image. This denoised image is then fed into BEV detection models (DETR3D or BEVFormer) to produce final 3D object detection results."}, {"id": "Agrawal_UINavBench_A_Framework_for_Comprehensive_Evaluation_of_Interactive_Digital_Agents", "title": "UINavBench: A Framework for Comprehensive Evaluation of Interactive Digital Agents", "authors": ["Harsh Agrawal", "Eldon Schoop", "Xinlei Pan", "Anuj Mahajan", "Ari Seff", "Di Feng", "Ruijia Cheng", "Andres Romero Mier Y Teran", "Esteban Gomez", "Abhishek Sundararajan", "Forrest Huang", "Amanda Swearngin", "Mohana Prasad Sathya Moorthy", "Jeff Nichols", "Alexander Toshev"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Agrawal_UINavBench_A_Framework_for_Comprehensive_Evaluation_of_Interactive_Digital_Agents_ICCV_2025_paper.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Verifier"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["UI detection model", "UGround"], "generation": [], "execution": ["Mobile device controller (iOS automation)"]}, "summary": "The agent receives a natural language goal and screenshot, uses a UI detection model to extract UI elements with Set-of-Marks prompting, feeds this structured perception to GPT-4o which reasons and plans the next action (ReACT), converts the planned action to pixel coordinates either via heuristics or UGround grounding model, and executes the action on the mobile device. A Reflexion loop enables the LLM to critique its own actions and correct errors iteratively."}, {"id": "Fan_Embodied_VideoAgent_Persistent_Memory_from_Egocentric_Videos_and_Embodied_Sensors", "title": "Embodied VideoAgent: Persistent Memory from Egocentric Videos and Embodied Sensors Enables Dynamic Scene Understanding", "authors": ["Yue Fan", "Xiaojian Ma", "Rongpeng Su", "Jun Guo", "Rujie Wu", "Xi Chen", "Qing Li"], "venue": "ICCV", "year": 2025, "url": "https://openaccess.thecvf.com/content/ICCV2025/papers/Fan_Embodied_VideoAgent_Persistent_Memory_from_Egocentric_Videos_and_Embodied_Sensors_ICCV_2025_paper.pdf", "code": "https://github.com/Embodied-VideoAgent/embodied-videoagent", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["YOLO-World", "CLIP", "DINOv2", "DUSt3R", "LaViLa", "InternVL2"], "generation": [], "execution": ["Habitat-Sim action primitives", "Franka robot arm"]}, "summary": "Egocentric video and embodied sensors (depth, pose) are processed by YOLO-World, CLIP, DINOv2, and DUSt3R to build a persistent 3D object memory with 3D re-identification. GPT-4o queries this memory via tools (query_db, vqa, spatial_loc) to reason and plan actions, then executes navigation/manipulation primitives. A VLM updates memory states based on action outcomes, forming a closed loop until task completion."}, {"id": "G2Q2Mh3avow", "title": "Socratic Models: Composing Zero-Shot Multimodal Reasoning with Language", "authors": ["Andy Zeng", "Maria Attarian", "brian ichter", "Krzysztof Choromanski", "Adrian Wong", "Stefan Welker", "Federico Tombari", "Aveek Purohit", "Michael Ryoo", "Vikas Sindhwani", "Johnny Lee", "Vincent Vanhoucke", "Pete Florence"], "venue": "ICLR", "year": 2023, "url": "https://openreview.net/pdf?id=G2Q2Mh3avow", "code": "https://github.com/google-research/google-research", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-3"], "non_llm_models": {"perception": ["CLIP", "ViLD", "Audio-Language Models (ALM)", "Speech-to-Text", "RoBERTa"], "generation": [], "execution": ["CLIPort"]}, "summary": "Multimodal inputs (images, video, audio) are processed by perception models to extract text descriptions via zero-shot classification and transcription. These descriptions undergo in-context substitution into LLM prompts, enabling GPT-3 to perform reasoning, planning, and dialogue. For robotic tasks, the LLM generates action sequences executed by CLIPort. The pipeline supports iterative refinement through natural language middleware, allowing models to exchange information in closed-loop cycles."}, {"id": "KTf4DGAzus", "title": "$\\textbf{\\textit{M}}^\\textbf{\\textit{3}}$: Towards Robust Multi-Modal Reasoning via Model Selection", "authors": ["Xiangyan Liu", "Rongxue LI", "Wei Ji", "Tao Lin"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=KTf4DGAzus", "code": "https://github.com/LINs-lab/M3", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Coordinator"], "llm_models": ["GPT"], "non_llm_models": {"perception": ["VQA models (multiple candidates)", "Localization models (text-guided object detection)", "BLIP (feature extractor)", "BERT (text encoder for graph descriptions)"], "generation": [], "execution": []}, "summary": "The user query (image + question) is first processed by an LLM (GPT) which decomposes it into a directed acyclic computation graph of subtasks. The M3 framework then uses a graph attention network (GAT) to select the optimal perception model (from candidate VQA or localization models) for each subtask node, considering input features and subtask dependencies. Finally, the selected models execute their subtasks along the graph to produce the final text answer."}, {"id": "PHGxChm1l5", "title": "Compositional VLM: Composing Visual Entities and Relationships in Large Language Models Via Communicative Decoding", "authors": ["Junyan Li", "Delin Chen", "Yining Hong", "Zhenfang Chen", "Peihao Chen", "Yikang Shen", "Chuang Gan"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=PHGxChm1l5", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Tight", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Reasoner", "Coordinator", "Translator"], "llm_models": ["Pythia-1.4B", "Pythia-2.8B"], "non_llm_models": {"perception": ["CLIP ViT-L", "YOLOX-based detector"], "generation": [], "execution": []}, "summary": "CLIP encodes the input image into embeddings that initialize the LLM context. The Pythia LLM generates text autoregressively. Upon emitting <visual> or <previsual> communication tokens, the YOLOX-based detector uses the LLM's last hidden state and image features to propose relevant ROIs. Features from these regions are extracted and fed back into the LLM via <box> or <prebox> tokens, enabling iterative vision-language communication until the final text answer is produced."}, {"id": "EnXJfQqy0K", "title": "Building Cooperative Embodied Agents Modularly with Large Language Models", "authors": ["Hongxin Zhang", "Weihua Du", "Jiaming Shan", "Qinhong Zhou", "Yilun Du", "Joshua B Tenenbaum", "Tianmin Shu", "Chuang Gan"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=EnXJfQqy0K", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "LLaMA-2", "CoLLAMA"], "non_llm_models": {"perception": ["Mask-RCNN"], "generation": [], "execution": ["Procedural execution controllers (code-based low-level action generation)"]}, "summary": "Raw RGB-D observations are processed by Mask-RCNN to extract segmentation masks and construct 3D semantic maps, which update a Memory Module (semantic, episodic, and procedural). The LLM-based Planning and Communication Modules retrieve structured information from memory to generate high-level plans and natural language messages via chain-of-thought prompting. Finally, the Execution Module retrieves procedural knowledge from memory to translate high-level plans into executable low-level primitive actions (navigation, interaction) for the embodied environment."}, {"id": "pAoqRlTBtY", "title": "Causal Modelling Agents: Causal Graph Discovery through Synergising Metadata- and Data-driven Reasoning", "authors": ["Ahmed Abdulaal", "Adamos Hadjivasiliou", "Nina Montaña-Brown", "Tiantian He", "Ayodeji Ijishakin", "Ivana Drobnjak", "Daniel Castro", "Daniel Alexander"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=pAoqRlTBtY", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Deep Structural Causal Model (DSCM)"], "generation": ["Deep Structural Causal Model (DSCM)"], "execution": []}, "summary": "User provides dataset and metadata → GPT-4 generates initial causal graph hypothesis → DSCM transmutes the graph into a computational model, trains on multi-modal data (tabular + imaging), and computes likelihood → GPT-4 post-processes results into memory → GPT-4 critiques and amends the graph based on fit and memory → iteration repeats until convergence → outputs final causal graph and trained SCM with counterfactual capabilities."}, {"id": "Pc8AU1aF5e", "title": "Synapse: Trajectory-as-Exemplar Prompting with Memory for Computer Control", "authors": ["Longtao Zheng", "Rundong Wang", "Xinrun Wang", "Bo An"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=Pc8AU1aF5e", "code": "https://github.com/ltzheng/Synapse", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-3.5", "CodeLlama-7B"], "non_llm_models": {"perception": ["text-embedding-ada-002", "element-ranking model"], "generation": [], "execution": ["browser automation environment (MiniWoB++/Mind2Web)"]}, "summary": "Task metadata is encoded by text-embedding-ada-002 to retrieve relevant trajectory exemplars from memory via similarity search. The LLM performs state abstraction on raw HTML (using few-shot prompting or the element-ranking model) to create clean observations. The LLM is then prompted with trajectory exemplars and current history to generate the next action(s), which are executed in the computer environment. This process iterates until task completion."}, {"id": "yozwqhIHXj", "title": "Image Translation as Diffusion Visual Programmers", "authors": ["Cheng Han", "James Liang", "Qifan Wang", "MAJID RABBANI", "Sohail Dianat", "Raghuveer Rao", "Yingnian Wu", "Dongfang Liu"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=yozwqhIHXj", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "DAG", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Mask2former"], "generation": ["Stable Diffusion v1.5", "Condition-flexible Diffusion Model"], "execution": []}, "summary": "GPT-4 acts as a planner to generate a visual program from the input image and text instruction. Mask2former segments the Region of Interest (RoI), Stable Diffusion inpaints the background, and the condition-flexible diffusion model performs the object translation. A Position Manipulator module finally adjusts the size and position of the translated object to produce the output image."}, {"id": "u6imHU4Ebu", "title": "Large Language Models as Generalizable Policies for Embodied Tasks", "authors": ["Andrew Szot", "Max Schwarzer", "Harsh Agrawal", "Bogdan Mazoure", "Katherine Metcalf", "Walter Talbott", "Natalie Mackraz", "R Devon Hjelm", "Alexander Toshev"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=u6imHU4Ebu", "code": "https://github.com/apple/ml-llarp", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaMA-7B", "LLaMA-13B"], "non_llm_models": {"perception": ["VisualCortex (VC1)"], "generation": [], "execution": ["Low-level skills (pick, place, navigate, open, close)"]}, "summary": "Egocentric RGB observations are encoded by the frozen VisualCortex (VC1) vision encoder and projected to the LLM embedding space via a learned MLP adapter. These are combined with embedded language instructions and fed into a frozen LLaMA backbone. The LLM's hidden outputs are projected via a learned action head to predict distributions over 70 low-level skills (e.g., pick, place, navigate) which are executed in the Habitat 2.0 simulator, with the entire system trained end-to-end using PPO reinforcement learning."}, {"id": "MNShbDSxKH", "title": "Generative Neuro-Symbolic Visual Reasoning by Growing and Reusing Modules", "authors": ["Zhenfang Chen", "Rui Sun", "Wenjun Liu", "Yining Hong", "Chuang Gan"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=MNShbDSxKH", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5-turbo-instruct", "GPT-3"], "non_llm_models": {"perception": ["CLIP", "VQA models", "depth estimation models", "localization models (LOC)"], "generation": [], "execution": ["Generated Python modules", "VisProg APIs", "ViperGPT APIs"]}, "summary": "The LLM first examines training examples to determine if new modules are needed, generates Python code implementing these modules, and iteratively debugs them against test cases before adding to a reusable library. During inference, the LLM parses input queries into executable programs composed of these modules, which orchestrate calls to perception models (CLIP, VQA, depth, localization) to extract information and compute final answers through code execution."}, {"id": "9pKtcJcMP3", "title": "Video Language Planning", "authors": ["Yilun Du", "Sherry Yang", "Pete Florence", "Fei Xia", "Ayzaan Wahid", "brian ichter", "Pierre Sermanet", "Tianhe Yu", "Pieter Abbeel", "Joshua B Tenenbaum", "Leslie Kaelbling", "Andy Zeng", "Jonathan Tompson"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=9pKtcJcMP3", "code": "https://github.com/video-language-planning/vlp_code", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["PaLM-E"], "non_llm_models": {"perception": [], "generation": ["text-to-video model"], "execution": ["goal-conditioned policy"]}, "summary": "Current image observation and language goal are processed by PaLM-E to generate candidate text actions. A text-to-video model simulates future video rollouts for each action. PaLM-E evaluates these rollouts using a learned heuristic function, and beam search selects the best branches to iteratively extend the plan. Finally, a goal-conditioned policy converts the video plan into low-level robot control actions."}, {"id": "hQVCCxQrYN", "title": "Plan-Seq-Learn: Language Model Guided RL for Solving Long Horizon Robotics Tasks", "authors": ["Murtaza Dalal", "Tarun Chiruvolu", "Devendra Singh Chaplot", "Ruslan Salakhutdinov"], "venue": "ICLR", "year": 2024, "url": "https://openreview.net/pdf?id=hQVCCxQrYN", "code": "https://github.com/planseqlearn/planseqlearn", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["SAM (Segment Anything)"], "generation": [], "execution": ["DRQ-v2", "AIT* motion planner"]}, "summary": "GPT-4 generates a high-level plan consisting of (target region, termination condition) pairs from natural language task descriptions. SAM estimates 3D poses of target regions from RGB-D images using language labels. AIT* motion planner achieves collision-free robot poses to initialize near targets. DRQ-v2 RL policy executes contact-rich manipulation using local observations until stage termination conditions are met, triggering progression to the next sub-goal."}, {"id": "9YNyiCJE3k", "title": "OSDA Agent: Leveraging Large Language Models for De Novo Design of Organic Structure Directing Agents", "authors": ["Zhaolin Hu", "Yixiao Zhou", "Zhongan Wang", "Xin Li", "Weimin Yang", "Hehe Fan", "Yi Yang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=9YNyiCJE3k", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4", "GPT-4o"], "non_llm_models": {"perception": ["CGCNN", "SMILES-BERT"], "generation": [], "execution": ["RDKit", "SCScore", "Binding Energy Estimation Model"]}, "summary": "The Actor (GPT-4) generates candidate OSDA molecules as SMILES strings using few-shot Chain-of-Thought prompting. The Evaluator validates these using RDKit (chemical rules), SCScore (synthetic complexity), and a binding energy prediction model that uses CGCNN and SMILES-BERT encoders. The Self-reflector (GPT-4o) analyzes evaluation metrics and generates improvement feedback, which is used to refine the Actor's subsequent generation attempts in an iterative loop."}, {"id": "vQFw9ryKyK", "title": "ImagineNav: Prompting Vision-Language Models as Embodied Navigator through Scene Imagination", "authors": ["Xinxin Zhao", "Wenzhe Cai", "Likun Tang", "Teng Wang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=vQFw9ryKyK", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o-mini"], "non_llm_models": {"perception": ["ResNet-18 (Where2Imagine)"], "generation": ["Diffusion-based NVS (Yu et al. 2024)"], "execution": ["VER PointNav Policy"]}, "summary": "Current panoramic RGB observation is processed by Where2Imagine (ResNet-18) to predict candidate waypoints (relative poses). A pretrained diffusion-based NVS model generates imagined future views at these waypoints. GPT-4o-mini selects the optimal direction based on the imagined images and navigation goal. The VER PointNav policy executes low-level actions to reach the selected waypoint, and the process iterates until the target is found."}, {"id": "0bmGL4q7vJ", "title": "Multi-modal Agent Tuning: Building a VLM-Driven Agent for Efficient Tool Usage", "authors": ["Zhi Gao", "Bofei Zhang", "Pengxiang Li", "Xiaojian Ma", "Tao Yuan", "Yue Fan", "Yuwei Wu", "Yunde Jia", "Song-Chun Zhu", "Qing Li"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=0bmGL4q7vJ", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router"], "llm_models": ["MiniCPM-V-8.5B", "Qwen2-VL-7B"], "non_llm_models": {"perception": ["face detection", "object localization", "visual segmentation", "image_qa"], "generation": ["image generation", "image editing"], "execution": []}, "summary": "The T3-Agent is a VLM-driven ReAct agent that iteratively generates reasoning thoughts and Python code to invoke tools. It leverages learned perception and generation tools (e.g., face detection, object localization, image generation/editing) alongside deterministic utilities (web search, file inspector, Python interpreter) to solve multi-modal tasks."}, {"id": "y9A2TpaGsE", "title": "Language Agents Meet Causality -- Bridging LLMs and Causal World Models", "authors": ["Ioannis Gkountouras", "Matthias Lindemann", "Phillip Lippe", "Efstratios Gavves", "Ivan Titov"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=y9A2TpaGsE", "code": "https://github.com/j0hngou/LLMCWM", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaMA 3"], "non_llm_models": {"perception": ["Autoencoder", "Normalizing Flow", "Causal Encoder", "Sentence-BERT"], "generation": [], "execution": ["Causal Transition Model"]}, "summary": "Current state images are encoded by the Causal World Model (autoencoder → normalizing flow → causal encoder) to extract disentangled causal variables. Given a text action description (encoded by Sentence-BERT), the Causal Transition Model predicts the next state in latent space, which is decoded to a text description. The LLM iteratively interacts with this simulator via MCTS to plan action sequences for embodied tasks."}, {"id": "Ouu3HnIVBc", "title": "ADAM: An Embodied Causal Agent in Open-World Environments", "authors": ["Shu Yu", "Chaochao Lu"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=Ouu3HnIVBc", "code": "https://github.com/OpenCausaLab/ADAM", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4-turbo"], "non_llm_models": {"perception": ["LLaVA-v1.5-13B"], "generation": [], "execution": ["Mineflayer"]}, "summary": "LLaVA-v1.5-13B processes pixel observations into text descriptions for the GPT-4 controller. The controller maintains a causal graph (technology tree) and decomposes tasks into subtasks. The interaction module executes actions in Minecraft via Mineflayer APIs. Interaction records feed into the causal model module, which uses LLM-based reasoning and intervention-based verification to update the causal graph, supporting lifelong learning and robust task execution."}, {"id": "3RLxccFPHz", "title": "An Intelligent Agentic System for Complex Image Restoration Problems", "authors": ["Kaiwen Zhu", "Jinjin Gu", "Zhiyuan You", "Yu Qiao", "Chao Dong"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=3RLxccFPHz", "code": "https://github.com/Kaiwen-Zhu/AgenticIR", "pattern": "LLM + Perception + Action", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["DepictQA"], "generation": [], "execution": ["Restormer", "DehazeFormer", "AirNet", "PromptIR", "MiOIR", "DA-CLIP", "InstructIR", "AutoDIR"]}, "summary": "Input image is analyzed by DepictQA to identify degradations. GPT-4 schedules a sequence of IR models from the toolbox. Each selected IR model executes a restoration step. DepictQA reflects on the intermediate result to verify success. If verification fails, GPT-4 reschedules and the system rolls back to try alternative tools or orders, iterating until the image is fully restored."}, {"id": "VvDEuyVXkG", "title": "Benchmarking Multimodal Retrieval Augmented Generation with Dynamic VQA Dataset and Self-adaptive Planning Agent", "authors": ["Yangning Li", "Yinghui Li", "Xinyu Wang", "Yong Jiang", "Zhen Zhang", "Xinran Zheng", "HUI WANG", "Hai-Tao Zheng", "Fei Huang", "Jingren Zhou", "Philip Yu"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=VvDEuyVXkG", "code": "https://github.com/Alibaba-NLP/OmniSearch", "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4V", "Qwen-VL-Chat", "Qwen-VL-Max", "Qwen-7B-Chat"], "non_llm_models": {"perception": ["CLIP", "CLIP-based image retriever", "web search API", "image search with textual query"], "generation": [], "execution": []}, "summary": "Input image and question are processed by a Planning Agent (MLLM) which dynamically decomposes the question into sub-questions and selects retrieval APIs (web search, CLIP-based image search, or image-to-image search). Retrieved content is passed to a Sub-question Solver (MLLM) which generates intermediate answers and feedback. The Planning Agent iteratively refines retrieval actions based on this feedback until it determines sufficient knowledge has been gathered to produce the final text answer."}, {"id": "TjP1d8PP8l", "title": "Discriminator-Guided Embodied Planning for LLM Agent", "authors": ["Haofu Qian", "Chenjia Bai", "Jiatao Zhang", "Fei Wu", "Wei Song", "Xuelong Li"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=TjP1d8PP8l", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "Llama3-70B"], "non_llm_models": {"perception": ["InternVL2-8B", "RoBERTa (discriminator)"], "generation": [], "execution": ["ScienceWorld simulator", "VirtualHome simulator"]}, "summary": "Task descriptions and optional visual observations are processed by InternVL2-8B (for visual states) and fed to the LLM planner (GPT-4/Llama3), which generates action candidates. A RoBERTa discriminator scores each action's alignment with expert demonstrations. If scores are below threshold, the LLM iteratively replans using historical action-score pairs until validation, then the action is executed in ScienceWorld or VirtualHome simulators."}, {"id": "h7aQxzKbq6", "title": "HAMSTER: Hierarchical Action Models for Open-World Robot Manipulation", "authors": ["Yi Li", "Yuquan Deng", "Jesse Zhang", "Joel Jang", "Marius Memmel", "Caelan Garrett", "Fabio Ramos", "Dieter Fox", "Anqi Li", "Abhishek Gupta", "Ankit Goyal"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=h7aQxzKbq6", "code": "https://github.com/liyi14/HAMSTER_beta", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["VILA-1.5-13b"], "non_llm_models": {"perception": [], "generation": [], "execution": ["RVT-2", "3D Diffuser Actor (3D-DA)"]}, "summary": "VILA-1.5-13b processes RGB images and language instructions to predict coarse 2D end-effector paths representing the manipulation trajectory. These paths are overlaid on visual observations and fed to low-level 3D policies (RVT-2 or 3D Diffuser Actor) along with depth/pointcloud and proprioceptive inputs, which generate the final robot actions for task execution."}, {"id": "YauQYh2k1g", "title": "Dissecting Adversarial Robustness of Multimodal LM Agents", "authors": ["Chen Wu", "Rishi Shah", "Jing Yu Koh", "Russ Salakhutdinov", "Daniel Fried", "Aditi Raghunathan"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=YauQYh2k1g", "code": null, "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector"], "llm_models": ["GPT-4o", "GPT-4V", "Claude-3-Opus", "Gemini-1.5-Pro"], "non_llm_models": {"perception": ["Captioner (VLM)"], "generation": [], "execution": []}, "summary": "The paper studies multimodal web agents in VisualWebArena, where a policy LLM (and optionally a separate VLM captioner, an LLM evaluator for reflexion, or an LLM value function for tree search) interacts with a real web environment through deterministic browser automation. The proposed ARE framework decomposes robustness by modeling adversarial information flow through the agent component graph, evaluating attacks such as text injection, white-box captioner perturbations, and black-box CLIP-based image attacks."}, {"id": "8NlUL0Cv1L", "title": "Generative World Explorer", "authors": ["TaiMing Lu", "Tianmin Shu", "Alan Yuille", "Daniel Khashabi", "Jieneng Chen"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=8NlUL0Cv1L", "code": "https://github.com/Beckschen/GenEx", "pattern": "LLM + Perception + Generation", "domain": "Embodied_Navigation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Gemini-1.5"], "non_llm_models": {"perception": ["CLIP", "Depth Anything", "DUSt3R"], "generation": ["GenEx", "Stable Video Diffusion"], "execution": []}, "summary": "The embodied agent receives an egocentric RGB observation and goal. GPT-4o acts as a policy model to plan exploration configurations (orientation/distance), which are sent to GenEx. GenEx generates imagined panoramic video sequences representing the explored views. GPT-4o updates its belief based on these imagined observations and makes an informed decision, outputting the final action for the agent."}, {"id": "Pm1NXHgzyf", "title": "SegLLM: Multi-round Reasoning Segmentation with Large Language Model", "authors": ["Xudong Wang", "Shaolun Zhang", "Shufan Li", "Kehan Li", "Konstantinos Kallidromitis", "Yusuke Kato", "Kazuki Kozuka", "trevor darrell"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=Pm1NXHgzyf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaVA-v1.5-7B"], "non_llm_models": {"perception": ["CLIP-ViT-Large (image encoder)", "CLIP-ViT-Large (mask encoder)"], "generation": ["HIPIE-R50 (mask decoder)"], "execution": []}, "summary": "The pipeline processes an image through CLIP to obtain visual embeddings, which along with text queries are fed into LLaVA. The LLM reasons about the query and generates [SEG] or [REF] tokens, which HIPIE-R50 decodes into segmentation masks. These masks are then encoded (using CLIP and bounding box coordinates) and fed back into LLaVA's input stream, allowing for multi-round conversational segmentation where subsequent queries can reference previously segmented objects."}, {"id": "00SnKBGTsz", "title": "DataEnvGym: Data Generation Agents in Teacher Environments with Student Feedback", "authors": ["Zaid Khan", "Elias Stengel-Eskin", "Jaemin Cho", "Mohit Bansal"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=00SnKBGTsz", "code": "https://github.com/codezakh/DataEnvGym", "pattern": "LLM + Generation", "domain": "Benchmark_Evaluation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": [], "generation": ["SDXL-Turbo"], "execution": []}, "summary": "The student model is evaluated to produce a performance state (errors or skill-specific metrics). GPT-4o (acting as the data generation policy) reasons over this state to create a structured data generation plan. The data generation engine executes this plan, using GPT-4o for text generation (math problems, code) and SDXL-Turbo for image generation (VQA training data). The student is then trained on the generated data and re-evaluated, creating an iterative teaching loop."}, {"id": "rDLgnYLM5b", "title": "Interleaved Scene Graph for Interleaved Text-and-Image Generation Assessment", "authors": ["Dongping Chen", "Ruoxi Chen", "Shu Pu", "Zhaoyi Liu", "Yanru Wu", "Caixi Chen", "Benlin Liu", "Yue Huang", "Yao Wan", "Pan Zhou", "Ranjay Krishna"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=rDLgnYLM5b", "code": "https://github.com/Flossiee/HonestyLLM", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion 3", "UltraEdit", "DynamiCrafter", "SV3D", "DreamMover"], "execution": []}, "summary": "ISG-AGENT follows a Plan-Execute-Refine pipeline: GPT-4o interprets the multimodal query and generates a JSON tool plan; Claude-3.5-Sonnet selects and executes appropriate generation tools (SD3, UltraEdit, etc.) with captions from MLLMs; a refinement module verifies outputs, analyzes errors, and reconstructs steps to fix misalignments, iterating until the final interleaved text-and-image output meets requirements."}, {"id": "FvIASa0tau", "title": "Sitcom-Crafter: A Plot-Driven Human Motion Generation System in 3D Scenes", "authors": ["Jianqi Chen", "Panwen Hu", "Xiaojun Chang", "Zhenwei Shi", "Michael Kampffmeyer", "Xiaodan Liang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=FvIASa0tau", "code": "https://github.com/WindVChen/Sitcom-Crafter", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "DAG", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["Gemini", "GPT"], "non_llm_models": {"perception": ["CLIP"], "generation": ["GAMMA", "DIMOS", "InterGen", "SMPL", "SMPL-X"], "execution": []}, "summary": "User provides a 3D scene and plot text. The LLM comprehends the plot and generates structured commands, which are dispatched in parallel to three generation modules: GAMMA for locomotion, DIMOS for human-scene interaction, and a modified InterGen for human-human interaction. The generated motions undergo synchronization for consistency, CLIP-based hand pose retrieval for expressiveness, collision revision to prevent inter-character penetration, and finally retargeting to high-quality 3D character assets."}, {"id": "ncCuiD3KJQ", "title": "Visual Agents as Fast and Slow Thinkers", "authors": ["Guangyan Sun", "Mingyu Jin", "Zhenting Wang", "Chenglong Wang", "Siqi Ma", "Qifan Wang", "Tong Geng", "Yingnian Wu", "Yongfeng Zhang", "Dongfang Liu"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=ncCuiD3KJQ", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["CLIP-ViT-L-336px", "Proposal Adapter"], "generation": ["SAM (Segment Anything Model)"], "execution": []}, "summary": "Input image and query are processed by CLIP visual encoder. A switch adapter (fine-tuned LoRA on Vicuna) determines if the query requires System 2 processing based on confidence. If triggered, a proposal adapter generates bounding box regions using context clues, followed by a seg adapter (SAM decoder) producing pixel-level masks. The Vicuna LLM then synthesizes the final answer by reasoning over the constructed chain of evidence (context clues, boxes, masks)."}, {"id": "KRv9NubipP", "title": "CaPo: Cooperative Plan Optimization for Efficient Embodied Multi-Agent Cooperation", "authors": ["Jie Liu", "Pan Zhou", "Yingjun Du", "Ah-Hwee Tan", "Cees G Snoek", "Jan-jakob Sonke", "Efstratios Gavves"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=KRv9NubipP", "code": "https://github.com/jliu4ai/CaPo", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "LLaMA-2-13B"], "non_llm_models": {"perception": ["Mask-RCNN"], "generation": [], "execution": ["Execution Module (low-level action controller)"]}, "summary": "RGB-D observations are processed by Mask-RCNN to extract object detections, stored in a Memory Module. LLMs generate strategic meta-plans through multi-turn inter-agent discussion and consensus-based optimization. During execution, a Progress-adaptive Planning Module updates the meta-plan based on new discoveries (e.g., finding objects). The Plan Parsing Module converts meta-plans into sub-plans, which the Execution Module translates into primitive actions (grasp, navigate) in the 3D environment."}, {"id": "qPzYF2EpXb", "title": "GravMAD: Grounded Spatial Value Maps Guided Action Diffusion for Generalized 3D Manipulation", "authors": ["Yangtao Chen", "Chen", "Junhui Yin", "Jing Huo", "Pinzhuo Tian", "Jieqi Shi", "Yang Gao"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=qPzYF2EpXb", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Semantic-SAM", "CLIP ResNet50", "3D Scene Encoder", "DP3 encoder"], "generation": [], "execution": ["3D Diffuser Actor", "diffusion policy", "sampling-based motion planner", "Franka Panda robot"]}, "summary": "RGB-D observations and language instructions are processed by Semantic-SAM and GPT-4o (Detector) to identify task-relevant objects. GPT-4o (Planner/Composer) generates sub-goals and code to create Grounded Spatial Value Maps (GravMaps), which are encoded into tokens. A 3D scene encoder processes visual features using CLIP. The GravMAD diffusion policy (based on 3D Diffuser Actor) uses both the GravMap tokens and 3D scene features to denoise random noise into precise robot end-effector poses, which are executed by the robot."}, {"id": "rUvCIvI4eB", "title": "Towards Realistic UAV Vision-Language Navigation: Platform, Benchmark, and Methodology", "authors": ["Xiangyu Wang", "Donglin Yang", "ziqin wang", "Hohin Kwan", "Jinyu Chen", "Yue Liao", "wenjun wu", "Hongsheng Li", "Si Liu"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=rUvCIvI4eB", "code": "https://github.com/prince687028/TravelUAV", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["EVA-CLIP", "Q-former", "Grounding DINO", "ViT"], "generation": [], "execution": ["AirSim Flight Controller"]}, "summary": "Multi-view images are encoded by EVA-CLIP and Q-former, combined with text instructions and processed by Vicuna-7B MLLM using a learnable query to predict a target pose, which is refined by a fine-grained path decoder with front-view ViT features. Grounding DINO detects targets for landing, and the trajectory is executed via AirSim's flight control API with closed-loop feedback."}, {"id": "WpZyPk79Fu", "title": "AnyPrefer: An Automatic Framework for Preference Data Synthesis", "authors": ["Yiyang Zhou", "Zhaoyang Wang", "Tianle Wang", "Shangyu Xing", "Peng Xia", "Bo Li", "Kaiyuan Zheng", "Zijian Zhang", "Zhaorun Chen", "Wenhao Zheng", "Xuchao Zhang", "Chetan Bansal", "Weitong Zhang", "Ying Wei", "Mohit Bansal", "Huaxiu Yao"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=WpZyPk79Fu", "code": null, "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "LLaMA2-7B", "LLaVA-1.5", "LLaVA-Med", "OpenVLA"], "non_llm_models": {"perception": ["Grounded SAM", "Grounded SAM 2", "BLIP-2", "Florence-2", "MiniGPT-Med", "MedVInT", "CheXagent", "DuckDuckGo"], "generation": [], "execution": []}, "summary": "The target model (e.g., LLaVA-1.5, OpenVLA) generates candidate responses for an input prompt. Perception tools (Grounded SAM, BLIP-2, etc.) extract knowledge from the input data. The judge model (GPT-4o) routes to relevant tools, aggregates their outputs, and ranks the candidate responses to form preference pairs. A reward model evaluates pair quality, and if below a threshold, iterative feedback optimizes the prompts for both target and judge models until high-quality preference data is produced for DPO fine-tuning."}, {"id": "EdMb9TqqDY", "title": "Long-horizon Visual Instruction Generation with Logic and Attribute Self-reflection", "authors": ["Yucheng Suo", "Fan Ma", "Kaixin Shen", "Linchao Zhu", "Yi Yang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=EdMb9TqqDY", "code": "https://github.com/suoych/LIGER", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4O"], "non_llm_models": {"perception": ["LISA", "CLIP", "DINO-v2", "BLIP-2"], "generation": ["SDXL", "DragonDiffusion", "Stable Diffusion Inpainting", "LAMA"], "execution": []}, "summary": "GPT-4O generates historical context prompts from step descriptions. SDXL generates draft images conditioned on these prompts and visual memory from previous steps. GPT-4O analyzes drafts for errors (logic, attributes, identity). If errors are found, LISA segments objects and invokes specific editing tools: DragonDiffusion for identity consistency, SD Inpainting for attribute correction, or LAMA for object removal. GPT-4O then acts as a referee to select the final image. Visual memory is calibrated via DDIM inversion to prevent error accumulation in subsequent steps."}, {"id": "uy31tqVuNo", "title": "Unbounded: A Generative Infinite Game of Character Life Simulation", "authors": ["Jialu Li", "Yuanzhen Li", "Neal Wadhwa", "Yael Pritch", "David E. Jacobs", "Michael Rubinstein", "Mohit Bansal", "Nataniel Ruiz"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=uy31tqVuNo", "code": null, "pattern": "LLM + Generation", "domain": "Gaming", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Gemma-2B", "GPT-4"], "non_llm_models": {"perception": [], "generation": ["SDXL", "Latent Consistency Model (LCM)", "IP-Adapter", "DreamBooth LoRA"], "execution": []}, "summary": "User natural language input is processed by a distilled Gemma-2B LLM (acting as a game engine) to update character states and generate scene descriptions. These descriptions are converted into prompts for SDXL, which is conditioned via a regional IP-Adapter with dynamic masking and DreamBooth LoRA (merged with LCM LoRA for speed) to generate consistent character-in-environment images displayed to the user in real-time."}, {"id": "womU9cEwcO", "title": "Autonomous agents from automatic reward modeling and planning", "authors": ["Zhenfang Chen", "Delin Chen", "Rui Sun", "Wenjun Liu", "Chuang Gan"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=womU9cEwcO", "code": "https://github.com/heaplax/ARMAP", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["Llama3-70B-instruct", "Llama3-8B-instruct", "Mistral-7B", "Phi-3.8B"], "non_llm_models": {"perception": ["VILA (fine-tuned as reward model)"], "generation": [], "execution": []}, "summary": "ARMAP first uses an LLM agent to explore environments and collect trajectories. A separate LLM synthesizes task instructions and negative examples from these trajectories. A VILA model is fine-tuned as a reward model on this synthetic data to score trajectories. During inference, the LLM generates candidate action trajectories, VILA evaluates them, and deterministic planning algorithms (MCTS, Best-of-N, Reflexion) use these scores to select optimal action sequences."}, {"id": "YXRyYkb1im", "title": "COMBO: Compositional World Models for Embodied Multi-Agent Cooperation", "authors": ["Hongxin Zhang", "Zeyuan Wang", "Qiushi Lyu", "Zheyuan Zhang", "Sunli Chen", "Tianmin Shu", "Yilun Du", "Behzad Dariush", "Kwonjoon Lee", "Chuang Gan"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=YXRyYkb1im", "code": "https://github.com/UMass-Embodied-AGI/COMBO", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["LLaVA (fine-tuned)"], "non_llm_models": {"perception": ["World State Estimation diffusion model (image inpainting)"], "generation": ["Compositional World Model (video diffusion, AVDC-based)"], "execution": []}, "summary": "Egocentric RGBD observations are reconstructed into partial point clouds and inpainted by a diffusion model to estimate the complete world state. LLaVA acts as an Action Proposer, Intent Tracker, and Outcome Evaluator. The Compositional World Model (video diffusion) generates future state simulations conditioned on joint actions from all agents. A tree search procedure integrates these modules to select optimal action plans, which are then executed in the environment, with replanning occurring at each step."}, {"id": "GR0y0F3Ipd", "title": "MAPS: Advancing Multi-Modal Reasoning in Expert-Level Physical Science", "authors": ["Erle Zhu", "Yadi Liu", "Zhe Zhang", "Xujun Li", "JinZhou", "Xinjie Yu", "Minlie Huang", "Hongning Wang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=GR0y0F3Ipd", "code": "https://github.com/thu-coai/MAPS", "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Verifier"], "llm_models": ["GPT-4V", "Claude-3.5", "GLM-4V"], "non_llm_models": {"perception": ["PPM (Physics Perception Model, fine-tuned CogVLM-17B)"], "generation": [], "execution": ["NgSPICE"]}, "summary": "Input circuit diagrams are first converted to SPICE simulation language by the PPM. The MLLM refines this description using textual context, then NgSPICE executes the simulation to produce numerical results. Finally, the MLLM performs simulation-aided reasoning over the original question, diagram, simulation description, and execution results to derive the final answer."}, {"id": "BgxsmpVoOX", "title": "Rare-to-Frequent: Unlocking Compositional Generation Power of Diffusion Models on Rare Concepts with LLM Guidance", "authors": ["Dongmin Park", "Sebin Kim", "Taehong Moon", "Minkyu Kim", "Kangwook Lee", "Jaewoong Cho"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=BgxsmpVoOX", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o", "LLaMA3-8B-Instruct"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)"], "generation": ["Stable Diffusion 3.0", "SDXL", "FLUX", "IterComp"], "execution": []}, "summary": "User provides text prompt → LLM decomposes into sub-prompts per object, identifies rare concepts, maps them to semantically similar frequent alternatives, and assigns visual detail levels to determine stop points → Diffusion model performs alternating concept guidance (switching between rare and frequent prompts during early sampling steps) → Final image output. In the R2F+ extension, the LLM additionally generates spatial layouts (bounding boxes), object-wise images are generated in parallel and segmented by SAM to obtain masks, and region-controlled latent fusion produces the final compositional image."}, {"id": "rQ7fz9NO7f", "title": "Multimodal Large Language Models for Inverse Molecular Design with Retrosynthetic Planning", "authors": ["Gang Liu", "Michael Sun", "Wojciech Matusik", "Meng Jiang", "Jie Chen"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=rQ7fz9NO7f", "code": "https://github.com/liugangcode/Llamole", "pattern": "LLM + Perception + Generation", "domain": "Scientific_Discovery", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Llama-3", "Mistral", "Qwen2"], "non_llm_models": {"perception": ["Graph Isomorphism Network (GIN)", "Graph Neural Network (GNN)"], "generation": ["Graph Diffusion Transformer (Graph DiT)"], "execution": []}, "summary": "The pipeline begins with a user query processed by the base LLM for requirement analysis. The LLM generates a <design> trigger to activate the Graph DiT for conditional molecule generation. The generated molecule is encoded by the GIN and fed back to the LLM for descriptive text generation. For retrosynthesis, the LLM generates a <retro> trigger to activate the GNN for reaction template prediction. The LLM provides heuristic cost functions to guide A* search in iteratively planning multi-step synthesis routes, interleaving text, molecular graphs, and reaction steps until reaching purchasable reactants or termination criteria."}, {"id": "QAAsnSRwgu", "title": "From an LLM Swarm to a PDDL-empowered Hive: Planning Self-executed Instructions in a Multi-modal Jungle", "authors": ["Kaustubh Vyas", "Damien Graux", "Yijun Yang", "Sebastien Montella", "Chenxin Diao", "Wendi Zhou", "Pavlos Vougiouklis", "Ruofei Lai", "Yang Ren", "Keshuang Li", "J Pan"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=QAAsnSRwgu", "code": "https://github.com/dgraux/Hive-ICLR-2025", "pattern": "LLM + Perception + Generation + Action", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4", "Mistral-7B-Instruct-v0.3", "InternLM2.5-7B-chat"], "non_llm_models": {"perception": ["Whisper-large-v2", "Parakeet-rnnt-1.1b", "BERT-base-NER"], "generation": ["Stable-diffusion-2-1"], "execution": ["Python code execution engine"]}, "summary": "User queries are parsed by an LLM into structured components and decomposed into PDDL actions. A Best First Width Search logical planner sequences these actions into an executable plan. Models are dynamically selected from the Capability Knowledge Graph (C-KG) based on user constraints (license, size, performance). The plan is executed by retrieving and invoking Python code snippets associated with the selected models, running them sequentially to produce the final multi-modal output."}, {"id": "MPJ4SMnScw", "title": "Re-Aligning Language to Visual Objects with an Agentic Workflow", "authors": ["Yuming Chen", "Jiangyan Feng", "Haodong Zhang", "Lijun GONG", "Feng Zhu", "Rui Zhao", "Qibin Hou", "Ming-Ming Cheng", "Yibing Song"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=MPJ4SMnScw", "code": "https://github.com/FishAndWasabi/RealLOD", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["ChatGLM-6B", "Vicuna-v1.5-13B"], "non_llm_models": {"perception": ["LLaVA-v1.6-34B", "SigLIP"], "generation": [], "execution": []}, "summary": "Input images with detected objects and raw VLM expressions are processed by ChatGLM-6B (Real-Agent), which reasons about the current alignment state and plans actions. The agent adaptively adjusts image crops and text prompts for VLM/LLM tools (Vicuna) to re-perceive visual content or rewrite expressions. A reflector LLM analyzes outputs and provides feedback to the agent. This iterative cycle continues until expressions are correctly aligned, producing refined training data."}, {"id": "3bcN6xlO6f", "title": "Video Action Differencing", "authors": ["James Burgess", "Xiaohan Wang", "Yuhui Zhang", "Anita Rau", "Alejandro Lozano", "Lisa Dunlap", "trevor darrell", "Serena Yeung"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=3bcN6xlO6f", "code": "https://github.com/jmhb0/viddiff", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP (ViT-bigG-14)"], "generation": [], "execution": []}, "summary": "The VidDiff method processes a video pair and action description through three sequential stages: (1) GPT-4o proposes candidate difference statements; (2) CLIP computes frame similarities based on LLM-generated retrieval strings, and a Viterbi algorithm localizes key sub-action frames; (3) GPT-4o performs VQA on the retrieved frame pairs to classify each difference as applying to video A, B, or neither, outputting final text descriptions."}, {"id": "lIVRgt4nLv", "title": "Agent S: An Open Agentic Framework that Uses Computers Like a Human", "authors": ["Saaket Agashe", "Jiuzhou Han", "Shuyu Gan", "Jiachen Yang", "Ang Li", "Xin Wang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=lIVRgt4nLv", "code": "https://github.com/simular-ai/Agent-S", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Claude-3.5-sonnet"], "non_llm_models": {"perception": ["PaddleOCR"], "generation": [], "execution": ["Agent-Computer Interface (ACI)"]}, "summary": "The Manager receives a user task and initial screenshot, retrieves web knowledge and Narrative Memory to generate a subtask queue. Each Worker retrieves Episodic Memory and uses the Trajectory Reflector to generate symbolic actions, which the ACI translates into executable Python code to interact with the Desktop Environment. Observations flow back to the Worker, and the Self-Evaluator updates memories upon completion."}, {"id": "T5QLRRHyL1", "title": "PARTNR: A Benchmark for Planning and Reasoning in Embodied Multi-agent Tasks", "authors": ["Matthew Chang", "Gunjan Chhablani", "Alexander Clegg", "Mikael Dallaire Cote", "Ruta Desai", "Michal Hlavac", "Vladimir Karashchuk", "Jacob Krantz", "Roozbeh Mottaghi", "Priyam Parashar", "Siddharth Patki", "Ishita Prasad", "Xavier Puig", "Akshara Rai", "Ram Ramrakhya", "Daniel Tran", "Joanne Truong", "John Turner", "Eric Undersander", "Tsung-Yen Yang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=T5QLRRHyL1", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Llama3.1-70B-Instruct", "Llama3.1-8B"], "non_llm_models": {"perception": ["ConceptGraphs", "World Graph construction"], "generation": [], "execution": ["Learned neural skills (pick, place, navigate, open, close policies)"]}, "summary": "Natural language task instructions are processed by an LLM planner (ReAct) that maintains and queries a textual world graph constructed from ConceptGraphs 3D perception. The LLM selects high-level skills that are executed by learned low-level policies in the Habitat 3.0 simulator. Execution observations update the world graph, creating an iterative planning-execution loop until task completion or failure."}, {"id": "Mv3GAYJGcW", "title": "MetaDesigner: Advancing Artistic Typography through AI-Driven, User-Centric, and Multilingual WordArt Synthesis", "authors": ["Jun-Yan He", "Zhi-Qi Cheng", "Chenyang Li", "Jingdong Sun", "Qi He", "Wangmeng Xiang", "Hanyuan Chen", "Jin-Peng Lan", "Xianhui Lin", "kang zhu", "Bin Luo", "Yifeng Geng", "Xuansong Xie", "Alexander G Hauptmann"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=Mv3GAYJGcW", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["LLaVA"], "generation": ["Stable Diffusion", "ControlNet", "LoRA", "DiffVG"], "execution": []}, "summary": "User prompt is processed by the GPT-4 Pipeline Designer using Chain-of-Thought to generate structured instructions for the Glyph Designer (which uses DiffVG for vector optimization or font rendering) and Texture Designer (which uses Tree-of-Thought to select from 68 LoRA models and ControlNet for stylization). The Q&A Evaluation Agent employs LLaVA to verify consistency and quality, incorporating user feedback to iteratively refine hyperparameters until the final WordArt image is produced."}, {"id": "OZbFRNhpwr", "title": "SPA-BENCH: A COMPREHENSIVE BENCHMARK FOR SMARTPHONE AGENT EVALUATION", "authors": ["Jingxuan Chen", "Derek Yuen", "Bin Xie", "Yuhao Yang", "Gongwei Chen", "Zhihao Wu", "Li Yixing", "Xurui Zhou", "Weiwen Liu", "Shuai Wang", "Kaiwen Zhou", "Rui Shao", "Liqiang Nie", "Yasheng Wang", "Jianye HAO", "Jun Wang", "Kun Shao"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=OZbFRNhpwr", "code": "https://github.com/ai-agents-2030/SPA-Bench", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "GPT-4"], "non_llm_models": {"perception": ["OCR (MobileAgentV2)", "CogAgent (vision encoder)", "Auto-UI (vision encoder)", "T3A (accessibility tree parser)", "AutoDroid (accessibility tree parser)"], "generation": [], "execution": ["Android control interface (tap, type, swipe)", "DigiRL (RL policy)"]}, "summary": "The worker machine assigns tasks to agents within a plug-and-play framework. Each agent uses an LLM to process multimodal UI observations (screenshots, OCR text, accessibility trees) and plans actions (tap, type, swipe) executed on Android emulators. An automated evaluation pipeline then assesses task completion using coarse key-component matching and fine MLLM-based verification."}, {"id": "s3FTX4Ay55", "title": "Articulate-Anything: Automatic Modeling of Articulated Objects via a Vision-Language Foundation Model", "authors": ["Long Le", "Jason Xie", "William Liang", "Hung-Ju Wang", "Yue Yang", "Yecheng Jason Ma", "Kyle Vedder", "Arjun Krishna", "Dinesh Jayaraman", "ERIC EATON"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=s3FTX4Ay55", "code": "https://github.com/vlongle/articulate-anything", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Gemini Flash-1.5", "GPT-4o", "Claude-3.5 Sonnet"], "non_llm_models": {"perception": ["CLIP", "CoTracker"], "generation": [], "execution": []}, "summary": "Multimodal inputs (text/image/video) first undergo Mesh Retrieval using CLIP and VLM-based selection. Then, a VLM actor generates Python code for Link Placement, which is evaluated by a VLM critic comparing rendered outputs to inputs. Next, the actor extends the code for Joint Prediction, verified by the critic using CoTracker motion traces against input videos. This iterative actor-critic loop continues until the articulation meets quality thresholds, outputting a compiled URDF."}, {"id": "Y2Dh8rWwlb", "title": "EditRoom: LLM-parameterized Graph Diffusion for Composable 3D Room Layout Editing", "authors": ["Kaizhi Zheng", "Xiaotong Chen", "Xuehai He", "Jing Gu", "Linjie Li", "Zhengyuan Yang", "Kevin Lin", "Jianfeng Wang", "Lijuan Wang", "Xin Wang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=Y2Dh8rWwlb", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP-ViT-B-32", "OpenShape"], "generation": ["Graph Diffusion", "VQ-VAE"], "execution": []}, "summary": "The user provides a natural language command and source scene. GPT-4o analyzes the scene attributes and command to generate structured breakdown commands (planning). These commands, along with the source scene graph, feed into a conditional graph diffusion scene editor. First, Target Graph Diffusion generates the target scene graph (object categories, relations, and semantic features). Then, Target Layout Diffusion generates the final 3D layout (positions, rotations, sizes). The final scene is assembled by retrieving object meshes based on the generated features and arranging them according to the predicted layout."}, {"id": "tFDTHA3odg", "title": "ThinkBot: Embodied Instruction Following with Thought Chain Reasoning", "authors": ["Guanxing Lu", "Ziwei Wang", "Changliu Liu", "Jiwen Lu", "Yansong Tang"], "venue": "ICLR", "year": 2025, "url": "https://openreview.net/pdf?id=tFDTHA3odg", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["BERT (text encoder)", "ResNet18 (map encoder)", "Multimodal Transformer (Object Localizer)", "Pretrained Detector (instance segmentation)"], "generation": [], "execution": ["Pre-defined controller (AI2-THOR)"]}, "summary": "Sparse human instruction is processed by GPT-3.5 (instruction completer) which reasons a thought chain to recover missing actions and generate coherent subgoals. A multimodal object localizer (BERT+ResNet18+Transformer) processes the semantic map to predict object positions and Bayesian uncertainty. The uncertainty is fed back to the LLM for plan refinement (closed-loop). Finally, a pre-defined controller executes the subgoals in the AI2-THOR environment to complete the task."}, {"id": "vlraTIgUD3", "title": "InSight-o3: Empowering Multimodal Foundation Models with Generalized Visual Search", "authors": ["Kaican Li", "Lewei Yao", "Jiannan Wu", "Tiezheng YU", "Jierun Chen", "Haoli Bai", "LU HOU", "Lanqing HONG", "Wei Zhang", "Nevin Zhang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=vlraTIgUD3", "code": "https://github.com/m-Just/InSight-o3", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-5-mini", "Gemini-2.5-Flash", "Qwen2.5-VL-7B", "GPT-5-nano", "GPT-4o"], "non_llm_models": {"perception": ["InSight-o3-vS (Qwen2.5-VL-7B-based)", "PP-DocLayout plus-L"], "generation": [], "execution": []}, "summary": "The user query and image are first processed by the vReasoner (multimodal LLM), which decomposes the task and issues natural language region descriptions to the vSearcher. The vSearcher (specialized perception model) localizes the requested regions via visual search and returns cropped image patches. The vReasoner incorporates this evidence into its reasoning process, potentially requesting additional regions in iterative rounds, until it produces the final answer."}, {"id": "OG1JMhoBKU", "title": "LogiStory: A Logic-Aware Framework for Multi-Image Story Visualization", "authors": ["Chutian Meng", "Fan Ma", "Chi Zhang", "Jiaxu Miao", "Yi Yang", "Yueting Zhuang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=OG1JMhoBKU", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["DeepSeek-V3", "DeepSeek-R1"], "non_llm_models": {"perception": ["BLIP-2", "GPT-4o", "Gemini 2.0 Flash"], "generation": ["Flux", "GPT-image-1", "Gemini 2.0 Flash", "Inpainting models"], "execution": []}, "summary": "The input text story is first processed by a multi-agent system (SceneCrafter, LogicMiner, ShotPlanner) powered by DeepSeek-V3 to extract entities, causal events, and panel specifications. Flux generates initial draft images for each panel. A Local Causal Monitor (using MLLMs) evaluates each image against a causal memory buffer, while a Global Causal Verifier checks state transitions against a constructed causal graph. Based on plausibility scores, the system either accepts the image, regenerates it, or invokes GPT-image-1/Gemini for targeted editing, producing a logically coherent image sequence."}, {"id": "Vjruxvp1Xd", "title": "Agent-X: Evaluating Deep Multimodal Reasoning in Vision-Centric Agentic Tasks", "authors": ["Tajamul Ashraf", "Amal Saqib", "Hanan Gani", "Muhra AlMahri", "Yuhao Li", "Noor Ahsan", "Umair Nawaz", "Jean Lahoud", "Hisham Cholakkal", "Mubarak Shah", "Philip Torr", "Fahad Khan", "Rao Anwer", "Salman Khan"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=Vjruxvp1Xd", "code": "https://github.com/mbzuai-oryx/Agent-X", "pattern": "LLM + Perception", "domain": "Benchmark_Evaluation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router"], "llm_models": ["GPT-4o", "Gemini-1.5-Pro", "Gemini-2.5-Pro", "OpenAI-o4-mini", "Qwen2.5-VL-7B", "InternVL2.5-8B", "InternVL3-8B", "VideoLLaMA3-7B", "Phi-4-VL-Instruct", "Gemma-3-4B"], "non_llm_models": {"perception": ["SceneDescriber", "ObjectCounter", "OCR", "RegionDescriber"], "generation": [], "execution": []}, "summary": "Agent-X is a benchmark for evaluating LMMs on vision-centric agentic tasks. The LMM orchestrator performs step-by-step planning and reasoning, invoking learned perception tools (SceneDescriber, ObjectCounter, OCR, RegionDescriber) alongside deterministic utilities such as WebSearch and Calculator to answer multimodal queries. The framework assesses tool selection accuracy, reasoning coherence, and final answer correctness, but does not incorporate learned action policies or media generation models."}, {"id": "XCW1l9qcxy", "title": "Transductive Visual Programming: Evolving Tool Libraries from Experience for Spatial Reasoning", "authors": ["Shengguang Wu", "Xiaohan Wang", "Yuhui Zhang", "Hao Zhu", "Serena Yeung"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=XCW1l9qcxy", "code": "https://github.com/transductive-visualprogram/tvp", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier"], "llm_models": ["GPT-4o", "Qwen2.5-Coder"], "non_llm_models": {"perception": ["GroundingDINO", "UniDepth"], "generation": [], "execution": []}, "summary": "TVP uses GPT-4o or Qwen2.5-Coder to generate Python programs that call perception models (GroundingDINO for localization and UniDepth for depth) together with deterministic geometric utilities. A Python interpreter executes the programs, and a VLM judge verifies outputs; high-quality solutions populate an Example Library, from which reusable tool abstractions are periodically extracted and added to a Tool Library."}, {"id": "gqb1hvuGcj", "title": "TimeSearch-R: Adaptive Temporal Search for Long-Form Video Understanding via Self-Verification Reinforcement Learning", "authors": ["Junwen Pan", "Qizhe Zhang", "Rui Zhang", "Ming Lu", "Xin Wan", "Yuan Zhang", "Chang Liu", "Qi She"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=gqb1hvuGcj", "code": "https://github.com/Time-Search/TimeSearch-R", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL-7B"], "non_llm_models": {"perception": ["SigLIP"], "generation": [], "execution": []}, "summary": "The policy model (Qwen2.5-VL) generates textual reasoning interleaved with search instructions specifying temporal boundaries and queries. SigLIP retrieves the most relevant frames from the specified video segments, which are appended to the chain-of-thought. This iterative search-reasoning cycle repeats until the model emits a final answer. During RL training, GRPO-CSV provides additional supervision by verifying that the searched frames alone are sufficient to answer the question correctly."}, {"id": "hIwVFRLaFy", "title": "VisualPrompter: Semantic-Aware Prompt Optimization with Visual Feedback for Text-to-Image Synthesis", "authors": ["Shiyu Wu", "Mingzhen Sun", "Weining Wang", "Yequan Wang", "Jing Liu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=hIwVFRLaFy", "code": "https://github.com/teheperinko541/VisualPrompter", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2"], "non_llm_models": {"perception": ["Qwen2-VL"], "generation": ["Stable Diffusion v1.5", "Stable Diffusion v2.1", "Flux-dev", "Janus-Pro"], "execution": []}, "summary": "User prompts are parsed by Qwen2 into atomic DSG concepts. An initial image is generated by T2I models (SD/Flux/Janus). Qwen2-VL evaluates the image against DSG-derived questions to identify missing concepts. Qwen2 then expands these missing concepts and composes an optimized prompt, which is decorated with aesthetic keywords and used to generate the final image with improved semantic alignment."}, {"id": "fE14yWa68Z", "title": "WebGen-Agent: Enhancing Interactive Website Generation with Multi-Level Feedback and Step-Level Reinforcement Learning", "authors": ["Zimu Lu", "Houxing Ren", "Yunqiao Yang", "Ke Wang", "Zhuofan Zong", "Junting Pan", "Mingjie Zhan", "Hongsheng Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=fE14yWa68Z", "code": null, "pattern": "LLM + Perception + Action", "domain": "Code_Development", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Claude-3.5-Sonnet", "DeepSeek-V3", "Qwen2.5-Coder-7B-Instruct", "Qwen3-8B", "DeepSeek-R1", "Claude-4-Sonnet", "Gemini-2.5-Pro"], "non_llm_models": {"perception": ["Qwen2.5-VL-32B-Instruct", "GPT-4o"], "generation": [], "execution": ["GUI Agent", "Code Execution Engine"]}, "summary": "The pipeline begins with a coding LLM generating website code from instructions. The code is executed to launch a web service. A VLM analyzes screenshots to provide appearance scores and improvement suggestions. A GUI agent then tests website functionality to provide functional scores. This multi-level feedback is fed back to the LLM, which iteratively refines the code. The system includes backtracking to previous states on consecutive execution errors and a final select-best mechanism that chooses the optimal codebase state based on combined screenshot and GUI-agent scores."}, {"id": "eKhOrQWAVJ", "title": "Spatially Guided Training for Vision-Language-Action Model", "authors": ["Jinhui Ye", "Fangjing Wang", "Ning Gao", "Junqiu Yu", "Yangkun Zhu", "Bin Wang", "Jinyu Zhang", "Weiyang Jin", "Yanwei Fu", "Feng Zheng", "Yilun Chen", "Jiangmiao Pang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=eKhOrQWAVJ", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2.5-VL-3B-Instruct"], "non_llm_models": {"perception": ["DINOv2"], "generation": [], "execution": ["DiT (Diffusion Transformer)"]}, "summary": "Visual observations and language instructions are first processed by the Qwen2.5-VL planner to generate latent spatial plans via spatial prompting. These embeddings pass through a lightweight querying transformer to condition the DiT Action Expert, which combines them with DINOv2 visual features to output robot control actions. The system is trained via a two-stage recipe: spatial grounding pre-training of the VLM followed by spatially guided action post-training with gradient decay to preserve spatial priors."}, {"id": "U9meoc0Sau", "title": "SceneCOT: Eliciting Chain-of-Thought Reasoning in 3D Scenes", "authors": ["Xiongkun Linghu", "Jiangyong Huang", "Ziyu Zhu", "Baoxiong Jia", "Siyuan Huang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=U9meoc0Sau", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["LLaVA-1.5", "Vicuna-7B"], "non_llm_models": {"perception": ["PQ3D", "Mask3D", "2D Vision Encoder"], "generation": [], "execution": []}, "summary": "The system takes a 3D scene and question as input. LLaVA-1.5 first performs task recognition and region localization (using a symbolic engine), then generates grounding instructions to invoke PQ3D and Mask3D for object localization. For attribute questions, the 2D Vision Encoder processes retrieved object images. The grounding outputs (probabilities, coordinates, image tokens) are fed back into LLaVA-1.5, which performs step-by-step grounded reasoning to produce the final text answer."}, {"id": "RnuB0Nlbd5", "title": "JanusVLN: Decoupling Semantics and Spatiality with Dual Implicit Memory for Vision-Language Navigation", "authors": ["Shuang Zeng", "Dekang Qi", "Xinyuan Chang", "Feng Xiong", "Shichao Xie", "Xiaolong Wu", "Shiyi Liang", "Mu Xu", "Xing Wei"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=RnuB0Nlbd5", "code": "https://github.com/MIV-XJTU/JanusVLN", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Converge", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2.5-VL 7B"], "non_llm_models": {"perception": ["VGGT (Visual Geometry Grounded Transformer)"], "generation": [], "execution": []}, "summary": "JanusVLN processes RGB video frames in parallel through a frozen VGGT spatial-geometric encoder and the Qwen2.5-VL visual encoder. Their historical KV caches form a dual implicit memory (initial and sliding windows) to avoid redundant recomputation. The extracted spatial and semantic tokens are fused via a lightweight MLP projection layer and fed into the fine-tuned Qwen2.5-VL LLM backbone, which directly predicts the next low-level navigation action (e.g., move forward, turn, stop)."}, {"id": "dkIXAbWuxO", "title": "Earth-Agent: Unlocking the Full Landscape of Earth Observation with Agents", "authors": ["Peilin Feng", "Zhutao Lv", "Junyan Ye", "Xiaolei Wang", "Xinjie Huo", "Jinhua Yu", "Wanghan Xu", "Wenlong Zhang", "LEI BAI", "Conghui He", "Weijia Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=dkIXAbWuxO", "code": "https://github.com/opendatalab/Earth-Agent", "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-5", "GPT-4o", "Gemini-2.5", "DeepSeek-V3.1", "Kimik2", "Qwen3-max", "InternVL-3.5"], "non_llm_models": {"perception": ["SAM2", "SM3Det", "InternVL-3.5"], "generation": [], "execution": ["Google Earth Engine (GEE)", "Index Kit (NDVI, NDWI calculators)", "Inversion Kit (LST, PWV retrieval)", "Analysis Kit (trend detection, change point analysis)", "Statistics Kit (batch operations, cloud masking)"]}, "summary": "Earth-Agent receives a query and EO data (RGB, Spectrum, or Products), then uses an LLM controller with ReAct reasoning to iteratively plan and execute tool calls. It invokes perception models (SAM2, SM3Det, InternVL) for visual understanding and domain-specific execution tools (Index, Inversion, Analysis, Statistics kits) for quantitative calculations, updating its memory with observations after each step until producing the final scientific answer."}, {"id": "zJnPyb2xrp", "title": "PostAlign: Multimodal Grounding as a Corrective Lens for MLLMs", "authors": ["Yixuan Wu", "Yang Zhang", "JIAN Wu", "Philip Torr", "Jindong Gu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=zJnPyb2xrp", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaVA-1.5", "Qwen2-VL", "Qwen2.5-VL", "InternVL3", "InternVL3.5"], "non_llm_models": {"perception": ["SAM (Segment Anything Model) ViT-H/ViT-B/ViT-L"], "generation": [], "execution": []}, "summary": "Given an image and text query, the MLLM generates a visual grounding token (<LOC>) whose embedding is fed to a multi-task decoder combined with SAM features to produce segmentation masks and bounding boxes. The MLLM also performs selective reasoning (classifying queries as <SIMPLE> or <COMPLEX>) to determine whether to generate textual grounding rationales. The visual grounding evidence (and textual rationale if applicable) guides the MLLM to produce the final text answer, with a negative rejection mechanism (<REJ>) to handle cases where referred objects do not exist in the image."}, {"id": "PzIc2TxhwN", "title": "Seek-CAD: A Self-refined Generative Modeling for 3D Parametric CAD Using Local Inference via DeepSeek", "authors": ["Xueyang Li", "Jiahao Li", "Yu Song", "Yunzhong Lou", "Xiangdong Zhou"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=PzIc2TxhwN", "code": null, "pattern": "LLM + Perception + Action", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["DeepSeek-R1-32B-Q4"], "non_llm_models": {"perception": ["Gemini-2.0"], "generation": [], "execution": ["PythonOCC"]}, "summary": "DeepSeek-R1 generates initial CAD code using RAG (bge-m3) from a local corpus. PythonOCC executes the code to produce step-wise renderings of the 3D model. Gemini-2.0 evaluates these renderings against DeepSeek-R1's CoT to assess alignment, feeding back discrepancies to trigger iterative refinement of the CAD code."}, {"id": "2awntLXwR6", "title": "MMedAgent-RL: Optimizing Multi-Agent Collaboration for Multimodal Medical Reasoning", "authors": ["Peng Xia", "Jinglu Wang", "Yibo Peng", "Kaide Zeng", "Zihan Dong", "Xian Wu", "Xiangru Tang", "Hongtu Zhu", "Yun Li", "Linjun Zhang", "Shujie LIU", "Yan Lu", "Huaxiu Yao"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=2awntLXwR6", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL"], "non_llm_models": {"perception": ["GPT-4o", "o3", "HuatuoGPT-Vision", "Med-Flamingo", "RadFM", "LLaVA-Med"], "generation": [], "execution": []}, "summary": "A triage doctor (Qwen2.5-VL) analyzes the medical image and question to select an appropriate specialty, routing to specialist LVLMs (GPT-4o, HuatuoGPT-Vision, etc.) which provide independent diagnostic opinions. An attending physician (Qwen2.5-VL) then integrates these specialist judgments with its own visual reasoning to generate the final answer, trained via curriculum-based RL to handle noisy or conflicting specialist inputs."}, {"id": "cVX3VqO8BO", "title": "UniHM: Unified Dexterous Hand Manipulation with Vision Language Model", "authors": ["Zhenhao Zhang", "Jiaxin Liu", "Ye Shi", "Jingya Wang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=cVX3VqO8BO", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Converge", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen3-0.6B"], "non_llm_models": {"perception": ["CLIPort", "Point-SAM"], "generation": ["VQ-VAE (Unified Hand-Dexterous Tokenizer)"], "execution": ["Physics-guided dynamic refinement", "Dex-Retargeting", "MANO"]}, "summary": "CLIPort extracts target trajectories from RGB-D and language instructions, while Point-SAM segments the object point cloud. These converge with text embeddings into the Qwen3-0.6B VLM, which generates discrete hand pose tokens via the Unified Hand-Dexterous Tokenizer (VQ-VAE). The tokens are decoded to hand-specific joint trajectories and refined through physics-based optimization to ensure contact validity and smooth motion before execution on target dexterous hands."}, {"id": "80JylHgQn1", "title": "Instilling an Active Mind in Avatars via Cognitive Simulation", "authors": ["Jianwen Jiang", "Weihong Zeng", "Zerong Zheng", "Jiaqi Yang", "Chao Liang", "Wang Liao", "Han Liang", "Weifeng Chen", "XING WANG", "Yuan Zhang", "Mingyuan Gao"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=80JylHgQn1", "code": null, "pattern": "LLM + Generation", "domain": "Video_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["MiniCPM-o", "Seed-1.5-VL"], "non_llm_models": {"perception": [], "generation": ["MMDiT (Multimodal Diffusion Transformer)", "3D VAE"], "execution": []}, "summary": "Multimodal inputs (audio, reference image, text prompt) are first processed by MLLM-based agents (Analyzer and Planner) to generate a high-level textual 'schedule' representing deliberative reasoning. This schedule, along with the audio signal and a pseudo-last-frame reference image, is fed into a Multimodal Diffusion Transformer (MMDiT) with symmetric audio-text-video branches. The MMDiT iteratively denoises latent representations (encoded via 3D VAE) to generate the final avatar video, effectively fusing high-level semantic guidance with low-level reactive signals."}, {"id": "k3DZzBl2EZ", "title": "ContextNav: Towards Agentic Multimodal In-Context Learning", "authors": ["Honghao Fu", "Yuan Ouyang", "Kai-Wei Chang", "Yiwei Wang", "Zi Huang", "Yujun Cai"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=k3DZzBl2EZ", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Gemini-2.0-flash", "GPT-4o", "Qwen2.5-VL-7B/3B", "Phi-3.5V", "InternLMX2.5"], "non_llm_models": {"perception": ["CLIP", "SigLIP-2", "Qwen3-Embedding-4B/8B/0.6B", "Qwen2.5-VL vision encoder"], "generation": [], "execution": []}, "summary": "Given a multimodal query, the agent first performs resource-aware embedding of the context corpus using vision/text encoders to build a vector database. It retrieves initial candidates via similarity search, then applies semantic denoising (agentic retrieval) and structural alignment to refine contexts. An Operational Grammar Graph (OGG) orchestrates valid operation sequences. The cleaned contexts are fed to a downstream MLLM for in-context learning, with performance feedback stored in memory to optimize future workflows."}, {"id": "nUGPEmQ2ut", "title": "AdaReasoner: Dynamic Tool Orchestration for Iterative Visual Reasoning", "authors": ["Mingyang Song", "Haoyu Sun", "Jiawei Gu", "Linjie Li", "Ranjay Krishna", "Yu Cheng"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=nUGPEmQ2ut", "code": "https://github.com/ssmisya/AdaReasoner", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL-3B-Instruct", "Qwen2.5-VL-7B-Instruct"], "non_llm_models": {"perception": ["POINT (Molmo-7B-D)", "OCR", "DETECTBLACKAREA"], "generation": ["DRAW2DPATH", "INSERTIMAGE", "CROP"], "execution": []}, "summary": "The MLLM (Qwen2.5-VL) receives a visual question and image, then iteratively selects tools from a tool server. Perception tools extract visual evidence (coordinates, text, regions), while generation tools create intermediate visualizations (drawn paths, composed images) for verification. The LLM reasons over these outputs across multiple turns, reflecting on results and adjusting tool selection, until it synthesizes a final text answer. Training involves Tool Cold Start (SFT on multi-turn trajectories with reflection) and Tool GRPO (RL optimization for adaptive tool orchestration)."}, {"id": "BK7Mk5d4WE", "title": "LongHorizonUI: A Unified Framework for Robust long-horizon Task Automation of GUI Agent", "authors": ["Bin Kang", "Shaoguo Wen", "YIFEI BI", "Shunlong Wu", "Xinbin Yuan", "Rui Shao", "Junle Wang", "Zhuotao Tian"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=BK7Mk5d4WE", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Gemini2.5"], "non_llm_models": {"perception": ["Icon Detection Model", "OCR Model", "Template Matcher"], "generation": [], "execution": ["GUI Action Executor (click/key press controller)"]}, "summary": "The Multimodal Enhanced Perceiver extracts UI elements from screenshots using OCR and icon detection, assigning unique indices for consistent state representation. The Deep Reflection Decider (Gemini2.5) performs structured validation of historical actions and plans next steps. The Compensatory Action Executor translates decisions into GUI actions with multi-level coordinate fallback strategies, monitors execution outcomes, and initiates rollback and recovery procedures when degradation is detected."}, {"id": "8NXCwNjFNR", "title": "Presenting a Paper is an Art: Self-Improvement Aesthetic Agents for Academic Presentations", "authors": ["Chengzhi Liu", "Yuzhe YANG", "Kaiwen Zhou", "Zhen Zhang", "Yue Fan", "Yanan Xie", "Peng Qi", "Xin Wang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=8NXCwNjFNR", "code": "https://github.com/eric-ai-lab/EvoPresent", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude-4-Sonnet", "DeepSeek-R1", "GPT-5"], "non_llm_models": {"perception": ["Qwen-2.5-VL", "Qwen-Omni-7B", "Marker"], "generation": ["Qwen-Image", "TTS", "HTML/CSS Renderer"], "execution": []}, "summary": "The Storyline Agent extracts paper content using Marker, the Scholar Agent enriches it with knowledge tools and Qwen-Image-generated visuals, the Design Agent renders HTML slides, and the Checker Agent employs PresAesth (RL-trained on Qwen-2.5-VL) to score aesthetics and provide feedback, driving iterative refinement until quality thresholds are met."}, {"id": "bZAKJwyn1n", "title": "Pursuing Minimal Sufficiency in Spatial Reasoning", "authors": ["Yejie Guo", "Yunzhong Hou", "Wufei Ma", "Meng Tang", "Ming-Hsuan Yang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=bZAKJwyn1n", "code": "https://github.com/gyj155/mssr", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Qwen2.5-VL-7B", "Qwen3-VL-8B", "LLaVA-OneVision-7B"], "non_llm_models": {"perception": ["VGGT (3D reconstruction)", "Vision expert models (localization)", "VLM (for SOG module - orientation grounding)"], "generation": [], "execution": []}, "summary": "Multi-view images and a text query are first processed by the Perception Agent, which uses VGGT for 3D reconstruction and vision expert models (including a SOG module for directional grounding) to extract spatial primitives. This information is passed to the Reasoning Agent, which iteratively prunes redundant details and requests missing information from the PA in a closed loop. Once a Minimal Sufficient Set is curated, the RA performs final chain-of-thought reasoning over this compact set to generate the text answer."}, {"id": "5N3z9JQJKq", "title": "AutoFigure: Generating and Refining Publication-Ready Scientific Illustrations", "authors": ["Minjun Zhu", "Zhen Lin", "Yixuan Weng", "Panzhong Lu", "Qiujie Xie", "Yifan Wei", "Sifan Liu", "QiYao Sun", "Yue Zhang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=5N3z9JQJKq", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-5", "Claude-4.1-Opus", "Gemini-2.5-Pro"], "non_llm_models": {"perception": ["OCR"], "generation": ["GPT-Image"], "execution": []}, "summary": "Long-form scientific text is first parsed by an LLM to extract entities/relations and generate an initial symbolic layout (SVG/HTML). An iterative critique-and-refine loop optimizes the layout through AI designer-critic dialogue. The optimized layout is rendered by GPT-Image into a raster image, followed by OCR text extraction and LLM-based verification/correction to overlay accurate vector text, producing the final publication-ready illustration."}, {"id": "PMz29A7Muq", "title": "Seeing, Listening, Remembering, and Reasoning: A Multimodal Agent with Long-Term Memory", "authors": ["Lin Long", "Yichen He", "Wentao Ye", "Yiyuan Pan", "Yuan Lin", "Hang Li", "Junbo Zhao", "Wei Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=PMz29A7Muq", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Qwen3"], "non_llm_models": {"perception": ["Face Detection", "Speaker Diarization", "Qwen2.5-Omni"], "generation": [], "execution": []}, "summary": "Streaming video/audio is processed by Qwen2.5-Omni with Face Detection and Speaker Diarization to extract entities and generate episodic/semantic memories stored in an entity-centric graph. During control, Qwen3 receives questions and iteratively searches the memory graph (via search_node/search_clip tools) through multiple reasoning rounds to generate answers."}, {"id": "xtysskccFc", "title": "ProRe: A Proactive Reward System for GUI Agents via Reasoner–Actor Collaboration", "authors": ["Gaole Dai", "Shiqi Jiang", "Ting Cao", "Yuqing Yang", "Yuanchun Li", "Rui Tan", "Mo Li", "Lili Qiu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=xtysskccFc", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4o", "Gemini-2.5-Pro", "Gemini-2.5-Flash", "GPT-5"], "non_llm_models": {"perception": ["V-Droid", "UI-TARS", "M3A", "Qwen3-VL-4B"], "generation": [], "execution": ["V-Droid", "UI-TARS-72B", "M3A", "Qwen3-VL-4B", "Claude-Sonnet-4.5"]}, "summary": "The reasoner LLM analyzes the task objective and schedules targeted state probing tasks. Evaluator agents (GUI agents with vision and action capabilities) execute these tasks by interacting with the environment to collect key observations. The evaluators summarize both the original policy trajectory and probed states into structured claims, which the reasoner analyzes through chain-of-claims reasoning to verify consistency and assign the final binary reward."}, {"id": "WXFfMLyB6y", "title": "Generalizable Coarse-to-Fine Robot Manipulation via Language-Aligned 3D Keypoints", "authors": ["Jianshu Hu", "Lidi Wang", "Shujia Li", "Yunpeng Jiang", "Xiao Li", "Paul Weng", "Yutong Ban"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=WXFfMLyB6y", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen 2.5 VL-3B"], "non_llm_models": {"perception": ["SigLIP", "DINOv2"], "generation": [], "execution": ["Multi-View Transformer"]}, "summary": "The coarse task planner (Qwen 2.5 VL) decomposes high-level tasks into step-wise instructions and predicts 3D keypoints via reasoning about object positions. The fine-grained action predictor fuses SigLIP-encoded visual-language features, DINOv2-encoded depth features, and 3D position embeddings through a Multi-View Transformer to predict final robot actions (end-effector pose and gripper status)."}, {"id": "ZkoojtEm3W", "title": "Resp-Agent: An Agent-Based System for Multimodal Respiratory Sound Generation and Disease Diagnosis", "authors": ["Pengfei ZHANG", "Tianxin Xie", "Minghao Yang", "Li Liu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=ZkoojtEm3W", "code": "https://github.com/zpforlove/Resp-Agent", "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["DeepSeek-V3.2-Exp"], "non_llm_models": {"perception": ["BEATs"], "generation": ["Resp-MLLM (Qwen3-0.6B-based)", "DiT-style Flow-Matching Decoder", "Vocos"], "execution": []}, "summary": "The Thinker (DeepSeek-V3.2-Exp) orchestrates the workflow by routing tasks to specialized agents. For generation, BEATs extracts style features from reference audio, Resp-MLLM generates discrete acoustic units conditioned on diagnosis text and style, and a Flow Matching Decoder with Vocos reconstructs waveforms. For diagnosis, BEATs extracts audio features which are woven with clinical text via a Longformer to classify diseases. The Thinker analyzes diagnostic confidence and errors to iteratively guide the Generator toward synthesizing challenging cases, closing the loop."}, {"id": "8H0TkSusWI", "title": "NePTune: A Neuro-Pythonic Framework for Tunable Compositional Reasoning on Vision-Language", "authors": ["Danial Kamali", "Parisa Kordjamshidi"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=8H0TkSusWI", "code": "https://github.com/HLR/NePTune", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Grounding DINO", "InternVL2.5", "Qwen2VL", "Ovis1.6", "XVLM"], "generation": [], "execution": []}, "summary": "GPT-4o parses the natural language query into an executable Python program and extracts object names. Grounding DINO detects candidate objects in the image. A VLM (e.g., InternVL2.5) computes continuous concept probability scores for detected objects via visual prompting. The Symbolic Executor runs the Python program using differentiable soft logical operators (fuzzy AND/OR/quantifiers) over these scores to perform compositional reasoning and derive the final text answer."}, {"id": "bmQXN1Kg5i", "title": "TumorChain: Interleaved Multimodal Chain-of-Thought Reasoning for Traceable Clinical Tumor Analysis", "authors": ["Sijing Li", "Zhongwei Qiu", "Jiang Liu", "Wenqiao Zhang", "Tianwei Lin", "Yihan Xie", "Jianxiang An", "Boxiang Yun", "Chenglin Yang", "Jun Xiao", "Guangyu Guo", "Jiawen Yao", "Wei Liu", "Yuan gao", "Ke Yan", "Weiwei Cao", "Zhilin Zheng", "Tony C. W. MOK", "Kai Cao", "Yu Shi", "Jiuyu Zhang", "Jian Zhou", "Beng Chin Ooi", "Yingda Xia", "Ling Zhang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=bmQXN1Kg5i", "code": "https://github.com/ZJU4HealthCare/TumorChain", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5-VL-3B/7B"], "non_llm_models": {"perception": ["M3D (3D vision encoder)", "TotalSegmentator (segmentation expert)", "Auxiliary classification model"], "generation": [], "execution": []}, "summary": "The pipeline processes 3D CT volumes through M3D to extract global vision tokens. The LLM receives these tokens along with the task prompt to generate initial reasoning. Based on this output, the system uses TotalSegmentator to extract organ masks and local ROI tokens, which are enhanced by an auxiliary classification model. These local features are fed back to the LLM in an iterative loop (IIR) where the model performs multi-round self-reflection and causal reasoning, progressively refining the clinical analysis until producing the final chain-of-thought report with pathology conclusions."}, {"id": "3VIPmz7iAi", "title": "GTA1: GUI Test-time Scaling Agent", "authors": ["Yan Yang", "Dongxu Li", "Yutong Dai", "Yuhao Yang", "Ziyang Luo", "Zirui Zhao", "Zhiyuan Hu", "Junzhe Huang", "Amrita Saha", "Zeyuan Chen", "Ran Xu", "Liyuan Pan", "Caiming Xiong", "Junnan Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=3VIPmz7iAi", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["o3", "GPT-5", "Qwen2.5-VL"], "non_llm_models": {"perception": ["GTA1-7B", "GTA1-32B"], "generation": [], "execution": ["GUI automation controller"]}, "summary": "At each step, the planner LLM (o3/GPT-5) samples multiple action proposals based on the task instruction, trajectory history, and current screenshot. A judge model selects the best proposal, which is then passed to the grounding model (GTA1) to predict precise coordinates for coordinate-based actions (e.g., clicks). The action is executed in the GUI environment, and the process repeats with the updated state until task completion."}, {"id": "PVtZnUh04m", "title": "AutoGPS: Automated Geometry Problem Solving via Multimodal Formalization and Deductive Reasoning", "authors": ["Bowen Ping", "Minnan Luo", "Zhuohang Dang", "Chenxi Wang", "Chengyou Jia"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=PVtZnUh04m", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Qwen2.5-VL", "InternVL3"], "non_llm_models": {"perception": ["FPN (Feature Pyramid Network)", "PGDP-Net"], "generation": [], "execution": []}, "summary": "The pipeline processes geometry problem image-text pairs through: (1) FPN detecting key points and PGDP-Net parsing geometric primitives/relations from diagrams, (2) MLLM-based MPF aligning and formalizing multimodal inputs into structured language with syntax validation, (3) iterative feedback between MPF and DSR to ensure formalization correctness, and (4) DSR performing hypergraph-based deductive and algebraic reasoning to generate minimal, human-readable stepwise solutions."}, {"id": "1dH4ARGdwD", "title": "Scaling up Memory for Robotic Control via Experience Retrieval", "authors": ["Ajay Sridhar", "Jennifer Pan", "Satvik Sharma", "Chelsea Finn"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=1dH4ARGdwD", "code": "https://github.com/memer-policy/memer", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL-7B-Instruct"], "non_llm_models": {"perception": [], "generation": [], "execution": ["π0.5"]}, "summary": "The high-level VLM (Qwen2.5-VL) processes task instructions, recent camera frames, and selected keyframes from memory to generate language subtasks and nominate candidate keyframes. A 1D single-linkage clustering filter consolidates candidates into selected keyframes, which are fed back to the high-level policy. The low-level policy (π0.5) executes the subtasks using current observations to output robot actions, operating asynchronously in a closed loop."}, {"id": "yDmb7xAfeb", "title": "WoW!: World Models in a Closed-Loop World", "authors": ["Jiahan Zhang", "Muqing Jiang", "Nanru Dai", "Taiming Lu", "Arda Uzunoglu", "Shunchi Zhang", "Yana Wei", "Jiahao Wang", "Vishal Patel", "Paul Liang", "Daniel Khashabi", "Cheng Peng", "Rama Chellappa", "Tianmin Shu", "Alan Yuille", "Yilun Du", "Jieneng Chen"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=yDmb7xAfeb", "code": "https://github.com/World-In-World/world-in-world", "pattern": "LLM + Perception + Generation + Action", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["VLM (Vision-Language Model)"], "non_llm_models": {"perception": [], "generation": ["SVD", "LTX-Video", "Wan2.1", "Wan2.2", "Cosmos-P2", "Hunyuan", "PathDreamer", "SE3DS", "NWM"], "execution": ["3D Diffusion Policy"]}, "summary": "At each timestep, the VLM (as proposal policy) generates candidate action plans, which are translated by a unified action API into control inputs for video generation world models. These models predict future visual states, which the VLM (as revision policy) evaluates to select the best action for execution in embodied environments. New observations trigger replanning, forming a closed loop."}, {"id": "eNmANCkefl", "title": "Declarative Audio Editing with Audio Language Model", "authors": ["Zitong Lan", "Yiduo Hao", "Mingmin Zhao"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=eNmANCkefl", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Sequential", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Audio Flamingo 2 (AF2)"], "non_llm_models": {"perception": ["CLAP"], "generation": ["Latent Diffusion Model (DiT)"], "execution": []}, "summary": "The ALM (based on AF2) takes original stereo audio encoded by CLAP and a declarative text instruction, then generates a sequence of atomic editing steps (add, remove, adjust volume/direction, etc.). These steps are sequentially executed by an LDM (Diffusion Transformer) which edits the audio latent representation step-by-step to produce the final edited stereo audio."}, {"id": "YkV0fnXgJA", "title": "EdiVal-Agent: An Object-Centric Framework for Automated, Fine-Grained Evaluation of Multi-Turn Editing", "authors": ["Tianyu Chen", "Yasi Zhang", "Zhi Zhang", "Peiyu Yu", "Shu Wang", "Zhendong Wang", "Kevin Lin", "Xiaofei Wang", "Zhengyuan Yang", "Linjie Li", "Chung-Ching Lin", "Jianwen Xie", "Oscar Leong", "Lijuan Wang", "Yingnian Wu", "Mingyuan Zhou"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=YkV0fnXgJA", "code": "https://github.com/TianyuCodings/EdiVal", "pattern": "LLM + Perception", "domain": "Benchmark_Evaluation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Grounding-DINO", "Qwen2-VL", "HPSv3", "DINOv3"], "generation": [], "execution": []}, "summary": "EdiVal-Agent first decomposes input images into structured object descriptions using GPT-4o, validated by Grounding-DINO bounding box detection. It then generates multi-turn editing instructions via GPT-4o while dynamically updating object pools. Finally, it evaluates edited images through a hybrid approach: Grounding-DINO performs symbolic checks for instruction following (EdiVal-IF), Qwen2-VL verifies semantic attributes on detector-guided crops (EdiVal-IF), DINOv3 extracts features for content consistency (EdiVal-CC), and HPSv3 scores visual quality (EdiVal-VQ)."}, {"id": "3u6AkbWEls", "title": "ManipEvalAgent: Promptable and Efficient Evaluation Framework for Robotic Manipulation Policies", "authors": ["Yiteng Chen", "Wenbo Li", "Shiyi Wang", "Xiangyu Zhao", "Huiping Zhuang", "Qingyao Wu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=3u6AkbWEls", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLM", "VLM"], "non_llm_models": {"perception": ["VLM"], "generation": [], "execution": ["ACT", "Diffusion Policy", "DP3", "RDT", "π0"]}, "summary": "ManipEvalAgent uses a Plan Agent (LLM) to decompose user queries into evaluation sub-aspects. TaskGen and ToolGen agents generate Python code to construct simulation tasks and evaluation tools. Robotic manipulation policies execute actions in the simulator, while the VLM performs video understanding via VQA to assess outcomes. Results feed back iteratively to the Plan Agent for multi-round refinement, producing detailed diagnostic reports."}, {"id": "TIqzhBvCNB", "title": "Accelerating Materials Design via LLM-Guided Evolutionary Search", "authors": ["Nikhil Abhyankar", "sanchit kabra", "Saaketh Desai", "Chandan Reddy"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=TIqzhBvCNB", "code": "https://github.com/scientific-discovery/LLEMA", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4o-mini", "Mistral-Small-3.2-24B-Instruct-2506"], "non_llm_models": {"perception": ["CGCNN", "ALIGNN"], "generation": [], "execution": []}, "summary": "The LLM generates candidate materials as crystallographic information files (CIFs) based on task constraints and chemistry-informed rules. Surrogate models (CGCNN/ALIGNN) predict physicochemical properties, which are evaluated by a multi-objective scorer. Success/failure trajectories are stored in memory pools and fed back to the LLM to guide iterative refinement across multiple evolutionary generations."}, {"id": "r2g8TV4nJy", "title": "DriveAgent-R1: Advancing VLM-based Autonomous Driving with Active Perception and Hybrid Thinking", "authors": ["Weicheng Zheng", "Xiaofei Mao", "Nanfei Ye", "Pengxiang Li", "Kun Zhan", "XianPeng Lang", "Hang Zhao"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=r2g8TV4nJy", "code": "https://github.com/Zwc2003/DriveAgent-R1", "pattern": "LLM + Perception", "domain": "Autonomous_Driving", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Qwen2.5-VL-3B", "DriveAgent-R1"], "non_llm_models": {"perception": ["Depth Estimation model", "3D Object Detection model (open-vocabulary)"], "generation": [], "execution": []}, "summary": "DriveAgent-R1 is a Qwen2.5-VL-based autonomous driving agent that adaptively switches between efficient text-only reasoning and tool-augmented visual reasoning. For complex scenarios, it iteratively calls a Vision Toolkit that includes learned Depth Estimation and 3D Object Detection models, alongside deterministic tools such as Retrieve View and RoI Inspection, to acquire on-demand visual evidence before generating an 8-second discrete meta-action sequence."}, {"id": "GK4rznYwhn", "title": "Ground Slow, Move Fast: A Dual-System Foundation Model for Generalizable Vision-Language Navigation", "authors": ["Meng Wei", "Chenyang Wan", "Peng", "Xiqian Yu", "Yuqiang Yang", "Delin Feng", "Wenzhe Cai", "Chenming Zhu", "Tai Wang", "Jiangmiao Pang", "Xihui Liu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=GK4rznYwhn", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen-VL-2.5"], "non_llm_models": {"perception": ["DepthAnythingV2-Small", "Q-Former", "ViT"], "generation": [], "execution": ["Diffusion Transformer (DiT)"]}, "summary": "System 2 (Qwen-VL-2.5) processes RGB observations and language instructions to predict pixel goals (waypoints) and extracts latent goal features via learnable query tuning. These latent goals are passed to System 1, a lightweight Diffusion Transformer policy that fuses them with high-frequency RGB features (encoded by DepthAnythingV2-Small ViT and compressed by Q-Former) to generate smooth 32-point trajectories for real-time robot control. The systems operate asynchronously (2Hz vs 30Hz) with sequential information flow from planning to execution."}, {"id": "whRAOJiyHM", "title": "CARE: Towards Clinical Accountability in Multi-Modal Medical Reasoning with an Evidence-Grounded Agentic Framework", "authors": ["Yuexi Du", "Jinglu Wang", "Shujie LIU", "Nicha C Dvornek", "Yan Lu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=whRAOJiyHM", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-5 (Coordinator)", "InternVL3 (EG-VQA VLM)"], "non_llm_models": {"perception": ["InternVL3 (Entity Proposal VLM)", "SA-Med-2D", "SAM (Segment Anything Model)", "BERT (biomedical text encoder)"], "generation": [], "execution": []}, "summary": "The coordinator (GPT-5) plans the execution flow. First, the Entity Proposal VLM (InternVL3) identifies relevant medical entities from the image. Second, the referring segmentation model (SA-Med-2D/SAM) localizes these entities with pixel-level masks and confidence scores. Third, the EG-VQA VLM reasons over the full image augmented with selected visual evidence (zoom-in crop, mask, or global view). Finally, the coordinator reviews the consistency between the reasoning chain and answer, verifying correctness before output."}, {"id": "aVeaNahsID", "title": "Zephyrus: An Agentic Framework for Weather Science", "authors": ["Sumanth Varambally", "Marshall Fisher", "Jas Thakker", "Yiwei Chen", "Zhirui Xia", "Yasaman Jafari", "Ruijia Niu", "Manas Jain", "Veeramakali Vignesh Manivannan", "Zachary Novack", "Luyu Han", "Srikar Eranky", "Salva Rühling Cachay", "Taylor Berg-Kirkpatrick", "Duncan Watson-Parris", "Yian Ma", "Rose Yu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=aVeaNahsID", "code": "https://github.com/Rose-STL-Lab/Zephyrus", "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-5.2", "GPT-5-Mini", "Gemini 2.5 Flash", "Qwen3-30B-A3B-Thinking-2507"], "non_llm_models": {"perception": ["WeatherBench 2 Data Indexer", "Geolocator"], "generation": [], "execution": ["Stormer", "JCM (climate simulator)", "Climatology module", "Python code execution environment"]}, "summary": "The user query is processed by an LLM which generates Python code using ZEPHYRUSWORLD tools. The code is sent to a FastAPI execution server that distributes requests to workers. Workers acquire resources from tool pools (WeatherBench data, Stormer forecaster, JCM simulator, Geolocator, Climatology), execute the code with timeout protection, and return results or errors. The LLM receives these observations and either refines the code (in Reflective mode) or provides the final answer to the user."}, {"id": "eWoUcwEtLt", "title": "VisionLaw: Inferring Interpretable Intrinsic Dynamics from Visual Observations via Bilevel Optimization", "authors": ["Jiajing Lin", "Shu Jiang", "Qingyuan Zeng", "Zhenzhong Wang", "Min Jiang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=eWoUcwEtLt", "code": null, "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4.1-mini"], "non_llm_models": {"perception": ["3D Gaussian Splatting (3DGS)"], "generation": [], "execution": ["MPM Simulator (Material Point Method)"]}, "summary": "Visual observations are first processed by 3D Gaussian Splatting to reconstruct a 3D representation. GPT-4.1-mini generates candidate symbolic constitutive laws (Python code) representing elastic and plastic material behaviors. These laws are embedded into a differentiable MPM simulator, which executes the physics simulation and renders the predicted dynamics. The rendered output is compared against visual observations to compute a loss, optimizing continuous material parameters and generating fitness feedback that guides the LLM to iteratively refine the constitutive laws via a decoupled evolution strategy."}, {"id": "wQ4OykcxaV", "title": "ARMs: Adaptive Red-Teaming Agent against Multimodal Models with Plug-and-Play Attacks", "authors": ["Zhaorun Chen", "Xun Liu", "Mintong Kang", "Jiawei Zhang", "Minzhou Pan", "Shuang Yang", "Bo Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=wQ4OykcxaV", "code": null, "pattern": "LLM + Generation", "domain": "Benchmark_Evaluation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": [], "generation": ["FLUX.1-schnell"], "execution": []}, "summary": "ARMS takes a risk definition or harmful instruction as input. GPT-4o generates and diversifies seed prompts, retrieves relevant attack strategies from a layered memory via epsilon-greedy selection, and orchestrates 17 plug-and-play attack algorithms (implemented as MCP servers) including FLUX.1-schnell for image generation to craft adversarial multimodal instances. These instances query victim VLMs, and an LLM judge evaluates response harmfulness, with feedback driving iterative attack refinement until success."}, {"id": "NBOHB6aYZh", "title": "Video-STAR: Reinforcing Open-Vocabulary Action Recognition with Tools", "authors": ["Zhenlong Yuan", "Xiangyan Qu", "Chengxuan Qian", "Rui Chen", "Jing Tang", "Lei Sun", "Xiangxiang Chu", "Dapeng Zhang", "Yiwei Wang", "Yujun Cai", "Shuo Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=NBOHB6aYZh", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Qwen2.5-VL"], "non_llm_models": {"perception": ["YOLO 11"], "generation": [], "execution": []}, "summary": "Qwen2.5-VL acts as a central hub that dynamically selects and invokes domain-specific tools (YOLO 11 for pose estimation/human detection, Qwen API for action explanations). It integrates tool outputs with video features, decomposes actions into discriminative sub-motions, and performs hierarchical matching and scoring to produce the final action classification with structured reasoning chains."}, {"id": "l1MQVgIKEU", "title": "CoAct-1: Computer-using Multi-agent System with Coding Actions", "authors": ["Linxin Song", "Yutong Dai", "Viraj Prabhu", "Jieyu Zhang", "Taiwei Shi", "Li Li", "Junnan Li", "silvio savarese", "Zeyuan Chen", "Jieyu Zhao", "Ran Xu", "Caiming Xiong"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=l1MQVgIKEU", "code": "https://github.com/SalesforceAIResearch/CoAct-1", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator", "Translator"], "llm_models": ["OpenAI o3", "OpenAI o4-mini"], "non_llm_models": {"perception": [], "generation": [], "execution": ["OpenAI computer-use-preview"]}, "summary": "CoAct-1 is a hierarchical multi-agent system where an Orchestrator (OpenAI o3) decomposes user goals and routes subtasks to either a Programmer (OpenAI o4-mini) or a GUI Operator (OpenAI computer-use-preview VLA). The Programmer writes Python/Bash scripts that are executed by a deterministic code interpreter, while the GUI Operator runs an interactive loop in which its learned policy maps screenshots to GUI actions (clicks, keystrokes) enacted by a low-level action interpreter. After each subtask, an LLM summarizer condenses the executor’s history, and the Orchestrator uses this feedback to plan the next step until the task is complete."}, {"id": "7tlLpQpGlx", "title": "Simulation to Rules: A Dual-VLM Framework for Formal Visual Planning", "authors": ["Yilun Hao", "Yongchao Chen", "Chuchu Fan", "Yang Zhang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=7tlLpQpGlx", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Translator", "Coordinator", "Verifier"], "llm_models": ["GPT-4o (GenVLM)"], "non_llm_models": {"perception": ["SimVLM (fine-tuned Qwen2-VL-7B)"], "generation": [], "execution": ["PDDL planner"]}, "summary": "SimVLM first perceives the visual input to generate a scenario description and simulate action outcomes. GenVLM uses this to generate initial PDDL domain and problem files. After syntactic prescreening, random action sequences are executed in both the PDDL environment and SimVLM to check consistency. Any discrepancies are fed back to GenVLM for iterative refinement. Once consistent, the PDDL planner generates the final action plan."}, {"id": "sVN9K0BLQj", "title": "Urban Socio-Semantic Segmentation with Vision-Language Reasoning", "authors": ["Yu Wang", "Yi Wang", "Rui Dai", "Yujie Wang", "Kaikui Liu", "Xiangxiang Chu", "Yansheng Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=sVN9K0BLQj", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["VLM (Vision-Language Model)"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)"], "generation": [], "execution": []}, "summary": "Given a satellite image, digital map, and text instruction, the VLM first generates bounding boxes to localize candidate regions. These prompts are fed to SAM to produce a coarse mask. The mask and boxes are rendered onto the inputs and passed back to the VLM, which generates refined bounding boxes and point prompts. These are fed to SAM again to produce the final high-fidelity segmentation mask. The entire non-differentiable workflow is optimized end-to-end using GRPO reinforcement learning."}, {"id": "yDbJHQlrbf", "title": "Code Driven Planning with Domain-Adaptive Selector", "authors": ["Zikang Tian", "Shaohui Peng", "Di Huang", "Jiaming Guo", "Ruizhi Chen", "Rui Zhang", "Xishan Zhang", "Yuxuan Guo", "Zidong Du", "Qi Guo", "Ling Li", "Yewen Pu", "Xing Hu", "Yunji Chen"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=yDbJHQlrbf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Tight", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-3.5", "GPT-4o"], "non_llm_models": {"perception": [], "generation": [], "execution": ["TinyLlama with LoRA (Domain-Adaptive Selector)"]}, "summary": "CoPiC uses GPT-3.5/4o to generate multiple Python planning programs that produce candidate action plans based on textual environment observations. A separate TinyLlama model with LoRA—fine-tuned via PPO—serves as a domain-adaptive selector that scores and selects the best candidate plan for execution by a Python interpreter. After execution, the LLM refines the planning programs using summarized history, while the selector is updated with stored transitions, forming an iterative planning-learning loop."}, {"id": "yhhbL9T1QB", "title": "FaSTA*: Fast-Slow Toolpath Agent with Subroutine Mining for Efficient Multi-turn Image Editing", "authors": ["Advait Gupta", "Rishie Raj", "Dang Nguyen", "Tianyi Zhou"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=yhhbL9T1QB", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["YOLO", "SAM", "Grounding DINO", "VLM"], "generation": ["Stable Diffusion"], "execution": []}, "summary": "GPT-4o decomposes input instructions into subtasks and selects learned subroutines (sequences of perception and generation tools) for fast planning. Perception models (YOLO/SAM/Grounding DINO) extract visual information to guide Stable Diffusion for editing. A VLM verifies outputs, triggering A* search-based slow planning only when subroutines fail, progressively refining subroutines from execution traces."}, {"id": "Z091XLyVkJ", "title": "Omni-Captioner: Data Pipeline, Models, and Benchmark for Omni Detailed Perception", "authors": ["Ziyang Ma", "Ruiyang Xu", "Zhenghao Xing", "Yunfei Chu", "Yuxuan Wang", "Jinzheng He", "Jin Xu", "Pheng-Ann Heng", "Kai Yu", "Junyang Lin", "Ensiong Chng", "Xie Chen"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=Z091XLyVkJ", "code": "https://github.com/ddlBoJack/Omni-Captioner", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["Gemini 2.5 Pro"], "non_llm_models": {"perception": ["OCR", "ASR", "MLLM"], "generation": [], "execution": []}, "summary": "Omni-Detective uses an LLM agent to iteratively invoke perception tools (OCR, ASR, MLLM) and observers, gathering multi-modal evidence through tool-calling APIs. The LLM integrates these observations, cross-checks for accuracy, and synthesizes detailed audio-visual captions via iterative refinement."}, {"id": "CCSPm6V5EF", "title": "WebDevJudge: Evaluating (M)LLMs as Critiques for Web Development Quality", "authors": ["Chunyang Li", "Yilun Zheng", "Xinting Huang", "Tianqing Fang", "Jiahao Xu", "Lihui Chen", "Yangqiu Song", "Han Hu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=CCSPm6V5EF", "code": "https://github.com/lcy2723/WebDevJudge", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4.1", "GPT-4o", "Claude-4-Sonnet", "Claude-3.7-Sonnet", "Gemini-2.5-pro", "Qwen-2.5-VL", "DeepSeek-V3", "DeepSeek-R1"], "non_llm_models": {"perception": [], "generation": [], "execution": ["UI-TARS-1.5"]}, "summary": "The framework supports two evaluation paradigms: (1) Vanilla MLLMs directly analyze code and screenshots to judge quality; (2) Agentic workflow where an LLM planner generates test cases, UI-TARS-1.5 executes interactions in the web environment, and an LLM summarizer aggregates results into final judgments. The system performs pairwise comparisons or single-answer grading to predict human preference labels."}, {"id": "oN55r8iJJW", "title": "SAM-Veteran: An MLLM-Based Human-like SAM Agent for Reasoning Segmentation", "authors": ["Tianyuan Du", "Haopeng Li", "Zhen Fan", "Jiarui Zhang", "Panwang Pan", "Yang Zhang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=oN55r8iJJW", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Qwen2.5-VL-7B-Instruct"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)", "SAM2-Large"], "generation": [], "execution": []}, "summary": "Given an image and text query, Qwen2.5-VL generates a bounding box and reasoning chain. SAM produces an initial mask from the box. The mask is fed back to the MLLM, which evaluates it and generates refinement points (positive/negative) or termination signals. SAM uses these points to refine the mask iteratively until the MLLM determines the segmentation is satisfactory. The MLLM is trained via multi-task RL (GRPO) with rewards based on mask IoU and decision correctness."}, {"id": "tdN42GTv4S", "title": "PerfGuard: A Performance-Aware Agent for Visual Content Generation", "authors": ["Zhipeng Chen", "Chao Zhang", "zhongrui zhang", "Yifan Xu", "LAN YANG", "Jun Liu", "Ke Li", "Yi-Zhe Song"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=tdN42GTv4S", "code": "https://github.com/FelixChan9527/PerfGuard", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["QWen3-VL-32B", "GPT-4o"], "non_llm_models": {"perception": ["CLIP"], "generation": ["FLUX", "Stable Diffusion 3", "Step1X", "OmniGen", "AnySD", "ICEdit", "UltraEdit", "CreatiLayout"], "execution": []}, "summary": "User input is parsed by the Analyst (LLM) into task semantics and goals. The Planner (LLM) decomposes the task into subtasks, which the Worker matches to generation/editing tools using PASM based on multi-dimensional performance scores. Selected tools (e.g., FLUX, SD3) execute the subtasks. The Self-Evaluator assesses outputs against goals, feeding results back to update performance boundaries (APU) and guide the Planner's next decisions (CAPO), enabling iterative refinement of the visual content generation process."}, {"id": "fC27SxF4ba", "title": "MATA: A Trainable Hierarchical Automaton System for Multi-Agent Visual Reasoning", "authors": ["Zhixi Cai", "Fucai Ke", "Kevin Leo", "Sukai Huang", "Maria de la Banda", "Peter Stuckey", "Hamid Rezatofighi"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=fC27SxF4ba", "code": "https://github.com/ControlNet/MATA", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator"], "llm_models": ["Qwen3"], "non_llm_models": {"perception": ["Florence2-L", "DepthAnythingV2", "InternVL2.5"], "generation": [], "execution": []}, "summary": "A finetuned Qwen3 hyper agent iteratively routes control among agent states (Specialized Agent, Oneshot Reasoner, Stepwise Reasoner) by reading a shared memory snapshot. The Specialized Agent uses Florence2-L, DepthAnythingV2, and InternVL2.5 for visual perception. Reasoners generate Python programs that are verified and executed by a deterministic sandboxed interpreter. All intermediate results and verifier feedback are written back to shared memory to inform subsequent transitions."}, {"id": "ZOuU0udyA4", "title": "MedAgent-Pro: Towards Evidence-based Multi-modal Medical Diagnosis via Reasoning Agentic Workflow", "authors": ["Ziyue Wang", "Junde Wu", "Linghan Cai", "Chang Low", "Xihong Yang", "Qiaxuan Li", "Yueming Jin"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=ZOuU0udyA4", "code": null, "pattern": "LLM + Perception + Action", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["MedSAM", "Cellpose"], "generation": [], "execution": ["LLM-based coding tools (Copilot)", "Python code execution environment"]}, "summary": "The system first uses a RAG agent with PubMedBERT embeddings to retrieve medical guidelines and generate a disease-specific diagnostic plan. Then, GPT-4o executes this plan by orchestrating visual segmentation models (MedSAM/Cellpose) and coding tools to perform quantitative analysis on multi-modal patient data. An evidence-based reflection mechanism verifies each step's reliability before aggregating indicators into a risk-weighted final diagnosis."}, {"id": "HtpjSCs3g5", "title": "PixelCraft: A Multi-Agent system for High-Fidelity Visual Reasoning on Structured Images", "authors": ["Shuoshuo Zhang", "Zijian Li", "Yizhen Zhang", "Jingjing Fu", "Lei Song", "Jiang Bian", "Jun Zhang", "Yujiu Yang", "Rui Wang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=HtpjSCs3g5", "code": "https://github.com/microsoft/PixelCraft", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "GPT-4.1-mini", "Claude 3.7 Sonnet"], "non_llm_models": {"perception": ["Qwen2.5-VL-3B (fine-tuned grounding model)", "Matplotlib-based rendering", "contour detection", "geometric operators"], "generation": [], "execution": []}, "summary": "The dispatcher selects relevant tool agents based on the query. The planner orchestrates a dynamic workflow, managing an image memory to coordinate tool agents (which use the fine-tuned grounding model and CV algorithms to generate high-fidelity visual edits like cropping and masking) and a reasoner. A visual critic verifies intermediate edits in-loop, while a planning critic reviews the full trace to enable iterative self-correction, ultimately producing a text answer through progressive visual reasoning."}, {"id": "WffiETiSeU", "title": "Part-X-MLLM: Part-aware 3D Multimodal Large Language Model", "authors": ["Chunshi Wang", "Junliang Ye", "Yunhan Yang", "YANG LI", "Zizhuo Lin", "Jun Zhu", "Zhuo Chen", "Yawei Luo", "Chunchao Guo"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=WffiETiSeU", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen 2.5 VL"], "non_llm_models": {"perception": ["Structure Encoder (Hunyuan3D VAE)", "Semantic Encoder", "CLIP"], "generation": ["OmniPart", "VoxHammer"], "execution": []}, "summary": "RGB point clouds are processed by dual encoders (Structure for geometry, Semantic for appearance) to extract features that are fused with text prompts and fed into Qwen 2.5 VL. The LLM autoregressively generates a structured program with part bounding boxes and edit commands, which is then executed by downstream generation modules: OmniPart for part-aware synthesis or VoxHammer for localized editing."}, {"id": "7BLnSeWuei", "title": "CP-Agent: Context‑Aware Multimodal Reasoning for Cellular Morphological Profiling under Chemical Perturbations", "authors": ["Yuxin Zhang", "Yiyao Li", "Ping Ho", "Simon See", "Zhenqin Wu", "Kevin Tsia"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=7BLnSeWuei", "code": "https://github.com/letitia-zhang/CP-Agent", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["GPT-5", "Gemini-2.5-Pro"], "non_llm_models": {"perception": ["CP-CLIP (ViT-B/16, ViT-L/16)", "VISTA-2D", "CellProfiler"], "generation": [], "execution": []}, "summary": "CP-Agent processes Cell Painting microscopy images through a directed workflow: CP-CLIP retrieves experimental context and aligns images with structured metadata; VISTA-2D performs nuclei and whole-cell segmentation; CellProfiler extracts handcrafted morphological features; LLM-powered agents (FeatRank, StatSynth, ReportGen) sequentially rank features by perturbation relevance, compute statistical evidence (effect sizes, significance), and synthesize mechanism-of-action hypotheses into interpretable text reports."}, {"id": "SzhezVoaNB", "title": "Scenethesis: A Language and Vision Agentic Framework for 3D Scene Generation", "authors": ["Lu Ling", "Chen-Hsuan Lin", "Tsung-Yi Lin", "Yifan Ding", "Yu Zeng", "Yichen Sheng", "Yunhao Ge", "Ming-Yu Liu", "Aniket Bera", "Max Li"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=SzhezVoaNB", "code": null, "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-5"], "non_llm_models": {"perception": ["Grounded SAM", "DepthPro", "RoMa"], "generation": [], "execution": []}, "summary": "GPT-5 drafts a coarse scene plan from text. The vision module generates a guidance image (via GPT-5) and extracts a scene graph with 3D bounding boxes using Grounded SAM and DepthPro. A physics-aware optimization module uses RoMa for pose alignment and enforces collision/stability constraints via SDFs. Finally, a judge module (GPT-5) verifies spatial coherence and triggers re-planning if needed, outputting a 3D scene with retrieved Objaverse assets."}, {"id": "LfkPlFTfe0", "title": "Human-Object Interaction via Automatically Designed VLM-Guided Motion Policy", "authors": ["Zekai Deng", "Ye Shi", "Kaiyang Ji", "Lan Xu", "Shaoli Huang", "Jingya Wang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=LfkPlFTfe0", "code": "https://github.com/VLM-RMD/VLM-RMD-release", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": [], "generation": [], "execution": ["PPO-based RL policy", "physics-based humanoid controller (PD controller)", "Isaac Gym simulator"]}, "summary": "GPT-4V receives high-level text instructions and top-view environment images, then generates a multi-step interaction plan as an RMD (Relative Movement Dynamics) graph encoding spatio-temporal relationships between human and object parts. This structured plan is automatically parsed to construct goal states and reward functions, which condition a PPO-trained RL policy to output joint torques for a physics-based humanoid controller in Isaac Gym, executing the interaction sequence step-by-step."}, {"id": "H7gtryDnVK", "title": "No labels, No Problem: Training Visual Reasoners with Multimodal Verifiers", "authors": ["Damiano Marsili", "Georgia Gkioxari"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=H7gtryDnVK", "code": "https://github.com/damianomarsili/VALOR", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Qwen3-8B", "Gemini-2.5-Flash"], "non_llm_models": {"perception": ["GroundingDINO", "MoGe2", "GPT-5-mini"], "generation": [], "execution": []}, "summary": "Given an image and query, the LLM generates a natural language plan and Python program that sequentially calls perception tools (GroundingDINO for object detection, MoGe2 for depth estimation, and GPT-5-mini for VQA) to extract visual information; the program is executed to compute measurements and derive a text answer. During training, separate LLM and VLM verifiers critique the reasoning and grounding outputs to provide learning signals without ground truth labels."}, {"id": "81PJ2KPnmK", "title": "DreamPhase: Offline Imagination and Uncertainty-Guided Planning for Large-Language-Model Agents", "authors": ["Shayan Mohajer Hamidi", "Linfeng Ye", "Konstantinos Plataniotis"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=81PJ2KPnmK", "code": null, "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaMA-2-7B", "LLaMA3-70B", "Mistral-7B", "Phi-3-8B"], "non_llm_models": {"perception": ["Latent World Model (LWM) — encoder fθ, transition gθ, decoder dθ"], "generation": [], "execution": []}, "summary": "DreamPhase trains a compact latent world model (LWM) on logged trajectories to encode raw observations and simulate multi-step futures in latent space. At each step, the LWM rolls out M parallel imagined branches conditioned on actions from a frozen LLM policy; a learned value head scores each branch and an uncertainty gate filters high-risk ones. The best safe branch is distilled into a short natural-language reflection and summary that condition the frozen LLM to select the final action, drastically reducing real environment queries."}, {"id": "JoXwhGbuMi", "title": "ReCogDrive: A Reinforced Cognitive Framework for End-to-End Autonomous Driving", "authors": ["yongkang li", "Kaixin Xiong", "Xiangyu Guo", "Fang Li", "Sixu Yan", "Gangwei Xu", "Lijun Zhou", "Long Chen", "Haiyang Sun", "Bing Wang", "Kun Ma", "Guang Chen", "Hangjun Ye", "Wenyu Liu", "Xinggang Wang"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=JoXwhGbuMi", "code": null, "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["InternVL3-2B", "InternVL3-8B", "Qwen2.5"], "non_llm_models": {"perception": ["InternViT"], "generation": [], "execution": ["Diffusion Planner (DiT)"]}, "summary": "Multi-view camera images are encoded by InternViT and processed by InternVL3 (Qwen2.5-based VLM) to generate cognitive hidden states and reasoning. These cognitive tokens, combined with ego status and historical trajectories, condition a Diffusion Transformer planner via cross-attention to iteratively denoise and generate continuous future trajectories. The system is trained in three stages: VLM pre-training on hierarchical cognitive data, imitation learning for the diffusion planner, and DiffGRPO reinforcement learning to optimize for safety and comfort."}, {"id": "yv15C8ql24", "title": "pySpatial: Generating 3D Visual Programs for Zero-Shot Spatial Reasoning", "authors": ["Zhanpeng Luo", "Ce Zhang", "Silong Yong", "Cunxi Dai", "Qianwei Wang", "Haoxi Ran", "Guanya Shi", "Katia Sycara", "Yaqi Xie"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=yv15C8ql24", "code": "https://github.com/Zhanpeng1202/pySpatial", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator", "Translator", "Reasoner"], "llm_models": ["GPT-4o", "GPT-4.1", "GPT-4.1-mini"], "non_llm_models": {"perception": ["CUT3R", "VGGT", "Open3D (rasterization)"], "generation": [], "execution": ["Robot velocity-tracking controller"]}, "summary": "Given an image sequence and query, the MLLM generates a Python program (visual program) invoking spatial tools via API. The interpreter executes 3D reconstruction (CUT3R/VGGT) to build a point cloud, performs camera transformations (rotate/move), and synthesizes novel views via rasterization. The program outputs (rendered views, camera descriptions) are fed back to the MLLM with the original images to generate the final text answer. For navigation, the program outputs motion commands executed by a robot controller."}, {"id": "GN8OdkTo3B", "title": "Hilbert: Recursively Building Formal Proofs with Informal Reasoning", "authors": ["Sumanth Varambally", "Thomas Voice", "Yanchao Sun", "Zhifeng Chen", "Rose Yu", "Ke Ye"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=GN8OdkTo3B", "code": "https://github.com/Rose-STL-Lab/ml-hilbert", "pattern": "LLM + Perception + Action", "domain": "Code_Development", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["Gemini 2.5 Pro", "Gemini 2.5 Flash", "gpt-oss-120b", "DeepSeek-Prover-V2-7B", "Goedel-Prover-V2-32B"], "non_llm_models": {"perception": ["all-mpnet-base-v2"], "generation": [], "execution": ["Lean 4 Verifier (Kimina Lean Server)"]}, "summary": "Given a formal theorem, HILBERT retrieves relevant theorems using the semantic retriever, then uses the Reasoner LLM to generate an informal proof and formal sketch with subgoals. It attempts to solve each subgoal using the Prover LLM; upon failure, the Reasoner attempts a shallow solve with retrieval augmentation. If both fail, the system recursively decomposes the subgoal. The Lean Verifier checks all proof attempts, providing error feedback to the Reasoner for iterative refinement until a valid proof is assembled."}, {"id": "ovSDneawKY", "title": "FilMaster: Bridging Cinematic Principles and Generative AI for Automated Film Generation", "authors": ["Kaiyi Huang", "Yukun Huang", "Xintao WANG", "Zinan Lin", "Xuefei Ning", "Pengfei Wan", "Di ZHANG", "Yu Wang", "Xihui Liu"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=ovSDneawKY", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Gemini-2.0-Flash"], "non_llm_models": {"perception": ["Gemini-2.0-Flash (as audience reviewer)", "text-embed-3-small"], "generation": ["Kling Elements 1.6", "Audio generation models (foley/SFX/VO/music)"], "execution": []}, "summary": "The pipeline takes text and reference images, uses GPT-4o for script elaboration and scene-level RAG-based camera language design (retrieving from 440k film clips via text embeddings), generates video clips using Kling Elements 1.6, assembles a Rough Cut, has Gemini-2.0-Flash simulate audience review for feedback, and finally performs video editing and multi-track sound design to produce a professional film."}, {"id": "aQWSEjcN9V", "title": "Endowing GPT-4 with a Humanoid Body: Building the Bridge Between Off-the-Shelf VLMs and the Physical World", "authors": ["Yingzhao Jian", "Zhongan Wang", "Yi Yang", "Hehe Fan"], "venue": "ICLR", "year": 2026, "url": "https://openreview.net/pdf?id=aQWSEjcN9V", "code": "https://github.com/Shadow-Dream/BiBo", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-4o"], "non_llm_models": {"perception": [], "generation": ["Latent Diffusion Model (LDM)", "Variational Autoencoder (VAE)"], "execution": ["RL tracking policy"]}, "summary": "The VLM (GPT-4) perceives scene images and user instructions, then compiles high-level instructions into structured commands (motion caption, location, facing, joint targets) through a three-stage coarse-to-fine reasoning process. These commands condition a Latent Diffusion Model (LDM) with VAE that generates future humanoid motion trajectories, incorporating physical feedback from the actual executed motion to ensure smooth transitions. An RL tracking policy executes the generated motions in a physics simulator, with the executed motion fed back to the LDM for subsequent generation steps."}, {"id": "nottingham23a", "title": "Do Embodied Agents Dream of Pixelated Sheep: Embodied Decision Making using Language Guided World Modelling", "authors": ["Kolby Nottingham", "Prithviraj Ammanabrolu", "Alane Suhr", "Yejin Choi", "Hannaneh Hajishirzi", "Sameer Singh", "Roy Fox"], "venue": "ICML", "year": 2023, "url": "http://proceedings.mlr.press/v202/nottingham23a/nottingham23a.pdf", "code": "https://github.com/DeckardAgent/deckard", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["Codex"], "non_llm_models": {"perception": [], "generation": [], "execution": ["VPT", "VPT-a (VPT with adapter modules)"]}, "summary": "Codex generates a hypothesized Abstract World Model (AWM) as a DAG of item dependencies via few-shot prompting. During the Dream phase, the agent samples frontier subgoals from this AWM. In the Wake phase, VPT policies finetuned with lightweight adapters execute the subgoal paths in Minecraft. Execution results verify or correct the AWM, and the process iterates until the target item is crafted."}, {"id": "zhou23r", "title": "ESC: Exploration with Soft Commonsense Constraints for Zero-shot Object Navigation", "authors": ["Kaiwen Zhou", "Kaizhi Zheng", "Connor Pryor", "Yilin Shen", "Hongxia Jin", "Lise Getoor", "Xin Eric Wang"], "venue": "ICML", "year": 2023, "url": "http://proceedings.mlr.press/v202/zhou23r/zhou23r.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Deberta v3", "ChatGPT"], "non_llm_models": {"perception": ["GLIP (Grounded Language-Image Pre-training)"], "generation": [], "execution": ["Deterministic navigation policy"]}, "summary": "RGB-D observations are processed by GLIP to detect objects and rooms, which are projected to a semantic map. The LLM takes the detected scene context and goal object to infer commonsense spatial relationships (e.g., 'fireplace is likely in living room'), outputting confidence scores. These scores are combined with frontier distances in PSL (Probabilistic Soft Logic) to optimize frontier selection. A deterministic policy then navigates the agent to the selected frontier or directly to the goal when detected."}, {"id": "shaham24a", "title": "A Multimodal Automated Interpretability Agent", "authors": ["Tamar Rott Shaham", "Sarah Schwettmann", "Franklin Wang", "Achyuta Rajaram", "Evan Hernandez", "Jacob Andreas", "Antonio Torralba"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/shaham24a/shaham24a.pdf", "code": null, "pattern": "LLM + Generation", "domain": "Scientific_Discovery", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion v1.5", "Instruct-Pix2Pix", "DALL-E 3"], "execution": []}, "summary": "MAIA prompts a GPT-4V backbone with an interpretability query. GPT-4V writes Python programs that call a Tool API, and a deterministic Python interpreter executes them. The Tool API includes generation models (Stable Diffusion v1.5, Instruct-Pix2Pix, and optionally DALL-E 3) to synthesize and edit images, plus a System API to query target vision models. GPT-4V observes the outputs and iteratively refines its hypotheses until it produces a final description. No separate learned perception or action models are used."}, {"id": "zheng24e", "title": "GPT-4V(ision) is a Generalist Web Agent, if Grounded", "authors": ["Boyuan Zheng", "Boyu Gou", "Jihyung Kil", "Huan Sun", "Yu Su"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/zheng24e/zheng24e.pdf", "code": "https://github.com/OSU-NLP-Group/SeeAct", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": ["DeBERTa-base cross-encoder"], "generation": [], "execution": []}, "summary": "SeeAct uses GPT-4V to visually perceive a webpage screenshot and generate a textual action description. A DeBERTa-base cross-encoder processes the HTML to rank candidate elements, which are presented to GPT-4V as textual choices for element grounding. The selected action is then deterministically executed on the live website via Playwright."}, {"id": "cen24a", "title": "Using Left and Right Brains Together: Towards Vision and Language Planning", "authors": ["Jun Cen", "Chenfei Wu", "Xiao Liu", "Shengming Yin", "Yixuan Pei", "Jinglong Yang", "Qifeng Chen", "Nan Duan", "Jianguo Zhang"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/cen24a/cen24a.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Converge", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["ChatGPT", "LLaVA", "GPT-4V", "BERT"], "non_llm_models": {"perception": ["CLIP", "BLIP-2"], "generation": ["Stable Video Diffusion", "DMVFN", "MCVD"], "execution": []}, "summary": "User queries are converted into vision and language inputs. In parallel, ChatGPT generates step-by-step language plans via chain-of-thought prompting, while Stable Video Diffusion (or domain-specific alternatives) generates future frames that are filtered by a Vision Planning Selector using CLIP and BLIP-2. A Decision Maker (LLaVA, GPT-4V, or BERT) synthesizes both plans through multi-round conversation and voting to produce the final answer."}, {"id": "wang24cc", "title": "RoboGen: Towards Unleashing Infinite Data for Automated Robot Learning via Generative Simulation", "authors": ["Yufei Wang", "Zhou Xian", "Feng Chen", "Tsun-Hsuan Wang", "Yian Wang", "Katerina Fragkiadaki", "Zackory Erickson", "David Held", "Chuang Gan"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/wang24cc/wang24cc.pdf", "code": "https://github.com/Genesis-Embodied-AI/RoboGen", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["Gemini-Pro"], "generation": ["Midjourney", "Zero-1-to-3", "text-to-3D models"], "execution": ["SAC (Soft Actor-Critic)", "BIT* motion planning", "gradient-based trajectory optimization"]}, "summary": "GPT-4 proposes tasks based on robot capabilities and object affordances, then queries Midjourney, Zero-1-to-3, and text-to-3D models to generate required 3D assets. Gemini-Pro verifies the retrieved/generated assets visually. GPT-4 then decomposes tasks into sub-tasks, selects the optimal learning algorithm (RL, motion planning, or trajectory optimization), generates reward functions, and executes skill learning in simulation to acquire the proposed robotic skills."}, {"id": "wu24e", "title": "NExT-GPT: Any-to-Any Multimodal LLM", "authors": ["Shengqiong Wu", "Hao Fei", "Leigang Qu", "Wei Ji", "Tat-Seng Chua"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/wu24e/wu24e.pdf", "code": "https://github.com/NExT-GPT/NExT-GPT", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["ImageBind", "CLIP"], "generation": ["Stable Diffusion", "Zeroscope", "AudioLDM"], "execution": []}, "summary": "Multimodal inputs (text/image/audio/video) are encoded by ImageBind and projected into LLM space via input projection layers. Vicuna LLM performs reasoning and generates text responses alongside special signal tokens ([IMG], [AUD], [VID]) that dictate which modalities to output. These signals are projected via output projection layers to condition frozen diffusion models (Stable Diffusion for images, Zeroscope for video, AudioLDM for audio) for content generation."}, {"id": "hu24g", "title": "SceneCraft: An LLM Agent for Synthesizing 3D Scenes as Blender Code", "authors": ["Ziniu Hu", "Ahmet Iscen", "Aashi Jain", "Thomas Kipf", "Yisong Yue", "David A Ross", "Cordelia Schmid", "Alireza Fathi"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/hu24g/hu24g.pdf", "code": "https://github.com/gd3kr/BlenderGPT", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["CLIP", "GPT-4V"], "generation": ["Blender"], "execution": []}, "summary": "Text queries are decomposed by GPT-4 into sub-scenes and asset lists. CLIP retrieves 3D assets from a repository. GPT-4 constructs a relational scene graph representing spatial constraints, then generates Blender Python code to instantiate the scene. Blender renders the scene, and GPT-4V critiques the rendered image against the text description. This feedback loop iteratively refines the scene graph and code until convergence. An outer-loop library learning mechanism accumulates common code patterns across scenes to improve future generations."}, {"id": "sprueill24a", "title": "CHEMREASONER: Heuristic Search over a Large Language Model’s Knowledge Space using Quantum-Chemical Feedback", "authors": ["Henry W. Sprueill", "Carl Edwards", "Khushbu Agarwal", "Mariefel V Olarte", "Udishnu Sanyal", "Conrad Johnston", "Hongbin Liu", "Heng Ji", "Sutanay Choudhury"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/sprueill24a/sprueill24a.pdf", "code": "https://github.com/pnnl/chemreasoner", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["GemNet-dT"], "generation": [], "execution": []}, "summary": "User query initiates LLM-based tree search where each node generates candidate catalysts (text), which are converted to 3D structures and evaluated by GemNet-dT GNN predicting adsorption energies and reaction barriers. Rewards guide beam search pruning and feed back to the LLM planner for iterative refinement until optimal catalysts are identified."}, {"id": "yang24d", "title": "DoraemonGPT: Toward Understanding Dynamic Scenes with Large Language Models (Exemplified as A Video Agent)", "authors": ["Zongxin Yang", "Guikun Chen", "Xiaodi Li", "Wenguan Wang", "Yi Yang"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/yang24d/yang24d.pdf", "code": "https://github.com/z-x-yang/DoraemonGPT", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["YOLOv8", "Grounding DINO", "DeAOT", "Deep OC-Sort", "BLIP-2", "InstructBlip", "InternVideo", "Whisper", "PaddleOCR"], "generation": [], "execution": []}, "summary": "Input video is processed by perception models to extract task-related spatial-temporal attributes (trajectories, captions, actions, OCR, audio) into a symbolic SQL-based memory. The MCTS planner decomposes the task and routes queries to sub-task tools (specialized LLM agents) that retrieve information from the memory. The planner iteratively explores multiple reasoning paths via tree search with reward backpropagation, then aggregates candidate solutions into a final text answer."}, {"id": "wu24u", "title": "VoroNav: Voronoi-based Zero-shot Object Navigation with Large Language Model", "authors": ["Pengying Wu", "Yao Mu", "Bingxian Wu", "Yi Hou", "Ji Ma", "Shanghang Zhang", "Chang Liu"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/wu24u/wu24u.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-3.5", "GPT-4", "Gemini-pro"], "non_llm_models": {"perception": ["Grounded-SAM", "BLIP"], "generation": [], "execution": []}, "summary": "RGB-D inputs are processed by Grounded-SAM to construct a semantic map and by BLIP to generate farsight captions. A Reduced Voronoi Graph is extracted from the map via classical geometric algorithms. GPT-3.5 generates path descriptions and estimates target probabilities from fused textual prompts. A deterministic hierarchical reward mechanism selects the next waypoint, and the Fast Marching Method plans low-level actions to reach it."}, {"id": "zhen24a", "title": "3D-VLA: A 3D Vision-Language-Action Generative World Model", "authors": ["Haoyu Zhen", "Xiaowen Qiu", "Peihao Chen", "Jincheng Yang", "Xin Yan", "Yilun Du", "Yining Hong", "Chuang Gan"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/zhen24a/zhen24a.pdf", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["BLIP2-FlanT5XL"], "non_llm_models": {"perception": ["Grounded-SAM", "ZoeDepth", "RAFT", "Q-Former"], "generation": ["Stable Diffusion V1.4", "Point-E"], "execution": ["3D-VLA action token generator"]}, "summary": "Multi-view images and point clouds are processed by Q-Former and perception models (Grounded-SAM, ZoeDepth, RAFT) to extract 3D features and object locations. The BLIP2-FlanT5XL-based LLM reasons over these features and dispatches generation tasks via a projector to embodied diffusion models (Stable Diffusion for RGB-D goals, Point-E for point clouds). The generated goal states are fed back to the LLM, which then outputs discrete action tokens for robot manipulation control."}, {"id": "yang24ai", "title": "Mastering Text-to-Image Diffusion: Recaptioning, Planning, and Generating with Multimodal LLMs", "authors": ["Ling Yang", "Zhaochen Yu", "Chenlin Meng", "Minkai Xu", "Stefano Ermon", "Bin Cui"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/yang24ai/yang24ai.pdf", "code": "https://github.com/YangLing0818/RPG-DiffusionMaster", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "Multimodal LLM"], "non_llm_models": {"perception": [], "generation": ["SDXL", "Stable Diffusion"], "execution": []}, "summary": "User text prompts are processed by GPT-4 (MLLM) for recaptioning into detailed subprompts and chain-of-thought planning to assign them to complementary spatial regions. SDXL then executes complementary regional diffusion to generate images. For editing, the MLLM analyzes the generated image to identify discrepancies, plans refinement operations, and triggers region-wise inpainting in an iterative closed-loop manner."}, {"id": "lv24a", "title": "RoboMP$^2$: A Robotic Multimodal Perception-Planning Framework with Multimodal Large Language Models", "authors": ["Qi Lv", "Hao Li", "Xiang Deng", "Rui Shao", "Michael Y Wang", "Liqiang Nie"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/lv24a/lv24a.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "GPT-4V"], "non_llm_models": {"perception": ["GCMP", "EVA-CLIP", "flan-t5-xl"], "generation": [], "execution": ["RobotExecution"]}, "summary": "RAMP retrieves relevant code examples via coarse-to-fine retrieval (TF-IDF + SentenceBERT) and rewrites the query using GPT-4. GPT-4V then generates a Python policy incorporating the visual observation and retrieved demonstrations, which calls GCMP to localize objects via multimodal perception. Finally, RobotExecution carries out the planned manipulation actions."}, {"id": "mu24a", "title": "RoboCodeX: Multimodal Code Generation for Robotic Behavior Synthesis", "authors": ["Yao Mu", "Junting Chen", "Qing-Long Zhang", "Shoufa Chen", "Qiaojun Yu", "Chongjian Ge", "Runjian Chen", "Zhixuan Liang", "Mengkang Hu", "Chaofan Tao", "Peize Sun", "Haibao Yu", "Chao Yang", "Wenqi Shao", "Wenhai Wang", "Jifeng Dai", "Yu Qiao", "Mingyu Ding", "Ping Luo"], "venue": "ICML", "year": 2024, "url": "https://raw.githubusercontent.com/mlresearch/v235/main/assets/mu24a/mu24a.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["RoboCodeX (BLIP2-based VLM)"], "non_llm_models": {"perception": ["GLIP-Large", "AnyGrasp", "GAMMA", "PointNet++"], "generation": [], "execution": ["ROS motion planner", "Operational Space Controller"]}, "summary": "RoboCodeX receives RGBD observations and language instructions, decomposes tasks into object-centric units via tree-of-thought reasoning, queries perception APIs (GLIP for detection, AnyGrasp for grasps, GAMMA for articulation constraints), generates executable Python/ROS code tailored to specific robot morphologies, and executes via motion planning and operational space control to produce collision-free robot trajectories."}, {"id": "cJeFULIiot", "title": "LLMs can see and hear without any training", "authors": ["Kumar Ashutosh", "Yossi Gandelsman", "Xinlei Chen", "Ishan Misra", "Rohit Girdhar"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=cJeFULIiot", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["Llama 3", "Llama 3.1 8B"], "non_llm_models": {"perception": ["CLIP", "SigLIP", "ViCLIP", "ImageBind", "PickScore", "VGG19"], "generation": ["Latent Diffusion Model", "FLUX", "Emu"], "execution": []}, "summary": "Input (image/video/audio/text) is processed by the LLM (GENERATOR) proposing candidate captions or prompts. A SCORER (CLIP/SigLIP/etc.) evaluates candidates against the input, returning scores formatted as text feedback. The LLM iteratively refines candidates based on these scores. For generation tasks, selected prompts are passed to T2I models (LDM/FLUX/Emu) to produce final images; for captioning, the final text candidate is output directly."}, {"id": "6CAgbrjHTc", "title": "Cradle: Empowering Foundation Agents towards General Computer Control", "authors": ["Weihao Tan", "Wentao Zhang", "Xinrun Xu", "Haochong Xia", "gang Ding", "Boyu Li", "Bohan Zhou", "Junpeng Yue", "Jiechuan Jiang", "Yewen Li", "Ruyi An", "Molei Qin", "Chuqiao Zong", "Longtao Zheng", "YuJie Wu", "Xiaoqiang Chai", "Yifei Bi", "Tianbao Xie", "Pengjie Gu", "Xiyun Li", "Ceyao Zhang", "Long Tian", "Chaojie Wang", "Xinrun Wang", "Börje F. Karlsson", "Bo An", "Shuicheng YAN", "Zongqing Lu"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=6CAgbrjHTc", "code": "https://github.com/BAAI-Agents/Cradle", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o", "Claude 3 Opus"], "non_llm_models": {"perception": ["Grounding DINO", "SAM", "template matching"], "generation": [], "execution": ["Executor module (keyboard/mouse control)", "io_env"]}, "summary": "Screenshots/video input undergo Information Gathering (enhanced by Grounding DINO/SAM for visual grounding) to extract textual and visual information. The LMM performs Self-Reflection on past outcomes, Task Inference to determine the next task, and Skill Curation to retrieve or generate executable code skills. Action Planning then instantiates skills into specific keyboard/mouse commands, which the Executor module translates into OS-level actions to interact with the computer environment."}, {"id": "owulFly8oQ", "title": "Adapting While Learning: Grounding LLMs for Scientific Problems with Tool Usage Adaptation", "authors": ["Bohan Lyu", "Yadi Cao", "Duncan Watson-Parris", "Leon Bergen", "Taylor Berg-Kirkpatrick", "Rose Yu"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=owulFly8oQ", "code": "https://github.com/Rose-STL-Lab/Adapting-While-Learning", "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Llama-3.1-8B", "Qwen2.5-14B-Instruct"], "non_llm_models": {"perception": ["neural surrogate models (climate)", "neural surrogate models (epidemiology)"], "generation": [], "execution": ["Mujoco physics engine", "PDE numerical solvers"]}, "summary": "Scientific questions are processed by the LLM (Llama-3.1-8B) which first assesses problem difficulty. For easy questions, it performs direct reasoning; for hard questions, it generates tool traces to invoke appropriate simulators (neural surrogates for climate/epidemiology, Mujoco for physics, PDE solvers for equations). The tools execute computations and return results, which the LLM synthesizes into final answers. For open-ended questions, the LLM generates multiple proposals that are evaluated and ranked before final selection."}, {"id": "dtmTQawQN2", "title": "Modularized Self-Reflected Video Reasoner for Multimodal LLM with Application to Video Question Answering", "authors": ["Zihan Song", "Xin Wang", "Zi Qian", "Hong Chen", "Longtao Huang", "Hui Xue&amp;#x27;", "Wenwu Zhu"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=dtmTQawQN2", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["Qwen2-7B", "Qwen-VL", "LLaVA-NeXT", "Qwen2-VL", "LLaVA-Video"], "non_llm_models": {"perception": ["UniVTG", "YOLO-World"], "generation": [], "execution": []}, "summary": "User question is parsed by Qwen2-7B into a tree-structured JSON policy, which guides the MoST-Grounding module to recursively invoke UniVTG for temporal localization and YOLO-World for spatial localization. The grounded video segments and bounding boxes are combined with global video features and fed to a Multimodal LLM (Qwen-VL/LLaVA-NeXT/etc.) with guiding prompts to generate the final text answer. Training alternates between SFT of the Multimodal LLM and RL (DPO) of the Question Parser using cross-model feedback."}, {"id": "REnIf3dCsI", "title": "Toward Robust Hyper-Detailed Image Captioning: A Multiagent Approach and Dual Evaluation Metrics for Factuality and Coverage", "authors": ["Saehyung Lee", "Seunghyun Yoon", "Trung Bui", "Jing Shi", "Sungroh Yoon"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=REnIf3dCsI", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4", "LLaMA-3-8B", "GPT-4o"], "non_llm_models": {"perception": ["LLaVA-NeXT", "InternVL-Chat-V1.5", "GPT-4V", "LLaVA-v1.5-7B", "LLaVA-NeXT-13B", "InstructBLIP-7B"], "generation": [], "execution": []}, "summary": "An initial detailed caption is generated by an MLLM. An LLM (decomposer) splits the caption into atomic propositions. These propositions are verified against the image by an MLLM (fact-checker) via True/False questions, producing hallucination scores. Propositions are thresholded into True/False sets. Finally, an LLM (corrector) revises the initial caption based on these verification results to produce a factually accurate corrected caption."}, {"id": "lNVHg9npif", "title": "Hi Robot: Open-Ended Instruction Following with Hierarchical Vision-Language-Action Models", "authors": ["Lucy Xiaoyang Shi", "brian ichter", "Michael Equi", "Liyiming Ke", "Karl Pertsch", "Quan Vuong", "James Tanner", "Anna Walling", "Haohuan Wang", "Niccolo Fusai", "Adrian Li", "Danny Driess", "Lachy Groom", "Sergey Levine", "Chelsea Finn"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=lNVHg9npif", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["PaliGemma-3B"], "non_llm_models": {"perception": [], "generation": [], "execution": ["π0 VLA"]}, "summary": "User prompts and camera images are processed by a high-level VLM (PaliGemma-3B) to generate atomic language commands and verbal responses. These commands condition a low-level VLA (π0), which processes the commands along with visual observations and robot state to output continuous actions. The high-level policy is re-invoked periodically or upon receiving user feedback to update the plan."}, {"id": "umT6rMf1Rm", "title": "DEFAME: Dynamic Evidence-based FAct-checking with Multimodal Experts", "authors": ["Tobias Braun", "Mark Rothermel", "Marcus Rohrbach", "Anna Rohrbach"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=umT6rMf1Rm", "code": "https://github.com/mendableai/firecrawl", "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4O", "GPT-4O Mini", "LLaVA-ONEVISION (LLaVA-1V)", "LLaMA 4 Scout"], "non_llm_models": {"perception": ["GeoCLIP", "Google Vision API", "Google Image Search", "Serper API (Web Search)", "Firecrawl scraper"], "generation": [], "execution": []}, "summary": "The system receives a multimodal claim (text + image) and processes it through a six-stage pipeline: (1) MLLM plans retrieval actions selecting from available tools, (2) executes heterogeneous tools (web search, image search, reverse image search via Google Vision API, geolocation via GeoCLIP) to gather evidence, (3) MLLM summarizes and filters retrieved evidence into a structured report, (4) MLLM develops step-by-step reasoning over the evidence, (5) MLLM predicts a verdict with the option to loop back to planning if evidence is insufficient (NEI), and (6) MLLM generates a final human-readable justification."}, {"id": "s7HUJamWqX", "title": "Agent Reviewers: Domain-specific Multimodal Agents with Shared Memory for Paper Review", "authors": ["Kai Lu", "Shixiong Xu", "Jinqiu Li", "Kun Ding", "Gaofeng Meng"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=s7HUJamWqX", "code": null, "pattern": "LLM + Perception", "domain": "Document_Understanding", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o-mini", "Gemini-exp-1206", "Deepseek-V3", "GLM-4-Flash", "ERNIE-Speed-128K", "Qwen2.5-VL-72B-Instruct", "InternVL-2.5-78B"], "non_llm_models": {"perception": ["all-mpnet-base-v2", "MinerU"], "generation": [], "execution": []}, "summary": "The Meta-reviewer extracts keywords from the paper text and retrieves domain-specific memory from the Shared Memory Pool (SMP) to initialize specialized reviewers. A Multimodal reviewer analyzes the paper thumbnail to provide visual comments on layout and figures. Domain-specific reviewers integrate these visual comments with the paper text to generate initial reviews, which are iteratively refined through a peer discussion period. Finally, the Area Chair aggregates the revised reviews to produce the final decision, scores, and comments, and updates the SMP with the new paper metadata."}, {"id": "YqerkYZfvu", "title": "Perception in Reflection", "authors": ["Yana Wei", "Liang Zhao", "Kangheng Lin", "En Yu", "Yuang Peng", "Runpei Dong", "Jianjian Sun", "Haoran Wei", "Zheng Ge", "Xiangyu Zhang", "Vishal Patel"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=YqerkYZfvu", "code": "https://github.com/weiyana/RePer", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier", "Coordinator"], "llm_models": ["LLaVA-1.5", "LLaVA-Critic", "GPT-4o"], "non_llm_models": {"perception": [], "generation": [], "execution": []}, "summary": "Given an image and question, the policy model (LLaVA-1.5) generates an initial text response. The critic model evaluates this response, providing a quality score and textual feedback. The policy then reflects on this feedback to generate a refined response, and this iterative process continues until convergence or a maximum number of turns is reached."}, {"id": "f3iBgm2Zi0", "title": "Proactive Agents for Multi-Turn Text-to-Image Generation Under Uncertainty", "authors": ["Meera Hahn", "Wenjun Zeng", "Nithish Kannen", "Rich Galt", "Kartikeya Badola", "Been Kim", "Zi Wang"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=f3iBgm2Zi0", "code": "https://github.com/google-deepmind/proactive_t2i_agents", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Gemini 1.5", "Gemini 1.5 Pro"], "non_llm_models": {"perception": [], "generation": ["Imagen 3", "T2I diffusion model"], "execution": []}, "summary": "User provides an underspecified text prompt → Gemini 1.5 constructs a belief graph with probability distributions over entities, attributes, and relations → Agent calculates entropy and importance scores to identify uncertain elements → LLM generates targeted clarification questions → User feedback updates the belief graph and prompt → Process iterates for multiple turns → Final refined prompt is dispatched to Imagen 3 to generate the image."}, {"id": "onumui0nHi", "title": "Empowering World Models with Reflection for Embodied Video Prediction", "authors": ["Xiaowei Chi", "Chun-Kai Fan", "Hengyuan Zhang", "Xingqun Qi", "Rongyu Zhang", "Anthony Chen", "Chi-Min Chan", "Wei Xue", "Qifeng Liu", "Shanghang Zhang", "Yike Guo"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=onumui0nHi", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Vicuna-v1.5", "ChatUniVi", "LLaVA", "Qwen2-VL"], "non_llm_models": {"perception": ["CLIP (ViT-L/14)", "DINO"], "generation": ["Dynamicrafter", "Stable Video Diffusion", "VideoCrafter"], "execution": []}, "summary": "Visual observations are encoded by CLIP/DINO and processed by a VLM alongside text instructions. The VLM performs reflection to determine if the task is complete. If incomplete, the VLM's hidden states are aligned via a generation adapter to condition Video Diffusion Models (VDM) for frame generation. The VLM verifies the generated frames, and the process iterates (chunk-wise autoregressive extension) until task completion, producing the final video prediction."}, {"id": "tpbtodnI1p", "title": "World Model Implanting for Test-time Adaptation of Embodied Agents", "authors": ["Minjong Yoo", "Jinwoo Jang", "Sihyung Yoon", "Honguk Woo"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=tpbtodnI1p", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Tight", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Llama-3.2-3B"], "non_llm_models": {"perception": ["Object detection model (ΦD)", "Embedding model (ΦE)"], "generation": [], "execution": ["Domain-specific world models (Llama-3.2-1B based)"]}, "summary": "Raw state observations are processed by an object detection model (ΦD) and an embedding model (ΦE) to create object-wise state embeddings. Prototype-based retrieval using k-center clustering and Wasserstein distance selects relevant domain-specific world models (Llama-3.2-1B). A meta-learned world-wise compound attention module (Cθ) tightly integrates the intermediate representations of the retrieved world models and aligns them with a fixed reasoning LLM (Llama-3.2-3B), which then outputs actions for the embodied task."}, {"id": "JiFfij5iv0", "title": "MedRAX: Medical Reasoning Agent for Chest X-ray", "authors": ["Adibvafa Fallahpour", "Jun Ma", "Alif Munim", "Hongwei Lyu", "BO WANG"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=JiFfij5iv0", "code": "https://github.com/bowang-lab/MedRAX", "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CheXagent", "LLaVA-Med", "MedSAM", "PSPNet", "Maira-2", "DenseNet-121"], "generation": ["RoentGen", "SwinV2 with BERT decoder"], "execution": []}, "summary": "User queries and CXR images are processed by GPT-4o through a ReAct loop that observes the input, reasons about required analyses, and selects appropriate medical tools. Selected perception and generation models execute in parallel, with outputs cached in memory and fed back to the LLM for iterative reasoning until a final medical response is synthesized."}, {"id": "GCkhEPE1FG", "title": "Adversaries Can Misuse Combinations of Safe Models", "authors": ["Erik Jones", "Anca Dragan", "Jacob Steinhardt"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=GCkhEPE1FG", "code": null, "pattern": "LLM + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["Claude 3 Opus", "Claude 3 Sonnet", "Claude 3 Haiku", "Llama 2 7B-chat", "Llama 2 13B-chat", "Llama 2 70B-chat", "Mistral 7B Instruct v0.2", "Mixtral 8x7B v0.1", "GPT-4-0125-preview"], "non_llm_models": {"perception": [], "generation": ["DALL-E 3", "Stable Diffusion v1.5", "InstructPix2Pix"], "execution": []}, "summary": "The adversarial pipeline decomposes malicious tasks into benign subtasks using a weak LLM (e.g., Mistral or Llama 2), dispatches them to frontier LLMs (Claude 3) for solutions, and composes these solutions in-context to solve the original task. For image tasks, DALL-E 3 generates a base image and Stable Diffusion v1.5 / InstructPix2Pix edits it to add malicious features. GPT-4 is used offline as an evaluator."}, {"id": "W9s817KqYf", "title": "Windows Agent Arena: Evaluating Multi-Modal OS Agents at Scale", "authors": ["Rogerio Bonatti", "Dan Zhao", "Francesco Bonacci", "Dillon Dupont", "Sara Abdali", "Yinheng Li", "Yadong Lu", "Justin Wagle", "Kazuhito Koishida", "Arthur Bucker", "Lawrence Jang", "Zheng Hui"], "venue": "ICML", "year": 2025, "url": "https://openreview.net/pdf?id=W9s817KqYf", "code": "https://github.com/dockur/windows", "pattern": "LLM + Perception", "domain": "GUI_Web_Agent", "flow": "Converge", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4V", "GPT-4o", "o1", "Phi-3.5-V", "Phi-3-V", "GPT-4o-mini"], "non_llm_models": {"perception": ["OmniParser", "Grounding DINO", "Tesseract", "OneOCR"], "generation": [], "execution": []}, "summary": "Multiple perception models (OmniParser, Grounding DINO, Tesseract, OneOCR) process the screenshot in parallel to produce Set-of-Marks annotations. A multimodal LLM (e.g., GPT-4V) receives the annotated screenshot, task instruction, and action history, performs chain-of-thought reasoning, and outputs Python code. The code is deterministically executed via the Computer class API (wrapping PyAutoGUI-like mouse/keyboard commands) inside a Windows VM, and the loop repeats until the task is completed or fails."}, {"id": "xue25", "title": "Selective Invocation for Multilingual ASR: A Cost-effective Approach Adapting to Speech Recognition Difficulty", "authors": ["Hongfei Xue", "Yufeng Tang", "Jun Zhang", "Xuelong Geng", "Lei Xie"], "venue": "INTERSPEECH", "year": 2025, "url": "https://www.isca-archive.org/interspeech_2025/xue25_interspeech.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Audio_Speech", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Router", "Reasoner"], "llm_models": ["Spoken LLM (SLLM)"], "non_llm_models": {"perception": ["SeamlessM4T-large-v2", "OpenAI API (ASR)", "AssemblyAI Universal-1"], "generation": [], "execution": []}, "summary": "SIMA feeds speech into a Spoken LLM that assesses recognition difficulty via confidence metrics. For simple or low-confidence inputs, the SLLM outputs the transcription directly; for complex inputs, it routes the audio to an external SOTA ASR model (e.g., SeamlessM4T, OpenAI ASR, or AssemblyAI Universal-1) to produce the final transcript, cutting invocation costs while preserving accuracy."}, {"id": "9f9755fc4b16", "title": "Large Language Model with Curriculum Reasoning for Visual Concept Recognition", "authors": ["Yipeng Zhang 0003", "Xin Wang 0019", "Hong Chen 0011", "Jiapei Fan", "Weigao Wen", "Hui Xue 0001", "Hong Mei 0001", "Wenwu Zhu 0001"], "venue": "KDD", "year": 2024, "url": "https://doi.org/10.1145/3637528.3671653", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Vicuna-7b"], "non_llm_models": {"perception": ["SOLOv2", "CLIP ViT-L/14@336px", "SVM classifier", "Overlap tool", "Similarity tool"], "generation": [], "execution": []}, "summary": "Image input is processed by Vicuna-7b, which iteratively generates symbolic reasoning rules in DNF/CNF form. For each condition, the LLM dynamically selects appropriate tools (detection, overlap, similarity, or classifier) from the tool library to verify the condition on the image. Tools return probabilities that are aggregated via logical reasoning (min/max operations). A curriculum scheduler (2-layer MLP) resamples training data based on difficulty levels across iterations to refine rule quality, producing final visual concept recognition with interpretable rules."}, {"id": "fed392e749e3", "title": "Intelligent Agents with LLM-based Process Automation", "authors": ["Yanchu Guan", "Dong Wang 0062", "Zhixuan Chu", "Shiyu Wang 0001", "Feiyue Ni", "Ruihua Song", "Chenyi Zhuang"], "venue": "KDD", "year": 2024, "url": "https://doi.org/10.1145/3637528.3671646", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator", "Translator"], "llm_models": ["AntLLM-10b"], "non_llm_models": {"perception": ["YOLOX", "Text Extraction module"], "generation": [], "execution": ["Executor (click/scroll/type simulator)"]}, "summary": "User queries are first decomposed into instruction chains by AntLLM-10b. YOLOX detects UI elements and extracts text from the current screen, while the Previous Action Description Generator (AntLLM-10b) summarizes history. These inputs feed into Action Prediction (AntLLM-10b) to generate the next action. A CTR model verifies executability and logical coherence; passing actions are executed by the UI simulator, while failures trigger re-prediction."}, {"id": "799-Paper0242", "title": "Transforming Surgical Interventions with Embodied Intelligence for Ultrasound Robotics", "authors": ["Xu Huan", "Wu Jinlin", "Cao Guanglin", "Chen Zhen", "Lei Zhen", "Liu Hongbin", "Xu Huan", "Wu Jinlin", "Cao Guanglin", "Chen Zhen", "Lei Zhen", "Liu Hongbin"], "venue": "MICCAI", "year": 2024, "url": "https://papers.miccai.org/miccai-2024/paper/0242_paper.pdf", "code": "https://github.com/seanxuu/EmbodiedUS", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-4-Turbo"], "non_llm_models": {"perception": ["Image_Seg (segmentation model)", "RealSense depth camera", "M3815B force sensor"], "generation": [], "execution": ["RM65-B robotic arm", "control algorithms"]}, "summary": "Doctor's verbal instruction is embedded and used to retrieve relevant APIs and operational handbooks via bge-large-en-v1.5. GPT-4-Turbo interprets the command, assembles the context into a prompt, and enters a ReAct execution loop: observing the environment (segmentation results, depth, force feedback), reasoning about the next step, and generating JSON API calls. The robotic arm executes the physical scanning motions, with the loop iterating until the ultrasound scan is complete."}, {"id": "0537-Paper2575", "title": "MedAgentSim: Self-Evolving Multi-Agent Simulations for Realistic Clinical Interactions", "authors": ["Almansoori Mohammad", "Kumar Komal", "Cholakkal Hisham", "Almansoori Mohammad", "Kumar Komal", "Cholakkal Hisham"], "venue": "MICCAI", "year": 2025, "url": "https://papers.miccai.org/miccai-2025/paper/2575_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Converge", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaMA 3.3", "GPT-4o", "Mistral", "Qwen2.5", "Qwen2", "Mixtral"], "non_llm_models": {"perception": ["LLaVA 1.5", "QwenVL", "CLIP"], "generation": [], "execution": []}, "summary": "The patient agent presents symptoms through multi-turn dialogue. The doctor agent requests specific medical tests and imaging from a measurement agent. VLMs (LLaVA/QwenVL) process the imaging results, and CLIP retrieves relevant past cases from memory buffers. Multiple doctor agents then perform parallel chain-of-thought reasoning, with outputs combined via majority-vote ensembling to produce a final diagnosis. A reflection phase verifies correctness and triggers retry if needed, with successful cases stored for future retrieval."}, {"id": "0655-Paper2221", "title": "Operating Room Workflow Analysis via Reasoning Segmentation over Digital Twins", "authors": ["Shen Yiqing", "Li Chenjia", "Liu Bohan", "Li Cheng-Yi", "Porras Tito", "Unberath Mathias", "Shen Yiqing", "Li Chenjia", "Liu Bohan", "Li Cheng-Yi", "Porras Tito", "Unberath Mathias"], "venue": "MICCAI", "year": 2025, "url": "https://papers.miccai.org/miccai-2025/paper/2221_paper.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["OWLv2", "SAM2", "LLaVA-7B", "DepthAnything2"], "generation": [], "execution": []}, "summary": "OR video frames are processed in parallel by OWLv2 (object detection), SAM2 (instance segmentation prompted by bounding boxes), LLaVA-7B (semantic description of cropped regions), and DepthAnything2 (depth estimation) to construct a structured JSON Digital Twin. GPT-4o then implements a 'reason-retrieve-synthesize' paradigm over this JSON: decomposing implicit text queries into atomic requirements, retrieving candidate instances by filtering the DT based on semantic and spatial criteria, and synthesizing final segmentation masks and textual explanations."}, {"id": "0456-Paper2021", "title": "Intelligent Virtual Sonographer (IVS): Enhancing Physician-Robot-Patient Communication", "authors": ["Song Tianyu", "Li Feng", "Bi Yuan", "Karlas Angelos", "Yousefi Amir", "Branzan Daniela", "Jiang Zhongliang", "Eck Ulrich", "Navab Nassir", "Song Tianyu", "Li Feng", "Bi Yuan", "Karlas Angelos", "Yousefi Amir", "Branzan Daniela", "Jiang Zhongliang", "Eck Ulrich", "Navab Nassir"], "venue": "MICCAI", "year": 2025, "url": "https://papers.miccai.org/miccai-2025/paper/2021_paper.pdf", "code": "https://github.com/stytim/IVS", "pattern": "LLM + Perception + Generation + Action", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Meta Llama 3.1 8B"], "non_llm_models": {"perception": ["OpenAI Whisper", "MediaPipe SelfieMulticlass", "MediaPipe HandLandmarker", "UNet"], "generation": ["Kokoro"], "execution": ["KUKA LBR iiwa"]}, "summary": "Speech input is processed by OpenAI Whisper (STT) and fed to dual Meta Llama 3.1 8B instances (physician-facing and patient-facing) for dialogue management. The LLM generates responses via Kokoro (TTS) or translates physician commands into KUKA robot API calls for ultrasound scanning. MediaPipe (skin/hand segmentation) and UNet (vessel segmentation) provide visual feedback to the LLM for trajectory planning and physician updates, enabling closed-loop robotic control."}, {"id": "1022-Paper0994", "title": "WSI-Agents: A Collaborative Multi-Agent System for Multi-Modal Whole Slide Image Analysis", "authors": ["Lyu Xinheng", "Liang Yuci", "Chen Wenting", "Ding Meidan", "Yang Jiaqi", "Huang Guolin", "Zhang Daokun", "He Xiangjian", "Shen Linlin", "Lyu Xinheng", "Liang Yuci", "Chen Wenting", "Ding Meidan", "Yang Jiaqi", "Huang Guolin", "Zhang Daokun", "He Xiangjian", "Shen Linlin"], "venue": "MICCAI", "year": 2025, "url": "https://papers.miccai.org/miccai-2025/paper/0994_paper.pdf", "code": "https://github.com/XinhengLyu/WSI-Agents", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Task Agent (LLM)", "Logic Agent (LLM)", "Fact Agent (LLM)", "Consensus Agent (LLM)", "Summarizing Agent (LLM)", "Reasoning Agents (LLM)"], "non_llm_models": {"perception": ["WSI-LLaVA", "Quilt-LLaVA", "WSI-VQA", "Hist-Gen", "TITAN", "CONCH", "Prism"], "generation": [], "execution": []}, "summary": "Input WSI and question are processed by a Task Agent that routes to Expert Agents, which select appropriate models from an MLLM zoo to generate initial responses. These responses undergo verification by Logic Agent (internal consistency), Fact Agent (knowledge base validation), and Consensus Agent (foundation model agreement scoring). A Summarizing Agent aggregates verification scores and coordinates Reasoning Agents through iterative deliberation to produce the final diagnostic output with an integrated visual interpretation map."}, {"id": "2024.findings-naacl.60", "title": "LangNav: Language as a Perceptual Representation for Navigation", "authors": ["Bowen Pan", "Rameswar Panda", "SouYoung Jin", "Rogerio Feris", "Aude Oliva", "Phillip Isola", "Yoon Kim"], "venue": "NAACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-naacl.60.pdf", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaMA2-7B", "LLaMA-7B"], "non_llm_models": {"perception": ["BLIP", "Deformable DETR"], "generation": [], "execution": []}, "summary": "At each timestep, egocentric panoramic images are processed by off-the-shelf perception models (BLIP for captioning and Deformable DETR for object detection) to produce text descriptions of the agent's views. These descriptions are combined with the navigation instruction and trajectory history into a natural language prompt, which a finetuned LLaMA2-7B orchestrator processes to greedily decode the next navigable direction. During training, a shortest-path algorithm is used to generate recovery trajectories under random action noise, and GPT-4 is used offline to synthesize additional training instructions and trajectories."}, {"id": "2024.findings-naacl.24", "title": "OpenFMNav: Towards Open-Set Zero-Shot Object Navigation via Vision-Language Foundation Models", "authors": ["Yuxuan Kuang", "Hai Lin", "Meng Jiang"], "venue": "NAACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-naacl.24.pdf", "code": "https://github.com/yxKryptonite/OpenFMNav", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["GPT-4V", "Grounded-SAM", "SAM", "Grounding DINO"], "generation": [], "execution": []}, "summary": "OpenFMNav uses GPT-4 to extract proposed target objects and to reason over frontier semantics on a continuously updated Versatile Semantic Score Map. GPT-4V discovers novel objects from RGB observations, while Grounded-SAM (Grounding DINO + SAM) detects and segments objects to build the map. A deterministic FMM-based planner then executes low-level actions to reach the LLM-selected frontier, looping until the goal is found."}, {"id": "2024.findings-naacl.292", "title": "LLaMA-Rider: Spurring Large Language Models to Explore the Open World", "authors": ["Yicheng Feng", "Yuxuan Wang", "Jiazheng Liu", "Sipeng Zheng", "Zongqing Lu"], "venue": "NAACL", "year": 2024, "url": "https://aclanthology.org/2024.findings-naacl.292.pdf", "code": "https://github.com/PKU-RL/LLaMA-Rider", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaMA-2-70B-chat", "LLaMA-2-13B-chat"], "non_llm_models": {"perception": [], "generation": [], "execution": ["Plan4MC skill policies (RL-trained)"]}, "summary": "Textual observations (inventory, field-of-view items) and task descriptions are fed to LLaMA-2, which performs chain-of-thought reasoning to select the next skill. Action retrieval matches the skill description to executable Plan4MC RL policies. Upon execution failure, environmental feedback is returned to the LLM for revision (up to 5 rounds). Successful trajectories are collected to fine-tune the LLM using QLoRA, improving its planning and adaptation to the environment."}, {"id": "2025.naacl-long.186", "title": "Towards Rationality in Language and Multimodal Agents: A Survey", "authors": ["Bowen Jiang", "Yangxinyu Xie", "Xiaomeng Wang", "Yuan Yuan", "Zhuoqun Hao", "Xinyi Bai", "Weijie J Su", "Camillo Jose Taylor", "Tanwi Mallick"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.naacl-long.186.pdf", "code": "https://github.com/bowen-upenn/Agent_Rationality", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-4 Vision", "GPT-4o", "LLaVA", "Gemini 1.5 Pro", "LLaMA 3.2"], "non_llm_models": {"perception": ["CLIP", "SAM", "BLIP-2", "Whisper", "Grounded SAM", "CogVLM", "MiniGPT-4"], "generation": [], "execution": []}, "summary": "This survey examines how language and multimodal agents advance rationality through four axioms. It discusses systems where LLM orchestrators dispatch learned perception models (e.g., CLIP, SAM, Whisper) to gather multimodal information, and leverage deterministic tools such as Python interpreters, symbolic reasoners, search engines, and calculators for consistent execution and reasoning, without employing learned action policies or distinct generation models as core components."}, {"id": "2025.findings-naacl.19", "title": "UnifiedMLLM: Enabling Unified Representation for Multi-modal Multi-tasks With Large Language Model", "authors": ["Zhaowei Li", "Wei Wang", "YiQing Cai", "Qi Xu", "Pengyu Wang", "Dong Zhang", "Hang Song", "Botian Jiang", "Zhida Huang", "Tao Wang"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-naacl.19.pdf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Vicuna-v1.5"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "Imagebind", "Q-Former"], "generation": ["Stable Diffusion", "GLIGEN", "Instruct-pix2pix", "SEEM", "FRESCO", "ModelScopeT2V", "I2vgen-xl", "Auffusion"], "execution": []}, "summary": "Multi-modal inputs (images, video, audio) are encoded by CLIP, Imagebind, and Q-Former, then mapped via adapters to Vicuna LLM. The LLM performs reasoning to understand implicit intent and outputs task tokens and grounding tokens. A task router parses these tokens to activate specific expert generation models (e.g., Stable Diffusion for generation, SEEM for segmentation) which execute the task and return the final result."}, {"id": "2025.naacl-long.379", "title": "Hazards in Daily Life? Enabling Robots to Proactively Detect and Resolve Anomalies", "authors": ["Zirui Song", "Guangxian Ouyang", "Meng Fang", "Hongbin Na", "Zijing Shi", "Zhenhao Chen", "Fu Yujie", "Zeyu Zhang", "Shiyu Jiang", "Miao Fang", "Ling Chen", "Xiuying Chen"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.naacl-long.379.pdf", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": ["BLIP-2", "Sentence-BERT"], "generation": [], "execution": ["Soft Actor-Critic (SAC)", "Batch Informed Trees"]}, "summary": "GPT-4 agents brainstorm anomaly scenarios; Sentence-BERT retrieves auxiliary 3D assets from Objaverse while BLIP-2 validates visual appropriateness; GPT-4 configures scene parameters, detects anomalies from scene descriptions, and decomposes solutions into sub-tasks; finally, SAC or motion planning algorithms execute the physical manipulation actions in simulation."}, {"id": "2025.naacl-long.406", "title": "Follow the Beaten Path: The Role of Route Patterns on Vision-Language Navigation Agents Generalization Abilities", "authors": ["Kourosh T Baghaei", "Dieter Pfoser", "Antonios Anastasopoulos"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.naacl-long.406.pdf", "code": "https://github.com/kbaghaei/beaten_path_vln", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaMA 7B", "LLaMA 2 7B", "Mistral 7B"], "non_llm_models": {"perception": ["OpenCLIP"], "generation": [], "execution": []}, "summary": "The VELMA-based pipeline uses OpenCLIP to ground landmarks from 360° panoramas into textual observations that are added to the LLM's prompt. The fine-tuned LLM (LLaMA/Mistral) reasons over the navigation instruction and visual observations to predict discrete actions (FORWARD, LEFT, RIGHT, STOP), which are executed in a deterministic simulator to advance the agent's state."}, {"id": "2025.findings-naacl.25", "title": "DialogGen: Multi-modal Interactive Dialogue System with Multi-turn Text-Image Generation", "authors": ["Minbin Huang", "Yanxin Long", "Xinchi Deng", "Ruihang Chu", "Jiangfeng Xiong", "Xiaodan Liang", "Hong Cheng", "Qinglin Lu", "Wei Liu"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-naacl.25.pdf", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator", "Translator", "Reflector"], "llm_models": ["Qwen-VL"], "non_llm_models": {"perception": [], "generation": ["Hunyuan-DiT", "Stable Diffusion v1.5", "Stable Diffusion v2.1"], "execution": []}, "summary": "User provides multimodal input (text + optional image) to Qwen-VL, which recognizes user intent and decides between text chat or image generation. For image generation, Qwen-VL translates user instructions into aligned drawing prompts (matching the T2I model's preferred distribution) and dispatches them to Hunyuan-DiT or Stable Diffusion to generate the final image. The system supports multi-turn dialogue by maintaining conversation history and can perform self-correction through a two-step inference mechanism."}, {"id": "2025.findings-naacl.424", "title": "Tooling or Not Tooling? The Impact of Tools on Language Agents for Chemistry Problem Solving", "authors": ["Botao Yu", "Frazier N. Baker", "Ziru Chen", "Garrett Herb", "Boyu Gou", "Daniel Adu-Ampratwum", "Xia Ning", "Huan Sun"], "venue": "NAACL", "year": 2025, "url": "https://aclanthology.org/2025.findings-naacl.424.pdf", "code": "https://github.com/OSU-NLP-Group/ChemAgent", "pattern": "LLM + Perception + Action", "domain": "Scientific_Discovery", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Claude-3.5-Sonnet"], "non_llm_models": {"perception": ["ForwardSynthesis", "BBBPPredictor", "SideEffectPredictor", "Retrosynthesis", "FunctionalGroups", "PubchemSearchQA", "WebSearch"], "generation": [], "execution": ["PythonREPL"]}, "summary": "User submits a chemistry task to the LLM, which generates a Thought (reasoning/planning) and selects an Action (tool and input). The tool executes (neural predictor for molecular analysis or PythonREPL for computation) and returns an Observation. The LLM iteratively processes observations and selects new actions until generating the final answer."}, {"id": "yoAmURKDJi", "title": "TOA: Task-oriented Active VQA", "authors": ["xiaoying xing", "Mingfu Liang", "Ying Wu"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=yoAmURKDJi", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-turbo"], "non_llm_models": {"perception": ["Grounding DINO", "BLIP-2", "X-VLM", "CLIP", "PromptCAP"], "generation": [], "execution": []}, "summary": "The pipeline begins with PromptCAP generating an initial caption. GPT-3.5-turbo analyzes the question and caption to form hypotheses, then actively queries specific perception modules—Grounding DINO for spatial localization and BLIP-2/X-VLM for attribute verification—to collect visual evidence. Through iterative multi-round dialogue, the LLM verifies hypotheses against returned evidence, refining its reasoning dynamically until confirming the final text answer."}, {"id": "HtqnVSCj3q", "title": "Chameleon: Plug-and-Play Compositional Reasoning with Large Language Models", "authors": ["Pan Lu", "Baolin Peng", "Hao Cheng", "Michel Galley", "Kai-Wei Chang", "Ying Nian Wu", "Song-Chun Zhu", "Jianfeng Gao"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=HtqnVSCj3q", "code": "https://github.com/lupantech/chameleon-llm", "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["GPT-4", "ChatGPT"], "non_llm_models": {"perception": ["Image Captioner", "Text Detector"], "generation": [], "execution": ["Program Executor", "Bing Search"]}, "summary": "Given a query, the LLM planner generates a natural language program specifying a sequence of tools. The system executes these tools sequentially—including perception models for image/text understanding, knowledge retrieval modules, and Python execution engines—updating a shared cache between steps. The final answer is synthesized by the Solution Generator and formatted by the Answer Generator."}, {"id": "IL5zJqfxAa", "title": "EmbodiedGPT: Vision-Language Pre-Training via Embodied Chain of Thought", "authors": ["Yao Mu", "Qinglong Zhang", "Mengkang Hu", "Wenhai Wang", "Mingyu Ding", "Jun Jin", "Bin Wang", "Jifeng Dai", "Yu Qiao", "Ping Luo"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=IL5zJqfxAa", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["LLaMA-7B"], "non_llm_models": {"perception": ["ViT-G/14 (EVA-CLIP)", "ResNet50"], "generation": [], "execution": ["Policy Network (MLP)"]}, "summary": "Visual input (video frames) is encoded by ViT-G/14 and processed by the Embodied-Former to extract visual features, which are mapped to the language modality and fed into frozen LLaMA-7B (with prefix tuning) to generate step-by-step embodied plans. These plans are then used by the Embodied-Former to query task-relevant instance features from the visual tokens, which are combined with global ResNet50 features and fed into the Policy Network (MLP) to generate low-level robot actions."}, {"id": "dyXNh5HLq3", "title": "Compositional Foundation Models for Hierarchical Planning", "authors": ["Anurag Ajay", "Seungwook Han", "Yilun Du", "Shuang Li", "Abhi Gupta", "Tommi Jaakkola", "Josh Tenenbaum", "Leslie Kaelbling", "Akash Srivastava", "Pulkit Agrawal"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=dyXNh5HLq3", "code": "https://github.com/anuragajay/hip", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["LLM"], "non_llm_models": {"perception": ["VC-1", "MiniGPT-4"], "generation": ["Video Diffusion Model"], "execution": ["Inverse Dynamics Model"]}, "summary": "The LLM generates candidate language subgoals from the task goal and current observation, which are filtered by a visual plausibility classifier. A Video Diffusion Model then generates an image trajectory conditioned on the selected subgoal, refined by feedback from an action feasibility classifier. Finally, an Inverse Dynamics Model predicts executable actions from consecutive image pairs in the generated trajectory for robot execution."}, {"id": "sq4o3tjWaj", "title": "What’s Left? Concept Grounding with Logic-Enhanced Foundation Models", "authors": ["Joy Hsu", "Jiayuan Mao", "Josh Tenenbaum", "Jiajun Wu"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=sq4o3tjWaj", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-3.5"], "non_llm_models": {"perception": ["Faster R-CNN", "PointNet++", "2s-AGCN", "DenseCLIP"], "generation": [], "execution": ["Differentiable FOL Executor", "CLIPort"]}, "summary": "User query is processed by GPT-3.5 to generate a first-order logic program. A differentiable FOL executor recursively executes this program by querying domain-specific grounding modules. These modules use perception encoders (Faster R-CNN for 2D, PointNet++ for 3D, etc.) to extract features and MLP-based concept embeddings to ground symbolic concepts, ultimately producing answers or robotic actions."}, {"id": "yhBFG9Y85R", "title": "Visual Programming for Step-by-Step Text-to-Image Generation and Evaluation", "authors": ["Jaemin Cho", "Abhay Zala", "Mohit Bansal"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=yhBFG9Y85R", "code": "https://github.com/j-min/VPGen", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Translator"], "llm_models": ["Vicuna-13B", "GPT-3.5-Turbo"], "non_llm_models": {"perception": ["Grounding DINO", "DPT", "EasyOCR", "BLIP-2"], "generation": ["GLIGEN", "Stable Diffusion"], "execution": []}, "summary": "VPGen pipeline: Text prompt → Vicuna (finetuned for object/count generation) → Vicuna (layout generation producing bounding box text) → GLIGEN (layout-conditioned image generation). VPEval pipeline: Generated image and prompt → GPT-3.5-Turbo (evaluation program generation) → Execution invokes expert perception modules (Grounding DINO for detection, DPT for depth, EasyOCR for text, BLIP-2 for VQA) → Aggregated evaluation scores with visual and textual explanations."}, {"id": "Pk2x7FPuZ4", "title": "EHRXQA: A Multi-Modal Question Answering Dataset for Electronic Health Records with Chest X-ray Images", "authors": ["Seongsu Bae", "Daeun Kyung", "Jaehee Ryu", "Eunbyeol Cho", "Gyubok Lee", "Sunjun Kweon", "Jungwoo Oh", "Lei Ji", "Eric Chang", "Tackeun Kim", "Edward Choi"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=Pk2x7FPuZ4", "code": "https://github.com/baeseongsu/ehrxqa", "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["ChatGPT (gpt-3.5-turbo-0613)"], "non_llm_models": {"perception": ["M3AE", "PubMedCLIP", "MedViLL"], "generation": [], "execution": ["NeuralSQL Interpreter", "SQL engine"]}, "summary": "User poses a natural language question about patient EHR data. ChatGPT parses the question into NeuralSQL, an extended SQL syntax supporting FUNC_VQA API calls. The NeuralSQL interpreter executes the query: standard SQL operations retrieve structured data from EHR tables, while FUNC_VQA calls trigger VQA models (M3AE, etc.) to analyze chest X-ray images. The interpreter aggregates results from these heterogeneous sources to produce the final text answer."}, {"id": "gFf0a0ZxJM", "title": "OpenAGI: When LLM Meets Domain Experts", "authors": ["Yingqiang Ge", "Wenyue Hua", "Kai Mei", "jianchao ji", "Juntao Tan", "Shuyuan Xu", "Zelong Li", "Yongfeng Zhang"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=gFf0a0ZxJM", "code": "https://github.com/agiresearch/OpenAGI", "pattern": "LLM + Perception + Generation + Action", "domain": "Benchmark_Evaluation", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "Claude-2", "LLaMA-2-13B", "Vicuna-7B", "Flan-T5-Large"], "non_llm_models": {"perception": ["CLIP", "Image Classification models", "Object Detection models", "Visual Question Answering models", "Image Captioning models"], "generation": ["Stable Diffusion", "Text-to-Image Generation models", "Colorization models", "Text-to-Music models", "Text-to-Poem models"], "execution": ["Image Denoising models", "Image Deblurring models", "Image Super-Resolution models", "Machine Translation models", "Sentiment Analysis models", "Text Summarization models", "Fill Mask models", "Question Answering models"]}, "summary": "The system receives a natural language task instruction, which is processed by an LLM to generate a multi-step execution plan (structured as a linear sequence or non-linear DAG) selecting appropriate domain expert models from Hugging Face or LangChain. The plan is executed by perception, generation, and execution models, with results evaluated against ground-truth using automated metrics (CLIP, BERT, ViT) to provide feedback for the RLTF mechanism that improves the LLM's planning ability."}, {"id": "dHF3Im8Aic", "title": "LMC: Large Model Collaboration with Cross-assessment for Training-Free Open-Set Object Recognition", "authors": ["Haoxuan Qu", "Xiaofei Hui", "Yujun Cai", "Jun Liu"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=dHF3Im8Aic", "code": "https://github.com/Harryqu123/LMC", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5-turbo (ChatGPT)"], "non_llm_models": {"perception": ["CLIP (ViT-B/32)", "DINO (ViT-B/14)"], "generation": ["DALL-E"], "execution": []}, "summary": "ChatGPT generates virtual open-set class names via chain-of-thought reasoning and self-checking to identify spurious-discriminative features. It then creates diverse text descriptions for each class, which DALL-E uses to generate images. A cyclic cross-assessing module employs CLIP to verify image-text alignment; if misaligned, CLIP feeds back to ChatGPT to refine descriptions for iterative regeneration. During inference, test images are aligned with class names via CLIP and with generated images via DINO, with aggregated softmax probabilities determining open-set vs. closed-set classification."}, {"id": "yHdTscY6Ci", "title": "HuggingGPT: Solving AI Tasks with ChatGPT and its Friends in Hugging Face", "authors": ["Yongliang Shen", "Kaitao Song", "Xu Tan", "Dongsheng Li", "Weiming Lu", "Yueting Zhuang"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=yHdTscY6Ci", "code": "https://github.com/microsoft/JARVIS", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "DAG", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-3.5", "GPT-4", "text-davinci-003"], "non_llm_models": {"perception": ["facebook/detr-resnet-101", "google/vit-base-patch16-224", "hustvl/yolos-tiny", "openpose", "nlpconnect/vit-gpt2-image-captioning"], "generation": ["lllyasviel/sd-controlnet-openpose", "facebook/fastspeech2-en-ljspeech"], "execution": []}, "summary": "ChatGPT acts as a controller that parses a user request into a structured task plan with resource dependencies, dynamically selects suitable expert models from Hugging Face based on their descriptions, invokes the selected learned perception and generation models on hybrid endpoints to execute sub-tasks, and finally integrates all inference results into a coherent natural-language response."}, {"id": "bt7pQ7o7zG", "title": "Chatting Makes Perfect: Chat-based Image Retrieval", "authors": ["Matan Levy", "Rami Ben-Ari", "Nir Darshan", "Dani Lischinski"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=bt7pQ7o7zG", "code": "https://github.com/levymsn/ChatIR", "pattern": "LLM + Perception", "domain": "Retrieval_Augmented", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["ChatGPT", "FLAN-T5", "FLAN-ALPACA"], "non_llm_models": {"perception": ["BLIP", "BLIP2", "CLIP"], "generation": [], "execution": []}, "summary": "Starting from a user-provided caption, ChatGPT generates follow-up questions based on dialog history. BLIP2 acts as a visual dialog model to answer questions about the target image. The accumulated dialog is encoded by BLIP's text encoder and matched against image embeddings to retrieve candidates. This process iterates for multiple rounds, progressively narrowing down the retrieval results."}, {"id": "cwjh8lqmOL", "title": "GPT4Tools: Teaching Large Language Model to Use Tools via Self-instruction", "authors": ["Rui Yang", "Lin Song", "Yanwei Li", "Sijie Zhao", "Yixiao Ge", "Xiu Li", "Ying Shan"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=cwjh8lqmOL", "code": "https://github.com/AILab-CVC/GPT4Tools", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Vicuna-13B", "LLaMA-13B", "OPT-13B"], "non_llm_models": {"perception": ["SAM", "GroundingDINO", "OCR models", "caption models", "pose estimation models", "depth estimation models", "segmentation models", "detection models", "edge detection models"], "generation": ["ControlNet", "Stable Diffusion", "image generation models"], "execution": []}, "summary": "The user provides an image and text instruction. Image content (captions, bounding boxes) is extracted and fed to the fine-tuned LLM along with the instruction. The LLM generates a Thought (whether to use a tool), Action (tool selection), and Action Input (arguments). The selected perception or generation tool executes the action and returns an Observation (image or text). The LLM processes this observation and either continues the tool invocation chain or produces the final response."}, {"id": "7EMphtUgCI", "title": "AVIS: Autonomous Visual Information Seeking with Large Language Model Agent", "authors": ["Ziniu Hu", "Ahmet Iscen", "Chen Sun", "Kai-Wei Chang", "Yizhou Sun", "David Ross", "Cordelia Schmid", "Alireza Fathi"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=7EMphtUgCI", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["PALM 540B"], "non_llm_models": {"perception": ["PALI 17B (VQA)", "PALI 17B (Captioning)", "Google Lens Object Detection", "Google Lens OCR"], "generation": [], "execution": []}, "summary": "Input visual question is processed by a PALM-powered planner that dynamically selects tools (PALI, detection, OCR, image/web search) based on a transition graph and working memory. Selected tools extract information from the image or retrieve external knowledge. A PALM-powered reasoner then analyzes outputs to extract key information, update working memory, and determine whether to backtrack, continue, or output the final answer, iterating until completion."}, {"id": "JCCi58IUsh", "title": "Grounded Decoding: Guiding Text Generation with Grounded Models for Embodied Agents", "authors": ["Wenlong Huang", "Fei Xia", "Dhruv Shah", "Danny Driess", "Andy Zeng", "Yao Lu", "Pete Florence", "Igor Mordatch", "Sergey Levine", "Karol Hausman", "brian ichter"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=JCCi58IUsh", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["LLM"], "non_llm_models": {"perception": ["CLIP", "OWL-ViT"], "generation": [], "execution": ["CLIPort", "PPO policy"]}, "summary": "The user provides a high-level language instruction. The LLM decodes the task plan token-by-token, guided by grounded models that provide embodiment-aware probability scores (affordances from CLIPort/value functions, safety constraints, preferences) based on the current visual state. Once a complete command is decoded, it is dispatched to a low-level execution policy (CLIPort for manipulation or PPO policy for navigation) to perform the action in the environment."}, {"id": "KtvPdGb31Z", "title": "Describe, Explain, Plan and Select: Interactive Planning with LLMs Enables Open-World Multi-Task Agents", "authors": ["Zihao Wang", "Shaofei Cai", "Guanzhou Chen", "Anji Liu", "Xiaojian (Shawn) Ma", "Yitao Liang"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=KtvPdGb31Z", "code": "https://github.com/CraftJarvis/MC-Planner", "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator", "Verifier"], "llm_models": ["GPT-3", "Codex"], "non_llm_models": {"perception": ["Impala CNN", "CLIP"], "generation": [], "execution": ["Goal-conditioned Policy"]}, "summary": "The LLM generates an initial plan from the task instruction. A horizon-predictive selector (sharing Impala CNN backbone with the controller) ranks parallel sub-goals by estimated completion steps. The goal-conditioned policy executes the selected sub-goal. If execution fails, the descriptor summarizes the current state (using visual encoders or symbolic info), the LLM explains the error to verify the failure cause, and re-plans accordingly, iterating until the task is completed."}, {"id": "Xu8aG5Q8M3", "title": "LayoutGPT: Compositional Visual Planning and Generation with Large Language Models", "authors": ["Weixi Feng", "Wanrong Zhu", "Tsu-Jui Fu", "Varun Jampani", "Arjun Akula", "Xuehai He", "S Basu", "Xin Eric Wang", "William Yang Wang"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=Xu8aG5Q8M3", "code": "https://github.com/weixi-feng/LayoutGPT", "pattern": "LLM + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-3.5", "GPT-4", "Codex"], "non_llm_models": {"perception": ["CLIP", "GLIP"], "generation": ["GLIGEN", "Stable Diffusion", "ATISS", "ReCo", "Layout-Guidance"], "execution": []}, "summary": "User text prompt is processed by an LLM with in-context CSS exemplars to generate structured layout specifications. A layout parser extracts bounding boxes and attributes from the LLM output, which are then fed to layout-conditioned generation models (GLIGEN/Stable Diffusion for 2D images, ATISS for 3D scenes) to produce the final visual content."}, {"id": "ktYjrgOENR", "title": "DDCoT: Duty-Distinct Chain-of-Thought Prompting for Multimodal Reasoning in Language Models", "authors": ["Ge Zheng", "Bin Yang", "Jiajin Tang", "Hong-Yu Zhou", "Sibei Yang"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=ktYjrgOENR", "code": "https://github.com/SooLab/DDCOT", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Verifier"], "llm_models": ["GPT-3", "ChatGPT", "UnifiedQA"], "non_llm_models": {"perception": ["BLIP-2", "CLIP ViT-L/14", "VQA models"], "generation": [], "execution": []}, "summary": "The pipeline decomposes multimodal questions using an LLM, identifies visual sub-questions, uses BLIP-2/VQA models to extract visual information (perception), and feeds these sub-answers back to the LLM for critical integration and rationale generation to produce the final text answer."}, {"id": "9AcG3Tsyoq", "title": "AmadeusGPT: a natural language interface for interactive animal behavioral analysis", "authors": ["Shaokai Ye", "Jessy Lauer", "Mu Zhou", "Alexander Mathis", "Mackenzie Mathis"], "venue": "NeurIPS", "year": 2023, "url": "https://openreview.net/pdf?id=9AcG3Tsyoq", "code": "https://github.com/AdaptiveMotorControlLab/AmadeusGPT", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Sequential", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-3.5", "GPT-4"], "non_llm_models": {"perception": ["SAM", "SuperAnimal"], "generation": [], "execution": []}, "summary": "AmadeusGPT augments GPT-3.5/4 with a dual-memory mechanism and API documentation to generate Python task programs. The executed code calls the learned perception models SAM and SuperAnimal to extract object masks and animal poses from video. Deterministic spatio-temporal reasoning modules and a Python interpreter then compute kinematic features and animal-object interactions, while an LLM-based Explainer generates natural language summaries of the results."}, {"id": "zw2K6LfFI9", "title": "PERIA: Perceive, Reason, Imagine, Act via Holistic Language and Vision Planning for Manipulation", "authors": ["Fei Ni", "Jianye HAO", "Shiguang Wu", "Longxin Kou", "Yifu Yuan", "Zibin Dong", "Jinyi Liu", "MingZhi Li", "Yuzheng Zhuang", "YAN ZHENG"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=zw2K6LfFI9", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Tight", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator", "Verifier"], "llm_models": ["LLaMA-based MLLM"], "non_llm_models": {"perception": ["CLIP-L (visual encoder)"], "generation": ["Latent diffusion model (image-editing)"], "execution": ["Low-level policy (action controller)"]}, "summary": "The MLLM perceives visual observations through an aligned CLIP encoder, reasons to decompose instructions into stepwise language plans, and generates special [IMG] tokens that are projected to guide a diffusion model in synthesizing subgoal images. A consistency alignment validates image-instruction coherence before a low-level policy executes actions to achieve the subgoals."}, {"id": "Ur00BNk1v2", "title": "GenArtist: Multimodal LLM as an Agent for Unified Image Generation and Editing", "authors": ["Zhenyu Wang", "Aoxue Li", "Zhenguo Li", "Xihui Liu"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=Ur00BNk1v2", "code": "https://github.com/zhenyuw16/GenArtist", "pattern": "LLM + Perception + Generation + Action", "domain": "Image_Generation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": ["Object detector", "Object segmentor", "Pose estimator", "Canny edge extractor", "Depth map extractor"], "generation": ["SDXL", "PixArt-α", "Stable Diffusion", "ControlNet", "LMD", "BoxDiff", "TextDiffuser", "BLIP-Diffusion", "λ-ECLIPSE"], "execution": ["AnyDoor", "LaMa", "DiffEdit", "MagicBrush", "DragDiffusion", "DragonDiffusion", "InST"]}, "summary": "GPT-4V decomposes user queries into sub-problems and constructs a planning tree with generation and editing nodes. It dynamically selects tools from generation/editing libraries, invoking auxiliary perception models to provide missing position information. After each tool execution, GPT-4V verifies the output; if incorrect, the system backtracks to alternative tools or executes editing sub-trees for self-correction, iterating until the final image satisfies the requirements."}, {"id": "NGuGVT7ar2", "title": "Enhancing LLM Reasoning via Vision-Augmented Prompting", "authors": ["Ziyang Xiao", "Dongxiang Zhang", "Xiongwei Han", "Xiaojin Fu", "Wing Yin YU", "Tao Zhong", "Sai Wu", "Yuan Jessica Wang", "Jianwei Yin", "Gang Chen"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=NGuGVT7ar2", "code": "https://github.com/google/BIG-bench", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-4V"], "non_llm_models": {"perception": [], "generation": ["Python Turtle", "Matplotlib", "DALL-E 3"], "execution": []}, "summary": "Textual problem input is first processed by GPT-4 to generate a high-level plan and select appropriate drawing tools (Matplotlib, Turtle, or DALL-E 3). The selected tool generates an initial image, which enters an iterative refinement loop with GPT-4V: the MLLM reasons over the current image and text, generates drawing instructions to update the image, and accumulates textual thoughts. Finally, GPT-4V performs self-alignment verification by describing the final image and checking against the initial plan before generating the conclusive answer."}, {"id": "3Odq2tGSpp", "title": "Stylus: Automatic Adapter Selection for Diffusion Models", "authors": ["Michael Luo", "Justin Wong", "Brandon Trabucco", "Yanping Huang", "Joseph E. Gonzalez", "Zhifeng Chen", "Russ Salakhutdinov", "Ion Stoica"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=3Odq2tGSpp", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["Gemini 1.5"], "non_llm_models": {"perception": ["Gemini Ultra", "text-embedding-3-large"], "generation": ["Stable Diffusion v1.5", "LoRA adapters"], "execution": []}, "summary": "Offline, adapter model cards (images and metadata) are processed by Gemini Ultra to generate improved descriptions, which are embedded by text-embedding-3-large and stored in a vector database. During inference, the user text prompt is embedded to retrieve candidate LoRA adapters. Gemini 1.5 segments the prompt into keywords and assigns relevant adapters to each task. The selected adapters are merged into Stable Diffusion weights to generate the final image."}, {"id": "Y1rOWS2Z4i", "title": "Long-Horizon Planning for Multi-Agent Robots in Partially Observable Environments", "authors": ["Siddharth Nayak", "Adelmo Morrison Orozco", "Marina Ten Have", "Jackson Zhang", "Vittal Thirumalai", "Darren Chen", "Aditya Kapoor", "Eric Robinson", "Karthik Gopalakrishnan", "James Harrison", "Anuj Mahajan", "brian ichter", "Hamsa Balakrishnan"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=Y1rOWS2Z4i", "code": "https://github.com/nsidn98/LLaMAR", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4V", "GPT-4", "LLaVA", "IDEFICS-2", "CogVLM"], "non_llm_models": {"perception": ["CLIP"], "generation": [], "execution": ["RL policies", "behavior cloning policies", "heuristic policies"]}, "summary": "User instructions are processed by the Planner module to generate subtasks, which the Actor module converts into high-level actions for execution by low-level RL/BC policies. The Corrector module analyzes execution failures to suggest fixes, and the Verifier validates subtask completion, with all modules sharing a joint memory that feeds back into the next planning iteration. CLIP provides semantic guidance for exploration in partially observable environments."}, {"id": "HmCmxbCpp2", "title": "SG-Nav: Online 3D Scene Graph Prompting for LLM-based Zero-shot Object Navigation", "authors": ["Hang Yin", "Xiuwei Xu", "Zhenyu Wu", "Jie Zhou", "Jiwen Lu"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=HmCmxbCpp2", "code": null, "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaMA-7B", "GPT-4-0613"], "non_llm_models": {"perception": ["open-vocabulary 3D instance segmentation", "LLaVA-1.6 (Mistral-7B)"], "generation": [], "execution": []}, "summary": "RGB-D streams are processed by an open-vocabulary 3D instance segmentation module to build an online hierarchical scene graph, where newly detected nodes are densely connected by prompting an LLM and short-range edges are pruned by LLaVA-1.6. The LLM performs hierarchical chain-of-thought reasoning over subgraphs to score exploration frontiers, and a re-perception mechanism accumulates credibility to correct false-positive goals. Low-level path planning and execution are handled deterministically by Frontier-based Exploration and a Fast Marching Method local policy."}, {"id": "YawXY6mWiK", "title": "A Full-duplex Speech Dialogue Scheme Based On Large Language Model", "authors": ["Peng Wang", "Songshuo Lu", "Yaohua Tang", "Sijie Yan", "Wei Xia", "Yuanjun Xiong"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=YawXY6mWiK", "code": "https://github.com/SpeechColab/GigaSpeech", "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Llama-3-8B-Instruct"], "non_llm_models": {"perception": ["Whisper", "U2++ Conformer"], "generation": ["VITS", "XTTS-v2"], "execution": []}, "summary": "User speech is processed by streaming ASR (Whisper/U2++) into text tokens that are appended to the LLM's token sequence. The fine-tuned Llama-3-8B operates a neural FSM with SPEAK/LISTEN states, generating response text tokens and control tokens for state transitions. Text tokens are streamed to TTS (VITS/XTTS-v2) for speech synthesis, with the TTS module reporting completion back to the LLM to trigger subsequent generation, enabling full-duplex simultaneous interaction."}, {"id": "O0nBMRlkc8", "title": "Mobile-Agent-v2: Mobile Device Operation Assistant with Effective Navigation via Multi-Agent Collaboration", "authors": ["Junyang Wang", "Haiyang Xu", "Haitao Jia", "Xi Zhang", "Ming Yan", "Weizhou Shen", "Ji Zhang", "Fei Huang", "Jitao Sang"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=O0nBMRlkc8", "code": "https://github.com/X-PLUG/MobileAgent", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "GPT-4V"], "non_llm_models": {"perception": ["GroundingDINO", "ConvNextViT", "Qwen-VL"], "generation": [], "execution": ["ADB (Android Debug Bridge)"]}, "summary": "User instruction is processed by the Planning Agent (GPT-4) to generate condensed task progress. The Decision Agent (GPT-4V) receives this progress, current screen perception (from GroundingDINO, ConvNextViT, Qwen-VL), and memory content to generate the next operation. ADB executes the operation on the device. The Reflection Agent (GPT-4V) then verifies the outcome against expectations; if erroneous, it loops back to the Decision Agent for correction, otherwise the cycle continues with updated history."}, {"id": "IxazPgGF8h", "title": "ChatCam: Empowering Camera Control through Conversational AI", "authors": ["Xinhang Liu", "Yu-Wing Tai", "Chi-Keung Tang"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=IxazPgGF8h", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4", "GPT-3.5", "LLaMA-2"], "non_llm_models": {"perception": ["CLIP ViT-B/32"], "generation": ["CineGPT", "VQ-VAE (trajectory tokenizer)"], "execution": []}, "summary": "User provides a natural language camera operation request to GPT-4, which reasons and decomposes the task into sub-queries. GPT-4 calls the Anchor Determinator (using CLIP to ground text descriptions in the 3D scene) to determine anchor points, and calls CineGPT (autoregressive transformer with VQ-VAE tokenizer) to generate atomic camera trajectories. GPT-4 then composes the final trajectory by aligning atomic trajectories with anchor points, which is used to render video on NeRF/3DGS."}, {"id": "H2ATO32ilj", "title": "ART: Automatic Red-teaming for Text-to-Image Models to Protect Benign Users", "authors": ["Guanlin Li", "Kangjie Chen", "Shudong Zhang", "Jie Zhang", "Tianwei Zhang"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=H2ATO32ilj", "code": "https://github.com/GuanlinLee/ART", "pattern": "LLM + Perception + Generation", "domain": "Benchmark_Evaluation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Llama-2-7B"], "non_llm_models": {"perception": ["LLaVA-1.6-Mistral-7B", "Q16 detector", "NSFW detector", "Meta-Llama-Guard-2-8B", "toxicity detector", "multi-head detector"], "generation": ["Stable Diffusion 1.5", "Stable Diffusion 2.1", "Stable Diffusion XL"], "execution": []}, "summary": "The Writer Model (LLM) generates an initial safe prompt for a target harmful category, which is fed to Stable Diffusion to generate an image. The Guide Model (VLM) perceives the image and prompt, then provides instructions to the Writer Model on how to modify the prompt to better trigger unsafe content. This iterative loop continues for predefined rounds, after which Judge Models (ensemble of detectors) evaluate the safety of the final prompts and images."}, {"id": "bmoS6Ggw4j", "title": "Can Graph Learning Improve Planning in LLM-based Agents?", "authors": ["Xixi Wu", "Yifei Shen", "Caihua Shan", "Kaitao Song", "Siwei Wang", "Bohang Zhang", "Jiarui Feng", "Hong Cheng", "Wei Chen", "Yun Xiong", "Dongsheng Li"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=bmoS6Ggw4j", "code": "https://github.com/WxxShirley/GNN4TaskPlan", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Router", "Coordinator", "Reasoner"], "llm_models": ["GPT-4", "GPT-3.5-turbo", "CodeLlama-13B", "Mistral-7B", "Vicuna-13B", "Baichuan2-13B"], "non_llm_models": {"perception": ["Pose Detection", "Image Classification", "Audio Classification", "Image-to-Text", "Image Caption"], "generation": ["Text-to-Speech", "Pose-to-Image", "Translation", "Summarization"], "execution": []}, "summary": "The LLM first decomposes the user request into natural language steps. These steps and task node descriptions are embedded using e5-335M. A GNN (SGC or GraphSAGE) then retrieves relevant task nodes from the predefined task graph based on these embeddings and graph dependencies, selecting a valid path. Finally, the selected sequence of tasks is executed by invoking the corresponding HuggingFace models (perception and generation models) via APIs to fulfill the request."}, {"id": "YTHJ8O6SCB", "title": "SpatialPIN: Enhancing Spatial Reasoning Capabilities of Vision-Language Models through Prompting and Interacting 3D Priors", "authors": ["Chenyang Ma", "Kai Lu", "Ta-Ying Cheng", "Niki Trigoni", "Andrew Markham"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=YTHJ8O6SCB", "code": null, "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4V", "GPT-4o"], "non_llm_models": {"perception": ["Language Segment-Anything", "ZoeDepth", "Perspective Fields"], "generation": ["LaMa", "One-2-3-45++"], "execution": ["RRT*"]}, "summary": "User provides an RGB image and spatial query to GPT-4V, which describes objects and coordinates the pipeline. Language Segment-Anything performs segmentation, LaMa inpaints occlusions, and the segmentation is refined. ZoeDepth and Perspective Fields estimate metric depth and camera intrinsics. One-2-3-45++ reconstructs 3D object models. GPT-4V then performs spatial reasoning over the reconstructed 3D scene to either answer VQA questions or generate robot trajectories using RRT* planning."}, {"id": "uHs6RJFDsg", "title": "MoVA: Adapting Mixture of Vision Experts to Multimodal Context", "authors": ["Zhuofan Zong", "Bingqi Ma", "Dazhong Shen", "Guanglu Song", "Hao Shao", "Dongzhi Jiang", "Hongsheng Li", "Yu Liu"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=uHs6RJFDsg", "code": "https://github.com/TempleX98/MoVA", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Router", "Coordinator", "Reasoner"], "llm_models": ["Vicuna-7B", "Llama3-8B", "Yi-34B"], "non_llm_models": {"perception": ["CLIP ViT-L-336px", "DINOv2", "Co-DETR", "SAM", "Pix2Struct", "Deplot", "Vary", "BiomedCLIP"], "generation": [], "execution": []}, "summary": "The user provides an image and question. First, the LLM performs coarse-grained context-aware routing to dynamically select the most relevant vision experts from a pool of task-specific encoders. The selected experts extract visual features from the image, which are then fused by the MoV-Adapter using cross-attention and dynamic gating networks. Finally, the LLM generates a text response based on the fused visual representations and user instruction."}, {"id": "XXOMCwZ6by", "title": "Optimus-1: Hybrid Multimodal Memory Empowered Agents Excel in Long-Horizon Tasks", "authors": ["Zaijing Li", "Yuquan Xie", "Rui Shao", "Gongwei Chen", "Dongmei Jiang", "Liqiang Nie"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=XXOMCwZ6by", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier", "Coordinator"], "llm_models": ["GPT-4V", "Deepseek-VL", "InternLM-XComposer2-VL"], "non_llm_models": {"perception": ["MineCLIP"], "generation": [], "execution": ["STEVE-1"]}, "summary": "Knowledge-Guided Planner (GPT-4V) receives visual observations and retrieves structured knowledge from HDKG to generate sub-goals. Action Controller (STEVE-1) executes low-level actions. Experience-Driven Reflector periodically retrieves multimodal experiences from AMEP (indexed using MineCLIP similarities) to verify progress and trigger replanning if failures are detected."}, {"id": "kPmSfhCM5s", "title": "Vitron: A Unified Pixel-level Vision LLM for Understanding, Generating, Segmenting, Editing", "authors": ["Hao Fei", "Shengqiong Wu", "Hanwang Zhang", "Tat-Seng Chua", "Shuicheng YAN"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=kPmSfhCM5s", "code": "https://github.com/SkyworkAI/Vitron", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["Vicuna-7B-v1.5"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "Sketch Encoder (Regional pixel-aware visual extractor)", "SEEM"], "generation": ["GLIGEN", "ZeroScope", "I2VGen-XL", "StableVideo"], "execution": []}, "summary": "User queries (text/visual) are encoded by CLIP and Sketch Encoder to extract pixel-level features. The Vicuna LLM processes these features to reason about the task and plan execution, then routes hybrid instructions (textual commands + continuous feature embeddings) to appropriate backend specialists: GLIGEN for image generation/editing, SEEM for segmentation, ZeroScope/I2VGen-XL for video generation, and StableVideo for video editing. The LLM aggregates outputs for the final response."}, {"id": "RH7tfqhiZY", "title": "YouDream: Generating Anatomically Controllable Consistent Text-to-3D Animals", "authors": ["Sandeep Mishra", "Oindrila Saha", "Alan Bovik"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=RH7tfqhiZY", "code": "https://github.com/YouDream3D/YouDream", "pattern": "LLM + Generation", "domain": "3D_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion", "TetraPose ControlNet", "NeRF"], "execution": []}, "summary": "Text prompt describing target animal and pose is processed by a multi-agent LLM system (Finder, Observer, Modifier) to generate a 3D pose by adapting from a limited library of reference poses. The 3D pose is projected to 2D views, which condition TetraPose ControlNet to generate multi-view consistent images. These images guide NeRF optimization via Score Distillation Sampling to produce the final 3D asset."}, {"id": "N4quRxE19p", "title": "AvaTaR: Optimizing LLM Agents for Tool Usage via Contrastive Reasoning", "authors": ["Shirley Wu", "Shiyu Zhao", "Qian Huang", "Kexin Huang", "Michihiro Yasunaga", "Kaidi Cao", "Vassilis N. Ioannidis", "Karthik Subbian", "Jure Leskovec", "James Zou"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=N4quRxE19p", "code": "https://github.com/zou-group/avatar", "pattern": "LLM + Perception + Action", "domain": "Retrieval_Augmented", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT-4", "Claude-3"], "non_llm_models": {"perception": ["CLIP", "DPR", "ada-002", "QAGNN", "VQA models"], "generation": [], "execution": ["StringMatching", "ComputeEmbeddingSimilarity", "GetTopk", "TokenMatchScore", "GetEntityDocuments", "ParseAttributeFromQuery", "GetTopkEntities", "GetEntityBrand", "GetRelatedProducts", "WeightedSum", "Multiply"]}, "summary": "User queries are processed by an actor LLM that decomposes the task and generates action sequences invoking heterogeneous tools (CLIP for vision, DPR/ada-002 for text retrieval, QAGNN for relational reasoning, and various matching/scoring functions). Intermediate results are aggregated to produce final answers. During optimization, a comparator LLM performs contrastive reasoning on batches of successful and failed queries to generate instructions that iteratively improve the actor's retrieval strategies and tool usage."}, {"id": "nvYDPF4LJK", "title": "VisionLLM v2: An End-to-End Generalist Multimodal Large Language Model for Hundreds of Vision-Language Tasks", "authors": ["Jiannan Wu", "Muyan Zhong", "Sen Xing", "Zeqiang Lai", "Zhaoyang Liu", "Zhe Chen", "Wenhai Wang", "Xizhou Zhu", "Lewei Lu", "Tong Lu", "Ping Luo", "Yu Qiao", "Jifeng Dai"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=nvYDPF4LJK", "code": "https://github.com/OpenGVLab/VisionLLM", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Router", "Coordinator", "Translator", "Reasoner"], "llm_models": ["Vicuna-7B-v1.5"], "non_llm_models": {"perception": ["CLIP ViT-L/14", "Grounding DINO", "UniPose", "Mask Decoder", "Region Encoder"], "generation": ["Stable Diffusion v1.5", "InstructPix2Pix"], "execution": []}, "summary": "Input images and visual prompts are encoded by CLIP and the region encoder, then processed by Vicuna-7B which parses instructions and generates routing tokens ([DET], [GEN], etc.). Super-link queries extract task-specific hidden states from the LLM and transmit them as conditions to the selected decoder (Grounding DINO for detection, UniPose for pose, Stable Diffusion for generation) to produce the final structured or visual output."}, {"id": "GNSMl1P5VR", "title": "Visual Sketchpad: Sketching as a Visual Chain of Thought for Multimodal Language Models", "authors": ["Yushi Hu", "Weijia Shi", "Xingyu Fu", "Dan Roth", "Mari Ostendorf", "Luke Zettlemoyer", "Noah A. Smith", "Ranjay Krishna"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=GNSMl1P5VR", "code": "https://github.com/Yushi-Hu/VisualSketchpad", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "GPT-4 Turbo"], "non_llm_models": {"perception": ["Grounding-DINO", "SAM (SegmentAnything)", "Semantic-SAM", "DepthAnything"], "generation": [], "execution": []}, "summary": "Given a multimodal query, the LLM generates a sketching plan and synthesizes Python code to either create plots (matplotlib/networkx) or invoke specialist vision models. The executed code produces intermediate visual sketches (auxiliary lines, segmentation masks, depth maps) that serve as observations, which the LLM analyzes through iterative reasoning cycles to arrive at the final text answer."}, {"id": "UGlDVc0GTU", "title": "LLM-based Skill Diffusion for Zero-shot Policy Adaptation", "authors": ["Woo Kyung Kim", "Youngseok Lee", "Jooyoung Kim", "Honguk Woo"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=UGlDVc0GTU", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Reflector", "Translator"], "llm_models": ["GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["CLIP", "VAE (skill encoder)"], "generation": [], "execution": ["Skill diffusion planner", "Skill prior"]}, "summary": "CLIP encodes language goals into embeddings. GPT-4/3.5 translates language contexts into executable loss function code. The skill prior samples skill embeddings conditioned on CLIP goal embeddings and current state. The skill diffusion planner generates trajectories guided by gradients of the LLM-generated loss function. The LLM validates trajectories in a closed loop, refining the loss function or guidance parameters until the trajectory aligns with the context, then actions are executed in MetaWorld."}, {"id": "oqdy2EFrja", "title": "Compositional 3D-aware Video Generation with LLM Director", "authors": ["Hanxin Zhu", "Tianyu He", "Anni Tang", "Junliang Guo", "Zhibo Chen", "Jiang Bian"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=oqdy2EFrja", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Video_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": ["Monocular depth estimator"], "generation": ["LucidDreamer", "HumanGaussian", "Motion-X", "Stable Diffusion", "3D Gaussian Splatting"], "execution": []}, "summary": "GPT-4V decomposes input text into sub-prompts and routes them to expert generation models (LucidDreamer for scenes, HumanGaussian for objects, Motion-X for motion) to create 3D Gaussian representations. GPT-4V then performs step-by-step reasoning over rendered images to estimate 2D trajectories, which are lifted to 3D using a monocular depth estimator. Finally, Stable Diffusion provides 2D priors via SDS to iteratively refine the composition parameters, and the result is rendered into video using 3D Gaussian Splatting."}, {"id": "C3ZHiij9QE", "title": "VLMimic: Vision Language Models are Visual Imitation Learner for Fine-grained Actions", "authors": ["Guangyan Chen", "Meiling Wang", "Te Cui", "Yao Mu", "Haoyang Lu", "Tianxing Zhou", "Zicai Peng", "Mengxiao Hu", "Haizhou Li", "Li Yuan", "Yi Yang", "Yufeng Yue"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=C3ZHiij9QE", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4V"], "non_llm_models": {"perception": ["SAM-Track", "FrankMocap", "BundleSDF", "FoundationPose", "Vision Foundation Models (VFM)"], "generation": [], "execution": ["OMPL motion planner", "robot controller"]}, "summary": "Human demonstration videos are first processed by perception models (VFM for detection, SAM-Track for segmentation, FrankMocap for hand pose, BundleSDF for reconstruction, FoundationPose for pose estimation) to extract object-centric interactions. GPT-4V then learns skills using hierarchical constraint representations (semantic and geometric) from these interactions. For unseen environments, a skill adapter iteratively refines constraints by comparing with stored knowledge. Finally, the derived skills are executed via motion planning (OMPL) and robot controllers to perform manipulation tasks, with failure reasoning for error recovery."}, {"id": "xgP5ynlZWf", "title": "RestoreAgent: Autonomous Image Restoration Agent via Multimodal Large Language Models", "authors": ["Haoyu Chen", "Wenbo Li", "Jinjin Gu", "Jingjing Ren", "Sixiang Chen", "Tian Ye", "Renjing Pei", "Kaiwen Zhou", "Fenglong Song", "Lei Zhu"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=xgP5ynlZWf", "code": null, "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Llava-Llama3-8b"], "non_llm_models": {"perception": [], "generation": ["DnCNN", "Real-ESRGAN", "StableSR", "AirNet", "PromptIR", "MiOIR", "InstructIR", "DA-CLIP", "AutoDIR", "DeblurGAN", "MIMO-UNet", "FBCNN"], "execution": []}, "summary": "Degraded image is input to the fine-tuned Llava-Llama3-8b MLLM, which analyzes degradation types and plans the optimal task sequence and model selection. The selected specialist restoration models (e.g., denoising, deblurring CNNs/GANs) are executed sequentially to produce the restored image. The system supports iterative re-planning and rollback based on execution history for mid-course correction."}, {"id": "HzANl2unCB", "title": "ChatTracker: Enhancing Visual Tracking Performance via Chatting with Multimodal Large Language Model", "authors": ["Yiming Sun", "Fan Yu", "Shaoxiang Chen", "Yu Zhang", "Junwei Huang", "Yang Li", "Chenhui Li", "Changbo Wang"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=HzANl2unCB", "code": null, "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector", "Translator", "Coordinator"], "llm_models": ["GPT-4V", "Gemini-1.0", "LLaVA-7B"], "non_llm_models": {"perception": ["GroundingDINO", "CLIP", "GVLM"], "generation": [], "execution": ["MixFormer", "ARTrack", "TransT", "Stark", "OSTrack"]}, "summary": "The template image is processed by an MLLM to generate initial target descriptions, which are iteratively refined via reflection using GroundingDINO grounding feedback (IoU-based validation). Optimized descriptions are then used by a Semantic Tracking module with GVLM and visual trackers to generate foreground/background proposals, and a Foreground Verification module selects the final bounding box using a trained scorer."}, {"id": "LEzx6QRkRH", "title": "RL-GPT: Integrating Reinforcement Learning and Code-as-policy", "authors": ["Shaoteng Liu", "Haoqi Yuan", "Minda Hu", "Yanwei Li", "Yukang Chen", "Shu Liu", "Zongqing Lu", "Jiaya Jia"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=LEzx6QRkRH", "code": null, "pattern": "LLM + Perception + Action", "domain": "Gaming", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Translator", "Verifier"], "llm_models": ["GPT-4", "GPT-3.5"], "non_llm_models": {"perception": ["CLIP"], "generation": [], "execution": ["PPO"]}, "summary": "RL-GPT employs a slow GPT-4 agent to decompose tasks and decide whether each sub-action should be handled by generated Python code or by RL. A fast GPT-4 agent then writes Python code or configures a PPO training job; the PPO policy is trained in MineDojo with CLIP-based dense rewards, and LLM-generated high-level coded actions are inserted into the RL action space. A critic GPT-3.5/4 agent evaluates outcomes, driving iterative refinement of the plan and implementations."}, {"id": "QMaLS4VeY3", "title": "Aligning Audio-Visual Joint Representations with an Agentic Workflow", "authors": ["Shentong Mo", "Yibing Song"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=QMaLS4VeY3", "code": null, "pattern": "LLM + Perception + Action", "domain": "Audio_Speech", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Vicuna-v1.5-7b"], "non_llm_models": {"perception": ["Multi-modal LLM", "Vision-Language Model", "ImageBind", "X-CLIP"], "generation": [], "execution": ["Spectral Subtraction", "Wiener Filtering", "Wavelet Denoising", "Spectral Gating", "Speed Modification", "Pitch Modification", "Volume Adjustment", "Filling Blanks"]}, "summary": "Input AV pair is processed by a multi-modal LLM to generate separate text descriptions for audio and visual content. The Vicuna agent reasons over these descriptions to plan audio editing actions (noise filtering or temporal coordination). Predefined signal processing actions execute the audio modifications. A VLM and ImageBind then evaluate the alignment and provide feedback scores. If alignment is insufficient, the cycle repeats with new actions planned on the original audio, progressively refining the AV alignment."}, {"id": "y9huwsnGRJ", "title": "Continuously Learning, Adapting, and Improving: A Dual-Process Approach to Autonomous Driving", "authors": ["Jianbiao Mei", "Yukai Ma", "Xuemeng Yang", "Licheng Wen", "Xinyu Cai", "Xin Li", "Daocheng Fu", "Bo Zhang", "Pinlong Cai", "Min Dou", "Botian Shi", "Liang He", "Yong Liu", "Yu Qiao"], "venue": "NeurIPS", "year": 2024, "url": "https://openreview.net/pdf?id=y9huwsnGRJ", "code": "https://github.com/PJLab-ADG/LeapAD", "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator", "Verifier"], "llm_models": ["GPT-4", "Qwen-1.5-1.8B"], "non_llm_models": {"perception": ["Qwen-VL-7B"], "generation": [], "execution": ["Action executor (low-level controller)"]}, "summary": "Camera input is processed by Qwen-VL-7B to generate text descriptions of critical objects. These descriptions are fed into the Heuristic Process (fine-tuned Qwen-1.5) which retrieves similar experiences from a memory bank (using OpenAI embeddings) and outputs driving decisions. An action executor translates these meta-actions into vehicle control signals. When accidents occur, the Analytic Process (GPT-4) reflects on the failure, updates the memory bank with corrected reasoning, and continuously improves the system through supervised fine-tuning of the Heuristic Process."}, {"id": "s6k9l5yX8e", "title": "Dynam3D: Dynamic Layered 3D Tokens Empower VLM for Vision-and-Language Navigation", "authors": ["Zihan Wang", "Seungjun Lee", "Gim Hee Lee"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=s6k9l5yX8e", "code": "https://github.com/MrZihan/Dynam3D", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["LLaVA-Phi-3-mini"], "non_llm_models": {"perception": ["CLIP-ViT-L/14", "FastSAM", "Generalizable Feature Field (g3D-LF)"], "generation": [], "execution": []}, "summary": "Dynam3D processes posed monocular RGB-D images using CLIP-ViT-L/14 and FastSAM to extract 2D patch features and instance masks, which are projected into 3D space and aggregated via learned Instance/Zone Encoders and a Merging Discriminator into hierarchical 3D tokens. A generalizable feature field (g3D-LF) renders panoramic 3D patch tokens. These multi-level 3D tokens, together with language instructions and action history, are fed into LLaVA-Phi-3-mini to directly predict atomic navigation actions. Deterministic geometric operations including frustum culling and cube-based spatial partitioning are used to maintain and update the dynamic 3D feature cloud."}, {"id": "h0LzGQq6uO", "title": "Knowledge-based Visual Question Answer with Multimodal Processing, Retrieval and Filtering", "authors": ["Yuyang Hong", "Jiaqi Gu", "Qi Yang", "Lubin Fan", "Yue Wu", "Ying Wang", "Kun Ding", "Shiming Xiang", "Jieping Ye"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=h0LzGQq6uO", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["VLM-PRF (based on Qwen2.5-VL-3B/7B, LLaMA-3.1-8B, or InternVL3-8B)"], "non_llm_models": {"perception": ["EVA-CLIP", "Qwen2.5-VL (captioning tool)", "Qwen2.5-VL (grounding tool)"], "generation": [], "execution": []}, "summary": "VLM-PRF receives a visual question and image, plans and invokes visual tools (captioning/grounding) to extract precise multimodal queries. EVA-CLIP retrieves relevant Wikipedia articles using these queries. VLM-PRF then filters the retrieved content to extract task-relevant knowledge, which is used to generate the final text answer."}, {"id": "72UR53jN7T", "title": "ThinkAct: Vision-Language-Action Reasoning via Reinforced Visual Latent Planning", "authors": ["Chi-Pin Huang", "Yueh-Hua Wu", "Min-Hung Chen", "Yu-Chiang Frank Wang", "Fu-En Yang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=72UR53jN7T", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Self_Correction", "uncertainty": "LLM_Verification", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL"], "non_llm_models": {"perception": ["DINOv2", "CLIP", "Q-Former"], "generation": [], "execution": ["DiT-based Diffusion Policy"]}, "summary": "Visual observations and language instructions are encoded by DINOv2 and CLIP. Qwen2.5-VL generates step-by-step reasoning and compresses it into a visual plan latent, which is projected via Q-Former to condition a DiT-based Diffusion Policy. The policy predicts executable 7-DOF robot actions conditioned on the latent plan and current state. The MLLM is trained with GRPO using action-aligned visual rewards derived from goal completion and trajectory alignment to ground reasoning in physical execution."}, {"id": "mj8VN4MyrO", "title": "ThinkSound: Chain-of-Thought Reasoning in Multimodal LLMs for Audio Generation and Editing", "authors": ["Huadai Liu", "Kaicheng Luo", "Jialei Wang", "Wen Wang", "Qian Chen", "Zhou Zhao", "Wei Xue"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=mj8VN4MyrO", "code": "https://github.com/liuhuadai/ThinkSound", "pattern": "LLM + Perception + Generation", "domain": "Audio_Speech", "flow": "Sequential", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["VideoLLaMA 2"], "non_llm_models": {"perception": ["Grounded SAM-2", "MetaCLIP", "CLIP"], "generation": ["Unified Audio Foundation Model", "Stability AI Audio VAE"], "execution": []}, "summary": "Video input is processed by a fine-tuned VideoLLaMA 2 to generate CoT reasoning about acoustic events and temporal dependencies. For interactive stages, Grounded SAM-2 extracts object ROIs from user clicks. The CoT reasoning, combined with video features (CLIP/MetaCLIP) and optional audio context, conditions a flow-matching-based Unified Audio Foundation Model to synthesize or edit audio through three sequential stages: initial generation, object-centric refinement, and instruction-based editing."}, {"id": "tRXt10xKc5", "title": "ContextAgent: Context-Aware Proactive LLM Agents with Open-world Sensory Perceptions", "authors": ["Bufang Yang", "Lilin Xu", "Liekang Zeng", "Kaiwei Liu", "Siyang Jiang", "Wenrui Lu", "Hongkai Chen", "Xiaofan Jiang", "Guoliang Xing", "Zhenyu Yan"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=tRXt10xKc5", "code": "https://github.com/openaiotlab/ContextAgent", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner"], "llm_models": ["Llama-3.1", "Qwen2.5", "GPT-4o", "DeepSeek-R1-Distill-Qwen"], "non_llm_models": {"perception": ["Qwen-2.5-VL", "speech recognition model"], "generation": [], "execution": []}, "summary": "ContextAgent extracts visual and audio contexts from wearable sensors using Qwen-2.5-VL and a speech recognition model. These sensory contexts, combined with persona contexts, are fed into a fine-tuned LLM reasoner that predicts a proactive score and plans tool chains. If the score exceeds a threshold, the system sequentially calls deterministic external tools (e.g., GPS, weather, bus schedule, Uber APIs) and integrates their outputs to generate the final proactive assistance response."}, {"id": "P6PijkA5lz", "title": "Image Editing As Programs with Diffusion Models", "authors": ["Yujia Hu", "Songhua Liu", "Zhenxiong Tan", "Xingyi Yang", "Xinchao Wang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=P6PijkA5lz", "code": "https://github.com/YujiaHu1109/IEAP", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Mseg (segmentation model)"], "generation": ["FLUX.1-dev", "Minpaint (inpainting model)", "Mattr (attribute editing model)", "Mfusion (fusion network)", "Mglobal (global transformation model)"], "execution": []}, "summary": "User instructions are first processed by GPT-4o using Chain-of-Thought reasoning to decompose complex edits into a sequence of atomic operations (RoI Localization, Inpainting, Editing, Compositing, Global Transformation). Mseg performs RoI localization via segmentation. The system then sequentially executes the program: Minpaint handles inpainting for add/remove operations, Mattr performs localized attribute editing, Mfusion blends edited regions using annular masks, and Mglobal applies full-image transformations, producing the final edited image."}, {"id": "yKUwkihcsi", "title": "Iterative Tool Usage Exploration for Multimodal Agents via Step-wise Preference Tuning", "authors": ["Pengxiang Li", "Zhi Gao", "Bofei Zhang", "Yapeng Mi", "Xiaojian Ma", "Chenrui Shi", "Tao Yuan", "Yuwei Wu", "Yunde Jia", "Song-Chun Zhu", "Qing Li"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=yKUwkihcsi", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Verifier"], "llm_models": ["Qwen2-VL-7B", "Qwen2.5-7B"], "non_llm_models": {"perception": ["OCR", "visualizer", "objectloc", "seg"], "generation": [], "execution": ["ask_search_agent"]}, "summary": "The SPORT framework first synthesizes multimodal tasks using an LLM. The Qwen2-VL-7B controller then performs iterative exploration: for each step, it samples multiple candidate actions (thoughts and code), executes them via heterogeneous tools (OCR, visualizer, search, etc.), and receives observations. A verifier LLM evaluates these parallel samples to construct step-wise preference pairs, which are used to update the controller via Direct Preference Optimization (DPO), enabling autonomous refinement without human annotations."}, {"id": "xrAqVVk2qe", "title": "TP-MDDN: Task-Preferenced Multi-Demand-Driven Navigation with Autonomous Decision-Making", "authors": ["Shanshan Li", "Da Huang", "Yu He", "Yanwei Fu", "Yu-Gang Jiang", "Xiangyang Xue"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=xrAqVVk2qe", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier"], "llm_models": ["GPT-4o", "Qwen2.5-VL-72B"], "non_llm_models": {"perception": ["Ram-Grounded-SAM"], "generation": [], "execution": ["Pretrained Specialist Policy (DDN navigation network)"]}, "summary": "BreakLLM decomposes long-horizon instructions into subtasks. Ram-Grounded-SAM segments RGB images to build a 2D semantic memory map (MASMap). LocateLLM selects the next target object and position. A Dual-Tempo Action Generator combines deterministic A* global planning (Generalist Policy) with a learned pretrained Specialist Policy for low-level control. StatusMLLM verifies subtask completion, and an Adaptive Error Corrector performs deterministic replanning when collisions or boundary violations occur."}, {"id": "Qla5PqFL0s", "title": "A Unified Reasoning Framework for Holistic Zero-Shot Video Anomaly Analysis", "authors": ["Dongheng Lin", "Mengxue Qu", "Kunyang Han", "Jianbo Jiao", "Xiaojie Jin", "Yunchao Wei"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=Qla5PqFL0s", "code": "https://github.com/Rathgrith/URF-ZS-HVAA", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Llama-3.1-8B-Instruct"], "non_llm_models": {"perception": ["VideoLLaMA3-7B", "Qwen2.5-VL-7B"], "generation": [], "execution": []}, "summary": "Video clips are processed by VideoLLaMA3-7B to generate captions and anomaly tag lists. Llama-3.1-8B-Instruct computes initial anomaly scores from these captions, and conditionally refines them via a score-gated reasoning step if confidence is ambiguous. The resulting scores and tags guide Qwen2.5-VL-7B to perform spatial localization (predicting bounding boxes) and textual anomaly understanding (generating descriptions), with visual prompts enhanced by overlaying detected boxes on frames when confidence is high."}, {"id": "zwCb9cKHpd", "title": "SAVVY: Spatial Awareness via Audio-Visual LLMs through Seeing and Hearing", "authors": ["Mingfei Chen", "Zijun Cui", "Xiulong Liu", "Jinlin Xiang", "Caleb Zheng", "Jingyuan Li", "Eli Shlizerman"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=zwCb9cKHpd", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Gemini-2.5-pro"], "non_llm_models": {"perception": ["CLIPSeg", "SAM2", "monocular depth estimator", "SRP-PHAT"], "generation": [], "execution": []}, "summary": "The pipeline operates in two stages: (1) Egocentric Spatial Track Construction, where the AV-LLM generates snapshot descriptions and temporal grounding, dispatches text queries to CLIPSeg/SAM2 for segmentation, and integrates outputs from a monocular depth estimator and SRP-PHAT spatial audio processor to build object trajectories; (2) Dynamic Global Map Construction, where egocentric tracks are transformed into global coordinates via SLAM-derived camera poses, clustered (DBSCAN) and smoothed (Kalman filter), then used to answer spatial questions through coordinate transformation."}, {"id": "qMm7tC1zvj", "title": "EfficientNav: Towards On-Device Object-Goal Navigation with Navigation Map Caching and Retrieval", "authors": ["Zebin Yang", "Sunjian Zheng", "Tong Xie", "Tianshi Xu", "Bo Yu", "Fan Wang", "Jie Tang", "Shaoshan Liu", "Meng Li"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=qMm7tC1zvj", "code": "https://github.com/PKU-SEC-Lab/EfficientNav", "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["LLaMA3.2-11b", "LLaVA-34b"], "non_llm_models": {"perception": ["Grounding DINO", "CLIP"], "generation": [], "execution": ["Low-level trajectory controller"]}, "summary": "RGB-D observations are processed by Grounding DINO for object detection to construct a semantic navigation map. CLIP encodes object groups and the target goal to select relevant map groups via similarity thresholding. The LLM planner (LLaMA3.2-11b or LLaVA-34b) reasons over the selected map segments, instruction, and trajectory history to generate the next sub-goal. A low-level controller then executes the trajectory to reach the sub-goal, with the process iterating until the target object is found."}, {"id": "h6xQClTm4W", "title": "Exploring the Limits of Vision-Language-Action Manipulation in Cross-task Generalization", "authors": ["Jiaming Zhou", "Ke Ye", "Jiayi LIU", "Teli Ma", "Zifan Wang", "Ronghe Qiu", "Kun-Yu Lin", "Zhilin Zhao", "Junwei Liang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=h6xQClTm4W", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Converge", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2.5-Instruct (7B/72B)"], "non_llm_models": {"perception": ["GroundingDINO", "Dynamics Diffusion Model (InstructPix2Pix-based)"], "generation": [], "execution": ["Robot controller (Franka Panda/xArm7)"]}, "summary": "Given an unseen task, the dynamics diffusion model retrieves relevant seen demonstrations by computing feature similarity between predicted future observations. GroundingDINO extracts 3D object coordinates from the current view. The Qwen2.5 LLM then constructs an in-context prompt combining the selected demonstrations and textualized object information to predict a 7-dimensional action sequence for robot execution."}, {"id": "zY5J1vp7tZ", "title": "RDD: Retrieval-Based Demonstration Decomposer for Planner Alignment in Long-Horizon Tasks", "authors": ["Mingxuan Yan", "Yuping Wang", "Zechun Liu", "Jiachen Li"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=zY5J1vp7tZ", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["LLaVA (llama3-llava-next-8B)", "Gemini-1.5-flash"], "non_llm_models": {"perception": ["LIV", "R3M", "CLIP", "DINOv2", "RVT (vision component)"], "generation": [], "execution": ["RVT (Robotic Transformer)"]}, "summary": "RDD first uses visual encoders (LIV, R3M, etc.) to extract features from video demonstrations and retrieves similar intervals from the visuomotor policy's training data via dynamic programming to create aligned sub-task decompositions. These are used to fine-tune LLaVA (with LoRA) as a high-level planner. During execution, the planner processes visual observations and generates language sub-task instructions, which the RVT policy executes to perform robotic manipulation actions step-by-step."}, {"id": "w0xm9oG8im", "title": "STRIDER: Navigation via Instruction-Aligned Structural Decision Space Optimization", "authors": ["Diqi He", "Xuehao Gao", "Hao Li", "Junwei Han", "Dingwen Zhang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=w0xm9oG8im", "code": "https://github.com/diqihe666/STRIDER-Nav", "pattern": "LLM + Perception", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Qwen-VL-Max"], "generation": [], "execution": []}, "summary": "At each timestep, a deterministic Structured Waypoint Generator extracts skeleton-based candidate waypoints from depth observations via morphological thinning and graph-based endpoint selection. A VLM (Qwen-VL-Max) generates directional visual descriptions and step-wise progress feedback by comparing consecutive observations. An LLM (GPT-4o) reasons over the instruction, structured waypoint descriptions, and feedback to select the next waypoint, which is executed by a deterministic controller, forming a closed-loop iterative pipeline."}, {"id": "L2W4wQsNkY", "title": "MindJourney: Test-Time Scaling with World Models for Spatial Reasoning", "authors": ["Yuncong Yang", "Jiageng Liu", "Zheyuan Zhang", "Siyuan Zhou", "Reuben Tan", "Jianwei Yang", "Yilun Du", "Chuang Gan"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=L2W4wQsNkY", "code": "https://github.com/UMass-Embodied-AGI/MindJourney", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator"], "llm_models": ["GPT-4o", "GPT-4.1", "InternVL3-14B", "OpenAI o1"], "non_llm_models": {"perception": [], "generation": ["Search World Model (SWM)", "Stable-Virtual-Camera (SVC)", "Wan2.2-TI2V-5B"], "execution": []}, "summary": "Given a spatial reasoning query and initial image, the VLM performs Spatial Beam Search: iteratively planning camera trajectories, querying the world model (SWM or SVC) to synthesize corresponding egocentric video frames, and evaluating observations to cache helpful evidence in a buffer. After n steps, the VLM answers the question using the original image and gathered multi-view evidence."}, {"id": "4xvE6Iy77Y", "title": "PRIMT: Preference-based Reinforcement Learning with Multimodal Feedback and Trajectory Synthesis from Foundation Models", "authors": ["Ruiqi Wang", "Dezhong Zhao", "Ziqin Yuan", "Tianyu Shao", "Guohua Chen", "Dominic Kao", "Sungeun Hong", "Byung-Cheol Min"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=4xvE6Iy77Y", "code": "https://github.com/primt25/PRIMT", "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "DAG", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["VLM (Vision-Language Model)", "CLIP"], "generation": [], "execution": ["SAC policy", "Kinova Jaco robot"]}, "summary": "Robot trajectories from SAC policy rollouts are preprocessed into textual projections for LLM analysis and visual keyframes for VLM analysis. GPT-4o and VLM evaluate these in parallel with confidence scoring; intra-modal crowd-check voting aggregates predictions, and PSL performs inter-modal fusion to generate preference labels. GPT-4o additionally generates bootstrapped trajectories (foresight) and counterfactual edits (hindsight) which, combined with a causal auxiliary loss, train the reward model to guide policy improvement."}, {"id": "VzSjSUE0BZ", "title": "CREA: A Collaborative Multi-Agent Framework for Creative Image Editing and Generation", "authors": ["Kavana Venkatesh", "Connor Dunlop", "Pinar Yanardag"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=VzSjSUE0BZ", "code": "https://github.com/ConnorDunlop/CREA.git", "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": [], "generation": ["Flux", "ControlNet", "CogVideoX"], "execution": []}, "summary": "User input (text concept or image) is processed by the Creative Director agent (GPT-4o) to formulate a creativity blueprint. The Prompt Architect (GPT-4o) translates this into contrastive prompts, which the Generative Executor uses to invoke Flux (for generation) or ControlNet (for editing). The Art Critic (GPT-4o) evaluates the output using a Creativity Index (CI); if CI < threshold, the Refinement Strategist (GPT-4o) adjusts prompts and the loop repeats for up to 3 iterations before producing the final creative output."}, {"id": "cU4ow1odRe", "title": "ComfyMind: Toward General-Purpose Generation via Tree-Based Planning and Reactive Feedback", "authors": ["Litao Guo", "Xinli Xu", "Luozhou Wang", "Jiantao Lin", "Jinsong Zhou", "Zixin Zhang", "Bolan Su", "Ying-Cong Chen"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=cU4ow1odRe", "code": "https://github.com/EnVision-Research/ComfyMind", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["VLM (Evaluation Agent)", "SAM (Segment Anything)"], "generation": ["Flux", "Flux Redux", "ACE++", "Hunyuan", "Wan", "Stable Diffusion", "SVD (Stable Video Diffusion)"], "execution": []}, "summary": "User instructions are processed by a Planning Agent (GPT-4o) that performs hierarchical task decomposition via search tree planning. The Execution Agent maps selected Semantic Workflow Interface (SWI) functions to JSON workflows executed on the ComfyUI platform using heterogeneous generative models (Flux, SD, etc.). An Evaluation Agent (VLM) verifies outputs, enabling a local feedback loop for iterative correction or tree backtracking until the task is successfully resolved."}, {"id": "kmv7yg6QXv", "title": "SoFar: Language-Grounded Orientation Bridges Spatial Reasoning and Object Manipulation", "authors": ["Zekun Qi", "Wenyao Zhang", "Yufei Ding", "Runpei Dong", "XinQiang Yu", "Jingwen Li", "Lingyun Xu", "Baoyu Li", "Xialin He", "Guofan Fan", "Jiazhao Zhang", "Jiawei He", "Jiayuan Gu", "Xin Jin", "Kaisheng Ma", "Zhizheng Zhang", "He Wang", "Li Yi"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=kmv7yg6QXv", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["GPT-4V", "LLaVA"], "non_llm_models": {"perception": ["SAM", "Florence-2", "PointSO", "CLIP"], "generation": [], "execution": ["GSNet", "OMPL", "Robot Controller"]}, "summary": "RGB-D input and language instructions are first processed by a VLM to extract object phrases and orientation descriptions. Florence-2 and SAM perform language-conditioned segmentation while PointSO predicts semantic orientations, together constructing a 6-DoF scene graph. The VLM performs spatial reasoning over this graph to compute target transformations. GSNet generates grasp candidates, OMPL plans collision-free trajectories, and the robot executes with closed-loop retry capability for error recovery."}, {"id": "cjjPn1EIwq", "title": "ESCA: Contextualizing Embodied Agents via Scene-Graph Generation", "authors": ["Jiani Huang", "Amish Sethi", "Matthew Kuo", "Mayank Keoliya", "Neelay Velingker", "JungHo Jung", "Ser-Nam Lim", "Ziyang Li", "Mayur Naik"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=cjjPn1EIwq", "code": "https://github.com/video-fm/ESCA", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Verifier"], "llm_models": ["GPT-4o", "InternVL-2.5", "Qwen2.5-VL", "Gemini-2.0"], "non_llm_models": {"perception": ["Grounding DINO", "SAM2", "SGClip"], "generation": [], "execution": []}, "summary": "ESCA uses an MLLM to extract relevant concepts from instructions and history, which guide Grounding DINO and SAM2 to detect and segment objects. SGClip then constructs a probabilistic scene graph from these segments, and the MLLM validates and summarizes this structured representation into natural language to contextualize task planning and generate executable actions for embodied environments. SGClip is trained via a neurosymbolic pipeline implemented in the Scallop programming language."}, {"id": "PQYazNKEYo", "title": "VLA-OS: Structuring and Dissecting Planning Representations and Paradigms in Vision-Language-Action Models", "authors": ["Chongkai Gao", "Zixuan Liu", "Zhenghao Chi", "Junshan Huang", "Xin Fei", "Yiwen Hou", "Yuxuan Zhang", "Yudi Lin", "Zhirui Fang", "Lin Shao"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=PQYazNKEYo", "code": "https://github.com/HeegerGao/VLA-OS", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "DAG", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Qwen2.5"], "non_llm_models": {"perception": ["DINOV2", "SigLIP", "AM-Radio", "CLIP"], "generation": ["Image foresight planning head", "Language planning head", "Visual planning head"], "execution": ["Action policy head", "Action head"]}, "summary": "Visual observations are encoded by vision encoders (DINOV2/SigLIP) and processed by the Qwen2.5 VLM. Planning heads generate task plans (language, visual tokens, or future images) which, along with VLM features, are fed to an action head that generates robot actions (end-effector poses, gripper commands) for manipulation tasks."}, {"id": "IPxOoU8aqt", "title": "Doctor Approved: Generating Medically Accurate Skin Disease Images through AI-Expert Feedback", "authors": ["Janet Wang", "Yunbei Zhang", "Zhengming Ding", "Jihun Hamm"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=IPxOoU8aqt", "code": "https://github.com/janet-sw/MAGIC.git", "pattern": "LLM + Perception + Generation", "domain": "Medical_Analysis", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Verifier", "Reasoner", "Translator", "Coordinator"], "llm_models": ["GPT-4o", "MedGemma-4B"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion v2-1"], "execution": []}, "summary": "Stable Diffusion v2-1 generates synthetic skin disease images via Image-to-Image translation from source images and text prompts. GPT-4o evaluates these images against expert-designed clinical checklists (Location, Lesion Type, Shape/Size, Color, Texture) and returns binary preference feedback. This feedback is used to fine-tune the diffusion model via DPO or RFT in an iterative loop, producing clinically accurate synthetic data for augmenting classifier training (ResNet18/DINOv2)."}, {"id": "VZQSrNfNHd", "title": "RobotSmith: Generative Robotic Tool Design for Acquisition of Complex Manipulation Skills", "authors": ["Chunru Lin", "Haotian Yuan", "Yian Wang", "Xiaowen Qiu", "Tsun-Hsuan Wang", "Minghao Guo", "Bohan Wang", "Yashraj Narang", "Dieter Fox", "Chuang Gan"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=VZQSrNfNHd", "code": "https://github.com/UMass-Embodied-AGI/RobotSmith", "pattern": "LLM + Perception + Generation + Action", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["o3-mini"], "non_llm_models": {"perception": [], "generation": ["Meshy"], "execution": ["Genesis", "XArm7 robot controller"]}, "summary": "The Proposer VLM generates parameterized JSON tool designs based on task/scene descriptions, iteratively refined by a Critic VLM using rendered visual feedback. Meshy synthesizes the 3D geometry. A Tool User VLM generates high-level API-based trajectories. CMA-ES then jointly optimizes tool parameters and trajectories using Genesis simulator feedback, with final deployment on an XArm7 robot."}, {"id": "7n2Kv5BUz2", "title": "MR. Video: MapReduce as an Effective Principle for Long Video Understanding", "authors": ["Ziqi Pang", "Yu-Xiong Wang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=7n2Kv5BUz2", "code": "https://github.com/ziqipang/MR-Video", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Gemini-2.0-Flash"], "generation": [], "execution": []}, "summary": "MR. Video applies a three-stage MapReduce pipeline: (1) Captioning: VLM processes video segments in parallel (Map) to generate dense captions; LLM aggregates these (Reduce) to enforce consistent character naming. (2) Question Intention Analysis: VLM analyzes segments for question relevance (Map); LLM aggregates to identify global question intent (Reduce). (3) Goal-Aware Analysis: VLM performs targeted detailed perception (Map); LLM synthesizes final answers (Reduce)."}, {"id": "dAwKePZvcN", "title": "SEEA-R1: Tree-Structured Reinforcement Fine-Tuning for Self-Evolving Embodied Agents", "authors": ["Wanxin Tian", "Shijie Zhang", "Kevin Zhang", "Xiaowei Chi", "Chun-Kai Fan", "Junyu Lu", "Yulin Luo", "Qiang Zhou", "Yiming Zhao", "Ning Liu", "Siyu Lin", "Zhiyuan Qin", "Xiaozhu Ju", "Shanghang Zhang", "Jian Tang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=dAwKePZvcN", "code": "https://github.com/AurumTian/seea-r1", "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Iterative", "coupling": "Tight", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["Qwen2.5-VL-7B-Instruct", "Qwen2.5-7B-Instruct"], "non_llm_models": {"perception": ["Multi-modal Generative Reward Model (MGRM)"], "generation": [], "execution": []}, "summary": "SEEA-R1 uses a Qwen2.5-VL LLM as the embodied policy that generates reasoning and discrete actions. A separate learned Multi-modal Generative Reward Model (MGRM) provides success/continue/failure signals from multi-modal history. During training only, deterministic MCTS explores trajectories to densify sparse rewards into step-wise process signals; at test time the agent uses fast ReAct-style single-path sampling without search."}, {"id": "ToNRHqX6xq", "title": "MIP against Agent: Malicious Image Patches Hijacking Multimodal OS Agents", "authors": ["Lukas Aichberger", "Alasdair Paren", "Guohao Li", "Philip Torr", "Yarin Gal", "Adel Bibi"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=ToNRHqX6xq", "code": null, "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Llama-3.2-11B-Vision-Instruct", "Llama-3.2-90B-Vision-Instruct", "Llama-3.2-11B-Vision"], "non_llm_models": {"perception": ["OmniParser", "GroundingDINO", "TesseractOCR"], "generation": [], "execution": ["OS APIs (Python execution engine)", "Mouse/Keyboard control APIs"]}, "summary": "The system captures screenshots and processes them through a screen parser (OmniParser or GroundingDINO+TesseractOCR) to generate Set-of-Marks (bounding boxes and textual descriptions). The annotated screenshot combined with task history is fed to Llama-3.2-Vision, which performs reasoning and outputs structured text instructions. These instructions are interpreted by API modules to execute Python code and low-level OS actions (mouse/keyboard controls), modifying the computer state."}, {"id": "7k7cubl1iL", "title": "CIDD: Collaborative Intelligence for Structure-Based Drug Design Empowered by LLMs", "authors": ["Bowen Gao", "Yanwen Huang", "Yiqiao Liu", "Wenxuan Xie", "Bowei He", "Haichuan Tan", "Wei-Ying Ma", "Ya-Qin Zhang", "Yanyan Lan"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=7k7cubl1iL", "code": "https://github.com/bowen-gao/CIDD", "pattern": "LLM + Perception + Generation", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "DeepSeek-v3", "DeepSeek-r1"], "non_llm_models": {"perception": ["AutoDock Vina", "BRICS fragmentation algorithm", "NCI detection (non-covalent interaction detection)"], "generation": ["MolCRAFT", "TargetDiff", "Pocket2Mol"], "execution": []}, "summary": "The Structure-Based Interaction Generator (SBIG) generates initial 3D molecular structures conditioned on protein pockets. The Interaction Analysis Module uses docking, fragmentation, and NCI detection to create interaction profiles. The Design Module (LLM) performs Chain-of-Thought reasoning to propose chemically-informed modifications. The Reflection Module evaluates designs and provides feedback for iterative refinement. Finally, the Selection Module ranks all candidates to output the final drug-like molecule with optimal binding affinity and chemical properties."}, {"id": "9Ook5bXnPr", "title": "TrajAgent: An LLM-Agent Framework for Trajectory Modeling via Large-and-Small Model Collaboration", "authors": ["Yuwei Du", "Jie Feng", "Jie Zhao", "Yong Li"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=9Ook5bXnPr", "code": "https://github.com/tsinghua-fib-lab/TrajAgent", "pattern": "LLM + Perception", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector", "Verifier"], "llm_models": ["GPT-4", "Qwen2", "GPT-3.5-Turbo", "GPT-4o-mini", "LLaMA3-8B", "LLaMA3-70B", "Mistral-7B-v3", "Gemma2-9B", "Gemma-2-27B", "Qwen2-72B"], "non_llm_models": {"perception": ["DeepMove", "GETNext", "TrajBERT", "GraphMM", "DeepTTE", "MulT-TTE", "FPMC", "RNN", "S2TUL", "DPLink", "LIMP", "GM-VSAE", "DSTPP", "CACSR", "DeepMM", "MainTUL", "ActSTD"], "generation": [], "execution": []}, "summary": "TrajAgent receives a natural language query and optional trajectory data. An LLM-based agent performs task understanding and planning to select appropriate datasets and specialized small deep learning models from the UniEnv library. The execution module trains the selected model, while a collaborative learning schema iteratively optimizes performance: the LLM reasons over training metrics to adjust data augmentation strategies and hyperparameters, the model re-trains, and feedback loops continue until convergence. Deterministic tools including Optuna, movingpandas, osmnx, and Python preprocessing scripts support the pipeline."}, {"id": "wOSZVnYH5w", "title": "COOPERA: Continual Open-Ended Human-Robot Assistance", "authors": ["Chenyang Ma", "Kai Lu", "Ruta Desai", "Xavier Puig", "Andrew Markham", "Niki Trigoni"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=wOSZVnYH5w", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Human_in_Loop", "uncertainty": "Cascaded_Filtering", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Llama-3.2-11B", "Llama-3.1-8B", "Mistral-7B-Instruct"], "non_llm_models": {"perception": [], "generation": [], "execution": ["Habitat 3.0 Fetch robot controller"]}, "summary": "The robot observes human video through the VLM (Llama-3.2-11B) to generate intention and task supersets. Classifiers (Mistral-7B) filter these candidates to select valid assistance tasks. The robot then executes these tasks using the Fetch controller in Habitat 3.0. A separate LLM (Llama-3.1-8B) simulates the human with memory retrieval (MiniLM) and reflection, operating over multiple days with end-of-day feedback."}, {"id": "yEq201U9AM", "title": "Policy Optimized Text-to-Image Pipeline Design", "authors": ["Uri Gadot", "Rinon Gal", "Yftah Ziser", "Gal Chechik", "Shie Mannor"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=yEq201U9AM", "code": null, "pattern": "LLM + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Router", "Coordinator"], "llm_models": ["Llama-based policy (fine-tuned LLM)"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion XL (SDXL)", "ControlNet", "LoRA adapters", "upscaling blocks (super-resolution modules)"], "execution": []}, "summary": "The system receives a text prompt and uses a fine-tuned Llama-based LLM to generate a custom-encoded ComfyUI workflow specification. This workflow orchestrates heterogeneous generative models (SDXL, ControlNet, LoRAs, upscalers) to produce the final image. During training, an ensemble of ModernBERT surrogate reward models predicts quality scores from prompt-workflow pairs, enabling GRPO-based policy optimization without costly image generation."}, {"id": "7Q1ApHpX31", "title": "Omni-R1: Reinforcement Learning for Omnimodal Reasoning via Two-System Collaboration", "authors": ["Hao Zhong", "Muzhi Zhu", "Zongze Du", "Zheng Huang", "Canyu Zhao", "Mingyu Liu", "Wen Wang", "Hao Chen", "Chunhua Shen"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=7Q1ApHpX31", "code": "https://github.com/aim-uofa/Omni-R1", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen2.5-Omni-7B"], "non_llm_models": {"perception": ["SAM2", "GroundingDINO (Fgrounding)"], "generation": [], "execution": []}, "summary": "Input video/audio and query are first processed by System 1 (Qwen2.5-Omni) at low resolution to select keyframes and reformulate the query into local instructions. These are passed to System 2, where a grounding model predicts bounding boxes on high-resolution keyframes, and SAM2 generates pixel-level segmentation masks temporally propagated across the video."}, {"id": "x1wZoyS0rC", "title": "SceneWeaver: All-in-One 3D Scene Synthesis with an Extensible and Self-Reflective Agent", "authors": ["Yandan Yang", "Baoxiong Jia", "Shujie Zhang", "Siyuan Huang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=x1wZoyS0rC", "code": "https://github.com/Scene-Weaver/SceneWeaver", "pattern": "LLM + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["GPT-4"], "non_llm_models": {"perception": [], "generation": ["ATISS", "DiffuScene", "PhyScene", "Architect", "ACDC"], "execution": []}, "summary": "A GPT-4 planner iteratively selects from modular 3D scene generation tools—data-driven initializers (ATISS, DiffuScene, PhyScene) and 2D-guided implementers (Architect, ACDC)—using standardized tool cards. The chosen generation model produces or modifies a 3D layout, which is then processed by a deterministic physics-aware executor (built on Blender and Infinigen) to resolve collisions and boundary violations. An MLLM reflection module evaluates the updated scene and feeds structured scores back to the planner for further refinement."}, {"id": "OFz4VDn0SO", "title": "Tool-Augmented Spatiotemporal Reasoning for Streamlining Video Question Answering Task", "authors": ["Sunqi Fan", "Jiashuo Cui", "Meng-Hao Guo", "Shuojin Yang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=OFz4VDn0SO", "code": "https://github.com/fansunqi/VideoTool", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator"], "llm_models": ["GPT-4o", "GPT-3.5-turbo"], "non_llm_models": {"perception": ["YOLO", "Grounding DINO", "BLIP", "LLaVA", "QwenVL-2.5", "Frame Selector", "Object Detector", "OCR-tool", "Object Tracker", "Temporal Grounding Tool", "Image Captioner", "Semantic Segmentation", "Action Localization", "Patch Zoomer", "Video Trimmer"], "generation": [], "execution": []}, "summary": "GPT-4o initializes a Visible Frame Dictionary with sparsely sampled video frames. It then iteratively alternates between temporal tools (e.g., Frame Selector, Video Trimmer) to narrow the temporal scope and spatial tools (e.g., YOLO, Grounding DINO, BLIP for detection/captioning) to extract visual information, progressively localizing the 3D RoI. Once the LLM determines sufficient information exists in the dictionary, it generates the final text answer via summarization."}, {"id": "PdRf0O7baQ", "title": "Scaffolding Dexterous Manipulation with Vision-Language Models", "authors": ["Vincent de Bakker", "Joey Hejna", "Tyler Ga Wei Lum", "Onur Celik", "Aleksandar Taranovic", "Denis Blessing", "Gerhard Neumann", "Jeannette Bohg", "Dorsa Sadigh"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=PdRf0O7baQ", "code": null, "pattern": "LLM + Perception + Action", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["Gemini 2.5 Flash Thinking"], "non_llm_models": {"perception": ["keypoint tracking model", "pose estimators"], "generation": [], "execution": ["residual RL policy (PPO)"]}, "summary": "Given a language instruction and RGB image, the VLM first detects semantic keypoints and generates coarse 3D trajectories (scaffolds) for hand and object motion. These trajectories condition a low-level residual RL policy that outputs dexterous finger and wrist actions. During execution, a keypoint tracking model provides closed-loop feedback to the RL policy to track the planned trajectories, enabling robust manipulation without human demonstrations."}, {"id": "08mjueZ0Iq", "title": "VLMLight: Safety-Critical Traffic Signal Control via Vision-Language Meta-Control and Dual-Branch Reasoning Architecture", "authors": ["Maonan Wang", "Yirong Chen", "Aoyu Pang", "Yuxin Cai", "Chung Shue Chen", "Yuheng KAN", "Man On Pun"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=08mjueZ0Iq", "code": null, "pattern": "LLM + Perception + Action", "domain": "Autonomous_Driving", "flow": "DAG", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator"], "llm_models": ["Qwen2.5-72B"], "non_llm_models": {"perception": ["Qwen2.5-VL-32B"], "generation": [], "execution": ["RL Policy (PPO)", "Transformer-based policy network"]}, "summary": "Multi-view intersection images are processed by Qwen2.5-VL-32B to generate textual traffic scene descriptions. Qwen2.5-72B acts as a meta-controller (AgentModeSelector) that routes to either a fast RL policy for routine traffic or a deliberative chain of LLM agents (AgentPhase, AgentPlan, AgentCheck) for safety-critical scenarios. The selected branch outputs the final traffic signal phase decision, with the LLM branch performing structured reasoning over phase descriptions and verifying rule compliance."}, {"id": "yTFJmGFsEy", "title": "Reviving DSP for Advanced Theorem Proving in the Era of Reasoning Models", "authors": ["Chenrui Cao", "Liangcheng Song", "Zenan Li", "Xinyi Le", "Xian Zhang", "HUI XUE", "Fan Yang"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=yTFJmGFsEy", "code": null, "pattern": "LLM + Generation", "domain": "Scientific_Discovery", "flow": "Sequential", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["QwQ-32B", "DeepSeek-R1-671B", "DeepSeek-V3-0324", "GPT-4o"], "non_llm_models": {"perception": [], "generation": ["BFS-Prover-7B", "InternLM2.5-StepProver"], "execution": ["Aesop"]}, "summary": "The pipeline takes a formal theorem statement, uses a reasoning model (QwQ-32B or DeepSeek-R1) to generate a concise natural language draft, which is autoformalized by DeepSeek-V3 into a Lean 4 sketch with hypothesis annotations. Error line masking repairs syntactic errors, then BFS-Prover integrated with Aesop symbolic search generates tactics to prove subgoals, producing a verified formal proof."}, {"id": "D1Iw4Unvfc", "title": "ReAgent-V: A Reward-Driven Multi-Agent Framework for Video Understanding", "authors": ["Yiyang Zhou", "Yangfan He", "Yaofeng Su", "Siwei Han", "Joel Jang", "Gedas Bertasius", "Mohit Bansal", "Huaxiu Yao"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=D1Iw4Unvfc", "code": "https://github.com/aiming-lab/ReAgent-V", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["LLaVA-Video-7B", "LLaVA-Video-72B", "Qwen2-VL-7B", "Qwen2.5-VL-7B", "Qwen2.5-VL-72B"], "non_llm_models": {"perception": ["CLIP", "OCR", "object detection", "video captioning", "ASR"], "generation": [], "execution": []}, "summary": "Video frames are first selected using entropy-calibrated CLIP scoring. The target LLM agent dynamically selects perception tools (OCR, detection, captioning, ASR) to extract information and generates an initial answer. A critic LLM agent evaluates this answer, generates reward scores and sub-questions, prompting the target agent to reflect from three perspectives (conservative, neutral, aggressive) to produce the final refined answer."}, {"id": "IHX5V6zQpY", "title": "LayerCraft: Enhancing Text-to-Image Generation with CoT Reasoning and Layered Object Integration", "authors": ["Yuyao Zhang", "Jinghao Li", "Yu-Wing Tai"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=IHX5V6zQpY", "code": "https://github.com/PeterYYZhang/LayerCraft", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Grounding DINO", "SAM 2"], "generation": ["FLUX.1-dev", "OIN (Object Integration Network)"], "execution": []}, "summary": "User input is processed by the LayerCraft Coordinator which enriches prompts via Chain-of-Thought reasoning. ChainArchitect generates structured 3D-aware layouts (bounding boxes, object relationships) using CoT reasoning. The Coordinator dispatches to OIN, which uses FLUX.1-dev with dual LoRA adapters to inpaint objects into backgrounds. The Coordinator verifies consistency and iteratively refines outputs through multiple agent interaction rounds until completion."}, {"id": "skS03tzYNw", "title": "ShapeCraft: LLM Agents for Structured, Textured and Interactive 3D Modeling", "authors": ["Shuyuan Zhang", "Chenhan Jiang", "Zuoou Li", "Jiankang Deng"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=skS03tzYNw", "code": "https://github.com/SanBingYouYong/shapecraft", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Cross_Model_Feedback", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["Qwen3-235B-A22B"], "non_llm_models": {"perception": ["Qwen-VL-Max"], "generation": ["Text-to-image diffusion model (SDS)"], "execution": []}, "summary": "ShapeCraft uses a Parser agent (LLM) to decompose text into a Graph-based Procedural Shape (GPS) representation. A Coder agent (LLM) generates Blender Python code snippets and bounding volumes for each node, with multi-path sampling and iterative refinement guided by an Evaluator agent (Qwen-VL-Max) that assesses rendered images. The procedural execution module Ω (deterministic Blender API executor) assembles the final mesh. A component-aware Score Distillation Sampling (SDS) module uses a pretrained 2D diffusion model to optimize a learnable BRDF texture field."}, {"id": "NKcwN347H7", "title": "InfantAgent-Next: A Multimodal Generalist Agent for Automated Computer Interaction", "authors": ["Bin Lei", "Weitai Kang", "Zijian Zhang", "Winson Chen", "Xi Xie", "Shan Zuo", "Mimi Xie", "Ali Payani", "Mingyi Hong", "Yan Yan", "Caiwen Ding"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=NKcwN347H7", "code": "https://github.com/bin123apple/InfantAgent", "pattern": "LLM + Perception + Action", "domain": "GUI_Web_Agent", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Claude-3.7-Sonnet", "GPT-4o", "DeepSeek-V3-0324"], "non_llm_models": {"perception": ["UI-TARS-1.5-7B", "gpt-4o-audio-preview"], "generation": [], "execution": ["DeepSeek-V3-0324"]}, "summary": "User requests trigger a Planner (Claude-3.7-Sonnet) to generate tasks, which are routed by a Tool Selector to appropriate specialist models: UI-TARS-1.5-7B for visual grounding (with iterative region cropping), gpt-4o-audio-preview for audio parsing, and DeepSeek-V3-0324 for file editing. Observations are parsed with special tags, stored in a unified memory cache, and fed back to the Planner in a loop until task completion."}, {"id": "IKxKs3rF9V", "title": "4KAgent: Agentic Any Image to 4K Super-Resolution", "authors": ["Yushen Zuo", "Qi Zheng", "Mingyang Wu", "Xinrui Jiang", "Renjie Li", "Jian Wang", "Yide Zhang", "Gengchen Mai", "Lihong Wang", "James Zou", "Xiaoyu Wang", "Ming-Hsuan Yang", "Zhengzhong Tu"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=IKxKs3rF9V", "code": "https://github.com/taco-group/4KAgent", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Llama-vision"], "non_llm_models": {"perception": ["CLIPIQA", "TOPIQ", "MUSIQ", "NIQE", "HPSv2", "ArcFace", "CLIB-FIQA"], "generation": ["Task-specific restoration networks", "Face restoration models"], "execution": []}, "summary": "The input image is first analyzed by the Perception Agent, which uses a VLM (Llama-vision) and IQA experts to assess degradations and generate a restoration plan. The Restoration Agent then executes this plan iteratively: for each step, it runs multiple restoration models in parallel (Q-MoE), selects the optimal output based on quality metrics (HPSv2, NIQE, MUSIQ), and triggers a rollback if quality is insufficient. A dedicated Face Restoration Pipeline enhances facial details using ArcFace and CLIB-FIQA before producing the final 4K image."}, {"id": "Qku7g56aWf", "title": "Direct Numerical Layout Generation for 3D Indoor Scene Synthesis via Spatial Reasoning", "authors": ["Xingjian Ran", "Yixuan Li", "Linning Xu", "Mulin Yu", "Bo Dai"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=Qku7g56aWf", "code": "https://github.com/rxjfighting/DirectLayout", "pattern": "LLM + Perception + Generation", "domain": "3D_Generation", "flow": "Iterative", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "Qwen2.5-32B", "Qwen2.5-72B", "QwQ-32B", "o1"], "non_llm_models": {"perception": ["Qwen2.5-VL-72B", "GPT-4o"], "generation": ["3D object generation model"], "execution": []}, "summary": "Text prompts are processed by a fine-tuned BEV Layout Generator (LLM) with chain-of-thought reasoning to create 2D layouts, which are lifted to 3D by a 3D Layout Generator (LLM) that also produces object generation prompts. A 3D object generation model creates assets, which are composited and rendered. A VLM (Spatial Evaluator) and reasoning LLM (Quantitative Evaluator) assess the rendered scene for physical and semantic violations, feeding back corrections to refine the layout iteratively until convergence."}, {"id": "N5vXT7AGuo", "title": "AffordBot: 3D Fine-grained Embodied Reasoning via Multimodal Large Language Models", "authors": ["Xinyi Wang", "Xun Yang", "Yanlong Xu", "Yuchen Wu", "Zhen Li", "Na Zhao"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=N5vXT7AGuo", "code": "https://github.com/hannahwxy/AffordBot", "pattern": "LLM + Perception", "domain": "Robot_Manipulation", "flow": "Sequential", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["Qwen2.5-VL-72B", "GPT-4o", "LLaVA-v1.6-34B"], "non_llm_models": {"perception": ["Mask3D"], "generation": [], "execution": []}, "summary": "The pipeline processes 3D point cloud scenes through Mask3D to segment affordance elements and generate geometry-semantic descriptors. These 3D elements are projected onto rendered surround-view images with adaptive labeling. The MLLM then performs chain-of-thought reasoning through three sequential steps: active view selection, affordance grounding, and motion estimation, ultimately outputting structured triplets (3D mask, motion type, motion direction) for the given instruction."}, {"id": "To7Rs2wsTd", "title": "VideoLucy: Deep Memory Backtracking for Long Video Understanding", "authors": ["Jialong Zuo", "Yongtai Deng", "Lingdong Kong", "Jingkang Yang", "Rui Jin", "Yiwei Zhang", "Nong Sang", "Liang Pan", "Ziwei Liu", "Changxin Gao"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=To7Rs2wsTd", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["DeepSeek-R1"], "non_llm_models": {"perception": ["Qwen-2.5-VL-7B"], "generation": [], "execution": []}, "summary": "The pipeline begins with DeepSeek-R1 (LLM) initializing sparse coarse memory and localizing relevant time periods. Qwen-2.5-VL-7B (MLLM) serves as the Captioning Agent to generate hierarchical text descriptions (coarse/fine/ultra-fine) for specified video clips. DeepSeek-R1 integrates these captions, verifies answer confidence through reasoning, and iteratively directs the MLLM to explore deeper memories via backtracking until sufficient information is gathered to generate a confident text answer."}, {"id": "jvq8nzOUp8", "title": "Safe + Safe = Unsafe? Exploring How Safe Images Can Be Exploited to Jailbreak Large Vision-Language Models", "authors": ["Chenhang Cui", "Gelei Deng", "An Zhang", "Jingnan Zheng", "Yicong Li", "Lianli Gao", "Tianwei Zhang", "Tat-Seng Chua"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=jvq8nzOUp8", "code": "https://github.com/gzcch/Safety_Snowball_Agent", "pattern": "LLM + Perception + Generation", "domain": "Benchmark_Evaluation", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["CLIP"], "generation": ["Stable Diffusion", "Google Custom Search API (image retrieval)"], "execution": []}, "summary": "Input images are first analyzed by GPT-4o for harmful intent recognition. Based on the identified topic, keywords are generated and used to retrieve or generate candidate jailbreak images via Stable Diffusion or search APIs. CLIP filters these candidates to select the best match. The selected jailbreak image is combined with the original image and a crafted prompt to query the target LVLM, producing an initial response that is then used in a follow-up prompt to induce progressively harmful outputs through iterative snowballing."}, {"id": "wTBhWbCRpN", "title": "Multi-scale Temporal Prediction via Incremental Generation and Multi-agent Collaboration", "authors": ["Zhitao Zeng", "Guojian Yuan", "Junyuan Mao", "Yuxuan Wang", "Xiaoshuang Jia", "Yueming Jin"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=wTBhWbCRpN", "code": "https://github.com/jinlab-imvr/MSTP", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Cross_Model_Feedback", "uncertainty": "LLM_Verification", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-VL-7B-Instruct"], "non_llm_models": {"perception": [], "generation": ["Stable Diffusion"], "execution": []}, "summary": "The IG-MC framework operates through an alternating iterative process: starting from the current state and image, the State Transition Controller (VLM-based agent) determines the transition level, triggering hierarchical LLM-based State Prediction agents to predict the next state. The VG module (Stable Diffusion) then generates a visual preview conditioned on this predicted state. This state-image pair feeds back into the system for subsequent predictions at expanding temporal scales, creating a closed-loop incremental generation process."}, {"id": "oQYq9L1NVT", "title": "Deep Video Discovery: Agentic Search with Tool Use for Long-form Video Understanding", "authors": ["Xiaoyi Zhang", "Zhaoyang Jia", "Zongyu Guo", "Jiahao Li", "Bin Li", "Houqiang Li", "Yan Lu"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=oQYq9L1NVT", "code": "https://github.com/microsoft/DeepVideoDiscovery", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["OpenAI o3"], "non_llm_models": {"perception": ["GPT-4.1", "WhisperX", "embedding model"], "generation": [], "execution": []}, "summary": "In the offline stage, GPT-4.1 extracts captions and subject registries from video frames while WhisperX transcribes audio, building a multi-granular database with embeddings and indexed frames. During inference, OpenAI o3 orchestrates an iterative search process: reasoning over the user query and dynamically selecting from three search tools (Global Browse, Clip Search, Frame Inspect) to retrieve relevant information, accumulating evidence through multiple rounds until producing a final text answer."}, {"id": "30iBKSQMXn", "title": "Retro-R1: LLM-based Agentic Retrosynthesis", "authors": ["Wei Liu", "Jiangtao Feng", "Hongli Yu", "Yuxuan Song", "Yuqiang Li", "Shufei Zhang", "LEI BAI", "Wei-Ying Ma", "Hao Zhou"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=30iBKSQMXn", "code": "https://github.com/GenSI-THUAIR/Retro-R1", "pattern": "LLM + Perception", "domain": "Scientific_Discovery", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["Qwen2.5-7B-Instruct-1M"], "non_llm_models": {"perception": ["template-based MLP (single-step retrosynthesis model)"], "generation": [], "execution": []}, "summary": "RETRO-R1 trains a Qwen2.5-7B-Instruct agent with PPO to iteratively decompose target molecules into available precursors. The agent queries a learned template-based MLP single-step model via CALL actions to obtain reaction candidates, then uses SELECT actions to update the molecular state. Deterministic environment modules handle action validation, building-block lookup, state updates, and final extraction of the shortest route from an AND-OR graph."}, {"id": "qE3knKF1rz", "title": "PANDA: Towards Generalist Video Anomaly Detection via Agentic AI Engineer", "authors": ["Zhiwei Yang", "Chen Gao", "Mike Zheng Shou"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=qE3knKF1rz", "code": "https://github.com/showlab/PANDA", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["Gemini 2.0 Flash"], "non_llm_models": {"perception": ["Qwen2.5VL-7B", "Object Detection"], "generation": ["Image Super-resolution", "Image Denoise", "Image Deblur"], "execution": []}, "summary": "Video input and user query are first processed by Qwen2.5VL-7B for environmental perception. Gemini 2.0 Flash performs RAG-based strategy planning using an anomaly knowledge base. Qwen2.5VL-7B then conducts goal-driven heuristic reasoning with chain-of-memory. If the result is uncertain (Insufficient), Gemini 2.0 Flash reflects and selects visual enhancement tools (super-resolution, denoise, deblur) or retrieval tools to augment the input. Qwen2.5VL-7B re-reasons with the enhanced frames for up to 3 iterations until producing a final anomaly status, confidence score, and explanation."}, {"id": "nfxTpNiSMH", "title": "SPAZER: Spatial-Semantic Progressive Reasoning Agent for Zero-shot 3D Visual Grounding", "authors": ["Zhao Jin", "Rong-Cheng Tu", "Jingyi Liao", "Wenhao Sun", "Xiao Luo", "Shunyu Liu", "Dacheng Tao"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=nfxTpNiSMH", "code": "https://github.com/JZ-9962/SPAZER", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Star", "coupling": "Loose", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Translator"], "llm_models": ["GPT-4o"], "non_llm_models": {"perception": ["Mask3D-based 3D detection/segmentation model", "2D perception models", "3D rendering tools"], "generation": [], "execution": []}, "summary": "GPT-4o first selects the optimal viewpoint from multi-view 3D renderings. A Mask3D-based 3D detector then extracts object proposals, which GPT-4o screens coarsely using retrieval-augmented anchor filtering (with confidence-based fallback). Relevant 2D camera images are retrieved via 3D-to-2D mapping for the top-k candidates, and GPT-4o performs joint 3D-2D decision-making to output the final target bounding box."}, {"id": "MdqirFiD38", "title": "Red-Teaming Text-to-Image Systems by Rule-based Preference Modeling", "authors": ["Yichuan Cao", "Yibo Miao", "Xiao-Shan Gao", "Yinpeng Dong"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=MdqirFiD38", "code": "https://github.com/caosip/RPG-RT", "pattern": "LLM + Perception + Generation", "domain": "Image_Generation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Reflector", "Coordinator"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["CLIP", "NudeNet", "GuardT2I", "Q16", "OWL-ViT", "CASCo", "celebrity classifier", "Scoring model"], "generation": ["Stable Diffusion", "DALL-E 3", "SDXL", "Open-Sora"], "execution": []}, "summary": "Vicuna-7B generates modified prompts which are queried against black-box T2I systems (Stable Diffusion, DALL-E 3, etc.). Generated images are evaluated by detection models (NudeNet, Q16, etc.) and a scoring model that transforms CLIP embeddings to assess harmfulness and semantic similarity. Rule-based preference modeling constructs partial orders from this feedback, which is used to fine-tune the LLM via DPO with LoRA. This iterative cycle continues until convergence, progressively adapting the LLM to bypass unknown defense mechanisms."}, {"id": "LyH2ISbOV8", "title": "Automated Detection of Visual Attribute Reliance with a Self-Reflective Agent", "authors": ["Christy Li", "Josep Lopez Camuñas", "Jake Thomas Touchet", "Jacob Andreas", "Agata Lapedriza", "Antonio Torralba", "Tamar Rott Shaham"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=LyH2ISbOV8", "code": "https://github.com/christykl/saia", "pattern": "LLM + Perception + Generation", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["Claude-Sonnet-3.5"], "non_llm_models": {"perception": ["CLIP", "YOLOv8", "Grounding DINO", "SigLIP", "FairFace"], "generation": ["Flux.1-dev"], "execution": []}, "summary": "The user specifies a target vision model and concept. Claude generates hypotheses about visual attributes the model may rely on. Flux.1-dev generates synthetic test images based on these hypotheses. Perception models (CLIP, YOLO, etc.) evaluate the images to measure model responses. Claude analyzes results and draws conclusions. A separate self-evaluation phase generates validation images to test the conclusion's predictiveness; if inconsistent, Claude reflects and initiates a new hypothesis-testing cycle. The final output is a natural language description of the detected attribute reliance."}, {"id": "cZVYswQQMt", "title": "ActiveVOO: Value of Observation Guided Active Knowledge Acquisition for Open-World Embodied Lifted Regression Planning", "authors": ["Xiaotian Liu", "Ali Pesaranghader", "Jaehong Kim", "Tanmana Sadhu", "Hyejeong Jeon", "Scott Sanner"], "venue": "NeurIPS", "year": 2025, "url": "https://openreview.net/pdf?id=cZVYswQQMt", "code": null, "pattern": "LLM + Perception + Action", "domain": "Embodied_Navigation", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator"], "llm_models": ["GPT-4o", "GPT-3.5"], "non_llm_models": {"perception": ["LLaVA-13B"], "generation": [], "execution": ["ALFWorld agent controller"]}, "summary": "The agent parses natural language instructions into symbolic goals, uses lifted regression to generate subgoals and extract object descriptions, calculates Value of Observation (VOO) scores using LLM commonsense beliefs to prioritize sensing targets, navigates to selected locations and queries VLMs to detect objects in visual observations, updates its symbolic knowledge base, and iterates this active acquisition loop until the plan can be grounded and executed by the ALFWorld controller."}, {"id": "71b21339db41", "title": "Empowering Large Language Models: Tool Learning for Real-World Interaction", "authors": ["Hongru Wang 0003", "Yujia Qin", "Yankai Lin 0001", "Jeff Z. Pan", "Kam-Fai Wong"], "venue": "SIGIR", "year": 2024, "url": "https://doi.org/10.1145/3626772.3661381", "code": null, "pattern": "LLM + Perception + Action", "domain": "Multi_Domain", "flow": "Star", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Reflector"], "llm_models": ["General LLMs", "Multi-modal LLMs"], "non_llm_models": {"perception": ["Perceiver modules", "Multi-modal encoders"], "generation": [], "execution": ["Physical robots", "GUI automation tools", "Program executors", "Search engines", "Calculators", "External APIs"]}, "summary": "The Controller LLM receives a user query and plans a sequence of tool executions. It routes commands to appropriate execution models (robots, APIs, programs) which interact with the environment. A Perceiver observes the resulting environment state and execution outcomes, feeding this information back to the LLM to iteratively refine the plan and generate the final integrated response."}, {"id": "aefd63fac0e1", "title": "GlFoMR: A Glance-then-Focus Multimodal Reasoning Framework for Diagram Question Answering", "authors": ["Yaxian Wang", "Bifan Wei", "Jun Liu 0002", "Lingling Zhang 0005", "Shuting He", "Jun Li", "Qika Lin"], "venue": "SIGIR", "year": 2025, "url": "https://doi.org/10.1145/3726302.3729990", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Router"], "llm_models": ["GPT-4", "Gemini-1.5-flash", "GPT-4o-mini", "GPT-3.5"], "non_llm_models": {"perception": ["SAM (Segment Anything Model)", "YOLOv3", "CLIP"], "generation": [], "execution": []}, "summary": "Diagrams are first parsed by SAM/YOLOv3 into hierarchical visual regions (single objects, object groups, whole diagram). In the Glance-Plan stage, an MLLM decomposes the question into sub-goals (knowledge extraction, visual perception, visual reasoning). For each sub-goal, CLIP retrieves the top-k most relevant visual regions, which the MLLM uses in the Focus-Reason stage to generate detailed clues. Finally, the Summarize-Answer stage aggregates all clues to produce the final rationale and answer."}, {"id": "553203efe3b0", "title": "Insight Agents: An LLM-Based Multi-Agent System for Data Insights", "authors": ["Jincheng Bai", "Zhenyu Zhang 0021", "Jennifer Zhang", "Jason Zhu"], "venue": "SIGIR", "year": 2025, "url": "https://doi.org/10.1145/3726302.3731959", "code": null, "pattern": "LLM + Perception + Action", "domain": "Retrieval_Augmented", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Verifier"], "llm_models": ["Claude-3 (anthropic.claude-3-sonnet-20240229-v1:0)"], "non_llm_models": {"perception": ["BERT-based classifier (bge-small-en-v1.5)", "Auto-encoder OOD detector"], "generation": [], "execution": ["Data Workflow Executor (internal data APIs)"]}, "summary": "User queries are processed by a Manager Agent that performs parallel OOD detection (Auto-encoder) and agent routing (BERT classifier). Valid queries are augmented and dispatched to either a Data Presenter or Insight Generator worker. The worker uses Claude-3 to decompose the query, select appropriate data APIs, and generate execution plans. The Data Workflow Executor retrieves and aggregates tabular data via internal APIs, and Claude-3 generates the final insights using few-shot prompting with domain knowledge, followed by guardrail checks."}, {"id": "0fdd909e8e4d", "title": "CapAlign: Improving Cross Modal Alignment via Informative Captioning for Harmful Meme Detection", "authors": ["Junhui Ji", "Xuanrui Lin", "Usman Naseem"], "venue": "WWW", "year": 2024, "url": "https://doi.org/10.1145/3589334.3648146", "code": "https://github.com/thunlp/OpenPrompt", "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Translator"], "llm_models": ["ChatGPT"], "non_llm_models": {"perception": ["BLIP-2", "CLIP"], "generation": [], "execution": []}, "summary": "ChatGPT generates informative questions based on task instructions and dialogue history, BLIP-2 answers these questions about the meme image iteratively through multi-turn interaction, ChatGPT summarizes the dialogue into a detailed caption and creates a meme abstract combining visual and textual content, CLIP extracts top-k visual attributes from the image, and FLAN-T5 performs harmfulness classification using prompt-based learning on the combined textual inputs."}, {"id": "9e5713008315", "title": "ChartCitor: Answer Citations for ChartQA via Multi-Agent LLM Retrieval", "authors": ["Kanika Goswami", "Puneet Mathur", "Ryan A. Rossi", "Franck Dernoncourt"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3716886", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "Confidence_Threshold", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector", "Translator"], "llm_models": ["GPT-4o", "GPT-4V"], "non_llm_models": {"perception": ["DETR", "GPT-4V"], "generation": [], "execution": []}, "summary": "Input chart images are processed by GPT-4V to extract HTML tables (with self-reflection verification). GPT-4o reformulates answers into atomic facts and generates contextual captions for table rows/columns/cells. An LLM pre-filtering agent scores and filters rows/columns by relevance, followed by RankGPT re-ranking to select supporting cells. Finally, DETR detects chart elements and GPT-4V localizes the selected cells to bounding boxes using set-of-marks prompting, outputting the answer with visual citations."}, {"id": "18809e4b5d37", "title": "RTBAgent: A LLM-based Agent System for Real-Time Bidding", "authors": ["Leng Cai", "Junxuan He", "Yikai Li", "Junjie Liang", "Yuanping Lin", "Ziming Quan", "Yawen Zeng", "Jin Xu 0014"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3715259", "code": "https://github.com/CaiLeng/RTBAgent", "pattern": "LLM + Perception", "domain": "Other", "flow": "Sequential", "coupling": "Loose", "feedback": "Self_Correction", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Reflector"], "llm_models": ["GPT-4", "Llama-3-8B-Instruct"], "non_llm_models": {"perception": ["Factorization Machines (FM)"], "generation": [], "execution": []}, "summary": "RTBAgent uses an LLM to orchestrate real-time bidding via a two-step decision process (insight reasoning then action making). It calls a learned Factorization Machines (FM) model to predict CTR and uses deterministic expert strategies (MCPC, LIN, LP) to obtain a base bidding factor. The LLM retrieves summarized environment, bidding, and reflection memories to output a bid-price adjustment factor, which is applied in the RTB environment."}, {"id": "126afef305fa", "title": "SupportPlay: A Multi-Agent Role-Playing System for Personalized and Sustained Multimodal Emotional Support Conversation", "authors": ["Geng Tu", "Bingbing Wang", "Erik Cambria", "Wenjie Li 0002", "Ruifeng Xu 0001"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3715200", "code": "https://github.com/HITSZ-HLT/Supportplay", "pattern": "LLM + Generation", "domain": "Audio_Speech", "flow": "Sequential", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GPT"], "non_llm_models": {"perception": [], "generation": ["StyleTTS2", "EAT (Emotion-Aware Talking face)"], "execution": []}, "summary": "User text input is processed by a GPT-powered supporter agent that retrieves personalized memories and generates a meta-response with emotional attributes. This meta-response is fed sequentially to StyleTTS2 for speech synthesis, and the resulting audio along with a reference image is processed by EAT to generate a talking-face video. The final output combines text, speech, and video for the user."}, {"id": "869d2a58f557", "title": "Towards Multimodal Empathetic Response Generation: A Rich Text-Speech-Vision Avatar-based Benchmark", "authors": ["Han Zhang 0035", "Zixiang Meng", "Meng Luo 0010", "Hong Han 0001", "Lizi Liao", "Erik Cambria", "Hao Fei 0001"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3696410.3714739", "code": "https://github.com/AvaMERG/AvaMERG-Pipeline", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Star", "coupling": "Medium", "feedback": "None", "uncertainty": "None", "interface": "Continuous", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector", "Translator"], "llm_models": ["Vicuna-7B"], "non_llm_models": {"perception": ["HuBERT", "CLIP ViT-L/14"], "generation": ["StyleTTS2", "DreamTalk"], "execution": []}, "summary": "Multimodal user queries (text, speech, video) are encoded by HuBERT and CLIP, aligned to the LLM's semantic space via projections, and processed by Vicuna using Chain-of-Empathy reasoning. The LLM outputs text tokens and multimodal signal features that flow through Content Synchronizer and Style Disentangler modules to ensure content and style consistency, then drive StyleTTS2 for speech synthesis and DreamTalk for talking-face video generation, producing synchronized avatar-based responses."}, {"id": "1f0103dd5ba6", "title": "Enhancing Product Search Interfaces with Sketch-Guided Diffusion and Language Agents", "authors": ["Edward Sun"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3717853", "code": "https://github.com/marqo-ai/marqo-ecommerce-", "pattern": "LLM + Perception + Generation", "domain": "Retrieval_Augmented", "flow": "Star", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "None", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Router", "Coordinator", "Translator"], "llm_models": ["GPT-4o-mini"], "non_llm_models": {"perception": ["CLIP"], "generation": ["Stable Diffusion XL", "T2I-Adapter"], "execution": []}, "summary": "User provides a sketch and text query to the GPT-4o-mini agent, which refines the text condition and calls Stable Diffusion XL with T2I-Adapter to generate a query image. The generated image is encoded by CLIP to perform similarity search over a pre-encoded product database. The agent then ranks retrieval results, updates its memory with user feedback, and provides personalized recommendations through an interactive chat interface."}, {"id": "336fd3d6e95e", "title": "ColaCare: Enhancing Electronic Health Record Modeling through Large Language Model-Driven Multi-Agent Collaboration", "authors": ["Zixiang Wang", "Yinghao Zhu", "Huiya Zhao", "Xiaochen Zheng", "Dehao Sui", "Tianlong Wang", "Wen Tang 0001", "Yasha Wang", "Ewen M. Harrison", "Chengwei Pan", "Junyi Gao", "Liantao Ma"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3696410.3714877", "code": null, "pattern": "LLM + Perception", "domain": "Medical_Analysis", "flow": "Star", "coupling": "Medium", "feedback": "Iterative_Refinement", "uncertainty": "Voting_Ensemble", "interface": "Mixed", "llm_roles": ["Planner", "Reasoner", "Verifier", "Coordinator", "Reflector"], "llm_models": ["DeepSeek-V2.5", "GPT-4o"], "non_llm_models": {"perception": ["AdaCare", "ConCare", "RETAIN", "MedCPT"], "generation": [], "execution": []}, "summary": "Structured EHR time-series data is processed by three expert models (AdaCare, ConCare, RETAIN) to extract features, prediction logits, and SHAP importance weights. MedCPT retrieves relevant medical guidelines. Each DoctorAgent generates an initial review based on one expert model's output and retrieved knowledge. The MetaAgent synthesizes these into a preliminary report, then orchestrates iterative rounds of debate where DoctorAgents verify and critique the report. Once consensus is reached, the final report is embedded by GatorTron and fused with EHR embeddings via an MLP to produce the final mortality/readmission prediction."}, {"id": "194d2cb33f69", "title": "Luoling: An Immersive Cross-Modal Interactive Poem Creation Factory through Multi-Agent Collaboration", "authors": ["Tao Tan 0005", "Quan Tu", "Songhao Wu", "Hongda Sun 0001", "Chuanqi Cheng", "Weikai Xu", "Rui Yan 0001"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3715184", "code": "https://github.com/chinese-poetry/chinese-poetry", "pattern": "LLM + Perception + Generation", "domain": "Multi_Domain", "flow": "Iterative", "coupling": "Loose", "feedback": "Human_in_Loop", "uncertainty": "LLM_Verification", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Router", "Verifier", "Coordinator", "Reflector"], "llm_models": ["GLM-4", "GPT-3.5", "Qwen1.5-7B-Chat"], "non_llm_models": {"perception": ["Qwen-VL-chat"], "generation": ["style-based TTS"], "execution": []}, "summary": "User provides image, text, and attributes. Qwen-VL-chat generates an image description (perception). GLM-4 engages in interactive dialogue with the user to refine intent (human-in-the-loop). A Poem Writer Agent generates an initial draft, which is iteratively refined by an Adviser Agent providing stylistic feedback, and verified by a Rhyme Checker Agent. Finally, style-based TTS synthesizes the finalized poem into audio."}, {"id": "59bae537cf3a", "title": "Multi-Model Workflows for Advanced Visual Understanding", "authors": ["Arun George Zachariah", "Varun Praveen", "Samuel Ochoa", "Parthasarathy Sriram"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3701716.3715188", "code": "https://github.com/NVIDIA/Multi-Model-Workflows", "pattern": "LLM + Perception + Action", "domain": "Visual_QA_Reasoning", "flow": "Sequential", "coupling": "Loose", "feedback": "None", "uncertainty": "None", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Router"], "llm_models": ["Llama Instruct", "Code Llama"], "non_llm_models": {"perception": ["OvSGTR", "Grounding DINO", "NVIDIA TAO models (object detection, segmentation)", "OCR models", "NV-Embed"], "generation": [], "execution": ["Python script execution engine"]}, "summary": "User provides image/video and text query. OvSGTR extracts a scene graph representing objects and relationships. A Model Multiplexer uses RAG (NV-Embed + vector DB) to dynamically select relevant CV models. An Instructional LLM (Llama) and Code Llama generate a Python script tailored to the query. The script is executed to run the selected perception models, perform analysis, and produce a textual answer with annotated visualizations."}, {"id": "63b351eae773", "title": "Ask, Acquire, Understand: A Multimodal Agent-based Framework for Social Abuse Detection in Memes", "authors": ["Xuanrui Lin", "Chao Jia", "Junhui Ji", "Hui Han", "Usman Naseem"], "venue": "WWW", "year": 2025, "url": "https://doi.org/10.1145/3696410.3714895", "code": null, "pattern": "LLM + Perception", "domain": "Visual_QA_Reasoning", "flow": "Iterative", "coupling": "Loose", "feedback": "Iterative_Refinement", "uncertainty": "Retry_Fallback", "interface": "Symbolic", "llm_roles": ["Planner", "Reasoner", "Coordinator", "Reflector"], "llm_models": ["GPT-3.5-Turbo"], "non_llm_models": {"perception": ["LLaVA-1.6-13B", "CogVLM"], "generation": [], "execution": []}, "summary": "GPT-3.5 agents (Internet User and Supervisor) engage in multi-round dialogue to generate targeted questions about meme images, which are dispatched to LLaVA-1.6 (vision expert) via API calls with formatted tags. The acquired QA history and meme text are then processed by a GPT-3.5 summary module using Chain-of-Thought reasoning to classify social abuse categories in a zero-shot manner."}];